KA_WEB_CHUNK(4,[{"n":"Rindfleisch mit schwarzem Pfeffer und grünen Bohnen","c":"fleisch","k":"","p":6,"t":30,"d":2,"v":0,"l":"en","g":["910 g grüne Bohnen, Enden abgeknipst und Fäden entfernt","910 g Hüftsteak, Fett entfernt","½ Tasse Sojasoße","¼ Tasse Speisestärke","¼ Tasse Reiswein oder Reisessig","1 EL Zucker","2 EL gemahlener Pfeffer","6 EL Speiseöl","½ Tasse Wasser","1 EL geriebener oder gemahlener Ingwer","2 große Zwiebel, in Scheiben geschnitten"],"s":["Grüne Bohnen halbieren.","Steak mit dem Korn in 5 cm breite Streifen schneiden. Anschließend die Streifen über das Korn in 1⁄4 Zoll dicke Scheiben schneiden.","In einer mittleren Schüssel Sojasauce, Maisstärke, Wein/Wein, Zucker und schwarzer Pfeffer zusammenwischen. Steakstreifen hinzufügen und gut vermischen. Lassen Sie für 10 Minuten stehen.","Erhitzen Sie 2 EL Öl in der Pfanne bei hoher Hitze, bis Öl heiß ist, aber nicht rauchen. Grüne Bohnen dazugeben und 1 Minute umrühren. Fügen Sie Wasser und reduzieren Wärme auf Medium. Bedecken und kochen, bis zart-Kreuzung, 6–9 Minuten. Bohnen in eine mittlere Schüssel übertragen.","Fügen Sie 1⁄4 Tasse Öl zu Pfanne bei hoher Hitze. Zwiebel und Ingwer hinzufügen und 1 Minute ständig umrühren. Die gesamte Rindfleischmischung in die Pfanne geben. Kochen, Rühren, bis Steak ist nicht mehr rosa, etwa 2 Minuten.","Grüne Bohnen in die Pfanne geben, rühren, bis alles gut miteinander vermischt ist.","Servieren Sie über Nudeln oder Reis."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Black_Pepper_Beef_with_Green_Beans","i":"wb-en-1000","on":"Black Pepper Beef with Green Beans","og":["2 lb green beans, ends snapped off and strings removed","2 lb sirloin steak, fat trimmed","½ cup soy sauce","¼ cup cornstarch","¼ cup rice wine or rice wine vinegar","1 tbsp white granulated sugar","2 tbsp ground pepper","6 tbsp cooking oil","½ cup water","1 tbsp grated or ground ginger","2 large onion, sliced"],"mt":1},{"n":"Sirup mit schwarzem Pfeffer","c":"saucen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 TL gemahlener schwarzer Pfeffer","60 ml Wasser","60 ml weißer Zucker","1 TL Zitronensaft (optional)"],"s":["Pfeffer, Wasser, Zucker und Zitrone in einem Topf mischen und langsam erhitzen, bis sich der Zucker auflöst und die Mischung hellbraun ist.","Von der Hitze nehmen und 1 Stunde abkühlen lassen."],"x":["Der Zitronensaft kann durch Zitronenschale oder Limette ersetzt werden.","Macht eine gute Sauce für frisches Obst oder Obst mit saurer Sahne."],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Black_Pepper_Syrup","i":"wb-en-1001","on":"Black Pepper Syrup","og":["1 tsp ground black pepper","¼ cup (60 ml) water","¼ cup (60 ml) granulated white sugar","1 tsp lemon juice (optional)"],"mt":1},{"n":"Augenbohnen mit Grünkohl","c":"beilagen","k":"","p":4,"t":30,"d":1,"v":2,"l":"en","g":["1 EL Olivenöl","2 Zehen Knoblauch, gehackt","1 mittelgroße Zwiebel, gehackt","1 Dose gewürfelte Tomaten (430 g), nicht abgetropft","1 Dose Augenbohnen (430 g), abgetropft","¼–½ TL Cayennepfeffer","1 Lorbeerblatt","1 Packung TK-Grünkohl (280 g), aufgetaut","Salz, nach Geschmack","Pfeffer, nach Geschmack"],"s":["Zwiebel und Knoblauch im Öl bei mittlerer Hitze einige Minuten lang anbraten.","Tomaten mit Saft, Erbsen, Cayenne und Lorbeerblatt dazugeben. Simmer, gedeckt, für 15 Minuten.","Grünkohl hinzufügen und aufgedeckt köcheln, bis der Grünkohl zart ist (5–10 Minuten). Mit Salz und frisch gemahlenem schwarzem Pfeffer abschmecken."],"x":[],"desc":"Schwarzäugige Erbsen und Grünkohl ist eine schmackhafte Beilage für Veganer geeignet.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Black-Eyed_Peas_and_Kale","i":"wb-en-1002","on":"Black-Eyed Peas and Kale","og":["1 tbsp olive oil","2 cloves garlic, chopped","1 medium onion, chopped","1 can (15 oz) diced tomatoes, undrained","1 can (15 oz) black-eyed peas, drained","¼–½ tsp cayenne pepper","1 bay leaf","1 package (10 oz) frozen kale, thawed","Salt to taste","Pepper to taste"],"mt":1},{"n":"Spaghetti mit Pfefferhähnchen","c":"fleisch","k":"","p":5,"t":60,"d":2,"v":0,"l":"en","g":["1 Packung Spaghetti (800 g)","1 l Wasser","5 EL Öl, aufgeteilt","6 Zehen Knoblauch, zerdrückt und fein gehackt","1 grüne Paprika, in 8 Stücke geschnitten","1 rote Paprika, in 8 Stücke geschnitten","1 große Zwiebel, fein gehackt","100 ml Sahne","6 Hähnchenfilets, in 2 cm große Stücke geschnitten","25 g schwarzer Pfeffer","2 EL Salz","2 EL Petersilie"],"s":["Bringen Sie das Wasser zum Kochen in einem Topf. Spaghetti und 2 EL Öl dazugeben. 10 Minuten kochen, dann die Spaghetti abtropfen lassen und etwas Kochwasser beiseite legen.","Kochen Sie das Huhn in Salzwasser, bis sich die Farbe ändert. Das Huhn abtropfen lassen.","Das verbleibende Öl in einer Antihaft Pfanne erhitzen. Knoblauch, Capsicum und Zwiebel dazugeben und anbraten.","Das abgelassene Hähnchen, Sahne, schwarzer Pfeffer, Salz und Petersilie dazugeben. Rühren bis gut kombiniert.","Die Spaghetti hinzufügen und bis gut gemischt zusammenwerfen.","Heiß servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Black-Peppered_Chicken_Spaghetti","i":"wb-en-1003","im":["9/92/Spaghettoni.jpg/960px-Spaghettoni.jpg","Nnaluci","CC BY-SA 3.0","Spaghettoni.jpg","w"],"on":"Black-Peppered Chicken Spaghetti","og":["1 pack (800 g) spaghetti noodles","1 L water","5 tbsp oil, divided","6 cloves garlic, crushed and minced","1 green capsicum, cut into 8 pieces","1 red capsicum, cut into 8 pieces","1 big onion, minced","100 ml cream","6 chicken fillets, cut into 2 cm pieces","25 g black pepper","2 tbsp salt","2 tbsp parsley"],"mt":1},{"n":"Brombeerbrei","c":"dessert","k":"","p":4,"t":15,"d":1,"v":0,"l":"en","g":["100 g Brombeeren","80 g Zucker","240 ml Wasser","20 g Speisestärke (20 g)"],"s":["Die Frucht in einen Topf geben.","Zucker, Maisstärke und Wasser hinzufügen und einem Fruchtfleisch einmassieren.","Simmer oder kochen, aufgedeckt, um Feuchtigkeit zu reduzieren.","Servieren Sie heiß über Eis oder kalt als Marmelade."],"x":["Himbeeren, Pflaumen, Heidelbeeren und Pfirsiche können auf die gleiche Weise gekocht werden."],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Blackberry_Mush","i":"wb-en-1004","on":"Blackberry Mush","og":["100 g (3.5 oz / 1 cup) blackberries","80 g (2.8 oz / ⅓ cup) white granulated sugar","240 ml (8.1 oz / 1 cup) water","20 g (0.71 oz / ⅙ cup) cornstarch"],"mt":1},{"n":"Brombeer-Hafer-Riegel (glutenfrei)","c":"veggie","k":"","p":4,"t":0,"d":2,"v":2,"l":"en","g":["3 Tassen Vollkorn-Haferflocken","1 Tasse Mandelmehl","1 Spritzer Salz","½ Tasse Kokosöl, geschmolzen","½ Tasse fest gedrückter brauner Zucker","¼ Tasse Honig","1 TL Vanilleextrakt","¼ TL gemahlener Zimt","2 TL Mandelmus","950 ml frische Brombeeren","2 EL Zucker"],"s":["Den Ofen auf 175 °C vorheizen. Eine 23 x 23 cm große Backform mit Backpapier auslegen und beiseite stellen. Der einfachste Weg, dies zu tun ist, zwei Streifen Backpapier schneiden und quer durch sie in der Pfanne.","In einem Lebensmittel-Verarbeiter mit der Klinge Befestigung ausgestattet, fügen Sie die Hafer, Mandelmehl und Salz. Vermischen Sie sich gut.","Fügen Sie das geschmolzene Kokosöl, braunen Zucker, Honig, Vanille, Zimt und Mandelbutter hinzu. Puls zu vermischen.","2⁄3 der Hafermischung in die vorbereitete Backform geben. Stellen Sie die restlichen 1⁄4 für die bröckelige Topping beiseite. Drücken Sie mit Ihren Händen fest, um eine untere Krustenschicht zu bilden. Den Teig leicht mit einem Gabel-Paring-Messer stechen, um zu verhindern, dass sprudeln.","Platzieren Sie in den Ofen und backen Sie für 10 Minuten vor.","Während die Kruste backt, legen Sie Brombeeren und Zucker in einen Lebensmittelverarbeiter und pulsieren, um die Beeren grob zu hacken und den Zucker einzubauen.","Die Backform aus dem Ofen nehmen und die Brombeerfüllung gleichmäßig darüber verteilen. Bestreuen Sie die restlichen bröckeligen Topping auf der Oberseite der Brombeeren. Zurück in den Ofen legen und für weitere 25 Minuten oder bis leicht golden backen.","Vor dem Schneiden vollständig abkühlen lassen."],"x":[],"desc":"Glutenfreie, vegan-freundliche Blackberry Haferbars, die Montagmorgen frühstücken könnten.","img":"Gluten-Free Blackberry Oat Bars.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Blackberry_Oat_Bars_(Gluten-Free)","i":"wb-en-1005","im":["e/e9/Gluten-Free_Blackberry_Oat_Bars.jpg/500px-Gluten-Free_Blackberry_Oat_Bars.jpg","Simmer + Sauce","CC BY 3.0","Gluten-Free Blackberry Oat Bars.jpg","r"],"on":"Blackberry Oat Bars (Gluten-Free)","og":["3 cups whole grain oats","1 cup almond flour","1 dash of salt","½ cup coconut oil, melted","½ cup packed brown sugar","¼ cup honey","1 teaspoon vanilla extract","¼ teaspoon ground cinnamon","2 teaspoons almond butter","2 pints fresh blackberries","2 tablespoons sugar"],"mt":1},{"n":"Geschwärzte Rinderhüfte","c":"fleisch","k":"USA","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 Hüftsteak (Top Sirloin)","2 EL schwarze Pfefferkörner, geschrotet","1 TL Salz","1 EL Cajun-Gewürz","Olivenöl"],"s":["Bürsten Sie Steak mit Öl. Auf beiden Seiten mit Gewürzen, Pfefferkörner und Salz würzen. Stehen lassen bis Raumtemperatur, ca. 30 Minuten.","Grill vorheizen auf 2 Einstellungen: Sehr hoch und mittelhoch.","Fügen Sie Steak zum heißesten Teil und kochen 3 Minuten pro Seite, rotieren 90 Grad auf halbem Wege durch jede Seite zu markieren.","Verschieben Sie Steak auf mittlere hohe Hitze und kochen, oft drehen, bis Kerntemperatur 3 °C weniger als die gewünschte \"Stoneness\".","Entfernen Sie auf eine Platte und decken Sie fest mit Aluminiumfolie. Lassen Sie sich 10 Minuten ausruhen.","Vor dem Servieren in einem 45-Grad-Winkel dünn über das Korn schneiden. Warm mit Bearnaise-Sauce servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Blackened_Sirloin","i":"wb-en-1006","on":"Blackened Sirloin","og":["1 top sirloin steak","2 tbsp black peppercorns, cracked","1 tsp salt","1 tbsp Cajun seasoning","Olive oil"],"mt":1},{"n":"Blini","c":"kuchen","k":"Russland","p":20,"t":0,"d":2,"v":0,"l":"en","g":["4 Tassen Milch, erwärmt (27 bis 35 °C)","1 EL Zucker","1 EL Salz","5 TL Butter, geschmolzen","30 g Hefe","1 Eiweiß","590 g Weizenmehl","5 TL Olivenöl"],"s":["Die Hefe in 3 Tassen der warmen Milch auflösen. 1⁄2 Esslöffel Zucker, Salz, Eigelb und geschmolzene Butter zugeben.","Rühren, dann die Hälfte des Mehls zugeben und den Teig kneten.","Bedecken Sie die Schüssel mit einem Tuch oder Handtuch und lassen Sie sie an einem warmen Ort für 1,5–2 Stunden, oder bis das Volumen des Teiges verdoppelt wird.","Den Rest der Milch auf 50 °C erhitzen, dann mit Mehl und Zucker in den Teig mischen. Gut verpacktes Eiweiß eingießen.","Den Teig noch einmal kneten und lassen, bis er aufsteigt.","Eine geölte Bratpfanne erhitzen. Mit einer großen Pfanne gießen Sie etwas Teig in die Mitte, so dass es einen Kreis macht.","Wenn der Boden des Blin bereit ist (die Kanten des Blin sollten sich von der Pfanne getrennt haben und nach oben zeigen), drehen Sie ihn um.","Nachdem es fertig ist, legen Sie den Blin auf eine große Platte und beginnen, die nächste zu machen."],"x":[],"desc":"Blini (singulärer Fleck; Auf Russisch, блин[ы]) sind kleine russische Pfannkuchen, typischerweise mit saurer Sahne, Marmelade oder Kaviar gekrönt.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bliny","i":"wb-en-1007","im":["e/ea/50_%D0%B1%D0%BB%D1%96%D0%BD%D0%BA%D0%BE%D1%9E_%D0%BD%D0%B0_%D1%82%D0%B0%D0%BB%D0%B5%D1%80%D1%86%D1%8B_240_%D0%BC%D0%BC.jpg/960px-50_%D0%B1%D0%BB%D1%96%D0%BD%D0%BA%D0%BE%D1%9E_%D0%BD%D0%B0_%D1%82%D0%B0%D0%BB%D0%B5%D1%80%D1%86%D1%8B_240_%D0%BC%D0%BC.jpg","Maksim L.","CC BY-SA 4.0","50 блінкоў на талерцы 240 мм.jpg","w"],"on":"Bliny","og":["4 cups of milk, warmed (80–95°F)","1 tablespoon of white granulated sugar","1 tablespoon of salt","5 teaspoons of butter, melted","1 ounce of yeast","1 egg white","1.3 pounds (5 cups) of wheat flour","5 teaspoons of olive oil"],"mt":1},{"n":"Blauschimmelkäse-Dressing","c":"saucen","k":"USA","p":3,"t":0,"d":1,"v":0,"l":"en","g":["2 EL Zitronensaft oder Essig (30 ml) (Cidre oder Weißwein)","160 ml Buttermilch","230 g Mayonnaise","180 g saure Sahne","½ TL Salz","½ TL schwarzer Pfeffer","½ TL Knoblauchpulver","½ TL Zwiebelpulver","115 g beliebiger Blauschimmelkäse"],"s":["Kombinieren Sie alle Zutaten außer dem Blaukäse und Whisky, bis glatt und homogen.","Den Blaukäse in etwa 1⁄2 Zoll (1 cm) Würfel schneiden. Die meisten blauen Käse ist bröckelig, so werden Sie mit einer Menge von Krümeln sowie größere Stücke landen.","Die Mayonnaisemischung in ein Servierbehältnis geben und die Würfel und Krümel des Käses unterrühren."],"x":[],"desc":"Angepasst aus dem Buttermilch Ranch Dressing Rezept.","img":"Blue cheese dressing.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Blue_Cheese_Dressing","i":"wb-en-1008","im":["f/f6/Blue_cheese_dressing.jpg/960px-Blue_cheese_dressing.jpg","jules","CC BY 2.0","Blue cheese dressing.jpg","r"],"on":"Blue Cheese Dressing","og":["2 tbsp (30 ml) lemon juice or vinegar (cider or white wine)","2/3 cup (160 ml) buttermilk","1 cup (230 g) mayonnaise","¾ cup (180 g) sour cream","½ tsp salt","½ tsp black pepper","½ tsp garlic powder","½ tsp onion powder","4 oz (115 g) any variety of blue cheese"],"mt":1},{"n":"Heidelbeer-Sahne-Pie","c":"brot","k":"USA","p":8,"t":60,"d":1,"v":1,"l":"en","g":["#Pie","1 Becher saure Sahne (225 g)","2 EL Mehl","150 g weißer Zucker","1 TL Vanille","1 Ei, verquirlt","500 g frische Heidelbeeren","1 ungebackener Mürbeteigboden (23 cm) (23 cm)","#Belag","3 EL Mehl","3 EL Butter","3 EL Pekannüsse, gehackt"],"s":["Backofen auf 200 °C vorheizen.","Kombinieren Sie in einer Schüssel Sauerrahm, Mehl, Zucker, Vanille und Ei.","Schlagen Sie bis sehr glatt.","In Blaubeeren falten.","Füllen in Kuchenschale gießen.","25 Minuten backen.","In einer kleinen Schüssel Mehl, Butter und Pekannüsse mischen und gut umrühren.","Über Kuchen streuen und weitere 10 Minuten backen.","Aus dem Ofen nehmen.","Cool auf Drahtgitter, dann chillen."],"x":["Ein wenig Schlagsahne auf der Oberseite ist eine schöne Ergänzung."],"desc":"Dieses Rezept für Heidelbeer-Creme ist von Küchenchef Taylor Piercefield.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Blueberry_Cream_Pie","i":"wb-en-1009","im":["8/84/Coconut_cream_pie.jpg/960px-Coconut_cream_pie.jpg","Kim Scarborough","CC BY-SA 2.5","Coconut cream pie.jpg","w"],"on":"Blueberry Cream Pie","og":["#Pie","1 container (8 ounces / 225 g) sour cream","2 tablespoons flour","¾ cup (150 g) white sugar","1 teaspoon vanilla","1 egg, beaten","2½ cups (500 g) fresh blueberries","1 ea. 9-inch (23 cm) unbaked pie shell","#Topping","3 tablespoons flour","3 tablespoons butter","3 tablespoons pecans, chopped"],"mt":1},{"n":"Heidelbeer-Muffin","c":"brot","k":"","p":12,"t":45,"d":1,"v":1,"l":"en","g":["250 g Mehl","65 g Zucker","2 TL Backpulver","¼ TL Salz","1 Ei, verquirlt","180 ml Milch","60 ml Speiseöl","180 ml Heidelbeeren, frisch oder tiefgekühlt"],"s":["Fett-Muffin-Tasse oder -Linie mit Papierbechern; Zur Seite gestellt.","Den Ofen auf 200 °C vorheizen.","In einer mittleren Schüssel Mehl, Zucker, Backpulver und Salz kombinieren. Machen Sie einen Brunnen in der Mitte der Mischung und beiseite stellen.","Kombinieren Sie in einer kleinen Schüssel geschlagenes Ei, Milch und Öl. Diese Mischung auf einmal in die Mehlmischung geben. Blaubeeren einklappen und nur bis zur Kombination umrühren. Nicht übertreiben.","Löffel Teig in vorbereitete Tassen, Füllung jeweils etwa zwei Drittel voll.","Für 18 bis 20 Minuten oder bis golden backen. Wenn ein hölzerner Zahnstocher nahe der Mitte eingesetzt wird, sollte er sauber herauskommen.","Aus Muffinbechern entfernen und 5 Minuten auf einem Drahtgitter abkühlen lassen."],"x":["Die Mischung sollte nach dem Rühren klumpig sein. Das Overstirring, um glatte Teig machen wird die Muffins zu hart sein.","Die Muffins in den Muffinbechern zu lassen, kann sie ärgerlich machen.","Um Jumbo-Muffins herzustellen, die Temperatur auf 180 °C reduzieren und 30 Minuten backen.","Für Mini-Muffins ca. 10 Minuten bei 200 °C backen."],"desc":"Heidelbeermuffins sind ein in vielen Teilen der Welt verbreitetes Gebäck.","img":"Blueberry muffins.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Blueberry_Muffin","i":"wb-en-1010","im":["0/0a/Blueberry_muffins.jpg/500px-Blueberry_muffins.jpg","Rob Pongsajapan from Arlington, VA, USA","CC BY 2.0","Blueberry muffins.jpg","r"],"on":"Blueberry Muffin","og":["1¾ cups (250 g) flour","⅓ cup (65 g) white granulated sugar","2 teaspoons baking powder","¼ teaspoon salt","1 egg, beaten","¾ cup (180 ml) milk","¼ cup (60 ml) cooking oil","¾ cup (180 ml) blueberries, fresh or frozen"],"mt":1},{"n":"Heidelbeerpfannkuchen","c":"kuchen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 ¾ Tassen Weizenmehl","2 EL Zucker","2 TL Natron","1 ½ TL Weinstein (oder Backpulver)","½ TL Salz","1 TL Zimt","1 TL Muskatnuss","1 TL Vanilleextrakt","2 Tassen Buttermilch","4 Eier, getrennt","¼ Tasse Butter (optional)","1 Tasse tiefgekühlte Heidelbeeren"],"s":["Mehl, Zucker, Backpulver, Tortencreme, Salz, Zimt und Muskat. Beiseite legen.","In einer großen Schüssel Buttermilch, Butter und Eigelb zusammenwischen. Mehlmischung in Buttermilchmischung mischen. Blaubeeren mischen.","Whip Eiweiß in einer kleinen Schüssel, bis steif, aber lassen Sie nicht trockene Spitzen bilden. Falten Sie in Pfannkuchen Teig.","Eine große Pfanne oder ein Gitter bei mittlerer Hitze erhitzen. Leicht mit Pflanzenöl besprühen oder bürsten. Pfanne in einer 1⁄4 Tasse Teig für jeden Pfannkuchen; Kochen bis gesetzt und sprudeln auf der Oberseite. Drehen Sie Pfannkuchen um, dann kochen für eine weitere Minute.","Servieren Sie warm mit dem, was Topping Sie bevorzugen."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Blueberry_Pancakes","i":"wb-en-1011","im":["7/7e/Blueberry_Pancakes_-_Nowhere_Man_2023-09-21.jpg/960px-Blueberry_Pancakes_-_Nowhere_Man_2023-09-21.jpg","Andy Li","CC0","Blueberry Pancakes - Nowhere Man 2023-09-21.jpg","c"],"on":"Blueberry Pancakes","og":["1¾ cup all-purpose flour","2 Tbsp white granulated sugar","2 tsp baking soda","1½ tsp cream of tartar (or baking powder)","½ tsp salt","1 tsp cinnamon","1 tsp nutmeg","1 tsp vanilla extract","2 cups buttermilk","4 eggs, separated","¼ cup butter (optional)","1 cup frozen blueberries"],"mt":1},{"n":"Bløtkake (norwegische Sahnetorte mit Beeren)","c":"kuchen","k":"Norwegen","p":4,"t":60,"d":3,"v":0,"l":"en","g":["#Teig","4 Eier","100 g Zucker","100 g Mehl","1 TL Backpulver","#Füllung","Himbeerkonfitüre","1 Dose Pfirsichspalten","Vanillepudding","Schlagsahne","1 TL Zucker","#Garnitur","Beeren oder anderes Obst (meist Heidelbeeren, Johannisbeeren oder andere weiche Beeren)"],"s":["Eier und Zucker rühren, bis sie Gipfel bilden. Mehl und Backpulver in die Eimischung einsieben und vorsichtig einfalten.","Den Teig in eine gefettete runde Dose (ca. 22 cm Durchmesser) gießen und 30–40 Minuten bei 170 °C backen.","Kühlen Sie komplett auf einem Rack, dann entsalzen Sie die Kuchen.","Schneiden Sie den Kuchen horizontal in 3 Schichten. Jede Scheibe mit etwas Pfirsichsaft aus der Dose bestreuen.","2 der Scheiben mit Marmelade, Pfirsichscheiben und Vanille-Custard bedecken. Legen Sie die dritte Ebene auf die anderen beiden.","Die Sahne mit dem Zucker abreiben. Den ganzen Kuchen, einschließlich der Seiten, mit der Schlagsahne bedecken.","Mit Beeren und/oder Früchten garnieren."],"x":[],"desc":"Bløtkake ist ein traditionelles norwegisches Dessert, das normalerweise für besondere Anlässe wie Geburtstage beiseite gelegt wird. Es wird auch an Norwegens Nationalfeiertag, 17. Mai serviert.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bløtkake_(Norwegian_Berries_and_Cream_Cake)","i":"wb-en-1012","im":["3/35/Bringeb%C3%A6rbl%C3%B8tkake.JPG/960px-Bringeb%C3%A6rbl%C3%B8tkake.JPG","Øyvind Holmstad","CC BY-SA 4.0","Bringebærbløtkake.JPG","w"],"on":"Bløtkake (Norwegian Berries and Cream Cake)","og":["#Batter","4 eggs","100 g white granulated sugar","100 g flour","1 tsp baking powder","#Filling","Raspberry jam","1 tin sliced peaches","Vanilla custard","Whipped cream","1 tsp white granulated sugar","#Garnish","Berries or other fruit (usually blueberries, redcurrants or other soft berries)"],"mt":1},{"n":"Bobotie","c":"fleisch","k":"Afrika","p":6,"t":90,"d":2,"v":0,"l":"en","g":["#Fleischfüllung","500 g Rinder- oder Lammhack","1 Zwiebel, fein gehackt","2 Scheiben Brot","125 ml Milch","1 EL Currypulver","1 TL Kurkuma","1 EL Fruchtchutney","1 EL Essig oder Zitronensaft","2 EL Rosinen","1 EL Speiseöl","Salz und schwarzer Pfeffer, nach Geschmack","#Eierguss","2 Eier","250 ml Milch","2 Lorbeerblätter"],"s":["Das Brot in die Milch einweichen und beiseite stellen.","Öl in einer Pfanne erhitzen und die Zwiebel weich anbraten.","Das Hackfleisch dazugeben und bräunen.","Currypulver, Kurkuma, Chutney, Essig, Rosinen, Salz und Pfeffer einrühren.","Überschüssige Milch aus dem Brot quetschen und das Brot in die Fleischmischung mischen.","Übertragen Sie die Mischung auf eine gefettete Backform.","Die Eier mit der Milch schlagen und über das Fleisch gießen.","Legen Sie die Lorbeerblätter oben auf.","Backen Sie bei 180 °C für etwa 35–40 Minuten, oder bis die Custard gesetzt und leicht gebräunt ist.","Heiß mit gelbem Reis, Gemüse oder Chutney servieren."],"x":["Bobotie stammt vermutlich aus der kapmalaiischen Küche in Südafrika.","Die Kombination von süßen und herzhaften Aromen ist charakteristisch für das Gericht.","Traditionell wird es mit gelbem Reis mit Kurkuma aromatisiert serviert.","Bobotie aus Lamm statt Rindfleisch.","Vegetarische Bobotie mit Linsen oder auf Pflanzenbasis.","Spicier-Versionen mit zusätzlichen Chilischoten."],"desc":"Bobotie ist ein traditionelles südafrikanisches Gericht, das aus gewürztem Hackfleisch besteht, das mit einem herzhaften Eier-basierten Custard Topping gebacken wird. Es gilt als eines der nationalen Gerichte Südafrikas und spiegelt die kulinarischen Einflüsse malaiischer, niederländischer und indigener afrikanischer Traditionen wider.","img":"Bobotie South Africa.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Bobotie","i":"wb-en-1013","im":["4/46/Bobotie_South_Africa.jpg/960px-Bobotie_South_Africa.jpg","Olivier Lemoine Photographe professionnel vigne / vin, Beaun","CC BY-SA 4.0","Bobotie South Africa.jpg","r"],"og":["#Meat filling","500 g minced beef or lamb","1 onion, finely chopped","2 slices bread","125 ml milk","1 tablespoon curry powder","1 teaspoon turmeric","1 tablespoon fruit chutney","1 tablespoon vinegar or lemon juice","2 tablespoons raisins","1 tablespoon cooking oil","Salt and black pepper, to taste","#Custard topping","2 eggs","250 ml milk","2 bay leaves"],"mt":1},{"n":"Boerewors (südafrikanische Wurst)","c":"fleisch","k":"Südafrika","p":12,"t":120,"d":3,"v":0,"l":"en","g":["1 EL Koriandersamen","910 g Rindfleisch, gewürfelt","910 g Hammelfleisch, gewürfelt","910 g Kalbfleisch, gewürfelt","115 g Speck, gewürfelt","1 ½ EL Salz","1 TL gemahlener schwarzer Pfeffer","¼ TL gemahlene Nelken","½ TL geriebene Muskatnuss","½ TL gemahlener Piment","½ Tasse Malzessig","1 ½ Weinbrand (optional)","5,6 cm breite Wurstdärme"],"s":["Samen in eine trockene Bratpfanne geben.","Legen Sie die Pfanne über niedrige Hitze und lassen Koriander leicht brennen.","Zerkleinern Sie die Samen mit einer Gabel oder verwenden Sie einen Kaffee/Spitzenschleifer, um sie fein zu mahlen.","Alles Fleisch schneiden und in Würfel spekulieren.","Spek und Fleisch gründlich vermischen, dann grob hacken oder mahlen.","Alle trockenen Gewürze, Essig und Brandy mit einer großen, zweizackigen Gabel vermischen.","Fleischmischung in den Kühlschrank stellen und 2 Stunden ruhen lassen, um die Aromen miteinander zu vermischen.","Während das Fleisch ruht, saugen Sie die Würstchen in Wasser für die gleichen 2 Stunden.","Ummantelung über Wurstmacher, und füllen Sie mit der Fleisch/Spitzen-Mischung. Seien Sie sehr vorsichtig, nicht zu über- oder unterfüllen die Boerewors, wie dabei wird sie ruinieren. Lange Dauerlängen ausfüllen; Mach keine Verbindungen.","Kochen Sie Würstchen auf einem Grill, aber nicht stechen, damit Säfte zu entkommen, so viel von dem Geschmack wird mit ihnen entkommen. Kochen bis noch rosa und saftig innen"],"x":["Versuchen Sie, etwa 100 ml regelmäßige Haferflocken hinzuzufügen – dies hilft, das Fleisch zu binden.","Achten Sie darauf, nicht überspeiste das Hackfleisch, die den Geschmack ruinieren wird.","Vorsicht bei der Zugabe von Salz; Der Spek enthält viel.","Boerewors können bis zu 3 Wochen im Gefrierschrank gelagert werden."],"desc":"Traditionell in Braais oder Grillen, Boerewors (Afrikaans: Bauernwurst) sind dicke, herzhafte und schmackhafte Afrikaner Würstchen, die oft mit einem Maisbrei namens pap gegessen werden.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Boerewors_(South_African_Sausage)","i":"wb-en-1014","im":["c/c6/Boerewors_raw.jpg/330px-Boerewors_raw.jpg","TempestSA at English Wikipedia","CC BY-SA 3.0","Boerewors raw.jpg","w"],"on":"Boerewors (South African Sausage)","og":["1 tbsp coriander seed","2 lb beef, cubed","2 lb mutton, cubed","2 lb veal, cubed","¼ lb spek, cubed","1½ tbsp salt","1 tsp ground black pepper","¼ tsp ground cloves","½ tsp grated nutmeg","½ tsp ground allspice","½ cup brown vinegar","1½ brandy (optional)","2¼-inch wide sausage casings"],"mt":1},{"n":"Boeuf bourguignon","c":"suppen","k":"Frankreich","p":4,"t":180,"d":2,"v":0,"l":"en","g":["1 kg Rindfleisch (Schaufelstück oder Schulter zum Schmoren)","3 große Zwiebeln, gehackt","1–2 Zehen Knoblauch","300 g gehackte Möhre","300 g weiße Champignons","Kräuterstrauß: Basilikum, Rosmarin und Thymian, mit Küchengarn gebunden","2–4 Tassen Rotwein","Salz","Pfeffer","Olivenöl","Mehl"],"s":["Rindfleisch in 5 cm große Stücke schneiden. Mit Salz, Pfeffer und Olivenöl würzen.","Kochen Rindfleisch eine kleine Menge zu einer Zeit in einem holländischen Ofen oder großen Topf, bis es goldbraun auf der Außenseite ist. Entfernen Sie jede Portion, wie es getan ist und beiseite stellen.","Zwiebeln und Knoblauch in den gleichen Topf geben und goldbraun kochen.","Mit 2 Esslöffel Mehl bestreuen. Noch ein paar Minuten kochen.","1–2 Tassen Rotwein hinzufügen.","Wein zum Kochen bringen, dann 5 Minuten köcheln lassen.","Rindfleisch, Karotten, Kräuter und Pilze hinzufügen.","Fügen Sie noch ein paar Tassen Rotwein und Wasser (Genug, um das Fleisch und Gemüse zu decken).","2–3 Stunden kochen, gelegentlich rühren. Entfernen Sie den Oberflächenabschaum nach Bedarf."],"x":["Verwenden Sie Reste, um Fleischkuchen oder Puff Gebäck zu machen.","Eine kleine Menge getrockneter Trompettes de la mort (Craterellus cornucopioides) hinzufügen. Für ein Gericht mit 4, 4 Trompetten können je nach Geschmack verwendet werden. Teile abschneiden, die Sand enthalten können, ausspülen, in kleine Stücke schneiden, 5 Minuten in warmes Wasser einweichen und nach Zugabe des Weins in das Gericht geben. Kann anstelle von Knoblauch verwendet werden.","Verwenden Sie einen fettarmen Schnitt von Rindfleisch und servieren mit gekochten Kartoffeln oder gedünsteten Reis auf der Seite, um das Fett und Kalorien in diesem Gericht zu senken."],"desc":"Boeuf bourguignon (französisch für Burgunder Rindfleisch) ist ein bekannter, traditioneller französischer Eintopf, der mit in Rotwein gebrütetem Rindfleisch (ursprünglich Burgunder Wein) und mit Knoblauch, Zwiebeln, Karotten, einem Strauß garni und mit Pilzen garniert zubereitet wird. Es ist eines von vielen Beispielen der Bauerngerichte sl","img":"Boeuf bourguignon servi avec des pâtes.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Boeuf_Bourguignon","i":"wb-en-1015","im":["5/53/Boeuf_bourguignon_servi_avec_des_p%C3%A2tes.jpg/960px-Boeuf_bourguignon_servi_avec_des_p%C3%A2tes.jpg","DC","CC BY 3.0","Boeuf bourguignon servi avec des pâtes.jpg","r"],"on":"Boeuf Bourguignon","og":["1 kg beef (blade steak or stewing shoulder cut)","3 large onions, chopped","1–2 cloves of garlic","300 g of chopped carrot","300 g of button mushrooms","Bouquet of herbs: basil, rosemary and thyme tied with string","2–4 cups of red wine","Salt","Pepper","Olive oil","Flour"],"mt":1},{"n":"Gekochtes Hähnchen mit Brühe","c":"suppen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 ganzes zartes Hähnchen, geputzt","2,85 l Wasser","2 EL Reis oder Perlgraupen","Salz, nach Geschmack","frische Petersilie","Butterschmalz, geschmolzen"],"s":["Das Huhn in Viertel schneiden und mit Wasser, Reis und Salz in einen großen Topf legen.","Bringen Sie Topf zu einem langsamen Kochen, Entfernen von Abschaum, der an die Oberfläche steigt. Kochen, bis das Huhn gründlich fertig ist.","Das Huhn entfernen und in ein Serviergericht geben. Mit Petersilie garnieren.","Die Brühe durch ein Sieb gießen.","Das Huhn mit aufgeklärter Butter und der heißen Brühe an der Seite servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Boiled_Chicken_with_Broth","i":"wb-en-1016","on":"Boiled Chicken with Broth","og":["1 whole tender chicken, cleaned","3 quarts water","2 tbsp rice or pearl barley","Salt to taste","Fresh parsley","Clarified butter, melted"],"mt":1},{"n":"Gekochter Taro","c":"welt","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["Taro (Cocoyam)","Wasser","Salz"],"s":["Waschen Sie den Cocoyam, um Schmutz von der Oberfläche zu entfernen, und schneiden Sie in kleinere Stücke ohne Peeling.","Cocoyam in einen Topf geben und mit Wasser bedecken.","Eine Prise Salz zugeben und mehrere Minuten köcheln lassen.","Cocoyam abtropfen lassen und die Schale entfernen.","Servieren Sie mit Garten-Ei Eintopf, Ei-Sauce oder gebratenem Pfeffer."],"x":[],"desc":"Der gekochte Cocoyam, auch Lambo (Yoruba), Gwaza (Hausa) und Akasi (Igbo) genannt, ist ein typisches nigerianisches Essen. Es wird angenommen, dass ein reicher Geschmack und einen höheren Nährwert als Yam haben.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Boiled_Cocoyam","i":"wb-en-1017","im":["3/3d/Boiled_cocoyam_and_garden_egg_stew_with_boiled_eggs.jpg/500px-Boiled_cocoyam_and_garden_egg_stew_with_boiled_eggs.jpg","DaSupremo","CC BY-SA 4.0","Boiled cocoyam and garden egg stew with boiled eggs.jpg","c"],"on":"Boiled Cocoyam","og":["Cocoyam","Water","Salt"],"mt":1},{"n":"Gekochter Blattkohl","c":"beilagen","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["900–1300 g Blattkohl (Collard Greens)","2 EL Schweineschmalz oder ein Öl (optional)","¼ TL Salz","2–3 TL Zucker (optional)","700–900 g geräucherter Schweinenackenknochen (optional, ersatzweise deutlich weniger Wurst)","¼ TL schwarzer Pfeffer","¼ TL Cayennepfeffer (Pulver oder Flocken, optional)","60 ml Essig (optional)","1 mittelgroße Zwiebel (optional), gewürfelt, gehackt, oder in Scheiben"],"s":["Grün mit sehr leicht seifigem Wasser gründlich waschen und mit klarem Wasser abspülen. Mindestens zweimal abspülen, um das Entfernen aller Grit und Seife zu gewährleisten.","Blätter können von Stängeln entfernt werden oder auf verlassen, wenn bevorzugt. Wenn auf links, schneiden Stiele in kleiner Länge (unter 2,5 cm / 2,5 cm) für Leichtigkeit.","Schneiden Sie Blätter in Biss-Größe Stücke. Sie können längs oder in der Breite gefaltet werden, um dies zu erleichtern.","Die gehackten Blätter in den Topf des kochenden Wassers legen – verwenden Sie gerade genug Wasser, um die Grüns vom Boden des Topfes zu halten; Oder sonst wird Ihr Grün wässrig sein und keinen Geschmack haben. Blätter verringern sich in der Größe beim Kochen, wenn auch nicht signifikant.","Abhängig von der Größe des Topfes, in dem sie gekocht werden, kann es notwendig sein, einige zu kochen, dann fügen Sie weitere Blätter nach kurzer Zeit.","Die restlichen Zutaten hinzufügen.","Etwa 20 Minuten kochen oder bis sie die gewünschte Zärtlichkeit erreichen. Wenn sie überkochen, wird ihr Geschmack nicht beeinflusst werden, aber sie werden matschig sein."],"x":["Heiße Pfeffersauce kann nach Belieben hinzugefügt werden.","Würstchen oder geräucherte Putenbeine oder Flügel können für das Schweinefleisch ersetzt werden, obwohl es überhaupt nicht notwendig ist, Fleisch zu verwenden.","Während des Kochens können weitere Gewürze und Kräuter hinzugefügt werden, darunter rote Paprika, frische gelbe Wachspaprika, Basilikum, Thymian oder Kurkuma. Brauner Zucker kann während des Kochens hinzugefügt werden, und Essig kann weggelassen, reduziert oder erhöht werden (wieder, je nach Geschmack).","Collards können auch in einer Pfanne gewelkt, par-boiled (gekocht einmal, dann wieder in Süßwasser gekocht), oder sogar roh gegessen werden.","Collards werden häufig mit Cornbread genossen. Der \"Töpfchen-Likker\" (Wasser, in dem die Halsbänder gekocht werden) kann für zusätzlichen Geschmack über das Kornbrot gegossen werden."],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Boiled_Collard_Greens","i":"wb-en-1018","im":["c/ce/Tearing_collard_greens.jpg/500px-Tearing_collard_greens.jpg","Kevin L. Bardon~enwikibooks at English Wikibooks","CC BY-SA 2.5","Tearing collard greens.jpg","c"],"on":"Boiled Collard Greens","og":["2–3 lbs (900–1300 g) collard greens","2 tablespoons pork fat or some type of oil (optional)","¼ teaspoon salt","2–3 teaspoons sugar (optional)","1.5–2 lbs (700–900 g) smoked pork neck bone (optional, or, may substitute a much smaller amount of sausage)","¼ teaspoon black pepper","¼ teaspoon cayenne pepper (powder or flakes; optional)","¼ cup (60 ml) vinegar (optional)","1 medium onion (optional), diced, chopped, or sliced"],"mt":1},{"n":"Gekochte Gurke mit Kokosraspeln (Pachadi)","c":"welt","k":"","p":4,"t":7,"d":1,"v":0,"l":"en","g":["1 Gurke (große Sorte mit dunkelgrüner und gelber Schale)","½ Tasse Kokosraspel","1 TL Kreuzkümmelsamen (Kreuzkümmel, Jeera)","1 TL Senfsamen","1–2 getrocknete rote Chilis","1 EL Öl","Salz nach Bedarf, nach Geschmack"],"s":["Haut die Gurke ab. Schneiden Sie in der Hälfte entlang der Länge und entfernen Sie den zentralen Kern der Samen. Wirf die Samen weg.","Die Gurke grillen. Alternativ in sehr kleine Stücke schneiden.","Die Gurke in der Mikrowelle ca. 4–5 min kochen.","Unterdessen eine feine Paste aus der geriebenen Kokosnuss und den Kümmelsamen machen","In einer tiefen Pfanne (kadhai) das Öl erhitzen. Die Senfsamen und die roten Chilis dazugeben und spritzen lassen.","Die gekochte Gurke, die Kokosnusspaste und das Salz nach Geschmack hinzufügen. Mischen Sie gut und lassen Sie es kochen auf langsamem Feuer. Lassen Sie es nicht kochen – es muss nur erwärmt werden.","Wenn die Mischung beginnt zu kochen, nehmen Sie sie vom Herd. Servieren."],"x":[],"desc":"Pachadi ist ein sehr beliebtes Gericht aus der Kerala-Region von Indien. Es ist schnell zubereiten und eine sehr leckere Begleitung zu einem Hauptgericht von Reis oder Roti.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Boiled_Cucumber_and_Grated_Coconut_(Pachadi)","i":"wb-en-1019","on":"Boiled Cucumber and Grated Coconut (Pachadi)","og":["1 cucumber (large variety, with dark green and yellow skin)","½ cup grated coconut","1 tsp cumin seeds (jeera)","1 tsp mustard seeds","1–2 dried red chillies","1 tbsp oil","Salt according to taste"],"mt":1},{"n":"Gekochte Eiercreme","c":"dessert","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["500 g Milch","2 Eier","55–110 g Zucker","1 TL Vanilleextrakt","1 Prise Salz (optional)","1 EL Speisestärke (optional)","2 EL Wasser (optional)"],"s":["Milch und Salz (bei Verwendung) in einem Doppelkessel erhitzen, bis sich Blasen um die Kanten bilden.","Eier mit Zucker bis zur Uniform schlagen.","Nach und nach etwa 1⁄2 Tasse (125 ml / 120 g) heiße Milch in die Ei-Mischung mischen, um sie zu temperieren.","Eigemisch langsam in die verbleibende heiße Milch rühren.","Optional Maisstärke und Wasser mischen und in Custard unterrühren.","Rühren Sie über Hitze bis verdickt (sollte den Löffel beschichten), ohne zum Kochen zu bringen.","Von der Hitze entfernen und weiterrühren, um die Custard leicht zu trocknen.","Vanille einrühren, bevor das Gericht vollständig abgekühlt ist.","Warm oder gekühlt servieren."],"x":["Vanilleextrakt durch Mandel- oder Ahornextrakt, Brandy oder geriebene Zitronenschale ersetzen.","Karamellkruste: 1⁄2 Tasse 110 g / 110 g) Zucker in einer kleinen Pfanne umrühren, bis es flüssig wird und gerade erst zu rauchen beginnt. Rühren Sie es in die heiße Milch vor dem Hinzufügen der Ei-Mischung."],"desc":"Gekochte Custard ist ein klassisches Dessert, mit einer leichten Textur und einem milden Geschmack. Dieses Rezept ist für \"gekochte\" Custard, aber ironischerweise, wie Mrs. == Einzelnachweise == Gillette sagte in The Whitehouse Cookbook, \"es darf nicht kochen oder es wird curdle.\" Siehe mehr über custard im Allgemeinen hier.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Boiled_Custard","i":"wb-en-1020","im":["7/77/Creme_anglaise_p1050164.jpg/960px-Creme_anglaise_p1050164.jpg","David Monniaux","CC BY-SA 3.0","Creme anglaise p1050164.jpg","w"],"on":"Boiled Custard","og":["2 cups (500 g / 1.1 pint) milk","2 eggs","¼–½ cup (55–110 g / 1.9–3.9 oz) white granulated sugar","1 teaspoon vanilla extract","1 pinch salt (optional)","1 tablespoon cornstarch (optional)","2 tablespoons water (optional)"],"mt":1},{"n":"Gekochte Ona (nigerianische gekochte Bitteryams)","c":"welt","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["Ona (Bitteryams)","Wasser","Salz, nach Geschmack"],"s":["Schneiden Sie den bitteren Yam in Stücke, und entfernen Sie die Haut.","Die Yamswurzeln abspülen, dann in einen Topf überführen und mit Wasser bedecken.","Schälen, ausspülen und Salz nach Geschmack zugeben.","Salz nach Geschmack hinzufügen und weich kochen.","Den bitteren Yam abtropfen lassen und mit Ei-Sauce, Palmöl oder Pfeffersauce servieren."],"x":[],"desc":"Ona, auch bekannt als Esuru in Yoruba Stamm und bittere Yam in Englisch ist ein typisches nigerianisches Essen, das häufig von Igbo-Leute verzehrt wird. Es wird mit Palmöl, Ei-Sauce oder Pfeffereintopf serviert.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Boiled_Ona_(Nigerian_Boiled_Bitter_Yam)","i":"wb-en-1021","on":"Boiled Ona (Nigerian Boiled Bitter Yam)","og":["Ona (bitter yam)","Water","Salt to taste"],"mt":1},{"n":"Gekochte Süßkartoffel","c":"veggie","k":"","p":4,"t":0,"d":1,"v":2,"l":"en","g":["Süßkartoffel, ungeschält und in Stücke geschnitten","Wasser","Salz"],"s":["Die Süßkartoffelstücke in einen Topf legen.","Die Süßkartoffel mit Wasser bedecken und eine Prise Salz dazugeben.","Zum Kochen bringen, dann köcheln, bis die Süßkartoffel zart ist.","Die Süßkartoffeln abtropfen lassen und die Haut abziehen.","Servieren Sie mit der Pfeffersauce Ihrer Wahl."],"x":[],"desc":"Gekochte Süßkartoffel ist ein typisches nigerianisches Essen, das im Vergleich zu Yam oder Cocoyam einen köstlichen Geschmack hat. Es enthält verschiedene Nährstoffe.","img":"Camote hervido (Peru).JPG","u":"https://en.wikibooks.org/wiki/Cookbook:Boiled_Sweet_Potato","i":"wb-en-1022","im":["7/71/Camote_hervido_%28Peru%29.JPG/960px-Camote_hervido_%28Peru%29.JPG","Dtarazona","CC BY-SA 3.0","Camote hervido (Peru).JPG","r"],"on":"Boiled Sweet Potato","og":["Sweet potato, unpeeled and cut into chunks","Water","Salt"],"mt":1},{"n":"Gekochte gelbe Schälerbsen","c":"beilagen","k":"","p":10,"t":120,"d":1,"v":1,"l":"en","g":["230 g getrocknete gelbe Schälerbsen (225 g bzw. 1¼ Tassen)","3–4 Tassen Trinkwasser (¾ bis 1 l) (Trinkqualität)","⅛ TL Natron, falls nötig (siehe Tipps)"],"s":["Wählen Sie Bohnen, dann heißes Wasser hinzufügen.","Zwei Minuten kochen.","Für 1 Stunde zur Seite stellen.","Abtropfen und abspülen.","Simmer bis zum Tender.","Wählen Sie Bohnen, dann kaltes Wasser hinzufügen.","Über Nacht einweichen, oder mindestens 6 Stunden.","Abtropfen und abspülen.","Simmer bis zum Tender."],"x":["Als Bohnen sind ein Naturprodukt, über Bohnen pflücken, wegwerfen Steine, Schmutzpartikel oder verfärbte Bohnen vor dem Einweichen oder Kochen.","Wenn Sie hartes Wasser in Ihrer Nähe haben, wird das Hinzufügen von 1⁄4 Teelöffel Backpulver die Kochzeit reduzieren.","Achten Sie darauf, dass das Wasser die Bohnen um mindestens 5 cm (5 Zentimeter) bedeckt, überprüfen Sie den Wasserstand jede kleine Weile, und lassen Sie nicht die oberen Bohnen über dem Wasser zu bekommen."],"desc":"Diese Hülsenfrüchte sind geschmacklich und gesund, aber benötigen einweichen.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Boiled_Yellow_Split_Peas","i":"wb-en-1023","on":"Boiled Yellow Split Peas","og":["½ pound (225 grams / 1¼ cups) dry yellow split peas","3–4 cups (¾–1 liter) potable (drinking) water","⅛ teaspoon baking soda, if needed (see tips)"],"mt":1},{"n":"Boilo (heißer Zitrus-Whiskey mit Gewürzen)","c":"getraenke","k":"","p":12,"t":0,"d":1,"v":1,"l":"en","g":["2 mittelgroße bis große Orangen","2 Zitronen","1 kleine Schachtel Rosinen (40 g)","220 g Honig","355 ml Whiskey oder mehr, nach Geschmack","½–1 TL je beliebige oder alle dieser Gewürze: Zimt, Muskatnuss, Zehen, Kümmel, Anis"],"s":["Orangen und Zitronen schälen. Schneiden Sie die Früchte auf und drücken Sie sie in einen Topf. Eine Knoblauchpresse oder Kartoffel-Recherche arbeitet, oder irgendeine Art von Saftpresse oder Fruchtpresse. Das restliche Fruchtfleisch auch in den Topf geben.","Rosinen, Honig und Gewürze dazugeben. Rühren. Whiskey noch nicht dazugeben!","Starten Sie den Crock Pot und lassen Sie die Mischung ca. 2–4 Stunden kochen. Gelegentlich umrühren. Es ist komplett, wenn das Fruchtfleisch gegart wird.","Ziehen Sie sich in einen Krug. Zerdrücken Sie die Frucht im Sieb, um die gesamte Flüssigkeit zu erhalten.","Den Whiskey in den Krug geben und umrühren. Wenn Sie den Whiskey kochen, auch für kurze Zeit, beginnt der Alkohol zu verdampfen. Geschmack, und fügen Sie mehr Whiskey nach Ihren Wünschen.","Servieren Sie heiß in Schuss Gläser, Espresso Tassen oder Kaffeebecher. Nach der ersten Runde kann jede einzelne Portion in der Mikrowelle aufgewärmt werden."],"x":["Verwenden Sie einen Whisky, der mindestens 80 Beweis (40% Alkohol) ist."],"desc":"Boilo ist ein traditionelles Yuletide-Getränk aus den nordöstlichen Vereinigten Staaten, insbesondere Pennsylvania. Es ist eine Art Whisky-Likör aus Orangen, Zitronen, Zucker und verschiedenen Gewürzen wie Zimt. Rezepte variieren und können Muskatnuss, Nelken, Kümmelsamen und Anis enthalten.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Boilo_(Hot_Spiced_Citrus_Whiskey)","i":"wb-en-1024","on":"Boilo (Hot Spiced Citrus Whiskey)","og":["2 medium-large oranges","2 lemons","1 small box (about 1½ oz / 40 g) raisins","8 oz (220 g) honey","12 oz (355 ml) whiskey or more to taste","½–1 teaspoon each of any or all of these spices: cinnamon, nutmeg, cloves, caraway seed, aniseed"],"mt":1},{"n":"Boliche (kubanischer Braten mit Chorizofüllung)","c":"fleisch","k":"Kuba","p":6,"t":0,"d":2,"v":0,"l":"en","g":["1,35 kg Rinderbraten aus der Unterschale","4 Chorizo (Goya), längs geviertelt","2 EL Adobo-Gewürz (Goya)","2 kräftige Prisen Safran","6 Zehen Knoblauch, fein gehackt","1 große Zwiebel, gehackt","1 große grüne Paprika","3 Lorbeerblätter","1–2 gehäufter EL Oregano","3 EL grüne spanische Oliven mit Paprikafüllung","3 EL Kapern","2 Packungen Sazón-Gewürz mit Safran (Goya)","1 Tasse Rotwein","1 Dose Tomatensoße (820 g)","¼ Tasse Olivenöl","1 Packung Badia-Koriander"],"s":["Schneide Schlitze in Augen runden Braten, und Zeug mit geviertelten Chorizos (folgen Sie dem Getreide des Fleisches).","Fleisch leicht mit Adobo würzen reiben.","Das Fleisch auf allen Seiten in einer Pfanne anbraten, um die Säfte zu versiegeln. Entfernen und in eine große, überdachte Bratpfanne legen.","In der gleichen Pfanne wie das Rindfleisch gebräunt wurde, fügen Safran, Knoblauch, Zwiebeln, Paprika, Lorbeerblätter, Oregano, Oliven, Kapern und die Sazon Würze. Sauté, bis die Zwiebeln durchscheinend sind.","Mit Rotwein deglasieren, abwärmen und ca. 5 Minuten köcheln lassen. Den Koriander und die Tomatensauce dazugeben und gut umrühren.","Gießen Sie diese Mischung über das Rindfleisch und braten bei 165 °C für 1 1⁄2-2 Stunden, oder bis Fleisch zart ist. Drehen Sie den Braten um und basteln Sie mit der Sauce einmal in eine Weile, um volle Geschmack Penetration und sogar Kochen zu gewährleisten.","Servieren."],"x":[],"desc":"Boliche (ausgesprochen Bow-lee-Chay) ist ein beliebtes kubanisches Gericht, bestehend aus Augen runden Braten gefüllt mit Chorizo Würstchen in einer Tomatensoße getaucht.","img":"Boliche.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Boliche_(Cuban_Chorizo-Stuffed_Roast)","i":"wb-en-1025","im":["a/a6/Boliche.jpg/960px-Boliche.jpg","Averette at English Wikipedia","Public domain","Boliche.jpg","r"],"on":"Boliche (Cuban Chorizo-Stuffed Roast)","og":["3–5 lb beef eye round roast","4 Goya chorizos, quartered lengthwise","2 tbsp Goya adobo seasoning","2 large pinches saffron","6 cloves garlic, minced","1 large onion, chopped","1 large green bell pepper","3 bay leaves","1–2 heaping tbsp oregano","3 tbsp green Spanish olives with pimentos","3 tbsp capers","2 packets Goya sazon con azafran","1 cup red wine","1 can (29 oz) tomato sauce","¼ cup olive oil","1 package Badia cilantro"],"mt":1},{"n":"Bolinhos de mandioca com mel (Maniokbällchen mit Honig)","c":"fisch","k":"Afrika","p":4,"t":0,"d":2,"v":0,"l":"en","g":["500 g Maniok (Maniok), geschält und gerieben","2 Eier","3 EL Zucker","1 TL Vanilleextrakt","½ TL gemahlener Zimt","¼ TL Salz","Pflanzenöl, zum Braten","4 EL Honig, zum Servieren"],"s":["Den geriebenen Kassava in eine große Schüssel geben.","Eier, Zucker, Vanilleextrakt, Zimt und Salz dazugeben.","Mischen Sie gründlich, bis sich ein einheitlicher Teig bildet.","Öl in einer tiefen Pfanne bei mittlerer Hitze erhitzen.","Scoop kleine Portionen der Mischung und legen Sie sie vorsichtig in das heiße Öl.","An allen Seiten bis goldbraun braten, ca. 3–4 Minuten.","Mit einem Schlitzlöffel entfernen und auf Papiertücher abtropfen lassen.","Die Fritter auf einer Servierplatte anordnen.","Vor dem Servieren großzügig mit Honig beträufeln."],"x":["Ein Nachmittagssnack","Ein Frühstück mit Tee oder Kaffee","Den Teig mit geriebener Kokosnuss füllen.","Honig durch Ahornsirup oder Fruchtsirup ersetzen.","Vor dem Servieren mit Puderzucker bestreuen.","Frischer Kassava sollte für die beste Textur verwendet werden."],"desc":"Bolinhos de Mandioca com Mel (Cassava Fritters with Honey) ist ein süßer Snack aus geriebenem Kassava, geformt in kleine Kuchen und bis golden gebraten. Die Fritters werden traditionell warm serviert und mit Honig beträufelt. Dieses Gericht wird häufig mit der Küche von Kap Verde, einem Inselland assoziiert","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bolinhos_de_mandioca_com_mel","i":"wb-en-1026","on":"Bolinhos de mandioca com mel","og":["500 g cassava (mandioca), peeled and grated","2 eggs","3 tbsp sugar","1 tsp vanilla extract","½ tsp ground cinnamon","¼ tsp salt","Vegetable oil, for frying","4 tbsp honey, for serving"],"mt":1},{"n":"Bolognese","c":"saucen","k":"USA","p":4,"t":105,"d":1,"v":0,"l":"en","g":["675 g mageres Rinderhack, zimmerwarm","2 Eiweiß von großen Eiern, zimmerwarm","1 Dose geschmorte San-Marzano- oder Romatomaten (800 g) (italienisch)","1 Dose Tomatenmark (170 g)","6 Zehen Knoblauch, geschält","2 EL Olivenöl","Lorbeerblatt","Oregano"],"s":["Mit Öl und Knoblauch einen dicken Topf auf eine mittelniedrige Hitze geben.","Während sich der Topf erwärmt, mischen Sie Rindfleisch und Eiweiß zu einer homogenen Paste.","Die Knoblauchzehen in das wärmende Öl einrühren, bis der Duft bemerkt werden kann.","Fügen Sie das Fleisch in den Topf, Rühren, um Cluster in feine Stücke brechen, und kochen, bis die meisten Säfte verdunstet haben.","Fügen Sie die Tomatenpaste hinzu und rühren Sie vor dem Hinzufügen der geschmorten Tomaten.","Den Topf bedecken, einen Entlüftungsschlitz hinterlassen und 1 Stunde lang bei niedriger Hitze köcheln lassen, alle 15 Minuten umrühren.","Schalten Sie die Hitze ab und holen Sie die Knoblauchzehen, entweder wegwerfen oder maische sie vor dem erneuten Hinzufügen der Soße.","Nach Geschmack abschmecken, unter Berücksichtigung des Salzgehalts der Tomatenprodukte.","Komplett bedecken und eine halbe Stunde ruhen lassen, während derer die Vorbereitung auf Montage und Beschichtung erfolgen kann."],"x":[],"desc":"Bolognese-Sauce, nicht zu verwechseln mit ragù alla bolognese, ist die Tomaten-basierte Fleischsauce, die in der Regel begleitet bestimmte Pasta, wie Spaghetti und Rigatoni, und verwendet, um Lasagne in Restaurants, in Nordamerika.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bolognese_Sauce","i":"wb-en-1027","im":["4/4d/Tagliatelle_al_rag%C3%B9_%28image_modified%29.jpg/960px-Tagliatelle_al_rag%C3%B9_%28image_modified%29.jpg","Ivan Vighetto","CC BY-SA 3.0","Tagliatelle al ragù (image modified).jpg","w"],"on":"Bolognese Sauce","og":["1.5 lb (675 g) of lean ground beef, at room temperature","2 large egg whites, at room temperature","1 can (28 oz / 800 g) of stewed San Marzano or Roma (Italian) tomatoes","1 can (6 oz / 170 g) tomato paste","6 cloves of garlic, peeled","2 Tbsp olive oil","Bay leaf","Oregano"],"mt":1},{"n":"Bonda (südindische Gemüseküchlein)","c":"snacks","k":"Indien","p":4,"t":0,"d":2,"v":2,"l":"en","g":["#Füllung","2 mittelgroße Kartoffeln","1 mittelgroße Zwiebeln","3–4 mittelgroße grüne Chilis","2 EL, fein gehackte Korianderblätter","1 TL fein gehackter Ingwer","1 TL fein gehackter Knoblauch","Salz, nach Geschmack","#Teig","4 Portionen Kichererbsenmehl (Besan, Kichererbsenmehl)","1 Portion Reismehl","½ TL Natron","Salz, nach Geschmack","Wasser oder Bier","#Sonstiges","Öl zum Braten"],"s":["Kartoffeln kochen, die Haut entfernen und grob zerkleinern.","2 EL Öl in einer Pfanne erhitzen. Wenn das Öl heiß ist, werfen Sie grüne Chilis und braten für ein paar Sekunden.","Zwiebeln hinzufügen und braten, bis sie gebräunt sind.","Ingwer und Knoblauch dazugeben und eine Minute braten.","Die gehackten Korianderblätter und Kartoffelpüree dazugeben und gut falten.","Erlauben Sie es zu kühlen und Form in kleinen Golfball-Bälle.","Das Grammmehl und das Reismehl mit Backpulver vermischen. Salz nach Geschmack hinzufügen.","Fügen Sie genug Wasser oder Bier, um einen glatten Teig zu machen. Die Teigkonsistenz sollte etwas dicker sein als Ketchup.","Sobald der Teig und die Füllung fertig sind, etwas Öl in einer tiefen Pfanne erhitzen. Das Öl sollte mindestens 11⁄2 Zoll (4 cm) tief für das Frittieren sein.","Tauchen Sie die Füllkugeln in den Teig, um sicherzustellen, dass sie vollständig beschichtet sind, und fallen in das heiße Öl. Überfüllt die Pfanne nicht.","Die Bonda bis golden braten, dann aus dem Öl entfernen.","Mit Ketchup oder Chutney servieren."],"x":[],"desc":"Bonda ist ein typischer südindischer Snack. Der Prozess der Herstellung Bonda beinhaltet tiefe Braten eine Füllung von Kartoffeln (oder andere Gemüse) in Gramm Mehl Teig getaucht.","img":"Bonda2.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Bonda_(South_Indian_Vegetable_Fritter)","i":"wb-en-1028","im":["3/3e/Bonda2.jpg/960px-Bonda2.jpg","No machine-readable author provided. Pamri assumed (based on","Public domain","Bonda2.jpg","r"],"on":"Bonda (South Indian Vegetable Fritter)","og":["#Filling","2 medium-sized potatoes","1 medium-sized onions","3–4 medium-sized green chiles","2 tbsp, finely-chopped coriander leaves","1 tsp finely-chopped ginger","1 tsp finely-chopped Garlic","Salt to taste","#Batter","4 portions gram flour (besan)","1 portion rice flour","½ tsp baking soda","Salt to taste","Water or beer","#Other","Oil for frying"],"mt":1},{"n":"Bonga Fish Domoda (gambischer Fisch in Erdnusssoße)","c":"saucen","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["2 EL Pflanzenöl","2 mittelgroße Zwiebeln, fein gehackt","3 Knoblauchzehen, fein gehackt","2 Tomaten, gewürfelt","2 EL Tomatenmark","1 Tasse Erdnussbutter","1 EL Paprikapulver","1 TL gemahlener Cayennepfeffer (je nach gewünschter Schärfe anpassen)","Salz, nach Geschmack","Pfeffer, nach Geschmack","4 Tassen Wasser","910 g Bongafischfilets","frische Petersilie oder Koriander, gehackt (zum Garnieren)"],"s":["Das Pflanzenöl in einem großen Topf bei mittlerer Hitze erhitzen.","Zwiebeln und Knoblauch in den Topf geben und anbraten, bis sie durchscheinend werden.","In die gewürfelten Tomaten und Tomatenpaste einrühren, für einige Minuten kochen, bis die Tomaten weich werden.","Erdnussbutter, gemahlene Paprika, Cayennepfeffer, Salz und Pfeffer in den Topf geben. Rühren Sie gut, um alle Zutaten zu kombinieren.","Gießen Sie langsam in das Wasser unter ständigem Rühren der Mischung, um sicherzustellen, dass die Erdnussbutter gut eingearbeitet ist.","Bringen Sie die Soße zu einem Schimmer und lassen Sie sie für etwa 15-20 Minuten kochen, so dass die Aromen zusammen verschmelzen.","Legen Sie die Bonga Fischfilets vorsichtig in die köchelnde Soße, um sicherzustellen, dass sie vollständig untergetaucht sind. Für weitere 10-15 Minuten kochen oder bis der Fisch vollständig gekocht ist und leicht flocken.","Die Sauce schmecken und die Würze bei Bedarf anpassen.","Den Topf aus der Hitze nehmen und vor dem Servieren etwas abkühlen lassen.","Mit frisch gehackter Petersilie oder Koriander garnieren.","Die Bonga Fisch Domoda heiß mit Reis oder Couscous servieren."],"x":["Bonga Fisch Domoda kann durch das Hinzufügen von Gemüse wie Karotten, Kartoffeln oder Paprika für zusätzlichen Geschmack und Textur angepasst werden."],"desc":"Bonga Fisch Domoda ist ein beliebtes Gambian Gericht, das Bonga Fisch in einer reichen Erdnuss-Sauce gekocht verfügt. Es ist ein würziger und herzhafter Eintopf, der in Gambia genossen wird und oft mit Reis oder Couscous serviert wird.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bonga_Fish_Domoda_(Gambian_Fish_in_Peanut_Sauce)","i":"wb-en-1029","im":["a/a1/Pecel_Solo.JPG/960px-Pecel_Solo.JPG","Gunawan Kartapranata","CC BY-SA 3.0","Pecel Solo.JPG","w"],"on":"Bonga Fish Domoda (Gambian Fish in Peanut Sauce)","og":["2 tablespoons vegetable oil","2 medium onions, finely chopped","3 garlic cloves, minced","2 tomatoes, diced","2 tablespoons tomato paste","1 cup peanut butter","1 tablespoon ground paprika","1 teaspoon ground cayenne pepper (adjust according to your spice preference)","Salt to taste","Pepper to taste","4 cups water","2 pounds bonga fish fillets","Fresh parsley or cilantro, chopped (for garnish)"],"mt":1},{"n":"Booyah (Hähnchen-Gemüse-Eintopf)","c":"suppen","k":"Belgien","p":16,"t":180,"d":1,"v":0,"l":"en","g":["1 großes Brathähnchen","2 Tassen grüne Bohnen","450 g gewürfelte Möhre","2 Tassen Erbsen","1 Tasse gewürfelter Kohl","4 Stangen Staudensellerie","2 Tassen Tomatensoße (oder 1 l ganze Tomaten)","1 große Zwiebel, gewürfelt","2 Tassen geschälte, gewürfelte Kartoffeln (optional)","Salz, nach Geschmack"],"s":["Hühner in einen großen Topf legen und mit Wasser bedecken. Simmer, bis Huhn gut gemacht ist.","Hähnchen aus der Brühe nehmen und Fett abschöpfen.","Die restlichen Zutaten in die Brühe geben.","Hühnerfleisch aus Knochen und Haut entfernen. Fleisch in kleine Stücke schneiden und zur Brühe geben. Salz und Wasser nach Geschmack hinzufügen.","Überdecken und mindestens 3 Stunden köcheln lassen. Es schmeckt am besten, wenn gekocht den ganzen Tag."],"x":[],"desc":"Booyah ist ein Eintopf, der im Nordosten von Wisconsin von wallonisch-belgischen Einwanderern (insbesondere in der Green Bay) gegründet wurde. Der Name wird vermutlich vom französischen Wort Bouillir abgeleitet, was \"kochen\" bedeutet. Der Eintopf wird manchmal in riesigen Stahlkesseln erzeugt und mit Bootspaddeln bei Dingen gerührt lik","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Booyah_(Chicken_Vegetable_Stew)","i":"wb-en-1030","im":["e/e6/Lamb-stew.jpg/960px-Lamb-stew.jpg","FiveRings ( talk )","CC BY 3.0","Lamb-stew.jpg","w"],"on":"Booyah (Chicken Vegetable Stew)","og":["1 large roasting chicken","2 cups green beans","3 cups (1 pound) diced carrot","2 cups peas","1 cup diced cabbage","4 stalks celery","2 cups tomato sauce (or 1 quart whole tomatoes)","1 large onion, diced","2 cups peeled and diced potatoes (optional)","Salt to taste"],"mt":1},{"n":"Borhani (gewürztes Joghurtgetränk)","c":"getraenke","k":"Indien","p":6,"t":0,"d":1,"v":1,"l":"en","g":["3 TL Kreuzkümmelsamen","500 ml Vollmilch-Naturjoghurt","200 ml kaltes Wasser","½ TL frische grüne Chilischoten","½ TL Minze","½ TL Koriander","¾ TL weiße Senfsamen","¾ TL gemahlener weißer Pfeffer","½ TL gemahlener schwarzer Pfeffer","3 TL Zucker","½ TL Steinsalz","½ TL Salz"],"s":["Trockenbraten Kümmelsamen durch Kochen sie bei geringer Hitze in kleinen Pfanne, bis Sie die Würze riechen können, ca. 2 Minuten. Kühlen und zu einem Pulver mahlen.","Joghurt mit Wasser schlagen, bis es glatt wird. Grüne Chili-, Minze-, Blatt- und Korianderpasten mit etwas Wasser in den Joghurt einrühren. Kombinieren Sie alle anderen Zutaten und gut mischen.","Diene kalt."],"x":[],"desc":"Borhani sind Getränke auf Joghurtbasis, die in Bangladesch beliebt sind. Es wird traditionell in Hochzeitszeremonien im ganzen Land serviert.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Borhani_(Spiced_Yogurt_Drink)","i":"wb-en-1031","im":["f/f2/A_Glass_of_Borhani.jpg/960px-A_Glass_of_Borhani.jpg","DarkSpartan","CC BY-SA 4.0","A Glass of Borhani.jpg","w"],"on":"Borhani (Spiced Yogurt Drink)","og":["3 tsp cumin seeds","500 mL (2 cups) full-fat plain yoghurt","1 cup (200 mL) cold water","½ tsp fresh green chile peppers","½ tsp mint","½ tsp coriander","¾ tsp white mustard seeds","¾ tsp ground white pepper","½ tsp ground black pepper","3 tsp sugar","½ tsp rock salt","½ tsp salt"],"mt":1},{"n":"Borschtsch","c":"suppen","k":"Ukraine","p":6,"t":75,"d":2,"v":1,"l":"en","g":["#Suppe","1 ½ Tassen Kartoffeln in dünnen Scheiben (etwa 3 kleine Kartoffeln)","1 Tasse Rote Bete in dünnen Scheiben","4 Tassen Wasser","1–2 EL Butter","1 ½ Tassen gehackte Zwiebel (etwa ⅓ große Zwiebel)","1 ½ TL Salz","1 Stange Staudensellerie, gehackt","1 mittelgroße Möhre, gehackt","3–4 Tassen geraspelter Kohl (etwa ⅓ großer Kohlkopf)","etwas frisch gemahlener schwarzer Pfeffer","1 TL Dillspitzen","1–2 EL Apfelessig","1–2 EL brauner Zucker oder Honig","1 Tasse passierte Tomaten oder ¼ bis ½ Tasse Tomatenmark","#Garnitur","saure Sahne oder Joghurt","Dillspitzen"],"s":["Kartoffeln, Rüben und Wasser in einen mittelgroßen Topf geben. Überdecken und bei mittlerer Hitze bis zart (20–30 Minuten) kochen. Während das Kochen ist, gehen Sie mit dem Rezept.","Die Butter in einem holländischen Ofen/Suppentopf schmelzen. Zwiebel und Salz dazugeben. Bei mittlerer Hitze bei gelegentlichem Rühren kochen, bis die Zwiebeln durchscheinend (8-10 Minuten) sind.","Sellerie, Karotten, Kohl und 2 Tassen Wasser hinzufügen, in denen Kartoffeln und Rüben kochen. Überdecken und bei mittlerer Hitze kochen, bis das Gemüse zart ist (8–10 Minuten).","Fügen Sie die restlichen Suppe Zutaten (einschließlich der Kartoffeln, Rüben und den Rest des Wassers, in dem sie kochen). Bedecken und mindestens 15 Minuten köcheln lassen. Korrigieren Sie die Gewürze.","Wenn es zu dünn ist, lassen Sie es aufgedeckt köcheln und fügen Sie vielleicht ein wenig mehr Tomatenpaste hinzu.","Heiß servieren, mit saurer Sahne oder Joghurt gekrönt und mit Dill bestreut. Auf Wunsch kann die saure Sahne oder Joghurt mit der Suppe serviert und als Würzmittel zum Geschmack verwendet werden."],"x":["Eine saure Umgebung ist für den authentischen Geschmack und die Erhaltung der roten Farbe, aber übermäßige Menge an Essigsäure aus dem Essig (esp. Destilliert) verursacht einen scharfen Restaurantgeruch und Geschmack. Der Apfelessig kann durch Sauerkraut oder extra Tomaten ersetzt werden.","Ukrainische Kohlsuppe (Kapusniak)","Montreal Russisch Borscht"],"desc":"Borscht oder Borschtsch ist eine herzhafte Rote Rübensuppe, die aus der Ukraine stammt. Die Suppe ist Teil des lokalen kulinarischen Erbes vieler ost- und mitteleuropäischer Nationen. Es ist auch ein Hauptgericht in Osteuropa, und machte seinen Weg in die amerikanische Küche durch jüdische Einwanderer (wie w","img":"Borscht.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Borscht","i":"wb-en-1032","im":["5/50/Borscht.jpg/960px-Borscht.jpg","No machine-readable author provided. Karmosin~commonswiki as","CC BY-SA 3.0","Borscht.jpg","r"],"on":"Borscht","og":["#Soup","1½ cups thinly-sliced potatoes (about 3 small potatoes)","1 cup thinly-sliced beets.","4 cups water","1–2 tablespoons butter","1½ cups chopped onion (about ⅓ of a large onion)","1½ teaspoons salt","1 stalk celery, chopped","1 medium carrot, chopped","3–4 cups shredded cabbage (about ⅓ of a large cabbage)","a little fresh-ground black pepper","1 teaspoon dill weed","1–2 tablespoons cider vinegar","1–2 tablespoons brown sugar or honey","1 cup tomato purée or ¼ to ½ cup tomato paste","#Garnish","Sour cream or yogurt","Dill weed"],"mt":1},{"n":"Boston Baked Beans","c":"beilagen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["6 dicke Scheiben Speck, in Scheiben geschnitten (oder 5 Tropfen Flüssigrauch)","4 Tassen Kidneybohnen aus der Dose, abgespült und abgetropft","½ Tasse Melasse","¼ Tasse Melasse, plus mehr nach Bedarf","¼ Tasse dunkler brauner Zucker","2 EL dunkler Rum","½ TL Salz","½ TL schwarzer Pfeffer","1 EL Senfpulver"],"s":["Speck kochen. Das Fleisch vom Fett trennen und den Speck hacken.","1 EL Speckfett in eine große Edelstahlpfanne geben. Nierenbohnen hinzufügen und bei mittlerer Hitze anbraten.","Rum hinzufügen und zum Entzünden neigen. Wenn Sie keinen Gasherd haben, einfach mit einem Feuerstab anzünden.","Restliche Zutaten und gehackten Speck hinzufügen und zusammenfalten.","1 1⁄2 Stunden in einem 165 °C Ofen backen, gelegentlich mit Blackstrap Melasse, um das Trocknen zu verhindern."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Boston_Baked_Beans","i":"wb-en-1033","im":["f/f9/Boston_Baked_Beans_in_Concord%2C_Mass_2012-0193.jpg/960px-Boston_Baked_Beans_in_Concord%2C_Mass_2012-0193.jpg","Victorgrigas","CC BY-SA 3.0","Boston Baked Beans in Concord, Mass 2012-0193.jpg","w"],"og":["6 rashers thick cut bacon, sliced (or 5 drops liquid smoke)","4 cups canned kidney beans, rinsed and drained","½ cup molasses","¼ cup blackstrap molasses, plus more as needed","¼ cup dark brown sugar","2 tbsp dark rum","½ tsp salt","½ tsp black pepper","1 tbsp dry mustard"],"mt":1},{"n":"Bouballe (gesüßtes Matzemehl-Omelett)","c":"veggie","k":"Jüdische Küche","p":4,"t":0,"d":1,"v":1,"l":"en","g":["1 EL Matzemehl","2 Eier","1 EL Speisestärke","Zucker"],"s":["Das Eiweiß rühren.","Fügen Sie das Eigelb, dann die Matzo-Mahlzeit und Maisstärke. Alles miteinander vermischen.","Die Mischung wie ein Omelett kochen.","Nach dem Kochen mit Zucker bestreuen und servieren."],"x":["Vor dem Bestreuen des Zuckers in kleine Quadrate schneiden, so dass es mit den Fingern gegessen werden kann.","Passt gut mit Ahornsirup"],"desc":"Bouballe ist ein jüdisches Gericht, das traditionell zum Passah gegessen wird. Es ist eine Art gesüßtes Omelett, gebunden mit Matzomehl und Stärke.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bouballe_(Sweetened_Matzo_Meal_Omelette)","i":"wb-en-1034","on":"Bouballe (Sweetened Matzo Meal Omelette)","og":["1 tbsp matzo meal","2 eggs","1 tbsp cornstarch","Sugar"],"mt":1},{"n":"Bouchée à la Reine (Königinpastete)","c":"brot","k":"Frankreich","p":2,"t":0,"d":2,"v":0,"l":"en","g":["4 Blätterteigpasteten","1 Schalotte, gehackt","2 große Hähnchen- oder Putenbrüste","115 g kleine oder mittelgroße Champignons","55 g Butter","2 EL Mehl","1 Eigelb","1 Tasse Crème fraîche (oder Sahne)","1 Bouquet garni","340 g Hühnerfond","Pfeffer"],"s":["Legen Sie die Hühnerbrühe und das Bouquet garni in einen Topf. Zum Kochen bringen und 10–11 Minuten einkochen lassen","Die Hühnerbrust in kleine Würfel schneiden.","Die Pilze schnell waschen und je nach Größe in Hälften oder Viertel schneiden.","In einer Sauteuse (oder einer Bratpfanne) die Butter auf mittlerer Hitze schmelzen und die gehackte Schalotte dazugeben. Für ca. 1 Minute Rühren kochen.","Mehl dazugeben und 1 zierliche Minute kochen, mit einem Schneebesen oder einem Holzlöffel ohne Bräunung vermischen.","Nach und nach die Hühnerbrühe dazugeben und 2 Minuten mit Rühren kochen.","Fügen Sie das gewürfelte Huhn und die Pilze und kochen für 5-6 Minuten, Rühren von Zeit zu Zeit.","Den Ofen auf 175 °C (Gaszeichen 6) vorheizen und die Vol-Auventschalen 5–10 Minuten oder wie vom Hersteller angeordnet backen, ohne sie zu verbrennen.","In einer Schüssel die Sahne mit dem Eigelb vermischen. Erhöhen Sie die Hitze unter der Sauteuse und fügen Sie das Eigelb / Sahne Mischung, schlagen gut mit der Soße zu kombinieren und senken Sie die Hitze, sobald es ein Kochen erreicht. Die Soße sollte offen sein und einen Löffel beschichten.","Nicht salzen, nur Pfeffer.","Die Vol-au-Erfinder aus dem Ofen nehmen. Schnell füllen und ohne Verzögerung dienen, wie sie schnell abkühlen."],"x":["Dieses Gericht ist manchmal mit vol-au-vent finocière verwechselt, aber das letztere ist ganz anders mit quenelles, Cockscombs, Hähne, Nieren, Trüffelscheiben, geriffelt Pilzmützen und schwarzen Oliven gebunden mit einer Madeira-Sauce."],"desc":"Bouchée à la Reine ist nach Marguerite de Valois, der Ehefrau von Henri IV. Dieser Entrée wurde etwas vernachlässigt, ist aber einer der großen Klassiker der französischen Gastronomie. Es wird in der Regel als Entrée (Einführungskurs) serviert, kann aber auch als Plat Principal (Hauptkurs) für ein Abendessen serviert werden,","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bouchée_à_la_Reine","i":"wb-en-1035","im":["2/28/Bouch%C3%A9e_%C3%A0_la_Reine.JPG/960px-Bouch%C3%A9e_%C3%A0_la_Reine.JPG","Arnaud 25","CC BY-SA 4.0","Bouchée à la Reine.JPG","c"],"on":"Bouchée à la Reine","og":["4 vol-au-vent shells","1 shallot, chopped","2 large chicken or turkey breasts","4 oz small or medium button mushrooms","2 oz butter","2 Tbsp flour","1 egg yolk","1 cup crème fraîche (or heavy cream)","1 bouquet garni","12 oz chicken stock","Pepper"],"mt":1},{"n":"Bouillabaisse","c":"suppen","k":"Frankreich","p":8,"t":60,"d":1,"v":0,"l":"en","g":["#Brühe","660 g ganzer ausgenommener Knurrhahn","660 g ganzer ausgenommener Drachenkopf","660 g ganzer ausgenommener Roter Knurrhahn","660 g ganzer ausgenommener Meeraal","660 g ganzer ausgenommener Seeteufel, oder Seeteufel","660 g ganzer ausgenommener Petersfisch","1 lebender Oktopus (optional), geputzt und in Stücke geschnitten","10 Seeigel","1 kg Kartoffeln, geschält und in große Scheiben geschnitten","7 Zehen Knoblauch","3 Zwiebeln, in Scheiben geschnitten","5 reife Tomaten, geschält, geviertelt und ohne Kerne","1 Tasse Olivenöl","1 Bouquet garni","1 Fenchelzweig","8 Safranfäden","10 Scheiben Bauernbrot","Salz","Cayennepfeffer","#Rouille","1 Eigelb","2 Zehen Knoblauch","1 Tasse Olivenöl","10 Safranfäden","Salz","Cayennepfeffer"],"s":["Skalieren Sie die Fische und waschen Sie sie, wenn möglich, im Meerwasser. Schneiden Sie sie in große Scheiben, so dass die Knochen.","Das Olivenöl in einem großen, tiefen Topf erwärmen.","Fügen Sie die Zwiebeln, zusammen mit 6 Nelken zerkleinerten Knoblauch, Oktopus Stücke und Tomaten. Bei niedriger Hitze 5 Minuten lang sanft drehen.","Die Fischscheiben hinzufügen; Zuerst die großen Scheiben dann die kleineren. Mit kochendem Wasser bedecken und Salz, Pfeffer, Fenchel, das Bouquet garni und Safran dazugeben. Bei geringer Hitze köcheln, von Zeit zu Zeit rühren, damit die Fische nicht an der Pfanne bleiben.","Korrigieren Sie die Würze. Entfernen Sie die Bouillabaise aus der Hitze, sobald das Öl und Wasser gründlich mit den anderen Zutaten vermischt sind. Das sollte etwa zwanzig Minuten dauern.","Bereiten Sie die Rouille vor: Verwenden Sie einen Mörtel, um die Knoblauchzehen nach dem Entfernen der Stiele in eine feine Paste zu zerkleinern. Das Eigelb und den Safran dazugeben, dann nach und nach in das Olivenöl mischen, um eine Mayonnaise zu machen und mit dem Pestel zu rühren.","Die Kartoffeln 15 bis 20 Minuten in Salzwasser kochen. Die Seeigel mit einer Schere öffnen und den Reh mit einem kleinen Löffel entfernen.","Ordnen Sie die Fische auf einer Platte an. Den Seeigel in die Brühe geben und umrühren.","Reiben Sie mehrere Scheiben Brot mit Knoblauch und verteilen Sie einen Esslöffel Rouille auf jedem. Legen Sie mindestens zwei Scheiben pro Servierschüssel.","Die Fische und Kartoffeln aus der Brühe nehmen und auf eine große Servierplatte legen.","Die heiße Brühe in jede Schüssel geben, die eine Scheibe Brot enthält, das in Rouille erstickt wird. Dann servieren Sie den Fisch und die Kartoffeln auf einer separaten Platte."],"x":["Die Suche nach allen oben aufgeführten Fischarten kann schwierig sein. Wenn ja, ersetzen Sie eine Kombination von vier von fünf Arten mit festem, weißem Fleisch.","Servieren Sie dieses Gericht ohne Rouille, um das Fett und Cholesterin in diesem Gericht zu reduzieren."],"desc":"Bouillabaisse ist ein traditioneller Fischeintopf aus der Hafenstadt Marseille. Es wird durch das Kochen mehrerer Fischarten mit Kräutern und Gemüse hergestellt. Die Brühe wird dann als Suppe über Brot mit Rouille (eine würzige französische Mayonnaise) gewürzt mit dem Fisch und Gemüse serviert serviert","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bouillabaisse","i":"wb-en-1036","im":["2/24/Bullabessa.jpg/500px-Bullabessa.jpg","Slastic","CC BY 3.0","Bullabessa.jpg","w"],"og":["#Broth","660 g whole cleaned sea robin","660 g whole cleaned scorpionfish","660 g whole cleaned red gurnard","660 g whole cleaned conger","660 g whole cleaned lotte, or monkfish","660 g whole cleaned John Dory","1 live octopus (optional), cleaned and cut into pieces","10 sea urchins","1 kg of potatoes, peeled and cut into large slices","7 cloves of garlic","3 onions, sliced","5 ripe tomatoes, peeled, quartered and without seeds","1 cup of olive oil","1 bouquet garni","1 branch of fennel","8 threads of saffron","10 slices of country bread","Salt","Cayenne pepper","#Rouille","1 egg yolk","2 cloves of garlic","1 cup of olive oil","10 threads of saffron","Salt","Cayenne pepper"],"mt":1},{"n":"Boule-Di (senegalesischer Fisch mit Reis)","c":"fisch","k":"Senegal","p":4,"t":0,"d":2,"v":0,"l":"en","g":["910 g festfleischige weiße Fischfilets (z. B. Kabeljau oder Tilapia)","2 EL Pflanzenöl","1 große Zwiebel, fein gehackt","4 Knoblauchzehen, fein gehackt","1 Dose gewürfelte Tomaten (400 g)","1 rote Paprika, gewürfelt","1 grüne Paprika, gewürfelt","2 Möhren, gewürfelt","1 Tasse TK-Okra, in Scheiben geschnitten","1 EL Tomatenmark","1 TL Paprikapulver","1 TL gemahlener Cayennepfeffer (auf die gewünschte Schärfe anpassen)","1 TL gemahlener schwarzer Pfeffer","1 TL getrockneter Thymian","Salz, nach Geschmack","2 Tassen Langkornreis","4 Tassen Fisch- oder Gemüsebrühe","gehackte frische Petersilie oder Koriander (zum Garnieren)"],"s":["Die Fischfilets unter kaltem Wasser abspülen und mit Papierhandtüchern mit Papierhandtüchern trocknen lassen. Den Fisch in mittelgroße Stücke schneiden und beiseite legen.","Das Pflanzenöl in einem großen Topf oder in einem holländischen Ofen bei mittlerer Hitze erhitzen. Die gehackten Zwiebeln und gehackten Knoblauch zugeben und anbraten, bis sie durchscheinend und duftend werden.","Die gewürfelten Tomaten, rote und grüne Paprika, Karotten und gefrorene Okra in den Topf geben. Mit Zwiebeln und Knoblauch gut umrühren.","Tomatenpaste, Paprika, Cayennepfeffer, schwarzer Pfeffer, getrockneter Thymian und Salz in den Topf geben. Alles zusammenrühren, um die Gewürze gleichmäßig zu verteilen und das Gemüse zu beschichten.","Legen Sie die Fischstücke vorsichtig auf die Gemüsemischung. Dann den Reis hinzufügen und gleichmäßig über die Fische und Gemüse verteilen.","Die Fisch- oder Gemüsebrühe vorsichtig in den Topf gießen, um sicherzustellen, dass sie die Mischung aus Fisch und Reis bedeckt. Die Flüssigkeit sollte etwa 2,5 cm über den Zutaten liegen.","Bringen Sie die Mischung bei mittlerer Hitze zum Kochen. Sobald es anfängt zu kochen, reduzieren Sie die Hitze auf niedrig und decken Sie den Topf mit einem Deckel. Lassen Sie für etwa 20-25 Minuten köcheln, oder bis der Reis zart ist und der Fisch durchgekocht wird.","Entfernen Sie den Topf von der Hitze und lassen Sie ihn für ein paar Minuten mit dem Deckel auf sitzen. Dadurch können die Aromen zusammen verschmelzen. Warm servieren, mit frischer Petersilie oder Koriander garniert."],"x":[],"desc":"Boule-di ist ein traditionelles westafrikanisches Gericht aus dem Senegal. Es ist ein herzhaftes und würziges Ein-Töpfe-Menü mit einer Kombination aus Fisch, Gemüse und Reis. Dieses Gericht ist beliebt für seine aromatischen Gewürze, lebendige Farben und reichen Geschmack.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Boule-Di_(Senegalese_Fish_and_Rice)","i":"wb-en-1037","on":"Boule-Di (Senegalese Fish and Rice)","og":["2 pounds firm white fish fillets (such as cod or tilapia)","2 tablespoons vegetable oil","1 large onion, finely chopped","4 garlic cloves, minced","1 can (14 ounces) diced tomatoes","1 red bell pepper, diced","1 green bell pepper, diced","2 carrots, diced","1 cup frozen okra, sliced","1 tablespoon tomato paste","1 teaspoon paprika","1 teaspoon ground cayenne pepper (adjust to your preferred level of spiciness)","1 teaspoon ground black pepper","1 teaspoon dried thyme","Salt to taste","2 cups long-grain rice","4 cups fish or vegetable broth","Chopped fresh parsley or cilantro (for garnish)"],"mt":1},{"n":"Bourbon-Äpfel","c":"dessert","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 Honeycrisp-Apfel, entkernt, geschält, und in Zwölftel geschnitten","¾ Tasse Bourbon","2 EL ungesalzene Butter, geschmolzen","1 EL frisch gepresster Zitronensaft","¼ Tasse Zucker","½ TL frisch gemahlener Piment","2 Zehen, frisch gemahlen","½ TL frisch gemahlener Zimt"],"s":["Äpfel mit Butter und Zitrone bedecken.","Kombinieren Sie Zucker, Allspice, Nelken und Zimt. Bestreuen Sie über Äpfel und werfen zu beschichten.","Heizen Sie eine kleine Edelstahl Pfanne bei mittlerer Hitze. Äpfel hinzufügen und anbraten, bis sie leicht gebräunt sind.","Bourbon zur Pfanne hinzufügen und ablöschen. Zum Kochen bringen, und kochen, gelegentlich Rühren, bis Äpfel sind Gabel zart. Servieren Sie sofort."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bourbon_Apples","i":"wb-en-1038","im":["d/df/Vegan_Bourbon_Baked_Apples_%283617911681%29.jpg/960px-Vegan_Bourbon_Baked_Apples_%283617911681%29.jpg","Veganbaking.net from USA","CC BY-SA 2.0","Vegan Bourbon Baked Apples (3617911681).jpg","c"],"on":"Bourbon Apples","og":["1 Honeycrisp apple, cored, peeled, and sliced into 12ths","¾ cup bourbon","2 tbsp unsalted butter, melted","1 tbsp freshly squeezed lemon juice","¼ cup white granulated sugar","½ tsp freshly ground allspice","2 cloves, freshly ground","½ tsp freshly ground cinnamon"],"mt":1},{"n":"Boxty (irische Kartoffelpuffer)","c":"veggie","k":"Irland","p":20,"t":60,"d":1,"v":1,"l":"en","g":["910 g Kartoffeln","1 Tasse Milch","1 EL Butter","1–2 EL Butter, zum Braten","1 ½ Tassen Weizenmehl","1 TL Natron","1 Tasse Buttermilch","frisch gemahlener schwarzer Pfeffer"],"s":["Die Hälfte der Kartoffeln nehmen und waschen, schälen, zerkleinern und kochen.","Die gekochten Kartoffeln mit Milch und 1 Esslöffel Butter zerkleinern und beiseite legen.","Das andere Pfund (rohe) Kartoffeln in ein kräftiges Tuch braten.","Tuch quetschen, um alle möglichen Flüssigkeiten aus den rohen Kartoffeln zu entfernen.","Die geriebenen Kartoffeln, die Kartoffelpüree, Backnatron, Buttermilch, Mehl und schwarzen Pfeffer (nach Geschmack) vermischen.","Umrühren, um gut zu kombinieren.","Warme Antihaft Griddle oder Pfanne bei mittlerer Hitze und schmelzen Butter.","Kartoffelkuchen auf Gitter gießen, 1⁄4 Tasse nacheinander.","Frittieren, bis die Kanten weich sind und der Kuchen sprudelt.","Auf der anderen Seite kochen.","Heiß servieren."],"x":[],"desc":"Variante der traditionellen irischen Bratkartoffelkuchen Rezept. Ein alter irischer Reim geht wie folgt:Boxty auf dem Griddle, Boxty in der Pfanne, Wenn Sie nicht boxty machen können, werden Sie nie bekommen Ihren Mann.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Boxty_(Irish_Potato_Cakes)","i":"wb-en-1039","im":["f/f6/Boxty_triangle.jpg/960px-Boxty_triangle.jpg","さえぼー","CC0","Boxty triangle.jpg","w"],"on":"Boxty (Irish Potato Cakes)","og":["2 pounds potatoes","1 cup milk","1 tablespoon butter","1–2 tablespoons butter, for frying","1½ cups all-purpose flour","1 teaspoon baking soda","1 cup buttermilk","Freshly-ground black pepper"],"mt":1},{"n":"Braai (sambisches Grillen)","c":"fleisch","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["2 EL Pflanzenöl","1 Zwiebel, fein gehackt","2 Zehen Knoblauch, fein gehackt","1 Zitrone, ausgepresst","1 TL Paprikapulver","1 TL Cayennepfeffer","1 TL gemahlener Kreuzkümmel","1 TL gemahlener Koriander","1 TL Salz","910 g Rindfleisch, in spießgerechte Stücke geschnitten"],"s":["In einer Mischschüssel die fein gehackten Zwiebeln, zerkleinerten Knoblauch, Pflanzenöl, Zitronensaft, Paprika, Cayennepfeffer, gemahlenem Kreuzkümmel, gemahlenem Koriander und Salz kombinieren. Mischen Sie gut, um eine Marinade zu schaffen.","Fügen Sie die Rindfleischstücke zur Marinade und werfen sie, bis sie gleichmäßig beschichtet sind. Bedecken Sie die Schüssel mit Plastikfolie oder einem Deckel und lassen Sie das Rindfleisch mindestens 1 Stunde im Kühlschrank marinieren, oder vorzugsweise über Nacht, um die Aromen zu verbessern.","Wenn Sie Holzspieße verwenden, einweichen sie in Wasser für etwa 30 Minuten, um zu verhindern, dass sie beim Grillen brennen.","Den Grill oder den Braai-Stand auf mittlerer Höhe vorheizen.","Fäden Sie die marinierten Rindfleischstücke auf die Spieße und stellen Sie sicher, dass sie gleichmäßig voneinander getrennt sind.","Legen Sie die Spieße auf den Grill und kochen das Rindfleisch für etwa 8-10 Minuten, drehen gelegentlich, bis sie verkohlt und gekocht werden, um Ihre gewünschte Ebene der Fertigkeit.","Sobald das Rindfleisch gekocht wird, entfernen Sie die Spieße aus dem Grill und lassen sie für ein paar Minuten vor dem Servieren ruhen."],"x":["Sie können verschiedene Teile von Rindfleisch, wie Sirloin, Ribeye oder Rumpel, für die Braai verwenden. Stellen Sie sicher, dass die Stücke in gleichmäßige Größen geschnitten werden, um ein gleichmäßiges Kochen zu gewährleisten.","Für zusätzlichen Geschmack, können Sie andere Gewürze oder Kräuter zu der Marinade hinzufügen, wie Thymian, Rosmarin oder Ingwer.","Wenn Sie bevorzugen, können Sie auch Huhn, Schweinefleisch oder Lamm mit der gleichen Marinade und Grillmethode marinieren.","Braai wird traditionell zu Beilagen wie nshima (Maismehl Brei), Salaten oder gegrilltem Gemüse serviert."],"desc":"Braai ist ein traditioneller sambischer Grill, der die Menschen zusammenbringt für ein herrliches Outdoor-Kocherlebnis. Diese Grillmethode ist in Sambia besonders bei gesellschaftlichen Anlässen und besonderen Anlässen beliebt.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Braai_(Zambian_Barbecue)","i":"wb-en-1040","im":["c/c6/Fire_at_A_braai.jpg/960px-Fire_at_A_braai.jpg","Thulani Godfrey Timba","CC BY-SA 4.0","Fire at A braai.jpg","c"],"on":"Braai (Zambian Barbecue)","og":["2 tablespoons vegetable oil","1 onion, finely chopped","2 cloves of garlic, minced","1 lemon, juiced","1 teaspoon paprika","1 teaspoon cayenne pepper","1 teaspoon ground cumin","1 teaspoon ground coriander","1 teaspoon salt","2 pounds beef, cut into skewer-friendly pieces"],"mt":1},{"n":"Geschmorte Rinderrippchen (Short Ribs)","c":"fleisch","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["8 Rinderrippchen mit Knochen","Olivenöl","1 große Zwiebel, geschält und von Pol zu Pol in Scheiben geschnitten","4 Selleriestangen, in Scheiben geschnitten","4 Möhren, geschält und in Scheiben geschnitten","3 Zehen Knoblauch, zerdrückt und in Scheiben geschnitten","4 Zweige Thymian (oder 1 TL getrocknet)","1 Dose Tomatenmark","1 Flasche trockener Rotwein","Salz","Pfeffer"],"s":["Gießen Sie sich ein Glas Wein.","Backofen auf 175 °C vorheizen.","Entfernen Sie alle großen Fettablagerungen an den Seiten der Rippen (Ihr Metzger sollte dies getan haben, aber manchmal braucht es eine zartere Hand) und Salz und Pfeffer alle Seiten.","Etwa 2 EL Olivenöl im niederländischen Ofen bei mittlerer Hitze erhitzen.","Rippen hinzufügen und an allen Seiten braun (ca. 2–3 Minuten pro Seite). Arbeiten Sie in Chargen, als nicht zu crowd pan.","Während Fleisch ist bräunende Mischung Tomatenpaste mit genügend Wein zu dünn (1⁄3 Flasche)","Fleisch entfernen und beiseite stellen.","Das Gemüse weich anbraten (ca. 5–10 Minuten).","Die Pfanne mit Wein ablöschen und jeden Fond aufkratzen.","In Tomatenmasse Mischung, sowie Salz und Pfeffer nach Geschmack.","Rippen hinzufügen (Nestrose in Gemüse).","Fügen Sie Sprünge von Thymian hinzu.","Fügen Sie Rest des Weins, um nur fast die Rippen zu decken.","Gießen Sie Rest von Wein in Ihr fast leeres Glas.","2,5–3 Stunden lang im Ofen bedecken und schmoren (einmal beim Kochen die Rippen umdrehen), bis die Rippen verzichtet sind und vom Knochen fallen.","Servieren Sie Rippen mit brühenden Flüssigkeit und Gemüse über Kartoffelpüree, entlang der Seite neue Kartoffeln oder über Eiernudeln."],"x":["Rippen abtrennen und Flüssigkeit brüten, Gemüse ausspannen und Flüssigkeit bei mittlerer Hitze verdicken.","Trennen Sie Rippen und brüten Flüssigkeit und mischen Gemüse und brauen Flüssigkeit in Mixer oder Lebensmittelverarbeiter, reduzieren über mittlere Hitze.","Alle Gemüse vor dem Anbraten mischen und bei hoher Hitze anbraten, bis fast verbrannt","Über Nacht kühlen, erstarrtes Fett entfernen, bei mittlerer Hitze erhitzen, bis die Sauce reduziert wird."],"desc":"Rindfleisch kurze Rippen sind billig und können einen ausgezeichneten Winter wärmer machen. Viele mögen es, im Herbst und Winter zu schmoren, da der Ofen dem Haus Wärme verleiht und die Gerüche, wenn sie aus der Kälte kommen, deine Socken abblasen. Dieses Rezept ist sehr einfach und es gibt viele Variationen.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Braised_Beef_Short_Ribs","i":"wb-en-1041","im":["9/96/Korean_braised_beef_short_ribs-Galbijjim.jpg/960px-Korean_braised_beef_short_ribs-Galbijjim.jpg","by Junho Jung at Flickr from South Korea","CC BY-SA 3.0","Korean braised beef short ribs-Galbijjim.jpg","c"],"on":"Braised Beef Short Ribs","og":["8 ea. (3.5–4 lbs) bone-in beef short ribs","Olive oil","1 large onion, peeled and sliced (pole to pole)","4 celery stalks, sliced","4 carrots, peeled and sliced","3 cloves garlic, smashed and sliced","4 sprigs thyme (or 1 tsp dried)","1 can tomato paste","1 bottle of dry red wine","Salt","Pepper"],"mt":1},{"n":"Geschmorter Blattkohl","c":"beilagen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["2 Eisbeine","2 Zehen Knoblauch","Meersalz, nach Geschmack","1,9 l Wasser","910 g Blattkohl (Collard Greens)","1 Tasse Branntweinessig"],"s":["Legen Sie Schinkenkeulen, Knoblauchzehen und eine gesunde Prise Meersalz in die 1,9-Liter Wasser, und langsam zum Kochen bringen in einem großen Eintopf, bis der Schinkenkeulen zart werden.","Unterdessen die Grüns gründlich mit kaltem Wasser waschen, um Schmutz zu entfernen, und dann einmal im Essig waschen (nicht mit Papiertüchern nach der Essigwäsche trocknen). Anschließend die Stiele entfernen und die Blätter in dünne Streifen zerkleinern.","Wenn das Wasser siedet, fügen Sie die Grüns durch die Handvoll und drehen Sie die Temperatur auf Medium. Simmer die Grüns aufgedeckt, bis sie ziemlich zart sind und die Brühe reduziert hat.","Mit Pfefferessig, Tabasco oder Paprikaflocken servieren."],"x":[],"desc":"Im Südosten der Vereinigten Staaten wird das Grün häufig als Nebenstück serviert. Sie werden traditionell in einem Topf aus vorgefertigter Brühe oder mit Schweinefleisch gewürztem Wasser gekocht.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Braised_Collard_Greens","i":"wb-en-1042","im":["9/90/Collard_greens_on_a_stovetop.jpg/960px-Collard_greens_on_a_stovetop.jpg","Nolabob","CC BY-SA 4.0","Collard greens on a stovetop.jpg","c"],"on":"Braised Collard Greens","og":["2 ham hocks","2 cloves of garlic","Sea salt to taste","2 quarts water","2 lbs collard greens","1 cup white vinegar"],"mt":1},{"n":"Geschmorte Short Ribs","c":"suppen","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["1.35 kg Rinderrippchen (Short Ribs, englischer Zuschnitt)","Salz","frisch gemahlener schwarzer Pfeffer","¼ Tasse Speckfett","6 Tassen Rinderbrühe","1 ½ Tassen Rotwein","1 Tasse Tomatenmark","2 TL getrockneter Rosmarin","1 EL getrockneter Thymian","fein gehackter Rosmarin","1 große Zwiebel, gewürfelt","3 EL fein gehackter Knoblauch","4 Möhren, geschält und in 2,5 cm dicke Scheiben geschnitten","3 rotschalige Kartoffeln, in 5-cm-Würfel geschnitten","1 EL Olivenöl","Mehl"],"s":["Speckfett in einem 5,7-Liter (6-Liter) Gusseisen niederländischen Ofen bei mittlerer Hitze erhitzen. Kurzrippen mit Salz, frisch gemahlenem schwarzem Pfeffer würzen, dann in Mehl abreiben. Legen Sie 1 oder 2 in den Topf auf einmal, und kochen, bis auf allen Seiten gebräunt.","Wiederholen Sie, bis alle Shortribs gebräunt wurden. Warm halten.","Wenn es nicht genug Fett in der Pfanne, um den Boden zu beschichten, hinzufügen Olivenöl. 1⁄4 des Gemüses zu einer Zeit hinzufügen und anbraten, bis um die Ränder gebräunt. Wiederholen Sie, bis alle Gemüse gebraten wurden.","Restliche Zutaten und gebräunte Shortribs zugeben. In einen kalten Ofen geben und dann für 120 °C einstellen. 5 1⁄2 Stunden kochen.","Um die Schüsseln zu servieren und mit fein gehacktem Rosmarin zu bestreuen. Warm servieren."],"x":[],"desc":"Shortribs in Rindfleischbrühe mit aromatischen Kräutern und Gemüse gekocht macht eine Gabel-Tender, geschmackvolle Entrée.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Braised_Shortribs","i":"wb-en-1043","on":"Braised Shortribs","og":["2 ½ pounds (1.35 kg) English cut beef shortribs","Salt","Freshly-ground black pepper","¼ cup bacon fat","6 cups beef broth","1 ½ cups red wine","1 cup tomato paste","2 tsp dried rosemary","1 Tbsp dried thyme","Finely-chopped rosemary","1 large onion, diced","3 Tbsp minced garlic","4 carrots, peeled and cut into 1-inch (2.5 cm) slices","3 red-skinned potatoes, cut into 2-inch (5 cm) cubes","1 Tbsp olive oil","Flour"],"mt":1},{"n":"Kleie-Muffins","c":"brot","k":"","p":12,"t":25,"d":1,"v":0,"l":"en","g":["240 ml Weizenkleie","180 ml Buttermilch","1 Ei","2 EL Margarine","240 ml Weizenmehl","1 TL Backpulver","½ TL Natron","½ TL Salz","120 ml brauner Zucker"],"s":["Weizenkleie und Buttermilch in einer Rührschüssel zusammenrühren.","Ei, brauner Zucker und Margarine in einer anderen Schüssel cremen.","Restliche Zutaten in einer dritten Schüssel kombinieren. Zum Teig geben und nur umrühren, um zu befeuchten.","Muffinbecher 3⁄4 voll füllen.","15 bis 20 Minuten bei 200 °C backen."],"x":["Für Kleie Rosinen Muffins, fügen Sie 1 Tasse Rosinen.","Wenn Sie nicht kaufen möchten, kaufen Sie gekaufte kultivierte Buttermilch, können Sie Ihre eigene machen, indem Sie 1 Esslöffel Zitronensaft oder Essig zu 1 Tasse Milch hinzufügen. Lassen Sie es für fünf Minuten vor dem Gebrauch sitzen.","Schmeckt am besten, wenn es noch warm ist."],"desc":"Ein köstliches Kleie-Muffin-Rezept, das ein ausgezeichnetes Frühstück macht.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bran_Muffins","i":"wb-en-1044","im":["2/25/NCI_Visuals_Food_Muffins.jpg/960px-NCI_Visuals_Food_Muffins.jpg","Unknown photographer/artist","Public domain","NCI Visuals Food Muffins.jpg","w"],"on":"Bran Muffins","og":["1 cup (240 ml) natural wheat bran","¾ cup (180 ml) cultured buttermilk","1 egg","2 tablespoons margarine","1 cup (240 ml) all-purpose flour","1 teaspoon baking powder","½ teaspoon baking soda","½ teaspoon salt","½ cup (120 ml) brown sugar"],"mt":1},{"n":"Brandybutter","c":"saucen","k":"","p":8,"t":10,"d":1,"v":0,"l":"en","g":["75 g ungesalzene Butter","75 g gesiebter Puderzucker oder feiner Zucker","2 EL Weinbrand"],"s":["Butter und Zucker bis leicht und flauschig schlagen.","Allmählich schlagen im Brandy.","Beruhige dich vor dem Servieren.","Mit weihnachtlichem Pudding und warmen Minzkuchen servieren."],"x":["Brandybutter kann mehrere Wochen aufbewahrt werden, wenn sie mit frischer Butter zubereitet und im Kühlschrank aufbewahrt wird.","Brandy Butter ist eine \"harte Soße\", d.h. sie enthält Alkohol. Andere, eher ähnliche Hartsoßen können hergestellt werden, indem man den Brandy mit Rum, Whiskey oder Sherry ersetzt.","Einige Leute mögen, um ein paar weitere Zutaten hinzuzufügen. Hier ist eine Liste von einigen der Optionen, die Sie versuchen könnten","Ein Schuss Vanille-Extrakt","Orangen- oder geriebene Zitronenschale","Gewürze wie Muskatnuss, Zimt oder Allspice"],"desc":"","img":"Brandy butter.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Brandy_Butter","i":"wb-en-1045","im":["c/c2/Brandy_butter.jpg/960px-Brandy_butter.jpg","Matt Biddulph","CC BY-SA 2.0","Brandy butter.jpg","r"],"on":"Brandy Butter","og":["75 g unsalted butter","75 g sieved icing sugar or caster sugar","2 tbsp brandy"],"mt":1},{"n":"Brasilianische Schwarze-Bohnen-Suppe","c":"suppen","k":"Brasilien","p":4,"t":0,"d":2,"v":2,"l":"en","g":["2 Tassen getrocknete schwarze Bohnen","8 Tassen Wasser","4 Zehen Knoblauch, fein gehackt","¼ Tasse gewürfelte weiße Zwiebel","¼ Tasse gehackte Frühlingszwiebel","2 ganze Gewürznelken","½ TL gemahlener Kreuzkümmel","1 EL Caribe-Chili oder andere gemahlene scharfe Chili","Saft von 1 Limette","Salz, nach Geschmack","Pfeffer, nach Geschmack"],"s":["Bohnen in eine große Pfanne geben und mit Wasser bedecken. Zum Kochen bringen und aus der Hitze entfernen. Überdecken und 1 Stunde stehen lassen. 2 Stunden köcheln und abtropfen lassen.","Bohnen in eine große Pfanne geben und 8 Tassen Wasser, Knoblauch, Salz, weiße Zwiebeln, Kreuzkümmel, gemahlenes Chili und Limettensaft hinzufügen. Krawatte Nelken in Käsetuch für die einfache Entfernung, wenn gewünscht.","Zum Kochen bringen; Hitze reduzieren, decken und 2 Stunden köcheln lassen oder bis Bohnen zart sind und Suppe dick ist.","In grüne Zwiebeln mischen und mit Kalkkeil servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brazilian_Black_Bean_Soup","i":"wb-en-1046","im":["f/f9/Black_bean_soup.jpg/960px-Black_bean_soup.jpg","newton64","CC BY-SA 2.0","Black bean soup.jpg","c"],"on":"Brazilian Black Bean Soup","og":["2 cups dried black beans","8 cups water","4 cloves garlic, minced","¼ cup diced white onion","¼ cup chopped green onion","2 whole cloves","½ teaspoon ground cumin","1 tablespoon caribe or another ground hot pepper","Juice of 1 lime","Salt to taste","Pepper to taste"],"mt":1},{"n":"Brasilianische Feijoada","c":"suppen","k":"Brasilien","p":4,"t":0,"d":3,"v":0,"l":"en","g":["#Bohneneintopf","230 g Schweinerippchen","Salz","2 Filet-Mignon-Medaillons","1 Räucherwurst","115 g Schinkensteak","1 Packung Kasseler-Koteletts (z. B. Hormel)","Jerk-Rindfleisch (optional)","1 Zwiebel, gehackt","Petersilie, gehackt","Schnittlauch, fein gehackt","2–3 Dosen vorgegarte schwarze Bohnen","#Reis","3 Tassen ungekochter Reis","2 Zehen Knoblauch, fein gehackt","¼ Zwiebel","#Blattkohl","Blattkohl (Collard Greens)","Speck in dünnen Scheiben (optional)","Zwiebel in Scheiben","1 Prise Salz","1 Prise Zucker","#Farofa","1 Tasse Speckscheiben","¼ Tasse schwarze Oliven","¼ Tasse Olivenöl","¼ Zwiebel, gehackt","2 Tassen weißes geröstetes Maniokmehl","2 TL Hühnerbrühe (Instant)","#Scharfe Bohnensoße","Koriandergrün","Schnittlauch","Salz","Olivenöl","ein wenig Essig","1 scharfe rote Fingerchili, fein gehackt","#Außerdem","Orangenscheiben (1 Orange pro Person)","Tabasco"],"s":["Drei Tage vor dem Servieren legen Sie die Schweinerippen in einen großen Topf und bedecken sie gründlich mit Salz. Eine der gesalzenen Rippen abschneiden, in einen Plastikbeutel legen und im Kühlschrank beiseite stellen.","Den großen Topf mit den restlichen Rippen bedecken und im Kühlschrank aufbewahren.","Einen Tag vor dem Servieren den großen Topf mit den Rippen aus dem Kühlschrank nehmen. Beginnen Sie den Prozess des Zurückziehens des überschüssigen Salzes, das Einweichen der Rippen in kaltes Wasser und das Ändern des Wassers dreimal in Abständen von 6 Stunden.","Jedes Mal, wenn Sie das Wasser wechseln, geben Sie den abgedeckten großen Topf mit Wasser und Rippen zurück in den Kühlschrank. Nach dem dritten und letzten Mal den großen Topf wieder mit den Rippen und Wasser füllen und im Kühlschrank lassen, bis der Kochvorgang beginnt.","Am Tag des Kochens und Servierens den Filet Mignon in 2,5 cm Würfel schneiden. Schneide die geräucherte Wurst so dick, wie du willst. Den Speck in kleine Würfel schneiden. Das Schinkensteak in 2,5 cm große Würfel schneiden. Die geräucherten Schweinekoteletts in kleine Stücke schneiden.","Wirf den Knochen noch nicht weg. Lassen Sie etwas Fleisch auf ihm zu kochen. Wenn Sie auch mit rucken Rindfleisch, schneiden Sie die Stücke proportional zum Rest des Fleisches.","Wenn ein Teil des Fleisches Knochen hat, lassen Sie einen Teil des Fleisches auf den Knochen zu kochen.","Den großen Topf mit den Rippen aus dem Kühlschrank nehmen und das Wasser herauswerfen. Die Rippen teilen; Wenn du denkst, dass sie zu groß sind, schneide jeden in die Hälfte.","In einer großen Pfanne 1⁄4 Tasse Olivenöl geben und erhitzen. Dann fügen Sie den geschnittenen Speck zusammen mit den Rippen, einschließlich der gesalzenen Rippe, die Sie im Kühlschrank beiseite gelassen haben (Anmerkung: Das Salz auf diesem speziellen Rippenstück wird das Grundsalz genug für die Zubereitung sein).","Legen Sie den Deckel auf, und kochen alle zusammen für 10-15 Minuten bei mittlerer Hitze, gelegentlich Rühren.","Die geschnittene Zwiebel, die Petersilie und die Schnittlauch dazugeben. Den Rest des in Scheiben geschnittenen Fleisches hinzufügen und 15 Minuten kochen lassen.","Dann 2–3 Dosen schwarze Bohnen, plus eine Dose Wasser hinzufügen und mehr als 30 Minuten kochen. Wenn es anfängt zu kochen, verringern Sie die Hitze auf mittlere niedrige Temperatur. Gelegentlich umrühren.","Schmeckt nach Salz. Es sollte reichen. Wenn Sie mehr Salz hinzufügen möchten, seien Sie vorsichtig. Salzen Sie Ihre Feijoada nicht zu viel.","Pass auf das Wasser auf. Fügen Sie mehr (heißes) Wasser hinzu, wenn Sie Ihre Feijoada mehr Flüssigkeit wollen. Ihre Feijoada wird bereit sein, wenn das Fleisch weich wird und sich von den Knochen löst. Jetzt kannst du die Knochen entfernen, wenn du willst. Es warm servieren.","Den Reis waschen und abtropfen lassen.","In eine mittlere Pfanne, Olivenöl und gehackte Zwiebel. Kochen, bis es weich wird. Fügen Sie Knoblauch, wenn Sie wollen.","Den zuvor gewaschenen Reis hinzufügen und trocknen. Eine Prise Salz dazugeben und umrühren.","Heißes Wasser (für jede Tasse Reis, verwenden Sie 2 Tassen Wasser) und kochen, bis es zu kochen beginnt.","Die Hitze reduzieren. Legen Sie den Deckel auf und beenden Sie das Kochen. Der Reis ist fertig, wenn das Wasser vollständig verdampft und der Reis weich ist.","In einer Pfanne 1 Tasse geschnittenen Speck braten, bis er goldbraun wird.","Gib schwarze Oliven hinzu und koche.","Olivenöl und Zwiebel hinzufügen. Kochen, bis es weich wird.","Gießen Sie beim Erhitzen das Kassava/Maniokmehl und rühren Sie um, bis Sie die gewünschte Konsistenz erhalten. Die Mehlmenge bestimmt die Konsistenz. Vorsicht mit der Hitze; Euer Farofa sollte nicht unten verbrannt werden.","Das gekrallte Blatt von Blatt zu Blatt waschen, dann in sehr dünne Streifen schneiden und beiseite stellen.","In eine Pfanne oder eine Pfanne, genug Olivenöl und geschnittene Zwiebel für die Menge der gekrallten Grüns Sie verwenden. Wenn Sie verwenden, fügen Sie in Scheiben geschnittenen Speck.","Fügen Sie die dünn geschnittenen Grüns mit einer Prise Salz und eine Prise Zucker hinzu (das hilft, dass Ihre Grüns grün bleiben).","Den Deckel auflegen und 15 Minuten kochen, gelegentlich rühren.","Die Orangen schälen, die Sie schon beiseite gelegt haben.","In runde Scheiben schneiden und in eine Keramikschüssel oder auf einen Teller geben.","In eine Keramik- oder Metallschüssel geben Sie das cilantro, Schnittlauch, Salz, Olivenöl, etwas Essig und einen fein gehackten roten scharfen Fingerpfeffer, und fügen Sie eine Tasse warme Bohnenbrühe hinzu, und rühren Sie zusammen.","Verwenden Sie einen Teelöffel zu dienen. Diese Soße kann oben auf der Feijoada verwendet werden und wird einzeln hinzugefügt.","Den Bohneneintopf mit begleitenden Seiten und Orangenscheiben servieren."],"x":["Feijoada kann am selben Tag gegessen werden, aber es wird viel schmackhafter sein, wenn es am nächsten Tag serviert wird."],"desc":"Brasilianische Feijoada oder \"Feijoada Brasileira\" beinhaltet in der Regel einen Bohneneintopf mit würziger Sauce, Schweinefleisch, weißem Reis, Farofa, Grünkohl und in Scheiben geschnittenen Orangen.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brazilian_Feijoada","i":"wb-en-1047","im":["9/90/Feijoada_%C3%A0_transmontada.jpg/500px-Feijoada_%C3%A0_transmontada.jpg","Adrião","CC BY 3.0","Feijoada à transmontada.jpg","w"],"on":"Brazilian Feijoada","og":["#Bean stew","½ lb pork ribs","Salt","2 filet mignon medallions","1 smoked sausage","¼ lb ham steak","1 package smoked pork chops (such as Hormell)","Jerked beef (optional)","1 onion, chopped","Parsley, chopped","Chives, minced","2–3 cans pre-cooked black beans","#Rice","3 cups uncooked rice","2 cloves garlic, minced","¼ onion","#Collard greens","Collard greens","Thinly-sliced bacon (optional)","Sliced onion","1 pinch salt","1 pinch sugar","#Farofa","1 cup sliced bacon","¼ cup black olives","¼ cup olive oil","¼ onion, chopped","2 cups white toasted cassava flour","2 tsp chicken flavor bouillon","#Spicy bean sauce","Cilantro","Chives","Salt","Olive oil","A little bit of vinegar","1 red hot finger pepper, finely chopped","#Additional","Sliced oranges (1 orange for each person)","Tabasco sauce"],"mt":1},{"n":"Brasilianische Garnelen in Maniokcreme (Bobó de Camarão)","c":"saucen","k":"Brasilien","p":4,"t":0,"d":2,"v":0,"l":"en","g":["1.2 kg mittelgroße Garnelen","1.2 kg Maniokwurzel","2 Tassen Zwiebel, gehackt","3 Zehen Knoblauch, gehackt","½ Tasse Olivenöl","6 mittelgroße Tomaten, geschält und entkernt (oder eine große Dose geschälte Tomaten)","¼ Tasse Koriandergrün, gehackt","2 Tassen Kokosmilch","¼ Tasse Palmöl (auch Dendê genannt)","Salz, nach Geschmack","Pfeffer, nach Geschmack"],"s":["Den Maniok schälen und schneiden und mit kaltem Wasser und Salz in eine Pfanne geben.","Den gekochten Maniok und die Flüssigkeit abtropfen lassen.","Wirf jede Maniokfaser weg.","Mit einer Gabel den Maniok zermalmen, solange er noch heiß ist. Verwenden Sie einige der Flüssigkeit, um dabei zu helfen. Verwenden Sie keinen Mixer oder Lebensmittelverarbeiter.","Die Garnelen schälen und entleeren.","Zwiebel und Knoblauch im Olivenöl anbraten, bis es verwelkt ist.","1⁄2 des gehackten Korianders und der Tomaten hinzufügen, gut umrührend.","Fügen Sie die Garnelen, und kochen Sie es für etwa 15 Minuten.","Fügen Sie den Puréed Maniok hinzu. Überprüfen Sie die Flüssigkeitsmenge und fügen Sie mehr der beiseite gelegten Maniokflüssigkeit hinzu, um die Mischung zu dünn, wenn nötig.","Fügen Sie die Kokosmilch, den restlichen Koriander und das Palmöl hinzu.","Überprüfen Sie nach Salz und Pfeffer.","Servieren Sie über brasilianischen weißen Reis."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brazilian_Shrimp_and_Cassava_Sauce_(Bobó_de_Camarao)","i":"wb-en-1048","on":"Brazilian Shrimp and Cassava Sauce (Bobó de Camarao)","og":["3 lbs (1.2 kg) medium size shrimp","3 lb (1.2 kg) yuca root","2 cups onion, chopped","3 cloves garlic, chopped","½ cup olive oil","6 medium tomatoes, peeled and seeded (or a large can of whole tomatoes)","¼ cup cilantro, chopped","2 cups coconut milk","¼ cup palm oil (also known as dendê)","Salt to taste","Pepper to taste"],"mt":1},{"n":"Brot mit Kartoffelcurry-Füllung (Pani Puri)","c":"veggie","k":"Indien","p":4,"t":0,"d":2,"v":2,"l":"en","g":["1 EL Chaat Masala","1 EL Amchur-Pulver (getrocknete grüne Mango)","1 EL rotes Chilipulver","1 EL gemahlener Koriander","1 EL gemahlener Kreuzkümmel (Kreuzkümmel)","1 EL Koriander","1 Prise Asant (Hing)","½ EL schwarzer Pfeffer","2 Löffel Zitronensaft","Schwarzsalz (Kala Namak) (nach Geschmack)","2 Kartoffeln","100 g Moong Dal (gelbe Linsen)","50 g Tamarinde","100 g Zucker","50 g Boondi (frittierte Kichererbsenperlen)","15 kleine Puris"],"s":["Amchor, Chaat, Jeera-Pulver, Korianderpulver, Zitronensaft, schwarzes Salz, rotes Chilipulver und Wasser zu einer feinen Mischung kombinieren und gekühlt aufbewahren.","Kartoffeln und Moong separat kochen. Die Kartoffeln schälen und grob maschen.","Machen Sie ein Chutney mit Tamarind und Zucker, und halten Sie es gekühlt.","Zerbrechen Sie den Puris von oben, legen Sie die Kartoffeln, Moong, gehackten Koriander, Chutney und gekühltes Wasser","Mit gehacktem Koriander garnieren und servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bread_Filled_with_Potato_Curry_(Pani_Puri)","i":"wb-en-1049","im":["e/e9/Pani_Puri1.JPG/960px-Pani_Puri1.JPG","Sruthi612","CC BY-SA 4.0","Pani Puri1.JPG","w"],"on":"Bread Filled with Potato Curry (Pani Puri)","og":["1 tablespoon of chaat masala","1 tablespoon of amchur (dried green mango) powder","1 tablespoon of red chile powder","1 tablespoon of coriander powder","1 tablespoon of jeera (cumin) powder","1 tablespoon coriander","1 pinch of hing","½ tablespoon of black pepper","2 spoons of lemon juice","Black salt (according to taste)","2 potatoes","100 grams moong dal","50 grams tamarind","100 grams sugar","50 grams boondi","15 small puris"],"mt":1},{"n":"Brotpudding","c":"dessert","k":"","p":12,"t":60,"d":1,"v":0,"l":"en","g":["6 Scheiben Brot, mit oder ohne Rinde, leicht altbacken oder frisch","30 g Butter, geschmolzen","80 g Rosinen (optional)","4 Eier","150 g Zucker","475 ml Milch","2 g gemahlener Zimt","5 ml Vanilleextrakt"],"s":["Ofen auf 175 °C erhitzen.","Rippen Sie Brot in kleine Stücke. Das Schneiden in Würfel ist auch okay. In die Backform geben. Rosinen beim Auffüllen der Schüssel vermischen.","Die geschmolzene Butter über das Brot gießen.","In einer Schüssel die Eier leicht schlagen. Zucker, Milch, Zimt und Vanille dazugeben. Mischen.","Mischung über das Brot gießen. Drücken Sie das Brot leicht, um es zu absorbieren die Mischung, wenn nötig. Das ganze Brot sollte nass sein.","45 Minuten im vorgeheizten Backofen backen.","Entfernen und abkühlen lassen.","Dienen kalt, obwohl warm kann auch akzeptabel sein. Verwenden Sie einen Löffel oder in Quadrate geschnitten, um zu dienen."],"x":[],"desc":"","img":"A slice of bread pudding.JPG","u":"https://en.wikibooks.org/wiki/Cookbook:Bread_Pudding","i":"wb-en-1050","im":["0/09/A_slice_of_bread_pudding.JPG/960px-A_slice_of_bread_pudding.JPG","Quillaja","Public domain","A slice of bread pudding.JPG","r"],"on":"Bread Pudding","og":["6 slices of bread, with or without crusts. Slightly stale or new bread is acceptable.","30 g (2 tbsp) butter, melted","80 g (½ cup) raisins (optional)","4 eggs","150 g (¾ cup) white granulated sugar","475 ml (2 cups) milk","2 g (1 tsp) ground cinnamon","5 ml (1 tsp) vanilla extract"],"mt":1},{"n":"Brot mit Tomatensoße (Pappa al Pomodoro)","c":"veggie","k":"Italien","p":2,"t":0,"d":2,"v":1,"l":"en","g":["½ Laib trockenes Brot","750 ml pürierte Tomate","1–2 Knoblauchzehen, zerdrückt und fein gehackt","Öl","1 Handvoll gut zerzupfte Basilikumblätter","Salz, nach Geschmack","Pfeffer, nach Geschmack"],"s":["Tauchen Sie das Brot in Wasser für eine kurze Zeit, so dass Sie es mit den Händen zermalmen können. Es sollte nicht durchnässt werden.","Den Knoblauch in einer großen Pfanne mit Öl braten, bis er zu wechseln beginnt.","Tomatenpüree und Salz dazugeben und bei mittlerer Hitze kochen, bis es zum Kochen kommt.","Nach dem Wringen und weiter mit der Tomate mischen, bis sie vollständig rot geworden ist, fügen Sie Brotstücke hinzu, die nicht kleiner als eine Walnuss sind.","An dieser Stelle sollte die Tomate noch ein frisches Aroma haben.","Von der Hitze nehmen und heiß in einer Schüssel servieren, gewürzt mit einem Nieselregen Olivenöl, Pfeffer und ein Basilikumblatt."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bread_with_Tomato_Sauce_(Pappa_al_Pomodoro)","i":"wb-en-1051","im":["d/d9/PappaPomodoro.png/960px-PappaPomodoro.png","Ɱ","CC BY-SA 3.0","PappaPomodoro.png","w"],"on":"Bread with Tomato Sauce (Pappa al Pomodoro)","og":["½ loaf dry bread","750 ml puréed tomato","1–2 garlic cloves, crushed and finely chopped","Oil","1 handful of well-ripped basil leaves","Salt to taste","Pepper to taste"],"mt":1},{"n":"Panierte Hühnerleber","c":"brot","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["Hühnerleber","Mehl","Salz, nach Geschmack","Pfeffer, nach Geschmack"],"s":["Schneiden Sie die Sehnen aus den Lebern.","Die Leber in Mehl überziehen und überschüssiges Material abklopfen.","Legen Sie die Leber vorsichtig in eine heiße, geölte Pfanne.","2–3 Minuten an jeder Seite braten, außen goldbraun und innen nur rosa.","Heiß servieren."],"x":["Cayenne-Pfeffer kann auch zu dem Mehl hinzugefügt werden.","Hühnerlebern werden manchmal mit Hühnermagen und Hühnerherz gekocht; Während das Herz sehr wie Lebern gekocht wird, benötigen Gizzards aufgrund ihrer Dichte zusätzliche Garzeit."],"desc":"Traditionelle Hühnerleber werden in heißem Öl gepaniert und gebraten. Hühnerlebern, zusammen mit Gizzards und Herzen, können von den meisten Lebensmittelhändlern gewonnen werden.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Breaded_Chicken_Livers","i":"wb-en-1052","on":"Breaded Chicken Livers","og":["Chicken livers","Flour","Salt to taste","Pepper, to taste"],"mt":1},{"n":"Panierte frittierte Austern","c":"snacks","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["470 ml ausgelöste große Austern, geputzt und getrocknet","2 Eier","¼ Tasse Sahne","2 Tassen feine Semmel- oder Kräckerbrösel","Salz, nach Geschmack","schwarzer Pfeffer, nach Geschmack","Cayennepfeffer, nach Geschmack","Pflanzenöl, zum Braten"],"s":["Die gereinigten Austern nehmen, auf ein sauberes Handtuch legen und trocknen.","Die Eier und Sahne zusammenschlagen und in eine flache Schüssel legen.","Kombinieren Sie die Brot- oder Crackerkrümel mit Salz, Pfeffer und Cayenne. In eine flache Schüssel oder auf einen Teller legen.","Mit einer Gabel, tauchen Sie jede Auster einzeln in das Ei, dann in die Krümel. Mit der Rückseite eines Löffels die Krümel streicheln, um sie an den Austern zu halten.","Erhitzen Sie das Öl in einer Bratpfanne – die Menge des Öls variiert mit der verwendeten Kochmethode.","Die Austern in der Pfanne tief braten, braten oder anbraten, aber sie nicht bedrängen; Bei Bedarf in Chargen kochen. Fry schnell bis hellbraun auf beiden Seiten; 1 oder 2 Minuten eine Seite sollte genug sein.","Heiß servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Breaded_Fried_Oysters","i":"wb-en-1053","on":"Breaded Fried Oysters","og":["1 pint shucked large oysters, cleaned and dried","2 eggs","¼ cup cream","2 cups fine bread crumbs or cracker crumbs","Salt, to taste","Black pepper, to taste","Cayenne pepper, to taste","Vegetable oil, to fry"],"mt":1},{"n":"Panierte Kartoffelspalten","c":"beilagen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["910 g mehligkochende Kartoffeln, in 10 Spalten geschnitten","2 EL Salz","2 EL schwarzer Pfeffer","1 ½ EL Cayennepfeffer","1 EL geräuchertes Paprikapulver","½ Tasse zerbröselte Cornflakes","3 Eier, verquirlt","2 EL fein gehackter Knoblauch","Öl zum Frittieren"],"s":["Eier mit Gewürzen kombinieren. Kartoffeln in Eiermischung geben und dann in Cornflakes abreiben. 2–3 Minuten ruhen lassen.","Öl auf 175 °C erhitzen. Fry Keile, in Chargen bei Bedarf, 3–4 Minuten oder bis hinken. Auf einem Kühlregal oberhalb einer Backform abtropfen lassen.","Öl auf 190 °C erhitzen. Fry Keile wieder, bis goldbraun und knusprig. Wieder auf demselben Regal abtropfen lassen. Warm servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Breaded_Potato_Wedges","i":"wb-en-1054","im":["6/67/DFC_3983_Crispy_breaded_schnitzel_with_lemon_wedge_golden_fried_potatoes_creamy_coleslaw_and_gravy_on_the_side_-_a_hearty_comfort_meal.jpg/960px-DFC_3983_Crispy_breaded_schnitzel_with_lemon_wedge_golden_fried_potatoes_creamy_coleslaw_and_gravy_on_the_side_-_a_hearty_comfort_meal.jpg","PattayaPatrol","CC BY-SA 4.0","DFC 3983 Crispy breaded schnitzel with lemon wedge golden fried potatoes creamy coleslaw and gravy on the side - a hearty comfort meal.jpg","c"],"on":"Breaded Potato Wedges","og":["2 pounds Russet potatoes, cut into 10 wedges","2 tbsp salt","2 tbsp black pepper","1 ½ tbsp cayenne pepper","1 tbsp smoked paprika","½ cup crushed cornflakes","3 eggs, beaten","2 tbsp minced garlic","Oil for deep-frying"],"mt":1},{"n":"Frühstücks-Burrito","c":"fruehstueck","k":"USA","p":2,"t":0,"d":1,"v":0,"l":"en","g":["8 Eier, entweder als Rührei, als Spiegelei, oder pochiert","4 große Weizentortillas für Burritos","8 Streifen gebratener Speck oder 450 g gebratene Frühstückswurst (400 g)","1 große Portion Rösti (Hash Browns)","Sauce hollandaise, Käse, Salz, und Pfeffer nach Geschmack"],"s":["Legen Sie ein Viertel der Hashbraunen in eine Tortilla.","Auf diesem Platz 2 Streifen Speck oder ein Viertel der Frühstückswurst.","Zwei Eier, Käse, Salz und Pfeffer dazugeben.","Rollt die Tortilla hoch, um alles einzuschließen. Wenn Sie pochierte oder sonnige Eier verwendet werden, können Sie die Burritos drücken, um das Eigelb zu knallen und dann das Eigelb herum häkeln, um eine Soße zu bilden."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Breakfast_Burrito","i":"wb-en-1055","im":["1/15/New_Mexican_breakfast_burrito.jpg/960px-New_Mexican_breakfast_burrito.jpg","Nurban","CC BY-SA 4.0","New Mexican breakfast burrito.jpg","w"],"on":"Breakfast Burrito","og":["8 eggs either scrambled, sunny-side up, or poached","4 large flour burrito skins","8 strips of cooked bacon or 1 lb (400 grams) cooked breakfast sausage","1 full order of hash browns","Hollandaise sauce, cheese, salt, and pepper to taste"],"mt":1},{"n":"Frühstücksauflauf","c":"fruehstueck","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["5 kleine Würstchen, gegart und fein gehackt","4 Eier (Größe M), verquirlt","½ TL Salz","½ TL frisch gemahlener schwarzer Pfeffer","2 Tassen fein zerkrümeltes Maisbrot","1 Tasse Ricotta","1 Tasse geriebener Monterey Jack","¼ Tasse ungesalzene Butter","8 Scheiben gebratener Speck, zerbröselt","½ Tasse Semmelbrösel"],"s":["Würstchen und Speck kombinieren. Kombinieren Sie in einer anderen Schüssel Ricotta, Eier, Butter, Salz, Pfeffer und Maisbrot.","In einer gefetteten großen Bratpfanne, Platz gerade genug Maisbrot Mischung, um den Boden zu decken. Fügen Sie gerade genug Fleischmischung, um diese Schicht zu decken, und wiederholen Sie die Schichtung, bis alle Mischungen verwendet wurden.","Kombinieren Sie Monterey Jack und Brotkrumen. Bestreuen Sie gleichmäßig über Schichten und backen Sie bei 190 °C für 30–35 Minuten oder bis gebräunt und sprudelnd auf der Oberseite.","Warm servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Breakfast_Casserole","i":"wb-en-1056","im":["5/51/Sausage_Breakfast_Casserole.jpg/960px-Sausage_Breakfast_Casserole.jpg","User:MarkTraceur","CC BY-SA 1.0","Sausage Breakfast Casserole.jpg","c"],"on":"Breakfast Casserole","og":["5 small sausage links, cooked and finely chopped","4 standard eggs, beaten","½ tsp salt","½ tsp freshly-ground black pepper","2 cups finely-crumbled cornbread","1 cup ricotta cheese","1 cup shredded Monterrey Jack cheese","¼ cup unsalted butter","8 slices cooked bacon, crumbled","½ cup dry breadcrumbs"],"mt":1},{"n":"Frühstücks-Dürüm","c":"fruehstueck","k":"","p":1,"t":60,"d":3,"v":0,"l":"en","g":["1 großes Lavash- oder Yufka-Fladenbrot","1 EL Wasser","1 mehligkochende Kartoffel, gerieben","4 Tassen heißes Wasser","4 EL Butter oder Olivenöl, aufgeteilt","½ Tasse braune Champignons in dünnen Scheiben","1 Handvoll frischer Spinat","2 große Eier","1 EL Milch","¼ Tasse geriebener würziger Cheddar","½ Zwiebel, gewürfelt","5 dünne Scheiben gegarte Rinderhüfte oder Flanke","#Gewürze","2 Prisen Salz","2 Prisen Paprikapulver","1 Prise Kreuzkümmel","1 Prise Chilipulver","1 Prise Muskatnuss","2 Prisen Pfeffer"],"s":["Bürsten Sie das Fladenbrot mit dem Esslöffel Wasser, um es weich zu halten. Toast das Brot mit einer Pfanne oder in einem Toaster, bis an den Rändern braun. Beiseite legen.","Kombinieren Sie die geriebene Kartoffel mit der Hälfte des heißen Wassers in einer Schüssel. 3 Minuten stehen lassen, dann gründlich umrühren und das Wasser aus der Schüssel abtropfen lassen. Wiederholen Sie diesen Vorgang mit dem restlichen heißen Wasser, dann die Kartoffeln in einem Sieb abtropfen lassen.","Schütteln Sie vorsichtig in einer waagrechten Bewegung, um überschüssige Stärke und Wasser zu entfernen, dann beiseite legen, um zu trocknen.","Die Pilze in 1 EL Butter anbraten. Spinat hinzufügen und bei mittlerer Hitze kochen, bis es leicht verwelkt ist.","Die Eier, Gewürze und Milch rühren, dann über den Spinat und die Pilze gießen. Wenn die Eier halb gesetzt sind, streuen Sie die Cheddar oben, dann falten Sie das Omelett in der Hälfte und entfernen Sie aus der Pfanne.","Die restliche Butter in der Pfanne erhitzen. Drehen Sie die Hitze zu hoch, dann fügen Sie die Kartoffeln, Zwiebeln und Steak, gleichmäßig und vollständig decken den Boden der Pfanne.","Saison nach Geschmack, dann lassen Sie sie zu Ihrem gewünschten Braunheit und knirschen, wobei darauf achten, sie umdrehen. Entfernen Sie aus der Hitze.","Versammeln Sie das dürüm, indem Sie das Brotblatt flach legen, mit den längeren Kanten nach links und rechts. Den Hummus gleichmäßig auf die Hälfte des Brotes verteilen, das am weitesten von dir entfernt ist. Die Kartoffelmischung und das Omelett gleichmäßig auf der nächsten Hälfte stapeln.","Den nächsten Rand falten und falten, dann in einen 5 cm dicken Zylinder rollen und servieren."],"x":[],"desc":"Dürüm ist ein nahöstliches Fastfood ähnlich einer Packung. Die Variation hier kombiniert ein modifiziertes Spinat Pilz Omelett Rezept, Hash Browns, Hummus und Rindfleischsteak, alle innerhalb eines erdigen, nussigen Weizen-Flatbreads bekannt als \"Lavash\" oder \"Yufka\", für ein intensiv würzig und fettig tragbares Frühstück","img":"Breakfast Dürüm.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Breakfast_Dürüm","i":"wb-en-1057","im":["9/98/Breakfast_D%C3%BCr%C3%BCm.jpg/960px-Breakfast_D%C3%BCr%C3%BCm.jpg","Jarrod Baniqued","CC0","Breakfast Dürüm.jpg","r"],"on":"Breakfast Dürüm","og":["1 large sheet of lavash or yufka flatbread","1 tbsp water","1 russet potato, grated","4 cups hot water","4 tbsp butter or olive oil, divided","½ cup thinly sliced baby bella or Crimini mushrooms","1 handful of fresh spinach","2 large eggs","1 tbsp milk","¼ cup shredded sharp cheddar","½ ea. onion, diced","5 thin slices cooked beef sirloin or flank","#Seasonings","2 pinches salt","2 pinches paprika","1 pinch cumin","1 pinch chili powder","1 pinch nutmeg","2 pinches pepper"],"mt":1},{"n":"Frühstücksbrei","c":"fruehstueck","k":"","p":1,"t":10,"d":1,"v":0,"l":"en","g":["Wasser","1 Müsliriegel oder Haferflocken bzw. Granola","1 Messlöffel Instantkaffee","1 Teebeutel oder 1 Messlöffel Chai-Pulver","1 EL Zucker","1 Messlöffel Kakaopulver","1 Prise gemahlener Zimt","Milch"],"s":["Wasser aufkochen.","Die Granola-Bar in eine Tasse aufteilen. Sie werden sicherstellen wollen, dass es sehr gut geschliffen ist. Die Stücke der Müslistange sollten etwa so groß sein wie Haferflockenstücke.","Fügen Sie den Instant-Kaffee, Chai, Zucker und heiße Schokolade Pulver auf die Tasse.","Zimt nach Geschmack hinzufügen.","Gießen Sie genug kochendes Wasser, um den Becher zu füllen.","Rühren Sie kräftig, bis alles vermischt ist und die Mischung ein dunkelbraunes Aussehen hat.","Fügen Sie Milch nach Geschmack."],"x":["Die meisten Zutaten in diesem Rezept können ihre Mengen nach Ihrem Geschmack geändert haben."],"desc":"Frühstücksschlamm ist ein Frühstück Rezept, das ursprünglich auf Imgur und Reddit im Jahr 2011. Es kombiniert eine Reihe von Getränken und Lebensmitteln, die häufig zum Frühstück gegessen werden. Das Getränk selbst sieht nicht sehr gut aus, aber es ist ziemlich lecker. Es ist am besten, es zu trinken, ohne es anzusehen. Dieses Rezept ist anzeigen","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Breakfast_Sludge","i":"wb-en-1058","on":"Breakfast Sludge","og":["Water","1 granola bar or oatmeal/granola","1 scoop of instant coffee powder","1 teabag or 1 scoop of chai powder","1 tablespoon of sugar","1 scoop of hot chocolate powder","1 pinch of cinnamon powder","Milk"],"mt":1},{"n":"Frühstückswaffeln","c":"fruehstueck","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["3 Eier, getrennt","1 ½ Tassen Milch","230 g Mehl","2 TL Backpulver","1 EL Zucker","½ TL Salz","¼ Tasse Pflanzenöl"],"s":["Eigelb und Milch vermischen.","Mehl, Backpulver, Zucker, Salz zugeben und gut vermischen.","Öl dazugeben.","Das Eiweiß steif rühren und dann in den Teig falten.","Ein Waffeleisen vorwärmen.","Einen Teig ins Waffeleisen geben und bis zum Braten kochen.","Waffel entfernen und den Kochvorgang mit verbleibendem Teig wiederholen."],"x":[],"desc":"Diese grundlegenden Frühstück Waffeln sind einfach und vorhersehbar zu machen. Der Teig kann in ca. 15 Minuten gemacht werden, so dass sie als Last-Minute Ergänzung zu einem Frühstück geeignet sind. Sie werden flauschig gemacht, indem sie das Eiweiß separat schlagen und als letzter Schritt einklappen.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Breakfast_Waffles","i":"wb-en-1059","im":["f/f6/Fried_Chicken%2C_Bacon_%26_Waffles_-_The_Breakfast_Club_2023-09-03.jpg/960px-Fried_Chicken%2C_Bacon_%26_Waffles_-_The_Breakfast_Club_2023-09-03.jpg","Andy Li","CC0","Fried Chicken, Bacon & Waffles - The Breakfast Club 2023-09-03.jpg","c"],"on":"Breakfast Waffles","og":["3 eggs, separated","1½ cups milk","½ lb (about 1¾ cups) flour","2 teaspoons baking powder","1 tablespoon sugar","½ teaspoon salt","¼ cup vegetable oil"],"mt":1},{"n":"Frühstückswaffeln (glutenfrei)","c":"fruehstueck","k":"","p":4,"t":0,"d":2,"v":1,"l":"en","g":["3 Eier, getrennt","420 ml Milch","225 g weizenfreie Backmischung","2 TL Backpulver","3 TL Zucker","½ TL Salz","55 g Pflanzenöl"],"s":["Eigelb und Milch vermischen.","Weizenfreie Backmischung, Backpulver, Zucker, Salz zugeben und gut vermischen.","Öl dazugeben.","Das Eiweiß steif schlagen und dann in den Teig falten.","Ein Waffeleisen vorwärmen.","Einen Teig ins Waffeleisen geben und bis zum Braten kochen.","Waffel entfernen und den Kochvorgang mit verbleibendem Teig wiederholen."],"x":[],"desc":"Diese Waffeln sind überraschend gut für ein glutenfreies Rezept. Sie sind ähnlich wie das Frühstück Waffeln mit Weizenmehl gemacht, außer das Mehl wird durch Weizen-Free Baking Mix ersetzt. Sie sind einfach und vorhersehbar zu machen. Der Teig kann in ca. 15 Minuten gemacht werden, so dass sie als Last-m geeignet sind","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Breakfast_Waffles_(Gluten-Free)","i":"wb-en-1060","im":["f/f6/Fried_Chicken%2C_Bacon_%26_Waffles_-_The_Breakfast_Club_2023-09-03.jpg/960px-Fried_Chicken%2C_Bacon_%26_Waffles_-_The_Breakfast_Club_2023-09-03.jpg","Andy Li","CC0","Fried Chicken, Bacon & Waffles - The Breakfast Club 2023-09-03.jpg","c"],"on":"Breakfast Waffles (Gluten-Free)","og":["3 eggs, separated","1¾ cups (420 ml) milk","½ lb (225 g) Wheat-Free Baking Mix","2 teaspoons baking powder","3 teaspoons granulated sugar","½ teaspoon salt","¼ cup (2 oz) vegetable oil"],"mt":1},{"n":"Brigadeiro (brasilianisches Schokoladenkonfekt)","c":"dessert","k":"Brasilien","p":25,"t":45,"d":2,"v":1,"l":"en","g":["1 Dose gezuckerte Kondensmilch (395 g)","1 EL Butter","3 EL Kakaopulver","1 Packung Schokostreusel (482 g)"],"s":["In einem schweren Topf die Milch, Kakaopulver und Butter zu kombinieren. Umrühren, um die Schokolade aufzulösen.","Niedrige Hitze überziehen und ständig umrühren, um die Bildung von Klumpen zu vermeiden.","Rühren Sie 10–12 Minuten weiter, oder bis Sie den Boden des Topfes eine Sekunde lang sehen können, wenn Sie ihn seitlich mit dem Löffel kratzen. Je mehr Sie kochen, desto härter werden die daraus resultierenden Süßigkeiten sein – es kann von flüssigen Fudge zu harten Süßigkeiten variieren.","Die Mischung abkühlen lassen.","Buttern Sie Ihre Hände, und rollen Sie die Mischung in kleine Kugeln (ca. 2 cm im Durchmesser). Alternativ können Sie die Bonbons mit zwei Metalllöffeln formen. Rollen Sie sie in die Schokoladenstreuer."],"x":["Sollten Sie versehentlich harte Bonbons bekommen, füllen Sie den Topf mit Wasser und lassen Sie sich ausruhen – die Bonbons lösen sich vollständig auf und der Topf wird leicht zu reinigen sein.","Sie können 100 g Backschokolade für das Kakaopulver ersetzen. Wenn Sie eine leichtere Süßigkeiten wollen, verwenden Sie pulverförmige Schokolade (wie Nestlé Quick). Sie können auch Rosinen oder Nüsse in die Mitte der Süßigkeiten. Sie können stattdessen mit Puderzucker oder Kakaopulver dekorieren.","Brasilianische Brigadeiros haben auch Gourmet-Sorten. Einige Referenzen sind in spezialisierten Häusern in Brasilien verfügbar: Maria Brigadeiro und Brigadeiríssimo und Brigadeiro Gourmet"],"desc":"Brigadeiro ist eine einfache brasilianische Schokolade Fudge Süßigkeiten in den 1920er Jahren erstellt. Benannt ist es nach dem brasilianischen Flieger Eduardo Gomes (Brigadeiro war sein Rang in der Luftwaffe). Es wird häufig mit Soda, Kaffee oder Milch serviert.","img":"Brigadeiro.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Brigadeiro_(Brazilian_Chocolate_Fudge)","i":"wb-en-1061","im":["a/a4/Brigadeiro.jpg/960px-Brigadeiro.jpg","User Mayra (Maych) on Flickr","CC BY-SA 2.0","Brigadeiro.jpg","r"],"on":"Brigadeiro (Brazilian Chocolate Fudge)","og":["1 can (395 g) of sweetened condensed milk","1 tablespoon of butter","3 tablespoons of cocoa powder","1 box (482 g) of chocolate sprinkles"],"mt":1},{"n":"Brioche-Füllung","c":"saucen","k":"","p":4,"t":65,"d":1,"v":0,"l":"en","g":["2 Tassen Brioche, grob gehackt","½ Tasse geschälte Walnüsse, fein gehackt","¼ Tasse getrocknete Äpfel, grob gehackt","Salz, nach Geschmack","Pfeffer, nach Geschmack","¼ Tasse Honig","¼ Tasse ungesalzene Butter, in kleine Würfel geschnitten","2 EL brauner Zucker","¼ Tasse gewürfelte rote Zwiebel","2 Zehen Knoblauch, zerdrückt und fein gehackt","½ TL getrockneter, geriebener Salbei","¼ Tasse gewürfelter Staudensellerie"],"s":["Kombinieren Sie alle Zutaten in einer tiefen Bratpfanne. Drücken Sie in eine lockere, flache Schicht.","25 Minuten im 190 °C Ofen backen.","Temperatur auf 220 °C erhöhen und 10 Minuten backen. Servieren Sie sofort."],"x":[],"desc":"Brioche Brot ist ein leicht gesüßtes Hefebrot, das häufig in Füllanwendungen verwendet wird.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brioche_Stuffing","i":"wb-en-1062","im":["a/ae/Stuffing_a_turkey.jpg/960px-Stuffing_a_turkey.jpg","Rick Kimpel","CC BY-SA 2.0","Stuffing a turkey.jpg","w"],"on":"Brioche Stuffing","og":["2 cups brioche bread, coarsely chopped","½ cup shelled walnuts, finely chopped","¼ cup dried apples, coarsely chopped","Salt, to taste","Pepper, to taste","¼ cup honey","¼ cup unsalted butter, cut into small cubes","2 tbsp brown sugar","¼ cup diced red onion","2 cloves garlic, smashed and minced","½ tsp dried rubbed sage","¼ cup diced celery"],"mt":1},{"n":"Britischer Christmas Pudding","c":"brot","k":"England","p":4,"t":0,"d":2,"v":0,"l":"en","g":["450 g gemischtes Trockenobst (Rosinen, Korinthen)","55 g Mehl","100 g brauner Zucker","½ Zitrone","½ Orange","40 g frische weiße Semmelbrösel","40 g gehackte Mandeln","2 Eier","75 g Butter","1 kleiner Apfel"],"s":["Kombinieren Sie alle getrockneten gemischten Früchte in einer großen Schüssel. Rühren Sie gut um.","Mischen Sie das Mehl, dann den Zucker, Zitrone, Orange, Brotkrumen und Nüsse.","Rühre Eier in einer separaten Schüssel. Eier in die trockenen Zutaten mischen.","Dampfen Sie den Pudding für mehrere Stunden, entfernen Sie ihn, und setzen Sie es an einem kühlen Ort.","Mit Butter, Sahne, Custard oder Brandy servieren."],"x":[],"desc":"Weihnachtspudding ist ein traditionelles britisches Gericht, das zu Weihnachten serviert wird. Briten in verschiedenen Regionen können dieses Gericht mit unterschiedlichen Namen nennen. Traditioneller Weihnachtspudding kann mit beschichteter Butter, Sauce oder sogar Sahne serviert werden. Außerdem kann es fast 6 Wochen vor Weihnachten gekocht werden. Br","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:British_Christmas_Pudding","i":"wb-en-1063","im":["e/e5/Christmas_pudding_%2811927643275%29.jpg/960px-Christmas_pudding_%2811927643275%29.jpg","James Petts from London, England","CC BY-SA 2.0","Christmas pudding (11927643275).jpg","w"],"on":"British Christmas Pudding","og":["450 g dried mixed fruit (raisins, currants)","55 g flour","100 g brown sugar","½ lemon","½ orange","40 g fresh white breadcrumbs","40 g chopped almonds","2 eggs","75 g butter","1 small apple"],"mt":1},{"n":"Brokkoli-Burger","c":"veggie","k":"","p":4,"t":0,"d":2,"v":1,"l":"en","g":["2 Eier (Größe M)","240 ml gehackter Brokkoli","120 ml gehackte geröstete Mandeln","190 ml gehackte rote Zwiebel","120 ml gewürzte Semmelbrösel","80 ml Wasser","Salz, nach Geschmack","Pfeffer, nach Geschmack","geröstete Brötchen oder Brot","Mayonnaise","Blattsalat"],"s":["In einer Schüssel Eier schlagen.","Brokkoli, Mandeln, Zwiebeln, Brotkrumen und Wasser einrühren.","Salz und Pfeffer nach Geschmack hinzufügen.","Auf einem geölten 30x38 cm (30 x 38 cm) Backblech, formen Sie die Mischung in 4 Patties, jeweils 2 cm dick.","Im 190 °C Ofen backen, halb durch Kochen drehen, bis jede Seite goldbraun ist, insgesamt etwa 25 Minuten.","Auf Brötchen mit Mayonnaise und Salat servieren."],"x":[],"desc":"Brokkoli Burger sind ein handgeführtes Lebensmittel, ähnlich wie Hamburger, obwohl mit Eiern und Gemüse anstelle von Rindfleisch produziert.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Broccoli_Burgers","i":"wb-en-1064","on":"Broccoli Burgers","og":["2 standard eggs","240 ml (1 cup) chopped broccoli","120 ml (½ cup) chopped toasted almonds","190 ml (¾ cup) chopped red onion","120 ml (½ cup) seasoned dry bread crumbs","80 ml (¼ cup) water","Salt to taste","Pepper, to taste","Toasted buns or bread","Mayonnaise","Lettuce"],"mt":1},{"n":"Brokkoli-Kugel (Auflauf)","c":"welt","k":"","p":8,"t":0,"d":2,"v":0,"l":"en","g":["1,35 kg gehackter TK-Brokkoli, aufgetaut","½ Tasse Margarine","½ Tasse Mehl","1 EL parve Hühnersuppenpulver","1 Tasse Wasser","1 Tasse Mayonnaise","2 EL Zwiebelsuppen-Mischung","6 Eier","½ TL Pfeffer","4 TL Pinienkerne"],"s":["Backofen auf 175 °C vorheizen.","Margarine schmelzen und Mehl einrühren.","Fügen Sie Wasser, Hühnersuppe Kraft und Mayonnaise, und rühren, bis verdickt.","Von der Hitze entfernen und die restlichen Zutaten hinzufügen.","In 23 x 33 cm (22x33-cm) Pfanne geben und ca. 1 Stunde backen, bis die Mitte fest ist."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Broccoli_Kugel","i":"wb-en-1065","im":["e/ef/Noodle_Kugel.jpg/960px-Noodle_Kugel.jpg","Off-shell","CC BY-SA 4.0","Noodle Kugel.jpg","w"],"on":"Broccoli Kugel","og":["3 lbs frozen chopped broccoli, thawed","½ cup margarine","½ cup flour","1 tablespoon parve chicken soup powder","1 cup water","1 cup mayonnaise","2 tablespoons onion soup mix","6 eggs","½ teaspoon pepper","4 teaspoons pine nuts"],"mt":1},{"n":"Brokkolisalat","c":"salate","k":"","p":12,"t":0,"d":1,"v":0,"l":"en","g":["700–800 g Brokkoliröschen","7–8 Scheiben knusprig gebratener Speck, zerbröselt (Räucherspeck passt gut)","1 rote oder milde Zwiebel, gehackt (am besten Vidalia)","1 Apfel, gehackt (optional)","80 g Rosinen, in kochendem Wasser eingeweicht","250 g Mayonnaise","110 g Zucker (oder die entsprechende Menge Süßstoff)","40 g Pekannüsse oder Sonnenblumenkerne","Spritzer Apfelessig oder Zitronensaft"],"s":["Whisky Mayonnaise, Zucker und Essig zusammen.s","Restliche Zutaten mischen und vollständig in einer großen Schüssel kombinieren.","Deckung.","Vor dem Servieren im Kühlschrank über Nacht abkühlen."],"x":["Kühlen lassen.","Kann mit zusätzlichen Pekannüssen oder Sonnenblumenkernen serviert werden, die über die Oberseite gestreut sind.","2 Bündel Brokkoli sollten genug Floretten liefern. Wenn nicht, dann fügen Sie Stängel und Stiel (gekielt und fein gehackt)."],"desc":"Dieser Brokkolisalat wird oft bei Potlucks serviert.","img":"MayoBroccoliSalad.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Broccoli_Salad","i":"wb-en-1066","im":["1/1d/MayoBroccoliSalad.jpg/960px-MayoBroccoliSalad.jpg","Jonathunder","CC BY-SA 3.0","MayoBroccoliSalad.jpg","r"],"on":"Broccoli Salad","og":["7–8 cups (700–800 g / 1.5–1.8 lb) broccoli florets","7–8 slices of crisp fried bacon, crumbled (smoked bacon works well)","1 red or sweet onion, chopped (Vidalia are recommended)","1 apple, chopped (optional)","1 cup (80 g / 2.8 oz) raisins, plumped in boiling water","1 cup (250 g / 8.8 oz) mayonnaise","½ cup (110 g / 3.9 oz) granulated sugar (or equivalent artificial sweetener)","½ cup (40 g / 1.4 oz) pecans or sunflower seeds","dash of cider vinegar or lemon juice"],"mt":1},{"n":"Gegrilltes Hüftsteak","c":"fleisch","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["1 Hüftsteak (Top Sirloin) (auch Top Butt oder Hüftsteak aus dem Mittelstück genannt)","Salz","frisch gemahlener schwarzer Pfeffer","Olivenöl"],"s":["Platzieren Sie einen Rack in das obere Drittel eines Ofens mit einem Broiler an der Spitze (dies funktioniert nicht mit einer Broilerschublade). Legen Sie noch eine rechts darunter. Legen Sie ein Tablett Aluminiumfolie auf den unteren Rack. Den Broiler vorheizen.","Bürsten Sie Steak auf beiden Seiten mit Olivenöl. Beide Seiten mit Salz und frisch gemahlenem schwarzem Pfeffer liberal würzen.","Legen Sie das Steak auf den oberen Rack. Stecken Sie ein Sondenthermometer in den dicksten Teil des Steaks. Die Ofentür mit einer Folie leicht offen halten und kochen, bis die Kerntemperatur 60 °C für mittlere Seltenheit, 68 °C für mittlere und 74 °C für Toast erreicht.","Auf eine Platte nehmen und mit Aluminiumfolie bedecken. Lassen Sie 7 Minuten vor dem Schneiden auf die Neigung über das Getreide ruhen. Warm servieren."],"x":[],"desc":"Ja, all diese Grill-Websites sagen, dass Sirloin nicht so zart ist, aber sie reden wahrscheinlich über Bottom-Sirloin. Top-Sirloin ist fast so gut wie ein Ribeye. Es ist saftig, zart und geschmackvoll.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Broiled_Sirloin_Steak","i":"wb-en-1067","on":"Broiled Sirloin Steak","og":["1 top sirloin steak (also known as a top butt and center cut sirloin steak)","Salt","Freshly-ground black pepper","Olive oil"],"mt":1},{"n":"Eintopf mit braunen Bohnen","c":"suppen","k":"","p":4,"t":15,"d":1,"v":0,"l":"en","g":["Öl oder Butter","übriges gegartes Gemüse und Fleisch, in mundgerechte Stücke geschnitten","1 Zwiebel, gehackt","1 Lauch, in dünne Scheiben geschnitten oder gehackt","1 Paprikaschote, gewürfelt","Salz","Pfeffer","Chilipulver","850 g braune Bohnen aus der Dose (kann in Tomatensoße sein)","400 g gehackte Tomate","400 g Reis oder 1,4 kg Kartoffeln, gegart zum Servieren"],"s":["Einen Topf bei mittlerer Hitze mit einem Schuss Öl erhitzen. Das Fleisch dazugeben und auf Wunsch etwas durchbraten und leicht braun braten.","Die Zwiebeln dazugeben und bis leicht weich und durchscheinend kochen.","Rühren Sie den Lauch, Paprika und jedes andere Gemüse, das Sie verwenden. Mit Salz, Pfeffer und Chilipulver abschmecken.","Bedecken Sie die Pfanne und schwitzen, bis das Gemüse nach Wunsch gekocht wird.","Die Bohnen und die gehackte Tomate in die Mischung geben und bis zum Erhitzen kochen.","Mit dem Reis oder Kartoffeln servieren."],"x":[],"desc":"Brauner Bohneneintopf ist ein billiges und leicht zu präparierendes Gericht, das besonders nützlich ist, um übrig gebliebenes Fleisch, Pilze und Gemüse im Kühlschrank zu verwenden.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brown_Bean_Stew","i":"wb-en-1068","im":["a/ac/Ugandan_brown_bean_stew.jpg/960px-Ugandan_brown_bean_stew.jpg","Roxanne.heston","CC0","Ugandan brown bean stew.jpg","c"],"on":"Brown Bean Stew","og":["Oil or butter","Leftover cooked vegetables and meat, cut into bite-size pieces","1 onion, chopped","1 leek, sliced thin or chopped","1 bell pepper, diced","Salt","Pepper","Chili powder","850 g canned brown beans (can be in tomato sauce)","400 g chopped tomato","400 g rice or 1.4 kg potatoes, cooked for serving"],"mt":1},{"n":"Kekse mit brauner Butter","c":"brot","k":"","p":20,"t":30,"d":1,"v":0,"l":"en","g":["125 g Butter","½ Tasse feiner Zucker","1 Ei","1 TL Vanilleextrakt","2 ½ Tassen selbsttreibendes Mehl (Mehl mit Backpulver)"],"s":["Heizen Sie den Ofen auf . Zeile 2 Backbleche.","Die Butter in einer Pfanne bei mittlerer Hitze 3–5 Minuten lang schmelzen, bis die Oberfläche schaumig ist.","Lassen Sie es für 5 Minuten abkühlen.","Bis zum Auflösen in den Zucker rühren.","Lassen Sie es für 10–15 Minuten kühl bis lauwarm.","In die Eier und Vanille schlagen.","In das Mehl falten, bis es kombiniert wird.","Den Teig in 20 Kugeln rollen und auf die vorbereiteten Backbleche legen.","Die Kekse mit einer Gabel glätten.","Für 12–14 Minuten golden backen.","Übertragen Sie die Kekse auf eine Drahtstange und lassen Sie sie abkühlen."],"x":[],"desc":"Braune Butterkekse ist ein Rezept, das von Seite 42 der Juli/August 2022 Ausgabe des Tesco Magazins angepasst wurde.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brown_Butter_Biscuits","i":"wb-en-1069","on":"Brown Butter Biscuits","og":["1 stick (125 g/4.4 oz) butter","½ cup () superfine sugar","1 egg","1 teaspoon vanilla extract","2½ cups () self-rising flour"],"mt":1},{"n":"Schokoladenkekse mit brauner Butter und Toffee","c":"brot","k":"","p":9,"t":2940,"d":3,"v":0,"l":"en","g":["#Toffee","90 g ungesalzene Butter","140 g locker gedrückter heller brauner Zucker","1 TL grobes Salz","Wasser, nach Bedarf","#Keksteig","250 g ungesalzene Butter","4 Eiswürfel","160 g Zucker","270 g fest gedrückter heller brauner Zucker","2 TL Espressopulver","2 TL grobes Salz","½ TL Natron","2 Eier (Größe M) (100 g)","2 TL Vanilleextrakt","350 g Weizenmehl","170 g Zartbitterschokolade (50 bis 70 % Kakao), gehackt","Meersalzflocken, zum Bestreuen"],"s":["Legen Sie ein Backblech mit Backpapier.","Butter, Zucker und Salz bei mittlerer Hitze in einem Topf schmelzen. Fügen Sie Wasser, wenn nötig, um Fett von der Trennung zu halten. Kochen Sie weiter, bis die Temperatur 150 °C beträgt und wenn sie in Wasser fallen, bildet sie spröde Fäden.","Den Toffee auf die vorbereitete Backform geben. Einfrieren bis gebrauchsfertig, ca. 30 Minuten.","In der Zwischenzeit ein weiteres Backblech mit Backpapier.","Die Butter in einem Topf schmelzen und kochen, bis sie dunkelbraun wird. Entfernen Sie aus der Hitze.","Fügen Sie einen Eiswürfel auf die Butter und lassen Sie sie schmelzen. Mit restlichen Eiswürfeln wiederholen.","Kombinieren Sie Zucker, Espressopulver, Salz und Backnatron in einer großen Schüssel.","Die braune Butter in die Zuckermischung geben und zusammenschlagen.","In die Eier und Vanille schlagen.","In das Mehl falten, bis es kombiniert wird.","Entfernen Sie das Toffee aus dem Gefrierschrank und brechen in Stücke. Stecken Sie in eine reißbare Tasche und brechen in Bits mit einem Rollstift.","Toffee und Schokolade in den Teig geben und zusammenfalten.","Den Teig auf das Backblech schütteln und 48 Stunden lang abkühlen lassen, damit sich Aromen entwickeln.","Nach dem Backen den Ofen auf 163 °C vorheizen. Linie 2 Backbleche mit Backpapier.","Die Kekse auf den Backblechen anordnen, wobei mindestens 5 cm (5 cm) Raum zwischen einander liegen.","Für 18–20 Minuten goldbraun backen.","Die Kekse aus dem Ofen nehmen und mit etwas Meersalz bestreuen, bevor sie abkühlen lassen."],"x":[],"desc":"Brown Butter Toffee Schokolade Chip Cookies sind geschmacksvolle Kekse, und es dauert 48 Stunden für den Teig, um die Aromen zu entwickeln. Dieses Rezept wird vom YouTube-Kanal Tasty angepasst.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brown_Butter_Toffee_Chocolate_Chip_Cookies","i":"wb-en-1070","im":["b/b4/Choco_chip_cookie.png/500px-Choco_chip_cookie.png","brainloc on sxc.hu (Bob Smith)","CC BY 2.5","Choco chip cookie.png","w"],"on":"Brown Butter Toffee Chocolate Chip Cookies","og":["#Toffee","¾ stick (90 g / 3 oz) unsalted butter","¾ cup (140 g / 5 oz) lightly packed light brown sugar","1 teaspoon kosher salt","Water, as needed","#Cookie dough","1 cup (2 sticks / 250 g / 9 oz) unsalted butter","4 ice cubes","¾ cup (160 g / 5.5 oz) white granulated sugar","1½ cups (270 g / 9.5 oz) packed light brown sugar","2 teaspoons espresso powder","2 teaspoons kosher salt","½ teaspoon baking soda","2 ea. (100 g) standard eggs","2 teaspoons vanilla extract","2½ cups (350 g / 12.5 oz) all-purpose flour","6 oz (170 g) dark chocolate (50–70% cacao), chopped","Flaky sea salt, for sprinkling"],"mt":1},{"n":"Braune Soße","c":"veggie","k":"","p":1,"t":0,"d":2,"v":1,"l":"en","g":["2 EL fein gehackte Zwiebel","2 EL Pflanzenöl","1 TL Salz","Pfeffer, nach Geschmack","2 EL Mehl","1 ½ Tassen Gemüsebrühe (oder Rinder- oder Pilzbrühe)","1 TL Hefeextrakt"],"s":["Die Zwiebel im Öl bei mittlerer Hitze mit Salz und Pfeffer anbraten, bis die Zwiebel goldbraun zu werden beginnt. Mehl dazugeben und umrühren. Ein Roux sollte sich bilden; Kochen Sie es für einige Minuten, bis es beginnt zu verdunkeln.","Die Brühe dazugeben und glatt umrühren. Fügen Sie den Hefeextrakt hinzu – da die Soße erwärmt, wird er eingearbeitet. Geschmack und Saison bei Bedarf. Wenn die Soße köchelt, ist es erledigt.","In ein Soßeboot oder einen anderen Servierbehälter einreiben und einige Minuten vor dem Servieren abkühlen lassen."],"x":[],"desc":"Braune Soße ist eine grundlegende Soße ähnlich dem, was Sie mit einem Beutel von Supermarkt Instant Soße erhalten.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brown_Gravy","i":"wb-en-1071","im":["8/88/Wine_sauces_on_the_sauceboat.jpg/960px-Wine_sauces_on_the_sauceboat.jpg","Peachyeung316","CC BY-SA 4.0","Wine sauces on the sauceboat.jpg","w"],"on":"Brown Gravy","og":["2 Tbsp finely-minced onion","2 Tbsp vegetable oil","1 tsp salt","Pepper to taste","2 Tbsp flour","1½ cup vegetable stock (or beef or mushroom stock)","1 tsp yeast extract"],"mt":1},{"n":"Frühstücksschale mit Naturreis","c":"veggie","k":"","p":4,"t":0,"d":1,"v":1,"l":"en","g":["½ Tasse Hafermilch","1 ½ Tassen gekochter Naturreis","4 Datteln, gehackt","2 Prisen Zimt","¼ Tasse ungesalzene Kürbiskerne"],"s":["Kombinieren Sie alle Zutaten und servieren."],"x":["Sofort brauner Reis wird gut funktionieren."],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brown_Rice_Breakfast_Bowl","i":"wb-en-1072","on":"Brown Rice Breakfast Bowl","og":["½ cup oat milk","1 ½ cups cooked brown rice","4 dates, chopped","2 pinches of cinnamon","¼ cup unsalted pumpkin seeds"],"mt":1},{"n":"Naturreis-Auflauf","c":"beilagen","k":"USA","p":6,"t":0,"d":1,"v":1,"l":"en","g":["230 g gewürfelter Schmelzkäse","1 Dose Pilze (115 g)","1 Dose Erbsen (430 g)","3 Tassen gekochter Naturreis","Backtrennspray","½ Tasse Mandelstifte"],"s":["Backofen auf 175 °C vorheizen.","Kombinieren Sie Käse, Pilze, Erbsen und Reis in einer großen Schüssel.","Überzug 11⁄2 quart Backform mit Kochspray.","Verschieben Sie gemischte Zutaten in Backform.","Bedecken und für 20 bis 25 Minuten backen.","Mandeln darüber bestreuen","Noch 5 Minuten backen."],"x":["Sofort brauner Reis wird gut funktionieren.","Pilz \"Stämme und Stücke\" sind in Ordnung."],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brown_Rice_Casserole","i":"wb-en-1073","on":"Brown Rice Casserole","og":["8 ounces cubed processed cheese","1 can (4 ounces) mushrooms","1 can (15 ounces) sweet peas","3 cups cooked brown rice","cooking spray","½ cup slivered almonds"],"mt":1},{"n":"Naturreis mit Putenhack","c":"fleisch","k":"","p":4,"t":30,"d":2,"v":0,"l":"en","g":["2 Tassen gekochter Naturreis","570 g extramagere Putenhackbrust","1 Dose gewürfelte Tomaten mit grünen Chilis (340 g)","30 g Pflanzenöl","1 EL Teriyaki-Soße","Gewürze (z. B. Knoblauchpulver, Zitronenpfeffer, Piment usw.), nach Geschmack"],"s":["Spray Pfanne mit Kochspray, und bestreuen Sie Knoblauchpulver und andere Gewürze. Fügen Sie Truthahn, und zerbröckeln, wie es kocht. Tomaten dazugeben und mit dem Truthahn vermischen, bis der Truthahn gekocht ist.","Fügen Sie Kochen Öl zu einem Wok oder tiefe Pfanne. 1 Teelöffel Allspice und/oder andere Gewürze hinzufügen.","Als Pfanne erwärmt langsam fügen Sie gekochten Reis (Achtung für das Splattern von heißem Öl). Wenn Reis gleichmäßig erhitzt wird, fügen Sie Teriyaki-Sauce hinzu und mischen Sie sie gleichmäßig.","Wenn gemahlener Truthahn fertig gekocht wird, fügen Sie es zu Reis in Wok hinzu, mischen Sie ihn gründlich und servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brown_Rice_with_Ground_Turkey","i":"wb-en-1074","on":"Brown Rice with Ground Turkey","og":["2 cups cooked brown rice","20 ounces of extra lean ground turkey breast","1 can (12 ounces) diced tomatoes with green chiles","1 ounce vegetable oil","1 tablespoon teriyaki sauce","Seasonings to taste (e.g. garlic powder, lemon pepper, allspice, etc.)"],"mt":1},{"n":"Naturreis mit anderen Stärkebeilagen und Gemüse (Pandoras Festmahl)","c":"veggie","k":"","p":1,"t":45,"d":2,"v":2,"l":"en","g":["#Boden","1 Tasse ungekochter Naturreis","2 Tassen Wasser","#Zugaben","1 Tasse eingeweichte und gekochte schwarze, Pintobohnen, Kidneybohnen oder andere Bohnen","1 Tasse gewürfelte Kartoffel","1 Tasse gewürfelte Süßkartoffel","1 Tasse gewürfelter Kürbis","1 Zehe Knoblauch, fein gehackt","1 Tasse gewürfelte Rote Bete","1 Tasse gehackter Grünkohl","#Servieren","Olivenöl, Hanföl, Leinöl, oder ein anderes hochwertiges Öl","Hefeflocken","Sojasoße","schwarzer Sesam"],"s":["Den braunen Reis und Wasser in einen Reiskocher geben.","Abtropfen, abspülen und die Bohnen in den Reiskocher geben.","Wenn Sie verwenden, fügen Sie den Knoblauch in den Herd.","Bei Verwendung die Süßkartoffel, Squash, Rübe oder Kartoffel hinzufügen.","Wenn mit einem fuzzy Logik (d.h. programmierbar) Kocher, stellen Sie den Herd auf die braune Reis Einstellung und schalten Sie es ein. Wenn Sie einen Ein-/Aus-Herd verwenden, schalten Sie ihn einfach ein.","In ca. 20–40 Minuten sollte Ihr Kocher den Reis fertig kochen. Wenn Sie fertig sind, öffnen Sie den Deckel, fügen Sie den Kohl hinzu, schließen Sie den Deckel, und warten Sie etwa eine oder zwei Minuten.","Öffnen und servieren. Oben mit Öl, Hefe, Sojasauce und/oder Sesamsamen nach Geschmack."],"x":["Wenn Sie \"Thai süßen schwarzen Reis\" oder \"Chinese verbotenen schwarzen Reis\" haben, ersetzen Sie etwa 10% Ihres braunen Reis mit diesem, und Ihr fertiges Produkt wird ein schönes lila und einen anderen Geschmack haben.","Das gewürfelte Gemüse sollte 1cm x 1cm für ein optimales Kochen sein."],"desc":"Pandora's Fest ist eine komplette vegane Mahlzeit, die mehrmals in der Woche serviert werden kann aufgrund der Leichtigkeit, mit der es modifiziert werden kann. Die Mahlzeit ist leicht in einem Reiskocher zuzubereiten.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brown_Rice_with_Other_Starches_and_Vegetables_(Pandora's_Feast)","i":"wb-en-1075","on":"Brown Rice with Other Starches and Vegetables (Pandora's Feast)","og":["#Base","1 cup uncooked brown rice","2 cups water","#Additions","1 cup soaked and boiled black, pinto, kidney or other beans","1 cup cubed potato","1 cup cubed sweet potato","1 cup cubed squash","1 clove garlic, minced","1 cup cubed beet","1 cup chopped kale","#Serving","Olive oil, hemp oil, flaxseed oil, or other nutritious oil","Nutritional yeast","Soy sauce","Black sesame seeds"],"mt":1},{"n":"Braune Soße (Hartshorne)","c":"saucen","k":"","p":50,"t":10,"d":1,"v":0,"l":"en","g":["1 EL Zucker","2 EL französischer Essig","3 EL Olivenöl","1 EL Senf","1 EL Salz","1 EL Pfeffer"],"s":["Zucker, Essig, Olivenöl, Senf, Salz und Pfeffer vermischen.","In einer Flasche servieren oder lagern."],"x":[],"desc":"Brown Sauce ist eine würzige, leicht süße Soße mit gekochtem Frühstück und Chips (Fries).","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brown_Sauce_(Hartshorne)","i":"wb-en-1076","im":["e/e1/Fried_breakfast_with_brown_sauce.jpg/960px-Fried_breakfast_with_brown_sauce.jpg","Bob Peters","CC BY 2.0","Fried breakfast with brown sauce.jpg","w"],"on":"Brown Sauce (Hartshorne)","og":["1 tbsp sugar","2 tbsp French vinegar","3 tbsp olive oil","1 tbsp mustard","1 tbsp salt","1 tbsp pepper"],"mt":1},{"n":"Brownies mit braunem Zucker","c":"brot","k":"USA","p":2,"t":60,"d":1,"v":1,"l":"en","g":["1 Tasse fest gedrückter heller brauner Zucker","½ Tasse Butter oder Margarine, weich","2 Eier","55 g ungesüßte Schokolade (2 Stücke), geschmolzen","½ Tasse Weizenmehl","1 Tasse grob gehackte Walnüsse"],"s":["Backofen auf 165 °C vorheizen.","Fetten Sie eine 8 x 20 x 5 cm große Backform.","Sahnezucker und Butter bis flauschig.","In Eiern schlagen.","Schlagen in geschmolzene Schokolade.","Mit Mehl vermischen, dann Nüsse einrühren.","In vorbereitete Pfanne gießen.","Backen Sie etwa 25 Minuten.","In der Pfanne abkühlen und in Quadrate schneiden."],"x":["Die Brownies können auch in einem holländischen Ofen bei mäßig langsamer Hitze statt in der Backform gebacken werden."],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brown_Sugar_Brownies","i":"wb-en-1077","im":["8/84/2026-06-23_01_49_46_Brown_sugar_brownies_in_Westampton_Township%2C_Burlington_County%2C_New_Jersey.jpg/960px-2026-06-23_01_49_46_Brown_sugar_brownies_in_Westampton_Township%2C_Burlington_County%2C_New_Jersey.jpg","Famartin","CC BY-SA 4.0","2026-06-23 01 49 46 Brown sugar brownies in Westampton Township, Burlington County, New Jersey.jpg","c"],"on":"Brown Sugar Brownies","og":["1 cup packed light brown sugar","½ cup (1 stick) butter or margarine, softened","2 eggs","2 ounces (2 squares) unsweetened chocolate, melted","½ cup all-purpose flour","1 cup coarsely-chopped walnuts"],"mt":1},{"n":"Guss aus braunem Zucker","c":"veggie","k":"USA","p":1,"t":0,"d":1,"v":1,"l":"en","g":["320 g brauner Zucker","1 TL Vanille","165 ml Sahne","1 EL Butter"],"s":["Zucker und Sahne zusammenkochen, bis sich ein weicher Ball in kaltem Wasser bildet.","Cool bis .","Vanille und Butter zugeben; Schlagen, bis dick genug, um sich zu verbreiten."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brown_Sugar_Icing","i":"wb-en-1078","on":"Brown Sugar Icing","og":["2 cups (320 g / 11 oz) brown sugar","1 teaspoon vanilla","⅔ cup (165 ml / 5.6 oz) cream","1 tablespoon butter"],"mt":1},{"n":"Glühweingewürz mit braunem Zucker","c":"saucen","k":"","p":1,"t":0,"d":1,"v":0,"l":"en","g":["1 Tasse brauner Zucker","2 TL gemahlener Zimt","1 TL gemahlene Nelken","1 TL gemahlene getrocknete Orangenschale","1 TL gemahlener Piment","½ TL gemahlene Muskatnuss"],"s":["Kombinieren Sie alle Zutaten in einer mittleren Schüssel.","Rühren Sie mit Draht bis gut gemischt.","In einem luftdichten Behälter an einem kühlen Ort aufbewahren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brown_Sugar_Mulling_Spice_Mix","i":"wb-en-1079","on":"Brown Sugar Mulling Spice Mix","og":["1 cup () brown sugar","2 teaspoons ground cinnamon","1 teaspoon ground cloves","1 teaspoon dried ground orange peel","1 teaspoon ground allspice","½ teaspoons ground nutmeg"],"mt":1},{"n":"Kekse mit braunem Zucker und Muskat","c":"brot","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["375 g Weizenmehl","3 g Weinstein","2 g Natron","0,8 g gemahlene Muskatnuss","205 g Backfett, geschmolzen und leicht abgekühlt","440 g fest gedrückter brauner Zucker","2 Eier","5 ml Vanilleextrakt"],"s":["Mehl, Tortencreme, Sodabacken und Muskatnuss in einer Schüssel kombinieren. Beiseite legen.","In einer großen Schüssel die geschmolzene Verkürzung und den braunen Zucker zusammenschlagen. In die Eier schlagen, dann den Vanille-Extrakt. Nach und nach in die trockenen Zutaten mischen.","Teig in ein Holz mit einem Durchmesser von 11⁄2 Zoll formen. Wickeln Sie Log in gewachste Papier oder Folie und kühlen für 4 Stunden oder über Nacht.","Backofen auf 180 °C vorheizen. Leicht fetten 2 Backbleche.","Schnitt in Scheiben 1⁄4 Zoll dick log. Die Scheiben 2,5 cm auseinander auf die Backbleche legen.","8–10 Minuten backen, bis sie leicht gefärbt sind. Cool auf Drahtträgern."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Brown_Sugar_Nutmeg_Cookies","i":"wb-en-1080","on":"Brown Sugar Nutmeg Cookies","og":["375 g all-purpose flour","3 g cream of tartar","2 g baking soda","0.8 g ground nutmeg","205 g shortening, melted and cooled slightly","440 g packed brown sugar","2 eggs","5 ml vanilla extract"],"mt":1},{"n":"Gebräunter Reis","c":"beilagen","k":"","p":4,"t":90,"d":1,"v":0,"l":"en","g":["120 g ungekochter Reis","1 Dose Rinderkraftbrühe","55 g Margarine","1 kleine Zwiebel, gehackt"],"s":["Zwiebel bei mittlerer Hitze in Margarine anbraten.","Reis und Consommé in einer Backform mischen. Zwiebel und Margarine über Reis und Consommé gießen und vermischen.","30 Minuten bei 180 °C backen.","Aus dem Ofen nehmen, und fügen Sie 1⁄2 kann Wasser über Reis Mischung.","Überdecken und kochen Sie weitere 30 Minuten."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Browned_Rice","i":"wb-en-1081","on":"Browned Rice","og":["½ cup (120 g) uncooked rice","1 can beef consommé","½ stick margarine","1 small onion, chopped"],"mt":1},{"n":"Bruschetta","c":"snacks","k":"Italien","p":4,"t":10,"d":1,"v":1,"l":"en","g":["#Boden","1 Laib italienisches oder französisches Brot, schräg in 1,25 cm dicke Scheiben geschnitten","½ Kopf Knoblauch","grobes Salz oder Meersalz","frisch gemahlener schwarzer Pfeffer","natives Olivenöl extra","Beläge nach Wahl (Beispiele siehe unten)","#Beläge","gehackte Tomaten mit Rucola oder Basilikum","gekochte weiße Bohnen (nach Belieben mit gebratenem Grünkohl)","gebratene Pilze (am besten wilde Sorten)","gehackte Sardellen mit Weinessig und Kräutern","dünne Pancetta-Scheiben, unter dem Grill knusprig gemacht","gehacktes Sommergemüse nach apulischer Art (rote Zwiebel, Gurke, Tomaten, Oregano, glatte Petersilie, Basilikum und Chiliflocken)"],"s":["Toast die Brotscheiben im Toaster, unter einem Broiler oder auf einem Grill, bis sie golden.","Sofort das Brot mit der Schnittseite des Knoblauchs reiben. Mit Salz und schwarzem Pfeffer bestreuen und großzügig mit Olivenöl extra vergine beträufeln.","Servieren Sie warm gekrönt mit allen Kombinationen von saisonalen Zutaten, die Sie wählen."],"x":[],"desc":"Dieser Artikel beschreibt allgemeine Zubereitungsverfahren für die beliebte italienische Vorspeise (oder Antipasta) Bruschetta (Plural Bruschette), Scheiben geröstetes oder gegrilltes Brot mit Knoblauch gerieben, mit Olivenöl beträufelt und mit Salz und Pfeffer gewürzt. Diese Grundpräparation wird häufig mit c","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bruschetta","i":"wb-en-1082","im":["1/1f/2014_Bruschetta_The_Larder_Chiang_Mai.jpg/960px-2014_Bruschetta_The_Larder_Chiang_Mai.jpg","Takeaway","CC BY-SA 4.0","2014 Bruschetta The Larder Chiang Mai.jpg","w"],"og":["#Base","1 loaf of Italian or French bread, sliced ½ inch (1.25 cm) thick on the bias","½ head garlic","Kosher salt or sea salt","Freshly-ground black pepper","Extra-virgin olive oil","Toppings of your choice (see examples below)","#Toppings","Chopped tomatoes with arugula or basil","Cooked white beans (topped, if you like, with sautéed kale)","Sautéed mushrooms (preferably wild varieties)","Minced anchovies flavored with wine vinegar and herbs","Thinly-sliced pancetta crisped under the broiler","Pugliese-style chopped mixture of summer vegetables (red onion, cucumber, tomatoes, oregano, flat-leaf parsley, basil, and red pepper flakes)"],"mt":1},{"n":"Bryndzové halušky (slowakische Nocken mit Schafskäse)","c":"beilagen","k":"","p":2,"t":0,"d":2,"v":0,"l":"en","g":["750 g Kartoffeln, geschält und fein gerieben","Salz (optional)","250 g Weizenmehl (glattes Mehl, hladká múka)","250 g Brimsen (Schafskäse), in sehr kleine Stücke geschnitten","100 g Speck (geräucherter Speck, údená slanina), gegart und in kleine Stücke geschnitten"],"s":["Die geriebenen Kartoffeln mit Mehl und Salz zu einem Teig kombinieren.","Den Teig in kleine zylindrische Stücke von weniger als 3 cm Größe formen.","Übertragen Sie die Knödel in einen Topf mit kochendem Salzwasser. Wenn die Knödel an die Spitze des kochenden Wassers steigen, entfernen Sie eine, um sicherzustellen, dass sie gründlich gekocht werden.","Die Knödel mit einem Schlitzlöffel aus dem Topf nehmen und auf eine erwärmte Platte übertragen.","Unmittelbar nach dem Knödeln werden auf die Platte gelegt, den Käse darüber streuen, und lassen Sie den Käse über die Knödel schmelzen. Mischen, wenn gewünscht.","Die knusprigen Speckstücke auf den Käse streuen.","Servieren Sie heiße Rohrleitungen."],"x":["Wenn in Eile, versuchen Sie den aus-kratzenden Halusky durch store-bought Kartoffel Gnocchi zu ersetzen.","Wenn Sie Bryndze nicht finden können, können Sie gebröckelten Ziegenkäse oder eine von mehreren Arten von zerfallenen Feta ersetzen. Einige Feta sind stärker geschmacklich, was hier vorzuziehen ist."],"desc":"Bryndzové halušky ist ein slowakisches Knödelgericht. Die Zutat, die dieses nationale Gericht der Slowakei zu einem Favoriten macht, ist der Schafsmilchkäse, der einen etwas schärferen Geschmack hat als der nicht-aromatisierte Ziegenkäse, der in vielen US-Lebensmittelgeschäften erhältlich ist. Die reichliche Zutat ist die rohe Kartoffel","img":"Bryndzové halušky so slaninou.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Bryndzové_Halušky_(Slovak_Dumplings_with_Cheese)","i":"wb-en-1083","im":["a/ad/Bryndzov%C3%A9_halu%C5%A1ky_so_slaninou.jpg/960px-Bryndzov%C3%A9_halu%C5%A1ky_so_slaninou.jpg","Gregory finster","CC0","Bryndzové halušky so slaninou.jpg","r"],"on":"Bryndzové Halušky (Slovak Dumplings with Cheese)","og":["750 g potatoes, peeled and finely grated","Salt (optional)","250 g all-purpose flour (hladkej múky)","250 g bryndze cheese, cut into very small pieces","100 g bacon (údenej slaniny), cooked and cut into small pieces"],"mt":1},{"n":"Bua Loi (Reisbällchen in süßer Kokosmilch)","c":"dessert","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["2 Tassen süßes Klebreismehl","1 Tasse gedämpfte, zerdrückte Taroknolle","¼ Tasse Wasser","Kokosmilch"],"s":["Kombinieren Sie Reismehl, mashed Taro und Wasser zu einem Teig.","Den Teig in kleine Kugeln formen, mit zusätzlichem Reismehl, um das Kleben zu verhindern.","Bringen Sie einen großen Topf mit Wasser zum Kochen. Die Teigkugeln in das kochende Wasser geben. Sie werden zunächst sinken, aber nach und nach an die Oberfläche schweben, während sie kochen.","Entfernen Sie die gekochte bua loi aus dem Topf, und das Wasser abtropfen lassen.","Übertragen Sie die bua loi auf ein Gericht und servieren Sie mit Kokosmilch. Dieses Gericht wird am besten heiß serviert."],"x":["Wenn Sie Ihre bua loi bunter machen möchten, können Sie Kürbis (gelb) oder Pandan (grün) hinzufügen."],"desc":"Bua loi ist ein traditionelles Thai Reismehl Dessert. Es ist oft für religiöse oder rituelle Zeremonien vorbereitet, aber es kann auch als tägliches Gericht gegessen werden. Bua loi sind oft hell gefärbt mit verschiedenen Zutaten (siehe Anmerkungen).","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bua_Loi_(Rice_Balls_in_Sweet_Coconut_Milk)","i":"wb-en-1084","im":["f/fc/Bualoi_Boiled_flour_balls_with_coconut_milk.jpg/500px-Bualoi_Boiled_flour_balls_with_coconut_milk.jpg","Kapook.com","CC BY-SA 4.0","Bualoi Boiled flour balls with coconut milk.jpg","w"],"on":"Bua Loi (Rice Balls in Sweet Coconut Milk)","og":["2 cups sweet glutinous rice flour","1 cup steamed and mashed taro root","¼ cup water","Coconut milk"],"mt":1},{"n":"Buah Melaka (malaysische Klößchen mit Palmzucker)","c":"dessert","k":"Malaysia","p":4,"t":0,"d":2,"v":0,"l":"en","g":["15 Pandanblätter","3 Tassen Wasser","3 Tassen Klebreismehl","Gula Melaka (Palmzucker), in kleine Stücke geschnitten","Kokosraspel","Salz"],"s":["Kombinieren Sie die geriebene Kokosnuss und eine Prise Salz zusammen, dann legen Sie sie in ein Gericht. Für später beiseite legen.","Verwenden Sie einen Mixer oder Mörtel, um die Pandanblätter und das Wasser zusammenzumahlen. Die Mischung durch ein Sieb gießen und die Feststoffe wegwerfen.","Das Reismehl und die Pandan-Flüssigkeit in einer Schüssel kombinieren und gut kneten, um einen Teig zu machen.","Schneide Stücke des Teiges ab und rolle sie in Kugeln. Sie sollten etwa 1–5 cm (2,5–5 cm) Durchmesser haben.","Verwenden Sie Ihre Hände, um einen Ball zu glätten oder eine kleine Tasche in der Mitte, so dass Platz für ein Stück Zucker. Legen Sie ein Stück Zucker in die Mitte, dann kneifen Sie den Teig um den Zucker geschlossen.","Den gefüllten Knödel vorsichtig wieder in einen Ball rollen.","Wiederholen Sie den Füll- und Formprozess für alle Teigstücke.","Bringen Sie 2 L Wasser zum Kochen in einem tiefen Topf.","Fügen Sie die Knödel in den Topf, arbeiten in Chargen, wenn nötig, um das Verdrängen der Pfanne zu vermeiden. Kochen Sie, bis die Knödel an die Oberfläche steigen – kochen Sie nicht zu hart, da Sie die Knödel nicht platzen wollen.","Entfernen und entleeren Sie die Knödel.","Während immer noch heiß, rollen Sie die gekochten Knödel in der Platte der Kokosnuss, bis sie vollständig beschichtet sind."],"x":[],"desc":"","img":"Onde-onde.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Buah_Melaka_(Malaysian_Palm_Sugar_Dumplings)","i":"wb-en-1085","im":["4/4d/Onde-onde.jpg/960px-Onde-onde.jpg","Yun Huang Yong from Harbord, Australia","CC BY-SA 2.0","Onde-onde.jpg","r"],"on":"Buah Melaka (Malaysian Palm Sugar Dumplings)","og":["15 pandan leaves","3 cups water","3 cups glutinous rice flour","Gula melaka palm sugar, cut into small pieces","Grated coconut","Salt"],"mt":1},{"n":"Bubble Tea","c":"getraenke","k":"Taiwan","p":1,"t":30,"d":1,"v":1,"l":"en","g":["125 ml gekochte Tapiokaperlen (Boba)","250 ml Crushed Ice","250 ml sehr starker, kalter schwarzer Tee","250 ml Milch, nach Geschmack","Honig oder Zucker, nach Geschmack"],"s":["Legen Sie Perlen in ein großes Glas.","Kombinieren Sie alle restlichen Zutaten in einem Cocktail-Shaker. Schütteln Sie kräftig, bis die Mischung schaumig ist.","In Glas geben und mit großen Durchmesser Strohhalmen servieren."],"x":["Wenn Sie nicht wollen, dass das Getränk schäumt, rühren Sie einfach die Zutaten zusammen, anstatt zu zittern."],"desc":"Bubble Tea ist ein Teegetränk mit schwarzen Tapioka-Perlen gemischt in.","img":"Classic bubble tea.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Bubble_Tea","i":"wb-en-1086","im":["1/18/Classic_bubble_tea.jpg/500px-Classic_bubble_tea.jpg","Oqmilteashop","CC BY-SA 3.0","Classic bubble tea.jpg","r"],"og":["½ cup (125 ml) cooked boba tapioca pearls","1 cup (250 ml) crushed ice","1 cup (250 ml) very strong chilled black tea","1 cup (250 ml) milk, to taste","Honey or granulated sugar, to taste"],"mt":1},{"n":"Bubble and Squeak (Bratkartoffeln mit Kohl)","c":"beilagen","k":"Großbritannien","p":4,"t":15,"d":1,"v":0,"l":"en","g":["1 mittelgroße Zwiebel (optional), gehackt","1 EL Fett oder Öl","verschiedenes gegartes Gemüse (z. B. Kartoffeln, Kohl, Möhren, Erbsen und/oder Rosenkohl)"],"s":["Die gehackte Zwiebel in Fett oder Öl braten.","Das Gemüse hacken und in die Pfanne geben.","Kochen Sie über eine mittlere Hitze, bis die Unterseite goldbraun und knusprig ist, dann drehen Sie es und kratzen die knusprigen Bits in die Mischung. Wiederholen Sie das Drehen und Abkratzen ein paar Mal, bis gebräunt und gekocht durch."],"x":[],"desc":"Bubble and quietak ist ein traditionelles englisches Gemüsegericht aus dem übrig gebliebenen Gemüse aus einem Sonntagsbraten. Der Name leitet sich vom Klang ab, den das Gericht beim Kochen macht.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bubble_and_Squeak","i":"wb-en-1087","im":["3/31/-2021-12-03_Pan_fried_Bubble_and_squeak%2C_Trimingham%2C_Norfolk_%284%29.JPG/960px--2021-12-03_Pan_fried_Bubble_and_squeak%2C_Trimingham%2C_Norfolk_%284%29.JPG","Kolforn","CC BY-SA 4.0","-2021-12-03 Pan fried Bubble and squeak, Trimingham, Norfolk (4).JPG","w"],"on":"Bubble and Squeak","og":["1 medium onion (optional), chopped","1 tablespoon fat or oil","Various cooked vegetables (e.g. potatoes, cabbage, carrots, peas, and/or Brussels sprouts)"],"mt":1},{"n":"Bubur Candil (süße Klebreisbällchen in Kokossoße)","c":"suppen","k":"Indonesien","p":4,"t":0,"d":1,"v":1,"l":"en","g":["#Teig","225 g Klebreismehl","120 g Tapiokamehl","175 ml Wasser","¼ TL Salz","#Soße","750 ml Wasser","250 ml Kokosmilch","125 ml verdünnter Gula Jawa (Palmzucker) (Palmzucker)","1 Stück Pandanblatt (oder etwas Pandanpaste)","¼ TL Salz","#Servieren","300 ml Kokosmilch, ein paar Minuten gekocht"],"s":["Reismehl und Tapiokamehl gut mischen. In der Mitte einen Brunnen machen, dann nach und nach mit Wasser und Salz vermischen. Von Hand gut vermischen, bis es einen weichen Teig bildet. Achten Sie darauf, dass der Teig nicht zu hart ist; Bei Bedarf etwas mehr Wasser hinzufügen.","Den Teig in kleine Kugeln ca. 1 cm Durchmesser formen.","In einem großen Topf viel Wasser kochen. Legen Sie die kleinen Kugeln eins nach dem anderen in das kochende Wasser. Für ca. 5 Minuten kochen, bis sie an die Oberfläche des kochenden Wassers schweben. Bringt sie raus und entwässert sie.","Für die Sauce, mischen Sie alle Sauce Zutaten in einem Topf, und erhitzen, bis sprudelnd.","Legen Sie die Reisbällchen in die Sauce. Für weitere 20 Minuten kochen und beiseite stellen.","Zum Servieren die Kokosmilch darüber gießen. Heiß servieren."],"x":[],"desc":"Bubur Candil sind traditionelle indonesische glutinöse Reisbällchen in einer süßen Kokossauce.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bubur_Candil_(Sweet_Glutinous_Rice_Balls_in_Coconut_Sauce)","i":"wb-en-1088","im":["4/4e/Bubur_Candil%2C_Mutiara%2C_dan_Sumsum.jpg/960px-Bubur_Candil%2C_Mutiara%2C_dan_Sumsum.jpg","Fhikri Latifi","CC BY 4.0","Bubur Candil, Mutiara, dan Sumsum.jpg","c"],"on":"Bubur Candil (Sweet Glutinous Rice Balls in Coconut Sauce)","og":["#Dough","225 g glutinous rice flour","120 g tapioca flour","175 ml water","¼ tsp salt","#Sauce","750 ml water","250 ml coconut milk","125 ml diluted gula jawa (palm sugar)","1 piece pandan leaf (or some pandan paste)","¼ tsp salt","#Serving","300 ml coconut milk, boiled for few minutes"],"mt":1},{"n":"Bubur Ketan Hitam (süßer schwarzer Reis mit Kokosmilch)","c":"dessert","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["#Brei","250 g schwarzer Klebreis","1 ½ l Wasser","2 Pandanblätter","250 g Kokosblütenzucker oder Palmzucker, ein paar Minuten in der Mikrowelle erwärmt, damit es sich leicht auflöst","1 Prise Salz","#Kokosmilchsoße","350 ml dicke Kokosmilch","¼ TL Salz","2 Pandanblätter"],"s":["Schwarzer Glutenreis über Nacht in Wasser einweichen.","Den Reis abtropfen lassen. Mit Wasser und Pandanblätter weich und dick kochen.","Kokoszucker und Salz hinzufügen und weiter kochen, bis der Zucker gelöst ist und das Wasser absorbiert wird.","Dicke Kokosmilch mit Salz und Pandan für ein paar Minuten kochen.","Den schwarzen Reispudding in einer Schüssel servieren und Kokosmilchsauce darüber gießen."],"x":["Zusätzliche Toppings können hinzugefügt werden, wie z.B. in Scheiben geschnittene gebackene Banane, braunes Zuckerpulver oder Zimtpulver."],"desc":"Bubur Ketan Hitam ist ein Gericht aus schwarzem Glutin Reis Pudding mit Kokosmilch.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bubur_Ketan_Hitam_(Sweet_Black_Rice_with_Coconut_Milk)","i":"wb-en-1089","im":["2/29/Bubuh_Injin_Bali_1.jpg/960px-Bubuh_Injin_Bali_1.jpg","Gunawan Kartapranata","CC BY-SA 4.0","Bubuh Injin Bali 1.jpg","w"],"on":"Bubur Ketan Hitam (Sweet Black Rice with Coconut Milk)","og":["#Porridge","250 grams black glutinous rice","1 ½ litres water","2 pandan leaves","250 grams coconut sugar or palm sugar, microwaved for couple minutes to dissolve easily","1 pinch salt","#Coconut milk sauce","350 ml thick coconut milk","¼ teaspoon salt","2 pandan leaves"],"mt":1},{"n":"Buckeyes (Erdnussbutterkugeln mit Schokolade)","c":"dessert","k":"","p":25,"t":12,"d":1,"v":1,"l":"en","g":["320 g Erdnussbutter","2 EL geschmolzene Butter","1 TL Vanille","3 Tassen Puderzucker","1 kleiner Beutel Halbbitter-Schokotropfen","25 Zahnstocher"],"s":["Erdnussbutter, geschmolzene Butter, Vanille und Puderzucker in einer Schüssel mischen.","Die Mischung in 2,5 cm Kugeln formen.","Legen Sie einen Zahnstocher in jede Kugel.","Eine Stunde kühlen oder einfrieren.","Die halbsüßen Schokoladenchips in einem Doppelkessel schmelzen.","Tauchen Sie die Kugeln in der geschmolzenen Schokolade, so dass ein kleiner freigelegter Kreis an der Spitze.","Auf Backpapier legen und Zahnstocher entfernen.","Kühlen oder einfrieren."],"x":[],"desc":"Buckeyes sind ein einfacher Snack, der aus ihrer Ähnlichkeit mit der Nuss des Buckeye-Baumes benannt wird.","img":"Buckeyes Peanut Butter Balls.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Buckeyes","i":"wb-en-1090","im":["e/e1/Buckeyes_Peanut_Butter_Balls.jpg/330px-Buckeyes_Peanut_Butter_Balls.jpg","Steven Depolo","CC BY 2.0","Buckeyes Peanut Butter Balls.jpg","r"],"on":"Buckeyes","og":["1 cup (320 g/11 oz) peanut butter","2 tablespoons melted butter","1 teaspoon vanilla","3 cups () powdered sugar","1 small bag () semi-sweet chocolate chips","25 toothpicks"],"mt":1},{"n":"Buchweizen-Crêpes","c":"kuchen","k":"Frankreich","p":12,"t":0,"d":1,"v":0,"l":"en","g":["500 g Buchweizenmehl","1 l Wasser","1 TL Salz","1 Ei (optional, siehe Hinweis)","Butter zum Braten","Füllungen nach Wunsch"],"s":["Das Mehl und das Salz in einer Rührschüssel zusammenrühren.","In das Ei und die Hälfte des Wassers, um einen Teig zu machen.","Den Teig mit einem Tuch bedecken und bei Raumtemperatur 1 Stunde ruhen lassen.","Allmählich im restlichen Wasser nach Bedarf rühren, um die richtige Konsistenz zu erhalten. Es muss dünn genug sein, um die Pfanne zu fliessen und zu beschichten, aber nicht so wässrig, dass der Pfannkuchen beim Kochen nicht bindet. Möglicherweise müssen Sie nicht das ganze Wasser hinzufügen.","Bereiten Sie Ihre gewünschten Füllungen im Voraus vor. Alles, was mehr als 1 Minute zum Kochen benötigt (z.B. Zwiebeln, Pilze, Fleisch usw.) sollte vorgekocht werden.","Erhitzen Sie eine große flache Pfanne (ca. 30 cm im Durchmesser) bei mittlerer Hitze.","Wenn die Pfanne heiß ist, schmieren Sie sie mit einem Dab Butter (beginnen Sie mit etwa einem Esslöffel), und verteilen, so dass es schmilzt und überzieht die Pfanne. Der Teig kann schnell eingestellt, so dass Sie das Volumen der Butter für die ersten paar Pfannkuchen verwendet anpassen müssen.","Pfanne genug Teig in die Pfanne, so dass Sie einen großen Pfannkuchen nicht mehr als 3 mm dick nach dem Ausbreiten erhalten.","Lassen Sie den Pfannkuchen kochen, bis er auf der oberen Oberfläche trocken und leicht golden auf dem Boden ist. Benutze einen Spatel, um ihn auf die andere Seite zu drehen.","Wenn Sie den Pfannkuchen nicht sofort füllen, kochen bis golden auf der anderen Seite, dann entfernen und beiseite stellen (siehe Notizen).","Wenn Sie den Pfannkuchen füllen werden, arrangieren Sie die Zutaten in der Mitte, so dass mehrere Zentimeter / Zoll nackt rund um die Füllung. Einmal auf der Unterseite gekocht, vier Kanten des Pfannkuchens in die Mitte falten, um die Füllung zu schließen und ein Quadrat zu machen.","Entfernen und servieren heiß.","Kochen Sie weiter, bis der Rest des Teiges verbraucht ist."],"x":["Es gibt eine Debatte darüber, ob man Eier in den Teig aufnehmen sollte. Es scheint als Stabilisator zu wirken, abhängig von der Qualität des verwendeten Mehls.","Wenn Sie die Galette vollständig falten (siehe Bild), können Sie sie noch einmal nach dem Befüllen umdrehen, ohne dass das Risiko besteht, dass die Füllung entweicht. Dies gibt Ihnen ein wenig zusätzliche Zeit zum Erhitzen oder Kochen der Füllung, wenn nötig.","Wenn Sie die Pfannkuchen vor dem Füllen vorkochen oder kaufen, sollten Sie sie in einer Pfanne vor dem Füllen erwärmen. Dazu einfach eine Pfanne über mittlerer Hitze buttern, den Pfannkuchen flach in die Pfanne legen und wie oben beschrieben füllen/falten. Stellen Sie sicher, dass alles gut erwärmt wird."],"desc":"Buchweizen-Crêpes sind eine Art herzhaftes Crêpe aus der Oberen Bretagne, das mit Buchweizenmehl hergestellt wird. Sie werden lokal als \"galettes de blé noir\" oder \"galettes de sarrasin\" bezeichnet und werden traditionell freitags gegessen. Heutzutage werden diese zu Hause gekocht, in Crêperies serviert und können ein typisches Takeaway-Gericht sein. Ich","img":"Galette de sarrasin complète bretonne.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Buckwheat_Crêpes","i":"wb-en-1091","im":["0/08/Galette_de_sarrasin_compl%C3%A8te_bretonne.jpg/960px-Galette_de_sarrasin_compl%C3%A8te_bretonne.jpg","Arnaud 25","CC BY-SA 4.0","Galette de sarrasin complète bretonne.jpg","r"],"on":"Buckwheat Crêpes","og":["500 g buckwheat flour","1 L water","1 tsp salt","1 egg (optional; see note)","Butter for cooking","Fillings as desired"],"mt":1},{"n":"Buchweizen-Ingwer-Bananenkuchen mit Schokolade","c":"kuchen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["135 g Buchweizenmehl","1 TL Backpulver","1 TL Natron","60 ml Ahornsirup","60 ml ungesüßtes Apfelmus","Saft von ½ Zitrone","1 EL geriebener frischer Ingwer (8 g)","3 sehr reife Bananen (die Schale sollte dunkle Flecken haben)","30 g grob gehackte Zartbitterschokolade oder Schokotropfen"],"s":["Backofen auf 170 °C vorheizen.","Das Buchweizenmehl, das Backpulver und das Backnatron in einer Schüssel vermischen und beiseite stellen.","Den Ahornsirup mit der Apfelmus, dem Zitronensaft und dem geriebenen Ingwer vermischen. Die Bananen mit der Rückseite einer Gabel zerdrücken, bevor sie mit den anderen feuchten Zutaten gemischt werden.","Kombinieren Sie die trockenen Zutaten mit der Bananenmischung. Achten Sie darauf, nicht zu übermixen – Sie wollen nicht alle Luft schlagen.","Sobald alles gut gemischt ist, die dunkle Schokolade dazugeben und wieder sanft mischen.","Eine Tortenpfanne (20 x 20 cm/20 x 20 cm) mit Backpapier auslegen und den Teig hineingießen.","In den Ofen legen und ca. 45 Minuten backen oder bis ein Zahnstocher in der Mitte sauber herauskommt."],"x":[],"desc":"Dieser Ingwer-Bananenkuchen wird mit Buchweizenmehl hergestellt, wodurch er glutenfrei ist. Ursprünglich geschrieben bei Foodista von Anne Pedersen. Foodista Rezepte werden unter einer CC-BY Lizenz veröffentlicht.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Buckwheat_Ginger_Banana_Cake_with_Chocolate","i":"wb-en-1092","im":["c/c8/Vegan_Banana_Celebration_Cake_%285061766386%29.jpg/960px-Vegan_Banana_Celebration_Cake_%285061766386%29.jpg","Vegan Feast Catering","CC BY 2.0","Vegan Banana Celebration Cake (5061766386).jpg","w"],"on":"Buckwheat Ginger Banana Cake with Chocolate","og":["1 cup (135 g) buckwheat flour","1 tsp baking powder","1 tsp baking soda","¼ cup (60 ml/70 g) maple syrup","¼ cup (60 ml/65 g) unsweetened applesauce","Juice of ½ lemon","1 tbsp (8 g) grated fresh ginger","3 very ripe bananas (should have dark spots on the peel)","¼ cup (30 g) roughly-chopped dark chocolate or chocolate chips"],"mt":1},{"n":"Buffalo-Hähnchen-Sandwich","c":"snacks","k":"USA","p":1,"t":0,"d":1,"v":0,"l":"en","g":["Öl zum Braten","½ Tasse Mehl","½ TL Salz","½ Tasse Milch","1 Hähnchenbrustfilet ohne Haut, flach geklopft","1 Hamburgerbrötchen","1 Blatt grüner Blattsalat","2 Tomatenscheiben","1 rote Zwiebel in Scheiben (wenn sie kräftig ist, nur ein paar Ringe)","2 EL scharfe Soße","Blauschimmelkäse-Dressing"],"s":["Gerade genug Öl erhitzen, um das Huhn in einer großen Bratpfanne oder einem Frittier auf 175 °C zu decken.","Mehl und Salz zusammenrühren. Hühnchen in der Milch, dann Mehlmischung, wieder in der Milch, dann Mehl ein zweites Mal. Kühlen Sie Huhn für 10-15 Minuten.","Das Huhn 10 Minuten in Öl oder goldbraun tief braten. Abtropfen auf ein Gestell.","Toast oder Grill das Gesicht des Brötchens.","Hühnchen in eine Schüssel mit Deckel geben. Heiße Sauce hinzufügen, Deckel aufsetzen und vorsichtig schütteln.","Hähnchen auf Brötchen und oben mit Salat und Tomaten. Servieren Sie offenes Gesicht, mit blauem Käse Dressing auf der Seite."],"x":[],"desc":"Ein Buffalo-Hühnchen-Sandwich ist ein Sandwich, das aus Stücken von knochenlosem Buffalo-Hühnchen und blauem Käse auf einer U-Boot-Sandwich-Rolle besteht. Das Rezept ist für ein Sandwich. Es kann verdoppelt werden, verdreifacht, vervierfacht, etc., aber braten Sie das Huhn ein Stück nach dem anderen.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Buffalo_Chicken_Sandwich","i":"wb-en-1093","im":["1/1f/Chicken_salad_sandwich_01.jpg/960px-Chicken_salad_sandwich_01.jpg","Lara604","CC BY-SA 2.0","Chicken salad sandwich 01.jpg","w"],"on":"Buffalo Chicken Sandwich","og":["Oil for frying","½ cup flour","½ teaspoon salt","½ cup milk","1 boneless skinless chicken breast, pounded flat","1 hamburger bun","1 leaf green leaf lettuce","2 tomato slices","1 red onion sliced (if it's strong, only use a few rings)","2 tablespoon hot sauce","Blue cheese dressing"],"mt":1},{"n":"Buffalo Wings (scharfe Hähnchenflügel)","c":"snacks","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["48 Hähnchenflügel-Mittelstücke","Öl zum Frittieren","Geflügelgewürz zum Streuen, nach Bedarf","½ Tasse ungesalzene Butter, geschmolzen","½ Tasse rauchige scharfe Chipotle-Soße","¼ Tasse Tomatenmark","1 EL Sojasoße","Chiliblätter, optional"],"s":["Huhn mit dem Geflügelshake bestreuen.","Öl auf 180 °C erhitzen. Die Hühnerstücke in das heiße Öl geben und 11 Minuten braten. Auf einem Kühlregal abtropfen lassen.","In der Zwischenzeit, kombinieren übrige Zutaten. Fügen Sie Flügel und werfen, um zu beschichten und servieren.","Mit den Chiliblättern garnieren, wenn gewünscht."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Buffalo_Wings","i":"wb-en-1094","im":["5/51/Buffalo_wings-01.jpg/960px-Buffalo_wings-01.jpg","Clotee Pridgen Allochuku","CC BY 2.0","Buffalo wings-01.jpg","w"],"on":"Buffalo Wings","og":["48 chicken wingettes","Oil for deep frying","Poultry Shake, as needed","½ cup unsalted butter, melted","½ cup Smoky Chipotle Hot Sauce","¼ cup tomato paste","1 tbsp soy sauce","Chili leaves, optional"],"mt":1},{"n":"Bulgarische frische Würstchen (Kebaptscheta)","c":"fleisch","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 kg Hackfleisch (etwa 60 % Schwein und 40 % Rind)","Salz, nach Geschmack","½ TL Kreuzkümmel","½ TL schwarzer Pfeffer","2–3 EL Wasser"],"s":["Das Fleisch salzen und gut mit Gewürzen und Wasser vermischen.","Decken, und lassen Sie im Kühlschrank für 1–2 Tage stehen. Dies ist der wichtigste und schwierigste Teil des Rezepts, da das Ziel ist es, das Fleisch zu gären.","Mischen Sie sich zu länglichen Risssohlen (hautlose Würste), indem Sie am Ende durch einen Schleifer mit einem Trichter gehen.","Grillwürste bei mittlerer Hitze. Drehen Sie nicht mehr als einmal beim Grillen – das mehrfache Flippen erzeugt ein trockenes statt saftiges Produkt.","Servieren Sie heiß mit Ihrer Wahl der Seiten. Am besten mit goldenen Pommes frites und kaltem Bier."],"x":["Wenn das Hackfleisch sehr mager ist, ändern Sie das Verhältnis zu 75% Schweinefleisch + 25% Rindfleisch – sonst wird die Kepabcheta trocken sein. Das Ziel Fettgehalt sollte etwa 30% Fett, wie ein US-Stil Burger.","Kebapche enthält keine Zwiebel, die in der damit verbundenen Schale namens Kyufte gefunden wird.","Wenn das Fleisch gut vergoren ist, sieht das gekochte Produkt aufgeblasen aus (vergleiche mit einem Walmart-Burger, der beim Kochen schrumpft)."],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bulgarian_Fresh_Sausage_(Kebapcheta)","i":"wb-en-1095","im":["9/92/Kebapche_bg.jpg/960px-Kebapche_bg.jpg","Ikonact","CC BY-SA 3.0","Kebapche bg.jpg","w"],"on":"Bulgarian Fresh Sausage (Kebapcheta)","og":["1 kg minced meat (approximately 60% pork + 40% beef)","Salt to taste","½ teaspoon cumin","½ teaspoon black pepper","2–3 tablespoons water"],"mt":1},{"n":"Bulgarische Fleischbällchensuppe (Supa Toptscheta)","c":"suppen","k":"Bulgarien","p":4,"t":0,"d":2,"v":0,"l":"en","g":["450 g Rinderhack","6 EL Reis","1 TL Paprikapulver","1 TL getrocknetes Bohnenkraut","Salz, nach Geschmack","Pfeffer, nach Geschmack","6 Tassen Wasser","2 Rinderbrühwürfel","½ Bund Frühlingszwiebeln, in Scheiben geschnitten","1 grüne Paprika, gehackt","2 Möhren, geschält und in dünne Scheiben geschnitten","3 Tomaten, geschält und gehackt","½ Bund Petersilie, fein gehackt","1 Ei","1 Zitrone, ausgepresst"],"s":["Kombinieren Sie Rindfleisch, Reis, Paprika und herzhaft.","Mit Salz und Pfeffer abschmecken und leicht, aber gründlich mischen.","Mischen in 2,5 cm (2,5 cm) Kugeln, dann in Mehl rollen.","Kombinieren Sie Wasser, Bouillonwürfel, 1 Esslöffel Salz, 1 Teelöffel Pfeffer, grüne Zwiebeln, grüner Pfeffer, Karotten und Tomaten in großen Topf. Bedecken, zum Kochen bringen, Wärme reduzieren und 30 Minuten köcheln lassen.","Fleischbällchen hinzufügen, abdecken und wieder zum Kochen bringen. Hitze reduzieren und 20 Minuten köcheln lassen.","Chilis zugeben und köcheln lassen, bedeckt, 40 Minuten oder bis Reis gekocht wird.","Fügen Sie Petersilie während der letzten 5 Minuten Kochzeit hinzu. Geschmack und fügen Sie mehr Salz und Pfeffer, wenn nötig.","Kurz vor dem Servieren Ei mit Zitronensaft schlagen. 1 bis 2 Esslöffel heiße Suppe in die Eiermischung einrühren und dann die Eimischung in die Suppe rühren.","Schonend erhitzen, rühren, bis die Suppe leicht verdickt ist, aber nicht kochen lassen."],"x":[],"desc":"Supa topcheta ist eine beliebte bulgarische Suppe.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bulgarian_Meatball_Soup_(Supa_Topcheta)","i":"wb-en-1096","im":["c/cb/Soup_with_meatballs-01.jpg/500px-Soup_with_meatballs-01.jpg","ralphhogaboom","CC BY-SA 2.0","Soup with meatballs-01.jpg","w"],"on":"Bulgarian Meatball Soup (Supa Topcheta)","og":["1 lb (450 g) ground beef","6 Tbsp rice","1 tsp paprika","1 tsp dried savory","Salt to taste","Pepper to taste","6 cups water","2 beef bouillon cubes","½ bunch green onions, sliced","1 green bell pepper, chopped","2 carrots, peeled and sliced thin","3 tomatoes, peeled and chopped","½ bunch parsley, minced","1 egg","1 lemon, juiced"],"mt":1},{"n":"Bulgarische Kuttelsuppe (Schkembe Tschorba)","c":"suppen","k":"Bulgarien","p":4,"t":0,"d":2,"v":0,"l":"en","g":["1 EL Butter","3 ½ Tassen Rinderfond","1 Zwiebel, fein gehackt","1 TL Salz","1 Paprikaschote, in dünne Streifen geschnitten","½ TL getrockneter Majoran","1 Lorbeerblatt","2 EL Mehl","2 EL Petersilie, fein gehackt","1 Dose Tomatenmark (180 g)","1 Knoblauchzehe, zerdrückt","675 g Kutteln, gegart","⅔ Tasse geriebener Kaschkawal"],"s":["Zwiebel, roter Pfeffer, Butter in großen Topf mischen.","Mehl über Zwiebelmischung streuen, dann die Tomatenpaste einrühren.","In dünne Streifen schneiden.","Tripe Stücke, Brühe, Salz, Majoran und Lorbeerblatt zur Zwiebelmischung hinzufügen.","Teilweise den Topf bedecken und 30 Minuten köcheln lassen.","Entfernen und wegwerfen Lorbeerblatt.","Suppe in eine Pute geben oder in einzelnen Schüsseln servieren.","In einer kleinen Schüssel Petersilie, Knoblauch und Käse kombinieren. Über heiße Suppe streuen und sofort servieren."],"x":[],"desc":"Shkembe chorba ist ein beliebtes Fleischgericht in der bulgarischen Küche.","img":"Shkembe-chorba.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Bulgarian_Tripe_Soup_(Shkembe_Chorba)","i":"wb-en-1097","im":["1/10/Shkembe-chorba.jpg/960px-Shkembe-chorba.jpg","Kiril Kapustin","CC BY 2.5","Shkembe-chorba.jpg","r"],"on":"Bulgarian Tripe Soup (Shkembe Chorba)","og":["1 tbsp butter","3½ cup beef stock","1 ea. onion, chopped fine","1 tsp salt","1 ea. bell pepper, cut into thin-strips","½ tsp dried marjoram","1 ea. bay leaf","2 tbsp flour","2 tbsp parsley, chopped fine","1 can (6 oz / 180 g) tomato paste","1 ea. garlic clove, crushed","1½ lb (675 g) tripe, cooked","⅔ cup grated Kashkaval cheese"],"mt":1},{"n":"Bulgogi","c":"fleisch","k":"Korea","p":6,"t":0,"d":2,"v":0,"l":"en","g":["450 g Rindfleisch zum Grillen, so dünn wie möglich geschnitten","3 Frühlingszwiebeln, schräg geschnitten","4 weiße Champignons (optional), in Scheiben geschnitten","½ Zwiebel (optional), in dünne Scheiben geschnitten","¾ Tasse Sojasoße","¼ Tasse Zucker","¼ Tasse Sesamöl","4 TL Pfeffer","1–2 EL fein gehackter Knoblauch","1 EL Mirin (optional)"],"s":["Kombinieren Sie alle Zutaten in einer großen Schüssel. Marinate für mindestens 30 Minuten, aber marinieren über Nacht wird den besten Geschmack und Ausschreibung erhalten.","Grillen Sie das Rindfleisch.","Mit Reis servieren."],"x":["Verwenden Sie die gleiche Menge an Sojasauce und Zucker.","Wenn Sie dies einen Tag vor, reduzieren Sie die Menge an Soja-Sauce und vergessen Sie nicht, es in einem Kühlschrank.","Verwenden Sie dünn geschnittenes Rindfleisch, das speziell für Bulgogi in einigen Lebensmittelgeschäften erhältlich ist, für beste Ergebnisse.","Sie können dies auf einer Tischplatte grillen, mit einer flachen Pfanne. Sie können auch nur eine normale Bratpfanne verwenden.","Grillen Sie bei mittlerer Hitze und den Saft von Rindfleisch und Gemüse auf Reis.","Sie können das Rindfleisch in Cola (Coca-Cola funktioniert am besten) marinieren, anstatt nur Zucker zu verwenden. Die extra Flüssigkeit hilft dem Fleisch, die Marinade schneller zu absorbieren."],"desc":"","img":"Korean.food-Bulgogi-01.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Bulgogi","i":"wb-en-1098","im":["c/c8/Korean.food-Bulgogi-01.jpg/960px-Korean.food-Bulgogi-01.jpg","brappy! (a flickr user)","CC BY-SA 2.0","Korean.food-Bulgogi-01.jpg","r"],"og":["1 lb (450 g) beef suitable for grilling, sliced as thin as possible","3 green onions, sliced on the bias","4 button mushrooms (optional), sliced","½ onion (optional), thinly sliced","¾ cup soy sauce","¼ cup white granulated sugar","¼ cup (4 tbsp) sesame oil","4 tsp pepper","1–2 tbsp minced garlic","1 tbsp mirin (optional)"],"mt":1},{"n":"Bulgur-Burger","c":"veggie","k":"","p":6,"t":45,"d":3,"v":2,"l":"en","g":["3 Tassen Wasser","2 Zehen Knoblauch","1 ½ Tassen Bulgur","2 EL Pflanzenöl","½ Tasse Frühlingszwiebeln, gehackt","½ Tasse Möhren, gerieben","¼ Tasse frische Petersilie, gehackt","¼ Tasse Tahini (Sesammus)","2 EL Tomatenmark","2 EL Sojasoße","1 TL Dijonsenf","1 Spritzer gemahlener schwarzer Pfeffer"],"s":["Bringen Sie das Wasser zum Kochen.","Während es erwärmt, verwenden Sie eine schwere Pfanne oder Pfanne, um den Knoblauch und Bulghur im Öl bei mittlerer Hitze für 2 Minuten zu braten, wobei häufiges Rühren.","Das kochende Wasser in die Pfanne geben. Zurück zu kochen, abzudecken und die Hitze auf niedrig zu reduzieren.","15 bis 20 Minuten köcheln, bis das gesamte Wasser absorbiert ist und der Bulghur weich, aber immer noch kaut.","Wenn der Bulghur fertig ist, die Jakobsmuscheln, Karotten, Petersilie, Tahini, Tomatenpaste, Sojasauce, Senf und Pfeffer einrühren. Mit befeuchteten Händen die Bulghur-Mischung zu 6 bis 8 Burgern formen.","Kochen Sie die Patties in einer leicht geölten schweren Pfanne bei mittlerer Hitze für etwa 10 Minuten, drehen Sie die Burger einmal, wenn die Außenseite knusprig ist, oder backen auf einem geölten Backblech für 20 Minuten bei 190 °C."],"x":["Für einen anderen Geschmack und mehr Protein, fügen Sie 1 Tasse gekochte Kichererbsen in den gekochten Bulghur zusammen mit den anderen Zutaten, bevor die Burger bilden."],"desc":"Ein Bulgur Burger ist ein schmackhaftes vegetarisches Patty für Sandwiches.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bulgur_Burgers","i":"wb-en-1099","on":"Bulgur Burgers","og":["3 cups water","2 cloves garlic","1 ½ cups bulghur","2 tablespoons vegetable oil","½ cup scallions, chopped","½ cup carrots, grated","¼ cup fresh parsley, chopped","¼ cup tahini","2 tablespoons tomato paste","2 tablespoons soy sauce","1 teaspoon Dijon mustard","1 dash ground black pepper"],"mt":1},{"n":"Wurstbrät","c":"fleisch","k":"","p":1,"t":5,"d":1,"v":0,"l":"en","g":["2 TL brauner Zucker","2 TL getrockneter Salbei","2 TL Salz","1 TL gemahlener schwarzer Pfeffer","½ TL Knoblauchpulver","½ TL getrockneter Thymian","½ TL Paprikapulver","½ TL gemahlene Nelken","1 kg rohes Schweinehack"],"s":["Kombinieren Sie alle Zutaten außer Schweinefleisch in einer großen Tasse oder einer kleinen Schüssel zusammen.","Die Würzmischung in das rohe gemahlene Schweinefleisch kneten, bis es gleichmäßig verteilt ist.","Verwenden Sie in jedem Rezept, das für Massenwurst."],"x":["Die Gewürze und ihre Proportionen sind nicht in Stein gemeißelt. Jegliche Würze kann nach Ihrem Geschmack erhöht, verringert oder weggelassen werden. Um die Wurst würziger zu machen, fügen Sie 1⁄2 TL Cayennepfeffer und/oder heißes Chilipulver hinzu. Das gemahlene Schweinefleisch kann durch gemahlenen Truthahn ersetzt werden, wenn Sie es bevorzugen."],"desc":"In einigen Ländern, wie z. B. in den Vereinigten Staaten, wird Massenwurst in Supermärkten verkauft. Dies ist Wurst ohne Gehäuse, die beim Kochen so leicht zerbricht wie jedes andere Hackfleisch. Aber in anderen Ländern, Bulk-Wurst wird nicht als solche verkauft, so dass, wenn Sie ein Rezept folgen wollen, die für Bulk-Wurst erfordert","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bulk_Sausage","i":"wb-en-1100","im":["2/29/Wurstplatte.jpg/960px-Wurstplatte.jpg","Alice Wiegand","CC BY-SA 4.0","Wurstplatte.jpg","w"],"on":"Bulk Sausage","og":["2 tsp brown sugar","2 tsp dried sage","2 tsp salt","1 tsp ground black pepper","½ tsp garlic powder","½ tsp dried thyme","½ tsp ground paprika","½ tsp ground cloves","1 kg raw ground pork"],"mt":1},{"n":"Beerensoufflé (Bumbleberry)","c":"brot","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 Scheibe Butter","1 Tasse Himbeeren","1 Tasse Brombeeren","Eier","1 Tasse Sahne","3 EL Vanilleextrakt","1 ⅓ Tassen Zucker"],"s":["Backofen auf 165 °C vorheizen.","Die Butter in eine Backform geben und im Ofen schmelzen.","Himbeeren und Brombeeren in das Buttergericht geben.","Kombinieren Sie die Eier, Sahne, Vanille und Zucker, dann gießen Sie es über die Beeren in das Gericht.","Für 45 Minuten bis 1 Stunde backen."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bumbleberry_Souffle","i":"wb-en-1101","im":["3/37/Bacon_and_Cheddar_Cheese_Souffl%C3%A9.jpg/960px-Bacon_and_Cheddar_Cheese_Souffl%C3%A9.jpg","Mark Miller","CC BY-SA 4.0","Bacon and Cheddar Cheese Soufflé.jpg","w"],"on":"Bumbleberry Souffle","og":["1 slice butter","1 cup raspberries","1 cup blackberries","Eggs","1 cup cream","3 tbsp vanilla extract","1 ⅓ cup sugar"],"mt":1},{"n":"Bunny Chow (gefülltes Brot mit Curry)","c":"fleisch","k":"Afrika","p":4,"t":60,"d":2,"v":0,"l":"en","g":["#Curry","2 EL Pflanzenöl","1 große Zwiebel, gehackt","2 Zehen Knoblauch, fein gehackt","1 TL geriebener frischer Ingwer","2 Tomaten, gehackt","2 EL Currypulver","1 TL gemahlene Kurkuma","1 TL Paprikapulver","500 g Rindfleisch, Hammel, Hähnchen, oder Mischgemüse, in Stücke geschnitten","2 mittelgroße Kartoffeln, gewürfelt","2 Tassen Wasser oder Brühe","Salz, nach Geschmack","schwarzer Pfeffer, nach Geschmack","#Servieren","1 groß, ungeschnittenes Weißbrot","frischer Koriander (optional)"],"s":["Das Öl in einem großen Topf bei mittlerer Hitze erhitzen.","Zwiebel dazugeben und kochen, bis sie weich ist.","Knoblauch und Ingwer einrühren und 1 Minute kochen lassen.","Currypulver, Kurkuma und Paprika dazugeben. Rühren Sie bis zum Duft.","Fleisch oder Gemüse dazugeben und bis leicht gebräunt kochen.","Tomaten dazugeben und weich kochen.","Kartoffeln und Wasser dazugeben und mit etwas Salz und Pfeffer würzen.","30–40 Minuten köcheln lassen, oder bis das Fleisch und die Kartoffeln zart sind und die Soße verdickt ist. Passen Sie die Würzung bei Bedarf an.","Schneiden Sie den Laib von Brot in Hälften oder Viertel, und entfernen Sie einen Teil des weichen Innenraums aus jedem Stück, um eine Kavität zu schaffen.","Füllen Sie die Brothöhle großzügig mit heißem Curry.","Auf Wunsch mit Koriander garnieren und sofort servieren."],"x":["Die Curry kann in einem luftdichten Behälter für bis zu 3 Tage gekühlt werden. Versammele das Häschen kurz vor dem Servieren, um zu verhindern, dass das Brot ärgerlich wird."],"desc":"Bunny Chow ist ein südafrikanisches Street Food, bestehend aus einem ausgehöhlten Laib Brot gefüllt mit Curry. Das in Durban hergestellte Fleisch wird häufig mit Hammelfleisch, Huhn, Rindfleisch oder Bohnencurry zubereitet. Das Gericht ist in ganz Südafrika beliebt und wird für seine Portabilität und reichen Geschmack geschätzt. Mit einer Leistung von","img":"Quarter Mutton Bunny Chow.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Bunny_Chow","i":"wb-en-1102","im":["7/70/Quarter_Mutton_Bunny_Chow.jpg/330px-Quarter_Mutton_Bunny_Chow.jpg","Luke Comins","CC BY-SA 3.0","Quarter Mutton Bunny Chow.jpg","r"],"on":"Bunny Chow","og":["#Curry","2 tbsp vegetable oil","1 large onion, chopped","2 cloves garlic, minced","1 tsp grated fresh ginger","2 tomatoes, chopped","2 tbsp curry powder","1 tsp ground turmeric","1 tsp ground paprika","500 g (1 lb) beef, mutton, chicken, or mixed vegetables, cut in pieces","2 medium potatoes, cubed","2 cups water or stock","Salt, to taste","Black pepper, to taste","#Serving","1 large, unsliced loaf of white bread","Fresh coriander (optional)"],"mt":1},{"n":"Burgoo (Fleischeintopf aus Kentucky)","c":"suppen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["450 g gemischter Aufschnitt (Rind, Lamm, Schwein, Hähnchen, Wild usw.)","1,9 l Hühnerfond (2 l)","1,9 l Rinderfond (2 l)","30 ml Worcestersoße","1 Tasse Tomaten, gewürfelt","1 große Zwiebel, gewürfelt","1 Stange Staudensellerie, gewürfelt","1 kleine grüne Paprika, gewürfelt","1 große Kartoffel, gewürfelt","2 große Möhren, gewürfelt","¼ Tasse Erbsen","½ Tasse Okra","¼ Tasse Limabohnen","½ Tasse gelber Mais","2 TL Knoblauch, fein gehackt","Salz, nach Geschmack","Pfeffer, nach Geschmack"],"s":["Kombinieren Sie alle Zutaten in einem Topf, und zum Kochen bringen.","Wärme reduzieren und 2 Stunden köcheln lassen, die Spitze nach Bedarf abschäumen."],"x":["Traditionelles Burgoo wurde oft im Freien in einem gusseisernen Wasserkocher über einem Holzfeuer gekocht. Puristen werden darauf bestehen, dass dies stark verbessert den Geschmack."],"desc":"Burgoo ist traditionell im westlichen Kentucky und hat unendliche Variationen. Während wahre Tradition Burgoo aus Wildfleisch oder Hammelfleisch hergestellt wird, werden moderne Variationen aus BBQ Schweinefleisch und/oder Huhn hergestellt. Rezepte reichen von genug, um eine Familie zu einer ganzen Gemeinschaft zu füttern. Während gekochtes Fleisch verwendet wird, Grillfleisch","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Burgoo","i":"wb-en-1103","im":["f/f4/Kentucky_burgoo.jpg/960px-Kentucky_burgoo.jpg","Mack Male","CC BY-SA 2.0","Kentucky burgoo.jpg","w"],"on":"Burgoo","og":["1 pound (450 g) mixed cooked meats (beef, lamb, pork, chicken, game, etc.)","½ gallon (2 liters) chicken stock","½ gallon (2 liters) beef stock","1 ounce (30 ml) Worcestershire sauce","1 cup tomatoes, diced","1 large onion, diced","1 stalk celery, diced","1 small green bell pepper, diced","1 large potato, diced","2 large carrots, diced","¼ cup peas","½ cup okra","¼ cup lima beans","½ cup yellow corn","2 teaspoons garlic, minced","Salt to taste","Pepper to taste"],"mt":1},{"n":"Burmesisches Schweinefleischcurry","c":"fleisch","k":"","p":4,"t":120,"d":1,"v":0,"l":"en","g":["8 getrocknete rote Chilis","2,5 cm frische Ingwerwurzel, zerdrückt","Zitronengrasstängel, fein gehackt","15 ml frischer Galgant, gehackt","15 ml Garnelenpaste","30 ml feiner brauner Zucker","675 g Schweinefleisch, in Stücke geschnitten","600 ml Wasser","10 ml gemahlene Kurkuma","5 ml dunkle Sojasoße","200 g grüne Bohnen (grün)","5 ml brauner Zucker","45 ml Tamarindensaft oder 5 ml Tamarindenmark-Konzentrat","15 ml fein gehackter Knoblauch","4 Schalotten, fein gehackt","15 ml Fischsoße","frische rote Chilis, zum Garnieren"],"s":["Den getrockneten Chili 20 Minuten in warmem Wasser einweichen.","Ingwer, Chili, Zitronengras und Galangal in einem Mörser und Pestle zerkleinern, bis sie eine grobe Paste bilden.","Die Garnelenpaste und den feinen Zucker hinzufügen und zu einer dunklen körnigen Paste weitermahlen.","Das Schwein bei mittlerer Hitze in eine Wok- oder große Bratpfanne geben und die Currypaste unterrühren, bis das Fleisch gut beschichtet ist.","Das Schweinefleisch bei geringer Hitze kochen, gelegentlich rühren, bis das Fleisch die Farbe ändert und etwas von seinem Fett wiedergibt, und der Curry hat begonnen, sein Aroma freizugeben.","Die Kurkuma, das Wasser und die Sojasauce einrühren, dann 40 Minuten lang sanft köcheln lassen, bis das Fleisch zart ist.","Die Bohnen für ca. 10 Minuten separat dampfen.","Zucker, Tamarind, Knoblauch, Schalotten und Fischsoße bis zur Auflösung von Zucker und Tamarind in das Fleisch einrühren.","Mit den frischen Chilis und gedämpften Bohnen garnieren und sofort servieren."],"x":["Das Schweinefleisch kann etwas von seinem Fett getrimmt haben, sollte aber noch einige übrig haben, um in die Sauce zu rendern, wie es kocht.","Anstelle von Galangal kann zusätzlich Wurzel-Ingwer verwendet werden."],"desc":"Burmesisches Schweinefleisch Curry ist ein leichtes, geschmacksvolles Schweinefleischgericht.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Burmese_Pork_Curry","i":"wb-en-1104","im":["f/f0/Pork_and_Potato_Curry_%28Oily-Style%29.jpg/960px-Pork_and_Potato_Curry_%28Oily-Style%29.jpg","Saosukham","CC0","Pork and Potato Curry (Oily-Style).jpg","c"],"on":"Burmese Pork Curry","og":["8 dried red chillis","2.5 cm fresh root ginger, crushed","Lemongrass stalks, finely chopped","15 ml (1 tbsp) fresh galangal, chopped","15 ml (1 tbsp) shrimp paste","30 ml (2 tbsp) fine brown sugar","675 g pork, diced into chunks","600 ml (2½ cup) water","10 ml (2 tsp) ground turmeric","5 ml (1 tsp) dark soy sauce","200 g French (green) beans","5 ml (1 tsp) brown sugar","45 ml (3 tbsp) tamarind juice or 5 ml (1 tsp) tamarind pulp concentrate","15 ml (1 tbsp) minced garlic","4 shallots, finely chopped","15 ml (1 tbsp) fish sauce","Fresh red chillis, to garnish"],"mt":1},{"n":"Burple Nurples (Shot)","c":"welt","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 Ei","230 g Butter, geschmolzen","1 Tasse Zucker","1 Prise gemahlener Koriander","1 Tasse Mehl"],"s":["Backofen auf 160 °C vorheizen.","In einer Schüssel das Ei sanft spalten.","Mit Zucker, dann Butter, Mehl und Koriander zu einem Teig machen.","Teig in kleine Kugeln formen.","Teigkugeln auf ein Backblech legen.","1 Stunde backen."],"x":[],"desc":"Dieses Rezept ist lose von der animierten Fernsehshow Chowder abgeleitet. Es ist unklar, ob es für den Verbrauch bestimmt ist.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Burple_Nurples","i":"wb-en-1105","on":"Burple Nurples","og":["1 egg","2 sticks butter, melted","1 cup granulated sugar","1 pinch ground coriander","1 cup flour"],"mt":1},{"n":"Burrito","c":"fleisch","k":"Mexiko","p":4,"t":0,"d":2,"v":0,"l":"en","g":["#Boden","große Weizentortilla","Bohnen (optional)","Reis (optional)","#Mögliche Füllungen","Schweinefleisch","gehacktes oder gezupftes Rindfleisch","gehacktes oder gezupftes Hähnchen","zerpflückter Fisch","Garnelen","Chorizo","Refried Beans (Bohnenmus)","Würze (z. B. Kreuzkümmel, Salz, Oregano, schwarzer Pfeffer, Chilis usw.)","Picadillo","Tomaten","schwarze Oliven","Blattsalat","Koriandergrün","Avocado","Zwiebel, roh oder angebraten","Knoblauch, roh oder angebraten","Pilze","Chilis","geriebener Käse","saure Sahne","Salsa","Guacamole"],"s":["Wenn Sie getrocknete Bohnen verwenden, waschen Sie sie und untersuchen Sie sie nach Steinen, dann über Nacht in viel Wasser einweichen. Werfen Sie das Wasser vor dem Kochen weg – Ihre Topfpflanzen werden es lieben!","Die Bohnen weich garen","Wenn Sie eine Kochplatte verwenden, köcheln Sie sie in viel Wasser, bis sie sehr weich sind. Sie müssen die Bohnen eine sehr lange Zeit bei sehr geringer Hitze kochen. Sie können Salz oder schwarzen Pfeffer ins Wasser geben.","Sie können Zwiebelhälften oder einen Schinkenknochen hinzufügen, den Sie am Ende entfernen können. Das Wechseln des Wassers von Zeit zu Zeit wird das Gasrisiko verringern. Erwarten Sie, dass das Kochen mindestens 3 Stunden dauert, wenn nicht 6 oder mehr.","Wenn Sie einen Druckkocher verwenden, legen Sie die Bohnen und etwas Aroma (typischerweise Salz) in genügend Wasser, um alle Bohnen vollständig zu decken und auf Druck zu bringen.","Halten Sie den Druck für etwa 20 Minuten, schalten Sie die Hitze ab und lassen Sie den Druck natürlich fallen (ca. 15 Minuten).","Wenn gewünscht, zertrümmern Sie die Bohnen, vielleicht mit einem Kartoffel-Mascher.","Mit Gewürzen nach Belieben würzen.","Holen Sie sich einen großen breiten Topf oder hochseitige Bratpfanne.","Nicht gekochtes Fleisch in die Pfanne geben und mit Rühren braten, damit es überall braun wird. Wenn Sie ein Hackfleisch verwenden, brechen Sie es auf, während es kocht. Überschüssiges Fett abtropfen lassen.","Gewürze und andere Aromen bei Bedarf hinzufügen.","Bei Verwendung von Reis den Reis gut ausspülen, bis das Wasser klar läuft.","2 Tassen Wasser pro 1 Tasse Reis hinzufügen, zum Kochen bringen, dann auf die niedrigste Hitze reduzieren und 15–20 Minuten köcheln lassen.","Mit dem Deckel mindestens 5 Minuten vor Gebrauch beiseite stellen.","Beruhigen Sie die Tortillas, indem Sie sie erhitzen. Verwenden Sie eine kleine Menge Öl, um zu verhindern, dass haften, wenn Heizung in einer Pfanne, die nicht Antihaft ist. Wenn Sie sie im Ofen erhitzen, decken Sie sie mit Aluminiumfolie ab, um die Tortillas vor Feuchtigkeitsverlust zu schützen.","Legen Sie eine Tortilla flach auf eine geeignete Oberfläche wie eine Küchentischplatte.","Legen Sie Ihre gewünschten Füllungen auf die Tortilla in jeder Reihenfolge, so dass eine Grenze von mindestens ein paar Zoll rund um.","Falten Sie die untere Klappe nach oben. Eine kleine Klappe ermöglicht es den Füllungen aus dem fertigen Burrito zu entkommen.","Bringen Sie die Seite hoch und über Ihre Füllung. Den Rand der Tortilla unter Ihrer Füllung zu ziehen, ist ein ausgezeichneter Extraschritt.","Erstellen Sie eine kleine Falte mit der restlichen Seite der Tortilla. Dies ist der Schlüssel zur Erhaltung der Integrität von Burrito. Versagen ist ein gegebenes, wenn Sie diesen Schritt nicht befolgen!","Die kleine, diagonale Klappe ist eine zusätzliche \"Lock\" für die untere Klappe der Tortilla – ohne sie hat das Gewicht der Füllung die Kraft, um die untere Klappe direkt aus sich heraus zu zwingen.","Bringen Sie die verbleibende Tortillaklappe über die Füllung.","Essen Sie mit Vertrauen, obwohl die Füllungen kann sehr heiß sein."],"x":["Es werden 30 cm Tortillas vorgeschlagen. Wenn Sie größere Tortillas finden, benutzen Sie sie!","Bei der Verwendung von Bohnen allein, können Sie bis zu 20% home-rendered Schmalz hinzufügen (Lärm Substitutionen sind offensichtlich, aber wird keinen Geschmack).","Häufige Zutaten in mexikanischen Burritos sind gebratenes Schweinefleisch (Carnitas), mariniertes gegrilltes Steak (Carne Asada), mariniertes gegrilltes Huhn (Pollo Asado), geschmortes Schweinefleisch (al Pastor), Schweinefleisch in grüner Chilisauce (Chile Verde), gebratener Fisch, Rindfleischzunge (Lengua), Rinderhirn (Cabeza), Ziegenfleisch (Birrien), Tripe (Tripas) und Chichharrone (Frittierte Schweinerinde, geräuchert).","Die Mission Burrito kombiniert in der Regel ganze Bohnen (manchmal gebackene Bohnen), mexikanischen Reis, traditionelle mexikanische Fleisch (manchmal gemahlen Rindfleisch), mit optional geriebenem Käse, saure Sahne, Guacamole, geschnitten Jalapenos, Salsa fresca/salsa cruda, und manchmal geschreddert Salat.","Ein erstickter Burrito (\"wet\") ist in der Regel ein Mission Burrito mit Enchilada-Sauce, entweder \"rot\" oder \"grün\", gegossen über ihn, mit geriebenem Käse gekrönt. Es soll mit einem Messer und Gabel gegessen werden, nicht in der Hand gehalten werden, wie andere Burritos sein können."],"desc":"Ein Burrito ist ein mit Füllung gefülltes Mehltortilla. Im Allgemeinen umfasst die Füllung Fleisch wie Schweinefleisch, Rindfleisch oder Huhn, aber auch oft Bohnen und/oder Reis. Vegetarische Burritos sind auch häufig.","img":"Papa chevos burrito.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Burrito","i":"wb-en-1106","im":["d/d4/Papa_chevos_burrito.jpg/960px-Papa_chevos_burrito.jpg","Ernesto Andrade from San Francisco","CC BY 2.0","Papa chevos burrito.jpg","r"],"og":["#Base","Large flour tortilla","Beans (optional)","Rice (optional)","#Possible fillings","Pork","Ground or shredded beef","Ground or shredded chicken","Flaked fish","Shrimp","Chorizo","Refried beans","Seasoning (e.g. cumin, salt, oregano, black pepper, chilis, etc.)","Picadillo","Tomatoes","Black olives","Lettuce","Cilantro","Avocado","Onion, raw or sautéed","Garlic, raw or sautéed","Mushrooms","Chiles","Shredded cheese","Sour cream","Salsa","Guacamole"],"mt":1},{"n":"Burrito-Füllung","c":"welt","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["450 g Fleisch","1 ganze Zwiebel, gewürfelt","1 Dose schwarze Bohnen, abgespült","1 Dose Mais mit Flüssigkeit","1 Dose gewürfelte Tomaten","1 Tasse Salsa (beliebiger Schärfegrad)","1 Tasse Instant-Reis","1 Tasse Wasser","1 Packung Taco-Gewürz"],"s":["Fleisch und Zwiebel in Pfanne anbraten.","Mit schwarzen Bohnen, Mais, Tomaten, Salsa, Reis, Wasser und Taco würzen. Simmer, bis es fertig ist.","Als Füllung in Burritos verwenden."],"x":[],"desc":"Diese Burrito-Mischung kann verwendet werden, um Tortillas zu füllen und Burritos herzustellen.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Burrito_Mix","i":"wb-en-1107","on":"Burrito Mix","og":["1–2 lbs meat","1 whole onion, diced","1 can black beans, rinsed","1 can corn w/ juice","1 can diced tomatoes","1 cup salsa (any heat intensity)","1 cup instant rice","1 cup water","1 packet taco seasoning"],"mt":1},{"n":"Butter Tart","c":"kuchen","k":"Kanada","p":24,"t":70,"d":1,"v":0,"l":"en","g":["#Teig","1 Tasse Backfett","1 großer TL Butter oder Margarine","¾ Tasse kochendes Wasser","3 ½ Tassen feines Weizenmehl oder 3 Tassen Weizenmehl","2 TL Backpulver","¼ TL Salz","#Füllung","2 Eier","1 ½ Tassen brauner Zucker","½ Tasse Maissirup","3 EL Butter, geschmolzen","1 Tasse Korinthen oder Rosinen","½ Tasse gehackte Walnüsse","2 TL Essig","1 Prise Salz","½ TL Vanilleextrakt"],"s":["Die Verkürzung, Butter und heißes Wasser zusammen bis cremig schlagen.","Während noch warm, Sieb in das Mehl, Backpulver und Salz. Schonend mischen, bis sich ein Teig bildet. Versuchen Sie nicht, es zu kneten, während sie in eine große Kugel.","Den Teig in zwei gleiche Portionen trennen und 20 bis 40 Minuten abkühlen.","Den Teig in zwei Dutzend gleiche Kugeln teilen. Rollen Sie jeden Ball in eine flache Scheibe.","Backofen auf 175 °C vorheizen.","Die Eier gut schlagen. Zucker, Sirup und geschmolzene Butter zugeben und wieder schlagen.","Die Johannisbeeren, Walnüsse, Essig, Salz und Vanilleextrakt zugeben und kräftig vermischen.","Legen Sie eine kleine Menge Maismehl in kleine Torte Pfannen, oder zählen Sie 24 Cupcake Papiere.","Passen Sie die flachen Kreise der Kuchenkruste in die Pfannen, oder passen Sie sie in Cupcake-Papiere und fügen Sie sie in die Pfannen.","Füllen Sie die Schalen 2⁄3 voll mit der vorbereiteten Füllung.","Backen, bis das Gebäck hellbraun ist (ca. 20 Minuten).","Aus dem Ofen nehmen und abkühlen lassen."],"x":["Für runnier Torten, kochen für 15 bis 17 Minuten. Sie können auch die Füllstoffe auf 1 Tasse Maissirup und 1 Tasse braunen Zucker einstellen.","Versuchen Sie, die Johannisbeeren durch Kokosnuss zu ersetzen oder ganz wegzulassen.","Versuchen Sie, die Walnüsse durch Pekannüsse zu ersetzen oder ganz wegzulassen.","Versuchen Sie das Nieseln von 115 g (120 g) geschmolzener Schokolade über den gekochten Torten.","Dieses Rezept (sowohl die Torten als auch die Kuchenkruste) ist ein Jahrhundert altes Rezept aus dem ländlichen North Western Ontario.","Wenn die Spitze der Torte beim Backen nicht geschäumt hat und eine cremefarbene knusprige Platte gebildet hat, bedeutet das, dass es zu viel Zeit zwischen dem Schlagen der Mischung und dem Backen gab. Wenn Sie mehrere Chargen im Ofen mit der gleichen Mischung zu tun haben, achten Sie darauf, den Teig kühl zu halten und halten Rühren sie, um sicherzustellen, dass die zweite Charge hat die traditionelle knusprige Spitze."],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Butter_Tart","i":"wb-en-1108","im":["3/30/ButtertartS1360020.jpg/960px-ButtertartS1360020.jpg","Alex Lozupone","CC BY-SA 4.0","ButtertartS1360020.jpg","w"],"og":["#Dough","1 cup shortening","1 large teaspoon butter or margarine","¾ cup boiling water","3 ½ cups pastry flour or 3 cups all-purpose flour","2 teaspoons baking powder","¼ teaspoon salt","#Filling","2 eggs","1 ½ cups brown sugar","½ cup corn syrup","3 tablespoons butter, melted","1 cup currants or raisins","½ cup chopped walnuts","2 teaspoons vinegar","1 pinch of salt","½ teaspoon vanilla extract"],"mt":1},{"n":"Buttertee","c":"welt","k":"Tibet","p":2,"t":20,"d":1,"v":0,"l":"en","g":["1 EL normale schwarze Teeblätter (am besten nepalesisch oder indisch)","3 Tassen Vollmilch (oder 1½ Tassen Kaffeesahne + 1½ Tassen Wasser)","2 EL ungesalzene Butter","Salz, nach Geschmack"],"s":["Tee mit Milch 2-10 Minuten kochen, je nach der gewünschten Stärke des Tees","In Teetassen einreiben.","Butter und Salz dazugeben. Umrühren Sie gründlich, idealerweise durch sorgfältige Verwendung eines Mixers, und servieren."],"x":[],"desc":"Buttertee, bekannt als Po Cha, ist ein traditionelles Getränk der Tibeter und wird auch in Bhutan konsumiert. Buttertee ist ein unverzichtbarer Bestandteil des tibetischen Lebens. Vor der Arbeit wird ein Tibeter mehrere Schüsseln dieses würzigen Getränks herunterlassen, und es wird immer den Gästen serviert. Da Butter der Hauptbestandteil ist,","img":"Tibetan butter tea.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Butter_Tea","i":"wb-en-1109","im":["5/54/Tibetan_butter_tea.jpg/960px-Tibetan_butter_tea.jpg","Yosomono","CC BY 2.0","Tibetan butter tea.jpg","r"],"on":"Butter Tea","og":["1 tablespoon regular black tea leaves (preferably Nepalese or Indian)","3 cups whole milk (or 1½ cup half-and-half + 1½ cup water)","2 tablespoons unsalted butter","Salt to taste"],"mt":1},{"n":"Butterbier","c":"getraenke","k":"","p":8,"t":5,"d":1,"v":0,"l":"en","g":["470 ml Vanilleeis, weich","¼ Tasse Butter, weich","⅓ Tasse brauner Zucker","2 TL gemahlener Zimt","1 TL geriebene Muskatnuss","950 ml Apfelsaft"],"s":["Alle Zutaten gründlich in eine Schüssel mischen.","Unterteilen Sie zwischen Bechern.","Wie gewünscht erhitzen und servieren."],"x":["Rum oder Brandy für ein erwachsenes Butterbier zugeben."],"desc":"Butterbier ist ein Drink aus der Harry Potter Buchreihe.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Butterbeer","i":"wb-en-1110","im":["3/36/Butterbeer%21_%2829066680340%29.jpg/960px-Butterbeer%21_%2829066680340%29.jpg","HarshLight from San Jose, CA, USA","CC BY 2.0","Butterbeer! (29066680340).jpg","c"],"on":"Butterbeer","og":["1 pint vanilla ice cream, softened","¼ cup butter, softened","⅓ cup brown sugar","2 teaspoons ground cinnamon","1 teaspoon grated nutmeg","1 quart apple juice"],"mt":1},{"n":"Butter-Popcorn","c":"welt","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 Schüssel Popcorn","Salz","geschmolzene Butter"],"s":["Das Popcorn mit geschmolzener Butter werfen","Auf Wunsch mit Salz bestreuen."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Buttered_Popcorn","i":"wb-en-1111","on":"Buttered Popcorn","og":["1 bowl of popped popcorn","Salt","Melted butter"],"mt":1},{"n":"Buttermilch-Currysuppe (Kadhi Pakora)","c":"suppen","k":"Indien","p":4,"t":35,"d":2,"v":0,"l":"en","g":["#Pakora","1 Tasse Besan (Kichererbsenmehl) (Kichererbsenmehl)","Wasser","Salz","gemahlene Kurkuma","Pflanzenöl","#Curry","2 Gläser Buttermilch","1 EL Besan (Kichererbsenmehl)","gemahlene Kurkuma","1 Prise Asafoetida (Asant)","Salz","schwarze Senfsamen","1 Zehe Knoblauch, fein gehackt","0,6 cm Stück Ingwerwurzel, geschält und fein gehackt","4–5 Curryblätter (Kadi Patta) (Curryblätter)","1 kleine Zwiebel, fein gehackt"],"s":["Besan mit Wasser, Salz und Kurkumapulver vermischen, bis man einen dicken Teig bekommt.","Öl in großer Pfanne erhitzen.","Drop Dollops von Teig in der Pfanne mit einem runden Löffel, so dass pakoras sind rund und flauschig.","Fry bis die Pakoras golden sind, dann entfernen Sie sie aus dem Öl.","Buttermilch, 1 EL Besan, Kurkumapulver, Asafoetida und Salz glatt und klumpenfrei vermischen.","Ein wenig Öl in einer Pfanne erhitzen. Senfsamen, Knoblauch, Ingwer, Curryblätter und Zwiebel hinzufügen, dann bis etwas rötlich anbraten.","Die Buttermilchmischung umrühren und in die Zwiebeln mischen. Mischen Sie es bei mittlerer Hitze weiter, bis es zu sprudeln beginnt.","Fügen Sie die pakoras, senken Sie die Hitze, und halten Sie für einige Zeit. Schließen Sie den Deckel und schalten Sie die Flamme aus.","Heiß mit Reis oder Roti servieren."],"x":["Wenn Sie es würziger machen wollen, legen Sie Garam Masala und Chilipulver in die Pakora und den Curry."],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Buttermilk_Curry_Soup_(Kadi_Pakora)","i":"wb-en-1112","im":["c/cf/Onion_pakora_-_a.jpg/960px-Onion_pakora_-_a.jpg","Babu iyer","CC BY-SA 4.0","Onion pakora - a.jpg","w"],"on":"Buttermilk Curry Soup (Kadi Pakora)","og":["#Pakora","1 cup besan (chickpea flour)","Water","Salt","Turmeric powder","Vegetable oil","#Curry","2 glasses cultured buttermilk","1 tbsp besan","Turmeric powder","1 pinch of asafoetida","Salt","Black mustard seeds","1 clove garlic, minced","¼-inch piece of ginger root, peeled and minced","4–5 kadi patta (curry leaves)","1 small onion, finely chopped"],"mt":1},{"n":"Buttermilch-Brathähnchen mit Bratensoße","c":"fleisch","k":"USA","p":4,"t":0,"d":2,"v":0,"l":"en","g":["#Hähnchen","1 ganzes Hähnchen","2 Tassen Buttermilch","1 TL Senfpulver","1 TL Cayennepfeffer","2 TL grob zerstoßene schwarze Pfefferkörner","1 TL Zimt","1 EL Oregano","1 EL Petersilie","1 TL Paprikapulver","Mehl, mit Kräutern und Gewürzen gewürzt (z. B. Pfeffer, Cayennepfeffer, Salz, gemahlener Koriander, Zimt, Thymian, Oregano)","Öl (z. B. Erdnuss- oder Maiskeimöl)","#Soße","Öl","1 kleine Zwiebel (oder Schalotten), gehackt","1 Zehe Knoblauch","3–4 EL Mehl","3 Tassen Hühnerfond (oder 2 Tassen Brühe + 1 Tasse Sahne)","Salz","Pfeffer"],"s":["Das Huhn in 8–10 Stücke schneiden.","Kombinieren Sie die Buttermilch und Gewürze, und marinieren Sie die Hühnerstücke für 4 Stunden in der Mischung.","Nehmen Sie jedes Stück Huhn aus der Marinade und lassen Sie es für ein paar Sekunden trocken tropfen. Dann ziehen Sie es in gewürztem Mehl. Ein einfacher Weg, um zu dredgen ist es, Mehl und Gewürze in einem kleinen Plastikbeutel, fallen das Stück in, und Schütteln.","Lassen Sie die Stücke ruhen (einzeln; Nicht stapeln) für etwa 10 Minuten. Dann ziehen Sie sie wieder ab. Das erste Baggern absorbiert die Buttermilchmarinade. Das zweite Baggern gibt eine gewürzte Mehl-Außenschicht.","Das Öl in einer tiefen, breiten Pfanne erhitzen. Wenn Öl heiß raucht, legen Sie Hühnerstücke in die Pfanne und achten Sie darauf, nicht überfüllt (Stücke sollten nicht berühren; In mehreren Chargen braten). Nach 3 oder 4 Minuten, drehen Sie das Huhn, und reduzieren Sie die Hitze.","Lassen Sie das Huhn für 20-25 Minuten braten, drehen die Stücke alle paar Minuten. Wenn das Huhn tief goldbraun ist und die Säfte klar laufen, ist es erledigt.","Das Huhn wird weiter kochen, nachdem es aus der Pfanne entfernt wurde, also auf der Seite von \"fast fertig\" irrt.","Das Huhn auf saugfähigem Papier oder Tuch abtropfen lassen. Wenn Sie das Huhn nicht sofort servieren, legen Sie es in einen leicht erwärmten Ofen, aufgedeckt, separat (nicht gestapelt).","Das angesammelte Öl aus der Pfanne abgießen, 3–4 Esslöffel und alle Mehl- und Hühnerreste beiseite legen. Die Pfanne auf mittlerer Flamme halten, die gehackte Zwiebel und Knoblauch hinzufügen. Sauté für ein paar Minuten.","In 3–4 Esslöffel Mehl rühren und weiterrühren, bis die Mischung hell bis mittelbraun wird. Nicht brennen.","In 3 Tassen Hühnerbrühe quietschen. Bei niedriger Hitze köcheln lassen, 15 Minuten bedecken. Salz und Pfeffer nach Geschmack.","Huhn mit Reis und etwas grünem Gemüse servieren. Löffelsoße über Reis und Huhn."],"x":["Die Gewürzmischung ist nicht fixiert. Sie können mehr oder weniger wie gewünscht verwenden."],"desc":"Gebratenes Huhn ist eine südliche Hauptmahlzeit in den USA, die oft beim \"Sonntagessen\" (\"Dinner\" ist das Mittagsmahl für viele Southerners) oder Kirche \"Suppers\" (\"Supper\" ist der Begriff für das Abendessen). Rezepte sind Legionen; Jede Familie hat einen überliefert.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Buttermilk_Fried_Chicken_with_Pan_Gravy","i":"wb-en-1113","im":["2/2c/Fried-Chicken-Set.jpg/960px-Fried-Chicken-Set.jpg","Evan-Amos","CC0","Fried-Chicken-Set.jpg","w"],"on":"Buttermilk Fried Chicken with Pan Gravy","og":["#Chicken","1 whole chicken","2 cups buttermilk","1 tsp mustard powder","1 tsp cayenne powder","2 tsp cracked black peppercorns","1 tsp cinnamon","1 tablespoon oregano","1 tablespoon parsley","1 tsp paprika","Flour seasoned with herbs and spices (e.g. pepper, cayenne, salt, ground coriander, cinnamon, thyme, oregano)","Oil (e.g. peanut or corn oil)","#Gravy","Oil","1 small onion (or shallots), chopped","1 clove of garlic","3–4 tablespoons flour","3 cups chicken stock (or 2 cups stock + 1 cup cream)","Salt","Pepper"],"mt":1},{"n":"Buttermilch-Ranch-Dressing","c":"saucen","k":"USA","p":2,"t":0,"d":1,"v":0,"l":"en","g":["2 EL Zitronensaft","1 Tasse Buttermilch","1 Tasse Mayonnaise","¾ Tasse saure Sahne","2 Zehen Knoblauch, fein gehackt","1 TL Oregano","2 TL Zwiebelpulver","½ TL schwarzer Pfeffer"],"s":["Zutaten glatt mischen."],"x":[],"desc":"Das All-American Dressing, ideal für Salate, Sandwiches oder als Dip mit Crudités. Tangy, aber nicht zu süß.","img":"Ranch dressing.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Buttermilk_Ranch_Dressing","i":"wb-en-1114","im":["d/d6/Ranch_dressing.jpg/960px-Ranch_dressing.jpg","Whitney from Chicago, IL","CC BY 2.0","Ranch dressing.jpg","r"],"on":"Buttermilk Ranch Dressing","og":["2 tbsp lemon juice","1 cup buttermilk","1 cup mayonnaise","¾ cup sour cream","2 cloves garlic, minced","1 tsp oregano","2 tsp onion powder","½ tsp black pepper"],"mt":1},{"n":"Butternusskürbissuppe","c":"suppen","k":"","p":4,"t":0,"d":1,"v":1,"l":"en","g":["1 mittelgroßer Butternusskürbis","2 mittelgroße Zwiebeln, geschält und halbiert","2 EL Olivenöl","2 Zehen Knoblauch, fein gehackt","4 Tassen Hühner- oder Gemüsefond","¼ Tasse Cream Sherry","1 TL Muskatnuss"],"s":["Backofen auf 205 °C vorheizen.","Squash halbieren und Samen entfernen.","Zwiebeln und Kürbis mit Olivenöl reiben. Backen Sie für etwa 1 Stunde oder bis fertig aufgedeckt. Etwas cool.","Spoon Squash Zellstoff in einen Lebensmittelverarbeiter. Zwiebeln und 1–2 Tassen Hühnerbrühe hinzufügen. Purée, bis er glatt ist.","In den Kochtopf gießen. Knoblauch, Sherry und Muskatnuss zugeben und bei mittlerer Hitze umrühren.","Restliche Brühe dazugeben und heiß kochen. Abschmecken."],"x":[],"desc":"","img":"Butternut Squash Soup.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Butternut_Squash_Soup","i":"wb-en-1115","im":["1/12/Butternut_Squash_Soup.jpg/960px-Butternut_Squash_Soup.jpg","Visitor7","CC BY-SA 3.0","Butternut Squash Soup.jpg","r"],"on":"Butternut Squash Soup","og":["1 medium butternut squash","2 medium onions, peeled and halved","2 tbsp olive oil","2 cloves garlic, minced","4 cups chicken stock or vegetable stock","¼ cup cream sherry","1 tsp nutmeg"],"mt":1},{"n":"Butterscotch-Soße","c":"saucen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["300 g brauner Zucker oder Muscovado","150 g ungesalzene Butter","1 TL Vanillearoma","1 EL Zuckerrübensirup (optional)","300 ml Double Cream (Sahne mit 48 % Fett) (etwa 48 % Fett)"],"s":["Kombinieren Sie Zucker, Butter, Vanille und Treakle in einem Topf bei geringer Hitze, und sanft rühren, bis alles geschmolzen ist. Niedrige Hitze ist erforderlich, damit der Zucker nicht brennt und so, wenn Sie die doppelte Creme hinzufügen, wird die Creme nicht gespalten.","Wenn alles kombiniert ist, langsam in die Doppelcreme geben und sanft umrühren.","Sobald die Creme eingemischt wurde, wird sie zu einer mittleren Hitze. Rühren Sie sanft, warten, bis die Sauce sprudelnd und heiß ist, dann nehmen Sie es von der Hitze.","Kombinieren Sie die Sauce mit dem Rezept Ihrer Wahl und/oder stellen Sie sie in einen Gießkanne und halten Sie warm."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Butterscotch_Sauce","i":"wb-en-1116","im":["6/6d/Butterscotch-Candies.jpg/960px-Butterscotch-Candies.jpg","Evan-Amos","CC BY-SA 3.0","Butterscotch-Candies.jpg","w"],"on":"Butterscotch Sauce","og":["300 g brown sugar or Muscovado sugar","150 g unsalted butter","1 tsp vanilla essence","1 tbsp black treacle (optional)","300 ml double cream (~48% butterfat)"],"mt":1},{"n":"Butternudeln mit Käse","c":"veggie","k":"","p":4,"t":0,"d":1,"v":1,"l":"en","g":["Linguine oder Spaghetti (reicht für 2 Personen)","1 vegetarischer Brühwürfel","1–2 Stückchen Butter (n)","Ziegenkäse (Parmesan geht auch) (so viel wie 2 Butterflöckchen)","3–5 Zehen Knoblauch (optional)","Kräuter (z. B. Basilikum, Oregano usw., optional)","Sojaschnetzel (optional)","1 ganze Tomate (optional), gewürfelt"],"s":["Füllen Sie Topf mit genügend Wasser für 2 Portionen Linguin.","Topf über hohe Hitze stellen und vegetarischen Bouillonwürfel hinzufügen.","Sobald das Wasser kocht, füge Linguin und texturiertes pflanzliches Protein hinzu.","Wenn die Linguine fertig ist, gießen Sie den größten Teil des Wassers aus, so dass es etwa einen Zentimeter links.","Butter, Käse, gehackte Tomaten und Kräuter hinzufügen.","Knoblauchzehen zerstoßen und in den Topf geben","Häufig umrühren, bis es von der gewünschten Dicke ist."],"x":[],"desc":"Dieses Rezept wurde durch den Wikipedia-Artikel über Alfredo inspiriert.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Buttery_Noodles_with_Cheese","i":"wb-en-1117","on":"Buttery Noodles with Cheese","og":["Dry linguine or Spaghetti (enough for 2 people)","1 vegetarian bouillon cube","1–2 pat(s) butter","Goat cheese (2 pats of butter worth)—Parmesan is an acceptable substitute","3–5 cloves garlic (optional)","Herbs (e.g. basil, oregano, etc; optional)","Textured vegetable protein (optional)","1 whole tomato (optional), diced"],"mt":1},{"n":"Buuz (mongolische Fleischtaschen)","c":"fleisch","k":"Mongolei","p":2,"t":20,"d":3,"v":0,"l":"en","g":["300 g Mehl","200–300 g kaltes Wasser","Zwiebel, gehackt","Rindfleisch, fein gehackt oder gemahlen","½ TL Salz (2.5 ml)","¼ TL Pfeffer (1.3 ml) (optional)","5 EL Wasser (75 ml)","400 ml Wasser"],"s":["Rindfleisch, Salz, Zwiebel, Pfeffer und Wasser in einer Schüssel mischen. Bei der Zubereitung des Teiges gründlich vermischen und überdeckt lassen.","In einer Schüssel Mehl und kaltes Wasser vermischen, um einen sehr weichen Teig zu machen. Bedecken Sie die Schüssel und lassen Sie den Teig für 5 Minuten zu entspannen.","Den Teig eine halbe Minute kneten. Den Teig in 10 Stücke schneiden und den Teig in Scheiben glätten.","Legen Sie eine faire Menge Fleischmischung auf jede Scheibe, und falten Sie die Kanten zusammen, um die Füllung zu schließen.","Eine Menge Wasser in einem Dampfer kochen. Verbreiten Sie etwas Öl auf der Dampferpfanne, um die Buuz-Brötchen beim Kochen zu schützen.","Legen Sie die Buuz-Brötchen vorsichtig auf die Dampferpfanne, wobei sie 1 cm (1 cm) voneinander entfernt sind. Die Pfanne in den kochenden Dampfer geben und den Dampfer sehr gut bedecken. Kochen Sie für 15 Minuten.","Nehmen Sie die Dampferbrett und Ventilator der Buuz für 30 Sekunden mit Dampfer Abdeckung oder ein sicheres, leichtes Objekt.","Servieren Sie mit etwas Kohlsalat, oder einige gehackte koscher Gurken. Viel Spaß!"],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Buuz_(Mongolian_Meat_Dumplings)","i":"wb-en-1118","im":["a/a2/Buuz.jpg/960px-Buuz.jpg","Mizu_Basyo","CC BY-SA 3.0","Buuz.jpg","w"],"on":"Buuz (Mongolian Meat Dumplings)","og":["300 g (11 oz) flour","200–300 g (7.1–11 oz) cold water","onion, chopped","beef, minced or ground","½ tsp (2.5 ml) salt","¼ tsp (1.3 ml) pepper (optional)","5 tbsp (75 ml) water","400 ml (14 oz) water"],"mt":1},{"n":"Buñuelos (süßes Schmalzgebäck)","c":"brot","k":"Mexiko","p":4,"t":0,"d":2,"v":0,"l":"en","g":["5 Eier","¼ Tasse weißer Zucker","1 TL Pflanzenöl","2 Tassen Weizenmehl","1 TL Backpulver","1 TL Salz","1 Tasse weißer Zucker","1 TL gemahlener Zimt","1 Tasse Pflanzenöl zum Braten"],"s":["In einer großen Schüssel Eier mit 1⁄4 Tasse Zucker kombinieren, und schlagen bis dick und zitronenfarben. Öl dazugeben.","1 1⁄2 Tassen Mehl, Backpulver und Salz kombinieren. Allmählich fügen Sie dies in die Ei-Mischung und schlagen gut.","Teig auf ein gemahlenes Brett auslegen (noch 1⁄2 Tasse Mehl verwenden) und gründlich kneten, bis der Teig glatt ist.","Teig in 16 Kugeln formen. Jeder in einen Kreis rollen, der etwa 13 cm (13 cm) Durchmesser hat. Lassen Sie auf Backpapier für etwa 10 Minuten aufgedeckt stehen.","Öl in einer tiefen Pfanne auf 175 °C erhitzen. Fry Teig Kreise bis goldbraun, einmal drehen. Auf Papiertücher abtropfen lassen.","Kombinieren Sie den Zimt und 1 Tasse Zucker. Frittierter Teig mit Zucker/Zimtmischung bestreuen. In einem luftdichten Behälter aufbewahren."],"x":[],"desc":"Buñuelos sind eine Art lateinamerikanisches Backwaren.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Buñuelos_(Sweet_Fried_Pastry)","i":"wb-en-1119","im":["3/33/Bunyol_de_carabassa.jpg/960px-Bunyol_de_carabassa.jpg","Baptiste Pons from Gandia / Burjassot, País Valencià, Spain","CC BY 2.0","Bunyol de carabassa.jpg","w"],"on":"Buñuelos (Sweet Fried Pastry)","og":["5 eggs","¼ cup white sugar","1 teaspoon vegetable oil","2 cups all-purpose flour","1 teaspoon baking powder","1 teaspoon salt","1 cup white sugar","1 teaspoon ground cinnamon","1 cup vegetable oil for frying"],"mt":1},{"n":"Bánh Chưng (vietnamesischer Klebreiskuchen)","c":"fisch","k":"Vietnam","p":10,"t":1080,"d":2,"v":0,"l":"en","g":["1 ½ Tassen Mungbohnen, gewaschen und 4 Stunden in Wasser eingeweicht, oder besser über Nacht","500 g Schweinebauch (sowohl mageres Schweinefleisch als auch Schweinefett), in große Würfel geschnitten","2 ½ TL Salz","2 ½ TL frisch gemahlener schwarzer Pfeffer","3 EL Röstschalotte","1 EL Pflanzenöl","3 Schalotten, fein gehackt","2 EL Fischsoße","1 kg Bananenblätter (frisch oder aufgetaut)","5 ½ Tassen Klebreis, gewaschen und über Nacht in Wasser eingeweicht"],"s":["Die Mung-Bohnen in einen Topf geben, mit Wasser bedecken und zum Kochen bringen.","Reduzieren Sie zu einem köcheln, und kochen für etwa 20 Minuten, bis die Bohnen weich und leicht maschierbar sind.","Die Bohnen in eine Paste zerdrücken. Mit 1 TL Salz, gebratenen Schalotten, 1 TL Pfeffer und Pflanzenöl abschmecken.","Das Fleisch mit 1⁄2 TL Salz und 11⁄2 TL Pfeffer würzen und mit Schalotten und Fischsauce vermischen. Gut vermischen und ein paar Stunden marinieren lassen.","Etwa 1 Tasse Mung-Bohne auf Plastikfolie verteilen, ein paar Stücke mageres Schweinefleisch und Schweinefett hinzufügen und in ein rundes oder quadratisches Stück formen.","Die Bananenblätter in sehr große Stücke zerreißen (ca. 18–51 cm).","Den eingeweichten Reis mit einer Prise Salz würzen.","Legen Sie zwei Blätter von teilweise überlappenden Bananenblättern auf einer flachen Oberfläche. Legen Sie 1 Tasse klebrigen Reis in die Mitte der Blätter. Legen Sie die Füllungen auf den Reis und decken Sie ihn dann mit einer anderen Tasse klebrigen Reis.","Falten Sie die Blätter und wickeln Sie sie fest wie ein Geschenk.","Um zu verhindern, dass während des Siedevorgangs Wasser in den Kuchen eindringt, ist es wichtig, den Kuchen ein zweites Mal einzuwickeln.","Für die innere Schicht, stellen Sie sicher, dass die dunklere Seite des Bananenblattes dem Reis gegenübersteht, so dass er den Kuchen mit einer schönen subtilen grünen Farbe später färben kann.","Jedoch für die äußere Schicht, sollte die dunklere Seite des Bananenblattes nach außen schauen, um ihm ein schönes grünes Paket zu geben.","Nach dem Wickeln den Kuchen fest mit Zwirnen binden.","Die Kuchen fest in einem großen Topf anrichten und mit Wasser füllen. Bringen Sie den großen Topf zum Kochen und lassen Sie ihn ca. 6 bis 8 Stunden köcheln, bis sich die Kuchen plump anfühlen und der Reis kongealiert ist.","Zum Servieren, losbinden und auspacken die Kuchen, und in Stücke mit einem Faden oder Zahnseide geschnitten."],"x":[],"desc":"Bánh ch ng ist ein traditionelles vietnamesisches Gericht aus Glutenreis, Mung-Bohnen und Schweinefleisch, das in Lá dong (Stachyphrynium plazentarium) verpackt und fest mit Fäden gebunden ist. Es wird traditionell während des Mond Neujahrs gegessen ().","img":"Nguyen lieu banh chung.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Bánh_Chưng","i":"wb-en-1120","im":["1/12/Nguyen_lieu_banh_chung.jpg/960px-Nguyen_lieu_banh_chung.jpg","vi:user:Viethavvh","Public domain","Nguyen lieu banh chung.jpg","r"],"on":"Bánh Chưng","og":["1½ cups mung beans, washed and soaked in water for 4 hours, or better overnight","500 g pork belly (both lean pork and pork fat), cut in large cubes","2½ tsp salt","2½ tsp freshly-ground black pepper","3 tbsp fried shallot","1 tbsp vegetable oil","3 shallots, minced","2 tbsp fish sauce","1 kg banana leaves (fresh or thawed)","5½ cups sticky rice, washed and soaked in water overnight"],"mt":1},{"n":"Bánh Mì","c":"snacks","k":"Vietnam","p":1,"t":0,"d":1,"v":2,"l":"en","g":["#Hauptzutaten","1 Baguette","Möhre in feinen Streifen","Daikon-Rettich in feinen Streifen","Salz","Wasser","Kokosessig oder Weißweinessig","Zucker","#Übliche Bánh-mì-Füllung","Korianderblätter und -stiele (Koriander)","hauchdünne Jalapeño-Scheiben","frische Gurkenscheiben","#Füllungen mit Fleisch, Fisch oder Tofu","Barbecue-Schweinefleisch","Barbecue-Hähnchen","Schweinepastete in Scheiben","Schweinehackbraten in Scheiben","Schinkenscheiben","Barbecue-Rindfleisch","Fleischbällchen","chinesische, thailändische oder vietnamesische Wurst in Scheiben (festkochend)","Sardinen","Kutteln","Räucherlachs","gegrillter oder gebratener weißer Fisch","Sojaschnetzel (Weizengluten, Seitan, Sueyu, Suegai, vegetarische Fischfilets)","gewürzter Tofu","#Weitere Füllungen (optional)","Speiserübe in Scheiben","Frühlingszwiebeln in Ringen","in Scheiben, trocken getupfte Tomaten","Minzzweige","Zweige Basilikum","geraspelter Kohl","Sprossenmischung","Blattsalat","#Soßen für das Sandwich","japanische Mayonnaise (Kewpie-Mayonnaise, Quetschflasche mit Baby vorn drauf)","Mayso (Mayonnaise und Sojasoße)","Maysocha (Mayonnaise, Sojasoße und Sriracha)","Maycha (Mayonnaise und Sriracha)","Hot Mom (Mayonnaise, Lao Gan Ma, chinesische Chilisoße)","eins der obigen mit Limetten- oder Zitronensaft und Zucker","Barbecuesoße und Mayonnaise"],"s":["Mit Salz leicht die Julienne Karotte und Radieschen bestreuen. 5 min ruhen lassen, dann mit kaltem Wasser abspülen.","Die gleichen Teile des Wassers, Essig mit Zucker vermischen. Zum Kochen bringen, abkühlen und über Gemüse gießen.","Diese Mischung mindestens einen Tag vor Gebrauch im Kühlschrank in einem Behältnis aufbewahren.","Schneiden Sie eine Länge von Baguette längs. Formen Sie einen Graben in jeder Hälfte, indem Sie entweder das überschüssige Brot entfernen oder komprimieren. Diese Depressionen sind, wo Sie die Füllung setzen.","Toast das Brot, wenn gewünscht.","Eine Schicht der gewünschten Sauce(n) auf jeder Hälfte des Brotes verteilen.","Füllen Sie das Sandwich mit einer der oben aufgeführten gewünschten Füllungen.","Servieren."],"x":[],"desc":"Bánh Mì bedeutet \"Brot\" in Vietnamesen, und es bezieht sich oft auf eine Art vietnamesisches Sandwich. Es könnte als \"Küchenspüle\"-Rezept in Vietnam begonnen haben, wo verschiedene Reste in ein Sandwich geworfen würden, um sie zu beenden (wie ein Po' Boy). Wird jetzt von vielen für seine einzigartige und köstliche f gesucht","img":"Banh Mi, Eden Center.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Bánh_Mì","i":"wb-en-1121","im":["b/b6/Banh_Mi%2C_Eden_Center.jpg/960px-Banh_Mi%2C_Eden_Center.jpg","Flickr user: freshcrackedpepper","CC BY 2.0","Banh Mi, Eden Center.jpg","r"],"og":["#Core ingredients","1 loaf baguette-style bread","Julienned carrot","Julienned daikon radish","Salt","Water","Coconut vinegar or white vinegar","Sugar","#Standard bánh mì fillings","Cilantro (coriander) leaves and stems","Super-thin jalapeño slices","Fresh sliced cucumber","#Protein fillings","BBQ pork","BBQ chicken","Sliced pork pâté","Sliced pork meatloaf","Sliced ham","BBQ beef","Meatballs","Sliced Chinese/Thai/Vietnamese-style sausage (waxy kind)","Sardines","Tripe","Smoked salmon","Grilled or fried whitefish","Textured vegetable protein (wheat gluten, seitan, sueyu, suegai - vegetarian fish fillets)","Seasoned tofu","#Optional additional fillings","Sliced turnip","Sliced green onions","Sliced, patted dry tomatoes","Sprigs of mint","Sprigs of basil","Shredded cabbage","Sprout mix","Lettuce","#Sauces for sandwich","Japanese mayonnaise (Kewpie Mayo - squeeze bottle with a baby on front)","Mayso (mayo and soy sauce)","Maysocha (mayo, soy sauce, and sriracha chili sauce)","Maycha (mayo and sriracha)","Hot Mom (mayo, Lao Gan Ma Chinese hot sauce)","Any of the above with lime or lemon juice and sugar","BBQ sauce and mayo"],"mt":1},{"n":"Sauce béarnaise","c":"saucen","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["30 ml Estragonessig","30 ml Sherryessig oder trockener Weißwein","1 Schalotte, fein gehackt","2 Eigelb","75–100 g geschmolzene Butter (warm, aber nicht heiß)","Salz","Cayennepfeffer, nach Geschmack","1 EL frisch gehackter Estragon","1 EL frisch gehackte Petersilie"],"s":["Die Essige, Schalotten und Kräuter in einen kleinen Topf geben; Bis auf 1 Esslöffel reduziert köcheln. Das ist die würzige Glasur. Abnehmen und abkühlen lassen.","Eigelb dazugeben und bis zum Band mit einem Ballonbesen aufsetzen.","Stellen Sie die Schüssel über eine Pfanne mit heißem Wasser (einen Doppelkessel) und fahren Sie mit dem Whisking fort. Nach und nach die geschmolzene Butter hinzufügen, schütteln, bis die Sauce dick wird und alle Butter hinzugefügt wurde.","Saison und Servieren."],"x":["Nicht getrockneten Estragon verwenden; Wenn Sie keinen frischen Estragon finden können, verwenden Sie einen Zweig aus der Essigflasche.","Um die richtige Temperatur zu finden, um die Eimischung und die Butter zu emulgieren, sollte die Schüssel einfach heiß genug sein, damit Sie sie noch berühren können. Wenn du die Schüssel nicht halten kannst, ist es zu heiß. Seien Sie gewarnt, dass dieser Trick kann nicht immer je nach einer Vielzahl von Bedingungen funktionieren."],"desc":"Béarnaise-Sauce ist eine Eigelb- und Butteremulsion aus der Familie Hollandaise.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Béarnaise_Sauce","i":"wb-en-1122","im":["5/57/B%C3%A9arnaise_sauce_with_Tarragon_garnish.jpeg/960px-B%C3%A9arnaise_sauce_with_Tarragon_garnish.jpeg","Alexander Guy","CC BY-SA 4.0","Béarnaise sauce with Tarragon garnish.jpeg","w"],"on":"Béarnaise Sauce","og":["30 ml (2 tablespoons) tarragon vinegar","30 ml (2 tablespoons) sherry vinegar or dry white wine","1 shallot, finely chopped","2 egg yolks","75–100 g (⅓–½ cup / 3–4 oz) melted butter (warm but not hot)","Salt","Cayenne pepper to taste","1 tablespoon freshly-chopped tarragon","1 tablespoon freshly-chopped parsley"],"mt":1},{"n":"Béchamelsoße (Grundrezept)","c":"saucen","k":"Frankreich","p":4,"t":30,"d":1,"v":1,"l":"en","g":["50 g Butter","50 g Weizenmehl (Type 405) (Type 405)","1000 ml Vollmilch (über 3 % Milchfett)","1 kleine Zwiebel","1 frisches Lorbeerblatt","Salz","Pfeffer"],"s":["In einem Topf die Butter bei mittlerer Hitze schmelzen. In das Mehl rühren, um einen Roux zu machen.","Den Roux bei sanfter Hitze 3–5 Minuten kochen, aber nicht braun machen. Diese Küche ist notwendig, um den mehligen Geschmack zu entfernen.","In einem separaten Topf die Milch erhitzen. Zwiebel schälen, aber nicht schneiden.","Die Zwiebel und das Lorbeerblatt mit der Milch in den Topf geben. Rühren Sie weiter, bis die Milch auf 80 °C erwärmt wird. Lassen Sie die Milch nicht haften und kochen zu Topf Boden.","Zwiebel und Lorbeerblatt entfernen.","Nach und nach die erwärmte Milch in gekochten Roux schütteln. Salz und Pfeffer nach Geschmack hinzufügen.","15 Minuten rühren und kochen, bis sie verdickt sind. Es sollten keine Klumpen vorhanden sein."],"x":[],"desc":"Béchamel ist eine der fünf \"Muttersoßen\" in der französischen Küche. Als weiße Grundsoße kann sie als Basis vieler anderer Saucen verwendet werden.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Béchamel_Sauce_(Basic)","i":"wb-en-1123","im":["8/8a/2021_Sos_beszamelowy.jpg/960px-2021_Sos_beszamelowy.jpg","Jacek Halicki","CC BY-SA 4.0","2021 Sos beszamelowy.jpg","w"],"on":"Béchamel Sauce (Basic)","og":["50 g (¼ cup) butter","50 g (¼ cup) white wheat flour (type 405)","1000 ml (4½ cups) whole milk (>3% milk fat)","1 small onion","1 fresh bay leaf","Salt","Pepper"],"mt":1},{"n":"Béchamelsoße (nach Beeton)","c":"saucen","k":"","p":4,"t":30,"d":1,"v":0,"l":"en","g":["40 g Weizenmehl (Type 405)","40 g Butter","700 ml Milch (oder heller Fond)","1 kleine Zwiebel oder Schalotte","1 kleines Bouquet garni (Petersilie, Thymian, Lorbeerblatt)","10 Pfefferkörner","½ Lorbeerblatt","½ TL Cayennepfeffer","½ TL Muskatnuss","½ TL Salz"],"s":["Die Milch in einen Topf geben und auf den Herd legen. Die Zwiebel oder Schalotte, das Bouquet garni, Pfefferkörner, Mace und Lorbeerblatt hinzufügen und zum Kochen bringen.","In einem anderen Topf die Butter schmelzen, das Mehl unterrühren und ein wenig kochen, ohne zu bräunen, um einen Roux herzustellen.","Rühren Sie Ihre heiße Milchmischung und rühren Sie über die Hitze, bis sie kocht, dann bringen Sie die Temperatur nach unten und lassen Sie es für 15 bis 20 Minuten köcheln.","Durch ein Sieb oder einen Muslin abseihen, zum Topf zurückkehren und leicht mit 1⁄2 tsp Muskatnuss, 1⁄2 tsp Cayenne und 1⁄2 tsp Salz würzen.","Servieren."],"x":[],"desc":"Béchamel oder weiße französische Soße (französisch: Sauce Béchamel) ist eine weiße, reichhaltige Soße, die als Grundsoße für viele Gerichte verwendet wird.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Béchamel_Sauce_(Beeton)","i":"wb-en-1124","im":["8/8a/2021_Sos_beszamelowy.jpg/960px-2021_Sos_beszamelowy.jpg","Jacek Halicki","CC BY-SA 4.0","2021 Sos beszamelowy.jpg","w"],"on":"Béchamel Sauce (Beeton)","og":["40 g (1½ oz) of plain flour","40 g (2 oz) of butter","700 ml (1¼ pints) of milk (or white stock)","1 small onion or shallot","1 small bouquet-garni (parsley, thyme, bay leaf)","10 peppercorns","½ bay leaf","½ tsp cayenne","½ tsp nutmeg","½ tsp salt"],"mt":1},{"n":"Béchamelsoße (Louisiana)","c":"saucen","k":"USA","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 Tasse Milch","¼ Zwiebel oder 2 Knoblauchzehen","1 Lorbeerblatt","1–2 EL Butter","1–2 EL Mehl","Salz","Pfeffer"],"s":["Die Milch erwärmen, dann Zwiebel und Lorbeerblatt dazugeben. Steil für 15 Minuten.","Die Butter in einem Topf schmelzen.","Wischen Sie das Mehl ein und kochen Sie auf mittlerer bis mittlerer Hitze, um einen Roux zu machen.","Allmählich in die Milch schütteln.","Kochen, ständig rührend, bis dick.","Mit Salz und Pfeffer würzen."],"x":[],"desc":"Sauce béchamel ist eine der Grundsoßen der französischen Küche. Diese Variante wird in Louisiana für Fischgerichte, vor allem Krebsfleisch verwendet.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Béchamel_Sauce_(Louisiannaise)","i":"wb-en-1125","im":["8/8a/2021_Sos_beszamelowy.jpg/960px-2021_Sos_beszamelowy.jpg","Jacek Halicki","CC BY-SA 4.0","2021 Sos beszamelowy.jpg","w"],"on":"Béchamel Sauce (Louisiannaise)","og":["1 cup milk","¼ ea. onion or 2 garlic cloves","1 bay leaf","1–2 tbsp butter","1–2 tbsp flour","Salt","Pepper"],"mt":1},{"n":"Bête Noire (Schokoladenkuchen ohne Mehl)","c":"kuchen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["½ Tasse Wasser","1 ⅓ Tassen Zucker","120 g Zartbitterschokolade, fein gehackt","230 g ungesüßte Schokolade, fein gehackt","225 g Butter","5 verquirlte Eier"],"s":["Wasser und Zucker zusammen erhitzen, bis sie vollständig aufgelöst sind.","Butter in einem großen Topf bei geringer Hitze schmelzen.","Die gehackte Schokolade zur geschmolzenen Butter geben und glatt rühren.","Den Zuckersirup einrühren und leicht abkühlen lassen.","Die Eier dazugeben und gut vermischen.","Gießen Sie die Mischung in eine gefettete und Backpapier gefütterte 23 cm (23 cm) Federform Pfanne.","Wickeln Sie den Boden und die Seiten der Federform in Aluminiumfolie, so dass kein Wasser beim Kochen im Wasserbad an den Kuchen sickern kann.","In einem Bain-Marie bei 180 °C im Backofen 25–30 Minuten kochen."],"x":[],"desc":"Bête Noire ist ein reichhaltiger Schokoladenkuchen ohne Mehl.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Bête_Noire_(Flourless_Chocolate_Cake)","i":"wb-en-1126","im":["e/e6/Flourless_Chocolate_Cake_with_Bourbon_Vanilla_Ice_Cream.jpg/960px-Flourless_Chocolate_Cake_with_Bourbon_Vanilla_Ice_Cream.jpg","Tammy Green","CC BY-SA 2.0","Flourless Chocolate Cake with Bourbon Vanilla Ice Cream.jpg","w"],"on":"Bête Noire (Flourless Chocolate Cake)","og":["½ cup water","1 ⅓ cup white granulated sugar","4 oz (120 g) bittersweet chocolate, finely chopped","8 oz (230 g) unsweetened chocolate, finely chopped","½ lb (225 g) butter","5 beaten eggs"],"mt":1},{"n":"Bò bía (vietnamesische Frühlingsrollen)","c":"fisch","k":"Vietnam","p":9,"t":60,"d":1,"v":0,"l":"en","g":["9 runde Reispapierblätter","3 chinesische süße Würstchen (Lap Cheong) (Lạp xưởng, chinesische Wurst)","2 Eier","4 EL getrocknete kleine Garnelen","400 g Yambohne (Jicama), geschält und in Stifte geschnitten","1 TL Knoblauch, fein gehackt","Blattsalat, Thai-Basilikum, frische Chili","zerstoßene Erdnüsse, Röstschalotte","Salz, Pfeffer, Zucker","1 EL Pflanzenöl","1 EL Pflanzenöl","1 EL fein gehackter Knoblauch","5 EL Hoisinsoße","5 EL Schweinebrühe oder Wasser","1 EL Erdnussbutter","1 EL Zucker","eingelegte Möhren und Daikon"],"s":["Die kleinen getrockneten Garnelen ohne Öl in einer Pfanne braten, indem sie 2 bis 3 Minuten lang bei mittlerer Hitze ständig umrühren, bis sie duften.","Die Pfanne reinigen, etwa halb voll mit Wasser füllen und zum Kochen bringen. Kochen Sie 2 chinesische Würstchen für etwa 10 Minuten zu erweichen und entfernen Sie etwas von dem Fett. Die Würstchen gut ausspülen, abkühlen lassen und auf einer Diagonalen dünn schieben.","2 Eier in einer kleinen Schüssel knacken und bis flauschig schlagen. Mit einer Prise Salz und einer Prise Zucker leicht würzen.","In einer Antihaftpfanne 1 TL Pflanzenöl hinzufügen. Wenn es heiß genug ist, gießen Sie die Hälfte der Eimischung ein und neigen Sie die Pfanne schnell in einer kreisförmigen Bewegung, um das Ei dünn und gleichmäßig zu verteilen.","Wenn eine Seite golden ist, drehen Sie sie um und braten die andere Seite für 5 weitere Sekunden. Wiederholen Sie, bis die Eimischung aufgebraucht ist.","Lassen Sie die Omeletts komplett abkühlen. Rollen Sie sie hoch und schneiden Sie in Halb-Zoll-Streifen.","In einem Topf etwas Speiseöl erhitzen und 1 EL Knoblauch bis zum Duften anbraten.","Fügen Sie die Jicama-Streifen hinzu und rühren Sie mit etwas Salz für etwa 10 bis 15 Minuten, bis es sich recht transluzent und schmeckt natürlich süß.","1 EL Pflanzenöl in einer kleinen Pfanne auf mittlerer Hitze erhitzen, dann 1 EL gehackten Knoblauch goldbraun anbraten.","Dann fügen Sie Hoisin-Sauce, Schweinebrühe, Erdnussbutter und Zucker. Gut umrühren und bei geringer Hitze 1-2 Minuten köcheln lassen.","Umsteigen in Gewürzschalen und auffüllen mit gehacktem frischem Chili, eingelegten Karotten und Daikon und zerkleinerten Erdnüssen.","Richten Sie eine Walzstation mit vorbereiteten chinesischen Würstchen, gebratenem Jicama, Omelettstreifen, frischem Grün (z.B. Salat und Thai Basilikum), gerösteten kleinen getrockneten Garnelen, ein paar zerkleinerten Erdnüssen und gebratenen Schalotten auf den Tellern bereit.","Bereiten Sie eine kleine Schüssel mit eingelegten Karotten und Daikon.","Bereiten Sie auch eine große Schüssel mit lauwarmem Wasser, um Reispapier zu erweichen, und eine flache Arbeitsfläche (wie ein Schneidbrett oder eine große Platte) für den Rolljob.","Um das Reispapier aufzuweichen, tauchen Sie es schnell in eine Schüssel mit warmem Wasser (die Tauchbewegung sollte nicht länger als 2 Sekunden dauern). Schütteln Sie überschüssiges Wasser vorsichtig ab und legen Sie es auf die flache Oberfläche.","Legen Sie ein Stück Salat und ein paar Basilikumblätter an einem Ende des Papiers, dann weiter einige der Rühr-gebratenen Jicama, einige Scheiben der chinesischen Würste, wenige Omelettstreifen, einige geröstete kleine getrocknete Garnelen, einige gebraten Schalotten und zerkleinerte Erdnüsse hinzufügen.","Ab dem Ende mit Gemüse, rollen 1-2 Runden zuerst, bis Sie die Mitte des Reispapiers erreichen, dann falten beide Seiten nach innen. Dann rollen Sie weiter bis zum anderen Ende des Papiers.","Roll sanft und eng genug, so dass die Zutaten nicht nach dem ersten Bissen herausfallen. Eine schöne Rolle sollte alle Farben der Zutaten im Inneren zeigen.","Zum Servieren die Salatrolle in die Dippensauce oder den Löffel etwas von der Soße auf die Rolle tauchen und einen Bissen essen."],"x":[],"desc":"Bò bía ist die südvietnamesische Variante von Popiah, eine Fujianese/Teochew-Stil frische Frühlingsrolle mit einer Auswahl an frischen, getrockneten und gekochten Zutaten gefüllt, während des Qingming Festivals und anderen feierlichen Anlässen gegessen.","img":"Bo Bia Jicama Rolls.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Bò_bía","i":"wb-en-1127","im":["2/2a/Bo_Bia_Jicama_Rolls.jpg/960px-Bo_Bia_Jicama_Rolls.jpg","Susan","CC BY 2.0","Bo Bia Jicama Rolls.jpg","r"],"on":"Bò bía","og":["9 rice paper rounds","3 ea. Chinese sweet sausages (lạp xưởng)","2 eggs","4 tbsps dried small shrimps","400 g jicama, peeled and cut into matchsticks","1 tsp garlic, minced","Lettuce, Thai basil, fresh chili","Crushed peanuts, fried shallot","Salt, pepper, sugar","1 tbsp vegetable oil","1 tbsp vegetable oil","1 tbsp minced garlic","5 tbsps hoisin sauce","5 tbsps pork broth or water","1 tbsp peanut butter","1 tbsp sugar","Pickled carrots and daikon"],"mt":1},{"n":"Börek (türkisches gefülltes Gebäck)","c":"brot","k":"Türkei","p":4,"t":0,"d":2,"v":0,"l":"en","g":["#Füllungen","Börek mit Käse (Füllung mit weißem Käse)","Börek mit Hackfleisch (Hackfleischfüllung)","Börek mit Hähnchen (Hähnchenfüllung)","Börek mit Spinat (Spinatfüllung)","#Zusammensetzen","2 Tassen vorbereitete Füllung (siehe oben)","1 Packung Yufka- oder Filoteigblätter","geschmolzene Butter oder hochwertiges Pflanzenöl"],"s":["Entfernen Sie die Phylloblätter aus dem Behälter. Entfalten Sie sorgfältig, um sie nicht zu brechen. Legen Sie sie flach und decken mit einem sauberen, feuchten Teetuch zu verhindern, dass sie austrocknen - das ist wichtig.","Schnell arbeiten, die Phyllo in Längsdrittel schneiden (Schritt 1 im Diagramm). Legen Sie eines dieser aus und decken Sie die anderen beiden mit dem feuchten Teetuch.","Den Streifen der Phyllo mit der geschmolzenen Butter bürsten. Legen Sie einen gehäuften Teelöffel Füllung auf ein Ende des Streifens (Schritt 2 im Diagramm).","Falten Sie die rechte untere Ecke nach oben über die Füllung, um ein Dreieck zu bilden (Schritt 3 im Diagramm).","Nun die rechte obere Ecke nach links falten (Schritt 4 im Diagramm).","Weiter so falten, bis Sie das Ende des Streifens zu erreichen.","Trimme jeden überschüssigen Teig und versiegele die Kanten, indem du einen feuchten Finger über den Teig reibst und die Kante des Dreiecks drückst, wo der Streifen endet.","Öl bei 170 °C goldbraun anbraten oder 15 Minuten bei 175 °C backen."],"x":[],"desc":"Börek ist ein allgemeiner Begriff in der türkischen Küche, der für eine Familie von Gebäck mit etwa fünfzig verschiedenen Mitgliedern gilt. Sie haben gemeinsam die Tatsache, dass sie alle Gebäckschichten irgendeiner Art sind, die eine Füllung umschließen. Es gibt zwei grundlegende Methoden; Man besteht aus dem Ausrollen sehr dünne Blätter des Teiges, calle","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Börek_(Turkish_Filled_Pastries)","i":"wb-en-1128","im":["1/13/Burek_trokut_1.png/500px-Burek_trokut_1.png","unbekannt","CC BY-SA 2.5","Burek trokut 1.png","w"],"on":"Börek (Turkish Filled Pastries)","og":["#Fillings","Peynirli börek (white cheese filling)","Kıymalı börek (minced meat filling)","Tavuklu börek (chicken filling)","Ispanaklı börek (spinach filling)","#Assembly","2 cups prepared filling (see above)","1 box yufka/phyllo pastry sheets","Melted butter or high-quality vegetable oil"],"mt":1},{"n":"Kohl-Fufu","c":"welt","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["Weißkohl","Xanthan","Wasser"],"s":["Außenblätter vom Kohl schälen und wegwerfen.","Kohl abspülen und in Stücke schneiden.","Kohl zu einer Paste mischen, Wasser nach Bedarf hinzufügen.","Entfernen Sie überschüssiges Wasser aus dem gemischten Kohl, indem Sie es durch Chiffon Tuch oder Muslin.","Für ein paar Minuten Kohlpaste kochen.","Xanthan-Gummi glatt und klumpenfrei einrühren.","Servieren."],"x":["Xanthan-Gummi wird verwendet, um das Fufu in Kugeln mit der Textur von Semo zu formen."],"desc":"Kohlfufu ist eine aus Kohl zubereitete Schwalbe und wird mit Suppe serviert.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cabbage_Fufu","i":"wb-en-1129","im":["1/1f/Wrapped_fufu.jpg/330px-Wrapped_fufu.jpg","daSupremo","CC BY-SA 4.0","Wrapped fufu.jpg","w"],"on":"Cabbage Fufu","og":["Cabbage","Xanthan gum","Water"],"mt":1},{"n":"Kohl-Kimchi","c":"beilagen","k":"Korea","p":4,"t":3,"d":2,"v":0,"l":"en","g":["1 Kopf Chinakohl (Baechu, Chinakohl, Wombok)","½ Tasse Meersalz (oder anderes grobes Salz)","1 Tasse Wasser","2 EL fein gehackter Knoblauch","1 TL fein gehackter Ingwer","½ Tasse Gochugaru (koreanische Chiliflocken) (koreanische Chiliflocken)","2 TL Salz","1 EL Zucker","¼ Tasse Aekjeot (koreanische Fischsoße) (koreanische Fischsoße)","½ Zwiebel, in dünne Scheiben geschnitten","¼ Möhre, in feine Streifen geschnitten","¼ koreanischer Rettich (Muwoo), in feine Streifen geschnitten","4 Frühlingszwiebeln, in 3 cm große Stücke geschnitten"],"s":["Den Napakohl vierteln, waschen und abtropfen lassen.","Kombinieren Sie grobes Meersalz und Wasser.","Bringen Sie Kohl in Salzwasser und nehmen Sie eine nach der anderen heraus, um Salz nach unten zu bekommen.","Kohl in einen Behälter geben. Gießen Sie gesalzenes Wasser über oben, und beiseite für mindestens 6–8 Stunden (Übernachtung ist toll). Der Kohl sollte weich genug sein, um sich zu biegen.","Kohl waschen und gut abtropfen lassen.","Kombinieren Sie gochugaru, Salz, Zucker, Jeot gal (Korean Fischsauce), gehackten Knoblauch und gehackten Ingwer.","Zwiebel, Karotte, Radieschen und grüne Zwiebel in die Chilipulvermischung mischen.","Nehmen Sie einen Kohl, und füllen Sie die oben genannte Mischung zwischen jeder Schicht.","Versuchen Sie, den Kohl in der Hälfte zu falten. Mit 2 Außenblättern das Ganze sicher wickeln.","Setzen Sie Kohl in einen luftdichten Behälter, und lassen Sie es bei Raumtemperatur über Nacht sitzen.","Kühlen Sie mindestens 2–3 Tage. Nach ein paar Tagen werden Sie etwas Flüssigkeit bemerken. Das ist völlig normal und ein Zeichen dafür, dass die Kimchi reifen.","Viel Spaß mit dem Kimchi!"],"x":["Koreanische Radieschen sind groß (ca. 1⁄2 bis 1 Kilogramm). Japanische (daikon) Radieschen oder eine größere Menge kleiner europäischer Radieschen könnten ersetzen.","Die Sole kann variiert werden, um viele andere Zutaten enthalten. Sei kreativ.","Der Aekjeot kann durch moderate Mengen an Saeujeot (koreanische gesalzene kleine Garnelen), roher Butterfisch oder rohe Austern ersetzt werden. Meeresfrüchte können auch ganz ausgelassen werden, obwohl eine angemessene Menge an Salz anstelle von fehlendem Jeot gal hinzugefügt werden muss. Alternative Aromen können asiatische Birnen oder Mandarinen sein."],"desc":"Kimchi () ist ein koreanisch-koreanisches Gericht aus eingelegtem Gemüse, in der Regel Napakohl oder koreanischer Radieschen und wird häufig als Beilage serviert. Es wird in der Regel in einer Sole Sardellensauce, Ingwer, Knoblauch, grüne Zwiebel und Chili gegoren. Es gibt unzählige Sorten – bei leas","img":"Gimchi.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Cabbage_Kimchi","i":"wb-en-1130","im":["a/a3/Gimchi.jpg/960px-Gimchi.jpg","Nagyman , a flickr user","CC BY-SA 2.0","Gimchi.jpg","r"],"on":"Cabbage Kimchi","og":["1 head napa cabbage (baechu, Chinese cabbage, wombok)","½ cup sea salt (or any coarse salt)","1 cup water","2 tbsp minced garlic","1 tsp minced ginger","½ cup gochugaru (Korean chile flakes)","2 tsp salt","1 tbsp sugar","¼ cup aekjeot (Korean fish sauce)","½ onion, thinly sliced","¼ carrot, thinly julienned","¼ Korean radish (muwoo), thinly julienned","4 green onions, cut into 3-cm pieces"],"mt":1},{"n":"Kohlrouladen in Tomatensoße (Holubzi)","c":"saucen","k":"Ukraine","p":4,"t":0,"d":2,"v":0,"l":"en","g":["12 Kohlblätter","½ Tasse gehackte Zwiebel","2 TL Salz","1 TL Pfeffer","½ Tasse Milch","450 g Rinderhack (etwa 500 g)","¾ Tasse gekochter Reis","1 Ei","#Soße","1 Dose Tomatenmark","1 Dose gehackte Tomaten","½ Tasse Wasser","2 EL Essig","3 EL Zucker","2 EL Speisestärke, mit ½ Tasse kaltem Wasser verrührt"],"s":["Backofen auf 175 °C vorheizen.","Kohl in den Topf mit kochendem Wasser geben, abdecken, für drei Minuten stehen lassen, dann abtropfen.","Kombinieren Sie Hackfleisch, Milch, Ei, Reis, Zwiebel, Pfeffer und Salz. Aufteilen in zwölf Portionen.","1 Fleischteil auf jedes Kohlblatt legen.","Blatt um Füllung rollen und mit Zahnstocher befestigen.","Die Brötchen in eine Backform geben.","Kombinieren Sie Tomatenpaste, Tomaten, Zucker, Wasser und Essig, dann über Kohl Rollen gießen.","Backform abdecken und bei 175 °C (175C) 40 Minuten backen.","Kohlrollen aus der Pfanne nehmen und Zahnstocher herausnehmen. Auf die Servierschale legen","Maisstärke und Wasser zur Saucenmischung hinzufügen und zusammenrühren. Bei Bedarf warm, damit die Maisstärkemischung die Sauce verdicken kann.","Die fertige Soße über die Brötchen auf das Serviergericht geben.","Nach Belieben garnieren und servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cabbage_Rolls_in_Tomato_Sauce_(Holubtsi)","i":"wb-en-1131","im":["f/f8/Tomato_sauce_for_stuffed_cabbage.jpg/500px-Tomato_sauce_for_stuffed_cabbage.jpg","gran","CC BY 3.0","Tomato sauce for stuffed cabbage.jpg","c"],"on":"Cabbage Rolls in Tomato Sauce (Holubtsi)","og":["12 cabbage leaves","½ cup chopped onion","2 tsp salt","1 tsp pepper","½ cup milk","1 lb (about 500 g) ground beef","¾ cup cooked rice","1 egg","#Sauce","1 can tomato paste","1 can chopped tomatoes","½ cup water","2 Tbsp vinegar","3 Tbsp sugar","2 Tbsp cornstarch mixed with ½ cup cold water"],"mt":1},{"n":"Kohlrouladen in Joghurtsoße (Sarmi)","c":"snacks","k":"Bulgarien","p":4,"t":0,"d":2,"v":0,"l":"en","g":["500 g Kalbs- oder Rinderhack (gemahlen)","300 g Schweinehack (gemahlen)","1 Bund Frühlingszwiebeln","½ Tasse ungekochter Reis","1 Tasse Joghurt","Petersilie","Minze","Paprikapulver (optional)","Pfeffer","30–40 Wein- oder Kohlblätter (je nach Größe können deutlich weniger Blätter reichen)","100 g Butter oder ½ Tasse Sonnenblumenöl","Salz"],"s":["Die Wein- oder Kohlblätter in Salzwasser kochen, bis sie gekocht aussehen und einfach biegsam genug sind, um zu rollen. Abtropfen und während der folgenden Schritte abkühlen lassen.","Die fein gehackten Zwiebeln in einer kleinen Menge Öl leicht anbraten und im Teelöffel oder mehr Paprika unterrühren.","Fleisch, Reis, Pfeffer, Minze und fein gehackte Petersilie dazugeben, dann kochen, bis das Fleisch fast fertig aussieht.","3⁄4 Tasse Wasser hinzufügen, zum Kochen bringen, dann sofort abdecken und die Hitze auf ein bloßes Minimum für 10 Minuten reduzieren, bis das Wasser vom Reis absorbiert wird. Enthüllen und flauschen nach Bedarf mit einem kleinen Spatel oder Löffel. Auf die Handhabungstemperatur abkühlen lassen.","1 Teelöffel der Fleischmischung auf jedes Blatt geben und in eine gerollte, vollständig umschlossene Packung, ähnlich einer kleinen Eirolle, machen. Ein bisschen mehr Füllung kann verwendet werden, wenn Sie große Kohlblätter verwenden, aber versuchen, alle Rollen etwas einheitlich in der Größe zu machen.","Die Brötchen in einem Topf anrichten, 11⁄2 Tassen warmes Wasser dazugeben, bedecken und bei geringer Hitze sanft köcheln lassen.","In der Zwischenzeit mischen Sie den Joghurt mit ein wenig Paprika für Farbe (oder weglassen, wenn Sie das Gericht etwas weiß in der Farbe zu halten), und andere Gewürze, wie Sie wünschen.","Wenn die Brötchen fertig sind, lassen Sie ein wenig abkühlen, übertragen Sie sanft auf eine Schüssel und fügen Sie die Joghurt-Mischung zu beschichten.","Servieren Sie mit Gemüse Ihrer Wahl. Viel Spaß!"],"x":[],"desc":"Sarmi ist ein bulgarisches Gericht aus gefüllten Kohlblättern, das bedeutende griechische Einflüsse zeigt. Für eine Versammlung können Sie diese etwas \"weißen\" Rollen nebeneinander mit einem Teller Kohlrollen in Tomatensauce (siehe Kohlrollen in Tomatensauce (Holubtsi)) präsentieren.","img":"Sarmi.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Cabbage_Rolls_in_Yogurt_Sauce_(Sarmi)","i":"wb-en-1132","im":["9/98/Sarmi.jpg/960px-Sarmi.jpg","unbekannt","CC BY 2.5","Sarmi.jpg","r"],"on":"Cabbage Rolls in Yogurt Sauce (Sarmi)","og":["500 g (about 1 ⅛ lb) minced (ground) veal or beef","300 g (about ¾ lb) minced (ground) pork","1 bunch of spring onions","½ cup uncooked rice","1 cup yogurt","Parsley","Mint","Paprika (optional)","Pepper","30–40 grape or cabbage leaves (depending on the size, a substantially smaller number of leaves may be needed)","100 g butter or ½ cup sunflower oil","Salt"],"mt":1},{"n":"Krautsalat","c":"salate","k":"","p":8,"t":5,"d":1,"v":0,"l":"en","g":["½ Kopf Weißkohl (500 g)","100 ml Rapsöl","2 EL Branntweinessig","1 Prise Salz","1 Prise grob gemahlener Pfeffer"],"s":["Den Kohl fein schneiden (ca. 1–2 mm dick).","Machen Sie einen Dressing mit Öl, Essig, Salz und Pfeffer. Wirf den Kohl mit dem Dressing.","Den Salat über Nacht in den Kühlschrank geben."],"x":[],"desc":"Dieser einfache Kohlsalat passt wunderbar zu Pizza.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cabbage_Salad","i":"wb-en-1133","im":["e/ed/Salad_with_red_cabbage%2C_pepper_and_unidentified_ingredient_%28probably_potato%29.jpg/960px-Salad_with_red_cabbage%2C_pepper_and_unidentified_ingredient_%28probably_potato%29.jpg","최광모","CC BY-SA 4.0","Salad with red cabbage, pepper and unidentified ingredient (probably potato).jpg","c"],"on":"Cabbage Salad","og":["½ head (500 grams) white cabbage","100 ml rapeseed oil","2 tablespoons white vinegar","1 pinch of salt","1 pinch of coarsely-ground pepper"],"mt":1},{"n":"Cabbie Claw (schottischer Weißfisch mit Ei und Kartoffeln)","c":"fisch","k":"Schottland","p":4,"t":0,"d":2,"v":0,"l":"en","g":["1 kg ganzer Spelding (getrockneter Dorsch) (Kabeljau oder anderer weißer Fisch wie Schellfisch oder Wittling)","2 EL grobes Meersalz (zum Pökeln)","2-3 Zweige frische Petersilie (plus etwas zum Garnieren)","2-3 Scheiben frischer Meerrettich (optional, für beides)","50 g Butter","40 g Mehl","250 ml Milch","250 ml aufbewahrte Fischbrühe","2 hartgekochte Eier (Eiweiß gehackt, Eigelb zum Garnieren aufheben)","1 Prise frisch geriebene Muskatnuss","Salz und Pfeffer, nach Geschmack","500 g Kartoffelpüree, zum Servieren","1 Prise Cayennepfeffer, zum Garnieren"],"s":["Säubern Sie das Spelding, entfernen Sie die Augen, teilen Sie den Fisch und wischen Sie es ab. Die Fische mit grobem Salz reiben und über Nacht verlassen.","Am folgenden Tag hängen Sie den Fisch 24 Stunden lang an einem schattigen, kühlen, luftigen Platz auf.","Die Fische in einem Wasserkocher mit kochendem Wasser bedecken. Petersilie und frische Meerrettich können der Brühe hinzugefügt werden. Simmer, bis der Fisch gekocht ist.","Die Fische aus der Brühe entfernen und die Brühe beiseite legen.","Haut und entbeinen die Fische, dann flocken das Fleisch grob und warm halten in einem langsamen Ofen.","Machen Sie einen Roux mit der Butter und Mehl, dann langsam fügen Sie die Fischbrühe und Milch, ständig rühren, um Lumpines zu vermeiden.","Das Weiß der Eier grob hacken (das Eigelb beiseite legen). Das Weiß in die Sauce mischen und nach Geschmack abschmecken.","Layer die flockigen Fische auf dem Kartoffelpüree. Die Sauce darüber gießen und mit gehacktem Eigelb, Petersilie und Cayenne garnieren."],"x":[],"desc":"Cabbie Kralle oder Cabelew ist ein traditionelles Gericht aus dem Nordosten von Schottland und Orkney. Es wird traditionell aus Speldings hergestellt, die junge Fische der Gadidae-Familie sind, wie Kabeljau, Schellfisch oder Wittling. Der obskure Name ist eine Ableitung des französischen Namens für Kabeljau, Cabillaud.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cabbie_Claw_(Scottish_Whitefish_with_Egg_and_Potato)","i":"wb-en-1134","on":"Cabbie Claw (Scottish Whitefish with Egg and Potato)","og":["1 kg (about 2 lb) whole spelding (cod or other whitefish like haddock or whiting)","2 tbsp Coarse sea salt (for curing)","2-3 springs fresh Parsley (plus extra for garnish)","2-3 slices fresh Horseradish (optional, for both)","50 g (3½ tbsp) Butter","40 g (⅓ cup) Flour","250 ml (1 cup) Milk","250 ml (1 cup) reserved fish broth","2 Hard boiled eggs (whites chopped, yolks reserved for garnish)","A pinch of freshly grated Nutmeg","Salt and pepper, to taste.","500 g (about 1 lb) Mashed potato, for serving","A pinch of cayenne pepper, for garnish"],"mt":1},{"n":"Cachapa (venezolanische Maispfannkuchen)","c":"kuchen","k":"Venezuela","p":4,"t":0,"d":1,"v":1,"l":"en","g":["1 Dose Rahmmais (398 g)","¾ Tasse Pfannkuchen-Backmischung","¼ Tasse Mehl","1 Ei","2 EL geschmolzene Butter oder Margarine","2 EL Zucker, oder nach Geschmack","Käse nach Wahl"],"s":["Alle Zutaten in einem Mixer mischen. Die Mischung sollte dick und schwer werden. Wenn nicht, fügen Sie mehr Mais.","Den Mix zu kleinen Pfannkuchen ca. 1⁄2 Zoll (1,5 cm) dick und ca. 13 cm (13 cm) im Durchmesser formen. Lassen Sie sie bei mittlerer Hitze für etwa 1 Minute auf jeder Seite kochen, oder bis kleine Blasen auf der Oberseite bilden.","Cachapas sollte heiß serviert werden und kann mit Käse begleitet werden (Feta-Käse ist eine Option, mexikanischer Weißwein \"Cotija\", venezolanische oder kolumbianische \"Queso Blanco\" ,\"Queso de Mano\" oder \"Queso Guayanes\", wo verfügbar)."],"x":[],"desc":"Cachapas werden traditionell mit frischem Mais hergestellt, und sind ein Sommer-Favorit, aber dieses einfache Rezept verwendet Konservencreme Mais, Pfannkuchen Mischung, und was Käse Sie auf der Hand haben. Probieren Sie diese einfache Vorspeise für einen Geschmack von Venezuela, wann immer Sie wollen.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cachapa_(Venezuelan_Corn_Pancakes)","i":"wb-en-1135","im":["6/6e/Cooking_a_cachapa.jpg/960px-Cooking_a_cachapa.jpg","Wilfredor","CC BY-SA 3.0","Cooking a cachapa.jpg","w"],"on":"Cachapa (Venezuelan Corn Pancakes)","og":["1 can (14 fl oz / 398 g) creamed corn","¾ cup pancake mix","¼ cup flour","1 egg","2 tablespoons melted butter or margarine","2 tablespoons sugar, or to taste","Cheese of your choice"],"mt":1},{"n":"Cachupa (kapverdischer Maiseintopf)","c":"suppen","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["910 g gepökelte Rinderbrust (Corned Beef), gewürfelt","680 g gesalzener Speck, in große Stücke geschnitten","3 TL Apfelmost oder Weißweinessig","2 frische Lorbeerblätter","2 TL geräuchertes Paprikapulver","1 TL Salz, oder nach Geschmack","½ TL schwarzer Pfeffer, oder nach Geschmack","3 EL zerdrückter Knoblauch","1 Tasse Feijão-Pedro-Bohnen (Steinbohnen)","3 EL Olivenöl","2 mittelgroße Zwiebeln, sauber gehackt","2 große Rinderbrühwürfel","3 TL Tomatenmark","etwa 18 Tassen Wasser","2 Tassen getrockneter gelber Hominy-Mais, gut abgespült","1 Tasse Borlottibohnen","1 ¼ Tassen große weiße Ackerbohnen","1 mittelgroßer Maniok","4 Tassen Blattkohl oder Grünkohl, abgespült und gehackt","910 g Chouriço oder Linguiça, abgespült und in runde Scheiben geschnitten"],"s":["Das Cornedbeef und das Salzschwein in der Nacht zuvor mit Essig, Lorbeerblättern, geräuchertem Paprika, Salz, schwarzem Pfeffer und 2 Esslöffel zerstoßenem Knoblauch würzen. Das Fleisch über Nacht im Kühlschrank marinieren lassen.","Die Bohnen auch über Nacht einweichen.","In einem Topf das Olivenöl bei mittlerer Hitze erhitzen und die fein gehackten Zwiebeln und die restlichen Esslöffel Knoblauch dazugeben. Übertragen Sie die Lorbeerblätter vom gewürzten Fleisch auf den Topf. Zwiebeln bis zum Duften anbraten.","Das marinierte Fleisch in den Topf geben und ca. 10 Minuten lang braun lassen (5 Minuten pro Seite). Das Fleisch aus dem Topf nehmen und beiseite stellen.","Die Tomatenpaste und einige der zerkleinerten Bouillonwürfel in den Topf geben. Faszinieren, bis es glatt ist.","Das Fleisch wieder in den Topf geben, dann mit Wasser bedecken. Den Topf bedecken und zum Kochen bringen.","In die Hominy einrühren, zum Kochen bringen und die Hitze auf niedrig reduzieren. Überdecken und ca. 1 Stunde köcheln lassen. Stellen Sie sicher, dass genug Wasser in der Pfanne ist, und überprüfen Sie die Hominy etwa alle 20 Minuten, um es zu rühren.","Entfernen Sie das Fleisch aus dem Topf und zerkleinern Sie es durch leichtes Ziehen einer Gabel gegen ihn. Dieser Schritt ist optional, kann aber helfen, brechen einige der Stücke von Fleisch zu machen mehr Platz in der Pfanne für die restlichen Zutaten.","Das Fleisch in den Topf geben, wieder umrühren und die Cranberrybohnen, Favabohnen, Yuca und Grün dazugeben. Wenn die Zutaten scheinen zu sperrig, fügen Sie etwa die Hälfte der Grüns auf den ersten und lassen Sie es kochen für etwa 5 Minuten, dann fügen Sie die restlichen.","Lassen Sie alles für etwa 50 Minuten kochen.","Fügen Sie die chourico, und lassen Sie kochen für etwa 20 Minuten.","Rühren und probieren Sie die Cachupa, dann passen Sie die Würze wie gewünscht. Lassen Sie es für weitere 10-15 Minuten köcheln.","Entfernen Sie von der Hitze, und lassen Sie die cachupa ruhen, bedeckt, für 20 Minuten.","Genießen Sie mit jeder kostenlosen oder Lieblings-Beilage Ihrer Wahl."],"x":["Bei der Zubereitung dieser Mahlzeit ist es ratsam, während des gesamten Kochvorgangs einen Wasserkocher mit kochendem Wasser zur Hand zu haben, so dass bei Bedarf in jeder Phase mehr Wasser hinzugefügt werden kann – verwenden Sie kein kaltes Wasser.","Sie können auch weiße hominy anstelle von gelb; Es hängt alles von Ihrer Vorliebe ab, obwohl die meisten Leute es vorziehen, die gelbe Hominie zu benutzen."],"desc":"Cachupa ist ein beliebtes Gericht in Westafrika gegessen. Es braucht viel Zeit, um sich vorzubereiten.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cachupa_(Cape_Verdean_Corn_Stew)","i":"wb-en-1136","im":["6/64/Cachupa_2.jpg/960px-Cachupa_2.jpg","Xandu","Public domain","Cachupa 2.jpg","w"],"on":"Cachupa (Cape Verdean Corn Stew)","og":["2 pounds corned beef brisket, cut into cubes","1½ pound salt pork, cut into big chunks","3 teaspoons apple cider or white vinegar","2 fresh bay leaves","2 teaspoons powdered smoked paprika","1 teaspoon salt or to taste","½ teaspoon black pepper or to taste","3 tablespoons crushed garlic","1 cup feijao Pedro beans (rock beans)","3 tablespoons olive oil","2 medium-size onions, neatly chopped","2 large beef bouillon cubes","3 teaspoons tomato paste","About 18 cups watery","2 cups dry yellow hominy, well-rinsed","1 cup cranberry beans","1¼ cup large white fava beans","1 medium size madioca or yuca","4 cups collard greens or kale, rinsed and chopped","2 pounds chourico or linguica sausage, rinsed and sliced into rounds"],"mt":1},{"n":"Caesar Salad","c":"salate","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 Kopf Römersalat, grob gehackt","¼ Tasse natives Olivenöl extra (etwa 50 ml), aufgeteilt","eine kräftige Prise Meersalz","frisch gemahlener schwarzer Pfeffer","ein Schuss Rotweinessig","3 Spritzer Worcestersoße","2 weichgekochte Eier","Knoblauch-Croûtons"],"s":["Nieselsalat mit 2 EL extra nativem Olivenöl. Werfen Sie in den Mantel.","Salz und Pfeffer dazugeben. Werfen Sie in den Mantel.","Essig und werfen, um zu beschichten.","Drizzle Worcestershire-Sauce über Salat. Werfen Sie in den Mantel.","Eier über Salat zerkratzen. Werfen Sie in den Mantel.","Oben mit Knoblauch Croûtons und servieren."],"x":[],"desc":"Der Caesar-Salat ist ein traditioneller Salat, der in amerikanischen Restaurants serviert wird. Es wird von einigen als \"König\" der Salate bezeichnet.","img":"CaesarSalad3.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Caesar_Salad","i":"wb-en-1137","im":["a/a7/CaesarSalad3.jpg/250px-CaesarSalad3.jpg","User Novellina on en.wikipedia","Public domain","CaesarSalad3.jpg","r"],"og":["1 head Romaine lettuce, roughly chopped","¼ cup (about 50 ml) extra-virgin olive oil, divided","Heavy pinch of sea salt","Freshly-ground black pepper","Drizzle of red wine vinegar","3 shots Worcestershire sauce","2 soft-boiled eggs","Garlic croûtons"],"mt":1},{"n":"Café au Lait","c":"getraenke","k":"","p":8,"t":20,"d":1,"v":0,"l":"en","g":["350–475 ml frisch gebrühter Kaffee oder 1,5 bis 2 Tassen Cold-Brew-Konzentrat","950 ml Milch"],"s":["Wenn Sie Kaffeekonzentrat verwenden, fügen Sie genügend heißes Wasser hinzu, um 4 Tassen Kaffee zu machen.","Gleichzeitig die Milch über eine niedrige bis mittlere Hitze erhitzen, bis sie verbrüht wird.","Gießen Sie die gleichen Mengen an Kaffee und Milch in Schüsseln oder Tassen."],"x":["Gedämpfte Milch kann durch gesalzene Milch ersetzt werden.","Die Milch kann in den Bechern erhitzt werden, indem jede Tasse halb mit Milch und Mikrowaving kurz gefüllt wird. Ein 1000W Mikrowellenherd erwärmt eine halbe Tasse Milch in 50 Sekunden, zwei in 60 Sekunden."],"desc":"Buchstäblich \"Kaffee mit Milch\" ist café au lait ein Getränk aus Kaffee und verbrühter Milch im Verhältnis 1:1. Es ist das Hauptkaffeegetränk von Französisch Louisiana und wird oft in Schüsseln in Acadiana serviert.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Café_au_Lait","i":"wb-en-1138","im":["9/9c/Caf%C3%A9_au_lait.jpg/960px-Caf%C3%A9_au_lait.jpg","Tim Boyd from Brooklyn","CC BY 2.0","Café au lait.jpg","w"],"og":["4 cups brewed coffee or 1.5–2 cups (350–475 ml) cold coffee concentrate","4 cups (950 ml) milk"],"mt":1},{"n":"Cajun-Burger","c":"fleisch","k":"USA","p":4,"t":0,"d":2,"v":0,"l":"en","g":["½ Tasse Mayonnaise (etwa 120 ml)","Cajun-Gewürz","450 g Rinderhack","4 Scheiben Pepper Jack (Käse mit Chili)","4 Hamburgerbrötchen, halbiert"],"s":["Mayonnaise und 1 Tbsp Cajun Würze kombinieren. Kühlen, bis nötig.","Fleisch in 4 gleiche Patties formen, 1⁄2 Zoll (1,25 cm) dick. Bestreuen Sie liberal auf beiden Seiten mit Gewürzen.","Grill vorheizen. Burger hinzufügen und kochen, oft drehen, bis die gewünschte Fertigkeit erreicht ist (74 °C).","Verteilen Sie Mayo auf Brötchen und stellen Sie die Burger in.","Iss!"],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cajun_Burger","i":"wb-en-1139","im":["0/05/05_Spiced_Cajun_Burger_-_Tchoup_Shop.jpg/500px-05_Spiced_Cajun_Burger_-_Tchoup_Shop.jpg","jasonlam","CC BY-SA 2.0","05 Spiced Cajun Burger - Tchoup Shop.jpg","c"],"on":"Cajun Burger","og":["½ cup (about 120 ml) mayonnaise","Cajun seasoning","1 pound (450 g) ground beef","4 slices pepper jack cheese","4 hamburger buns, split in half"],"mt":1},{"n":"Rote Bohnen mit Reis nach Cajun-Art","c":"beilagen","k":"","p":6,"t":4,"d":2,"v":0,"l":"en","g":["450 g getrocknete rote Bohnen (z. B. Kidneybohnen oder Augenbohnen)","6 große Eisbeine (1.5–2 kg)","2 Tassen fein gehackter Staudensellerie (½ Stange)","2 Tassen fein gehackte Zwiebeln","2 Tassen fein gehackte Paprika","5 Lorbeerblätter","3 EL Seafood Magic (Gewürz von Paul Prudhomme), oder ein ähnliches Gewürz","1 EL Tabasco oder eine ähnliche scharfe Soße","4 Tassen gekochter Reis"],"s":["Bohnen mit Wasser bedecken und über Nacht einweichen lassen. Entwässern.","Schinkenschinken, Sellerie, Zwiebeln, Paprika, Lorbeerblätter und Gewürze in einen großen Topf mit 10 Tassen Wasser geben. Bedecken und zum Kochen bringen.","Simmer, bis Fleisch Gabel zart ist, etwa eine Stunde nach dem Sieden beginnt, gelegentlich Rühren.","Schinkenkegel aus der Pfanne nehmen und beiseite stellen. Haut Fett aus der Pfanne und wegwerfen.","Entfernen Sie einen signifikanten Bruchteil der Flüssigkeit aus der Pfanne, fügen Sie abgelassene Bohnen, und fügen Sie gerade genug Flüssigkeit, um Bohnen zu decken. Bohnen köcheln, bis sie gerade anfangen zu brechen und die Flüssigkeit beginnt cremig zu werden, etwa 45 Minuten. Häufig umrühren.","Fügen Sie die Flüssigkeit nach Bedarf, um Bohnen bedeckt zu halten. Wenn Bohnen beginnen zu schmoren, nicht umrühren; Mischung auf eine andere Pfanne übertragen, ohne verbrannte Bohnen in einen neuen Topf zu kratzen.","Schinkenschinken hinzufügen und 45 Minuten mehr kochen, und sofort servieren.","Auf einer beheizten Servierplatte, hügelige 3⁄4 Tasse Reis pro Servieren an einem Ende der Platte, legen Sie Schinken-Hocken an anderen Ende, und 1 Tasse Bohnen pro Servieren in der Mitte."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cajun_Red_Beans_and_Rice","i":"wb-en-1140","im":["7/76/Red_beans.jpg/500px-Red_beans.jpg","Will7777 at en.wikipedia","Public domain","Red beans.jpg","w"],"on":"Cajun Red Beans and Rice","og":["1 pound dry red beans (e.g. kidney or cowpea)","6 ea. (3½–4 pounds / 1.5–2 kg) large ham hocks","2 cups (½ stalk) finely-chopped celery","2 cups (1 ea.) finely-chopped onions","2 cups (1 ea.) finely-chopped bell peppers","5 bay leaves","3 Tbsp Paul Prudhomme's Seafood Magic, or a similar spice","1 Tbsp tabasco sauce or similar hot sauce","4 cups cooked rice"],"mt":1},{"n":"Kuchen-Brownies","c":"brot","k":"","p":20,"t":30,"d":1,"v":0,"l":"en","g":["2 Eier","2.4 dl Zucker","120 g geschmolzene Butter oder Sahne","4 EL Kakao","180 g Mehl","½ TL Salz","½ TL Backpulver","1 TL Vanille","120 g gehackte Walnüsse oder andere Nüsse (optional)"],"s":["Backofen auf 175 °C vorheizen. Fett eine 23 x 23 cm (23 x 23 cm) quadratische Kuchen Pfanne.","Rühre Eier in einer mittelgroßen Schüssel bis zum Licht.","Zucker, geschmolzene Butter und Kakao zugeben. Mischen Sie gut.","Mehl, Salz, Backpulver, Vanille und Nüsse hinzufügen. Mit einem Gummispatel gut vermischen.","In vorbereitete Pfanne gießen. 20 Minuten bei 175 °C backen (Gasmark 4).","Ganz ruhig."],"x":[],"desc":"Diese Kuchen-Brownies sind etwas weniger dicht und fast kuchenartig im Vergleich zu Fertigmischungen, die man aus einem Laden kaufen würde.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cake_Brownies","i":"wb-en-1141","im":["c/c8/1899_Brownie_cake_recipe.png/960px-1899_Brownie_cake_recipe.png","Our Horticultural Visitor","Public domain","1899 Brownie cake recipe.png","c"],"on":"Cake Brownies","og":["2 eggs","1 cup (6 ¾ oz / 2.4 dl) white granulated sugar","½ cup (4 ¼ oz / 120 g) melted butter or cream","4 tbsp cocoa","¾ cup (6 ¼oz / 180 g / 1.8 dl) flour","½ tsp salt","½ tsp baking powder","1 tsp vanilla","½ cup (4 ¼ oz / 120 g / 1.2 dl) chopped walnuts or other nuts (optional)"],"mt":1},{"n":"Kekse aus Kuchenbackmischung","c":"brot","k":"","p":24,"t":20,"d":1,"v":0,"l":"en","g":["1 Packung Kuchenbackmischung (425 g) (beliebige Sorte)","2 Eier","6–7 EL geschmolzene Butter oder Pflanzenöl","Extras zum Untermischen, z. B. Schokotropfen (optional)"],"s":["Den Ofen auf 180 °C vorheizen. Legen Sie ein Backblech mit Backpapier.","Kombinieren Sie den Kuchen Mix, Eier und Butter in einer großen Schüssel, Mischen zu einem weichen Teig. Wenn Sie verwenden, falten Sie die Add-Ins.","Esslöffel Teig auf die Pfanne legen. Der Teig kann klebrig sein, aber das Abkühlen des Teiges für 30 Minuten macht sie fester und einfacher zu arbeiten.","Für 9–11 Minuten backen, bis fertig. Übertragen Sie auf einen Drahtträger und lassen Sie sie abkühlen."],"x":["Für rote Samtkuchen Plätzchen mischen, rote Samtkuchenmischung verwenden und 1 Tasse (125 g) weißen Schokoladenchip in Teig mischen.","Für M&Ms Kuchen-Mix Cookies, verwenden Sie weiße oder gelbe Kuchen-Mix und mischen 1 Tasse (125 g) M&Ms in Teig.","Für Zitronenkuchen Plätzchen mischen, Zitronenkuchen mischen und 1 Esslöffel geriebene Zitronenschale und 1 Esslöffel Zitronensaft in Teig mischen. Teig in Kugeln rollen und in Puderzucker rollen. Wie immer backen. Sie können weniger Butter benötigen, um die zusätzliche Feuchtigkeit zu kompensieren und es einfacher zu rollen.","Für snickerdoodle Kuchen mischen Cookies, verwenden Sie weiße Kuchen Mischung und mischen 1 Esslöffel Zimt in Teig gemahlen. Teig in Kugeln rollen und Zimtzucker (1⁄2 Tasse granulierten Zucker mit 1 Esslöffel gemahlenen Zimt gemischt) rollen. Wie immer backen."],"desc":"Kuchen-Mischkekse ist ein herrliches, schnelles Rezept. Es braucht nur drei Zutaten.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cake_Mix_Cookies","i":"wb-en-1142","im":["7/73/Lavender_Lemon_Cake_Mix_Cookies.jpg/960px-Lavender_Lemon_Cake_Mix_Cookies.jpg","HeatherMarieKosur","CC BY-SA 4.0","Lavender Lemon Cake Mix Cookies.jpg","c"],"on":"Cake Mix Cookies","og":["1 package (15 oz / 425 g) cake mix (any flavor)","2 eggs","6–7 tablespoons melted butter or vegetable oil","Add-ins, such as chocolate chips (optional)"],"mt":1},{"n":"Calamansi-Saftgetränk","c":"getraenke","k":"Philippinen","p":4,"t":0,"d":2,"v":0,"l":"en","g":["3 or 4 Calamansi","1 Glas kaltes Wasser","½ EL Zucker","Eiswürfel (optional)"],"s":["Die Calamansi mit einem scharfen Messer halbieren.","Verwenden Sie Ihre Hände, um den Saft aus dem Calamansi zu pressen.","Kombinieren Sie den Saft mit kaltem Wasser in einem Glas.","Zucker einrühren, bis es gelöst ist.","Eiswürfel hinzufügen."],"x":["Dieses Getränk kann auch heiß serviert werden.","Es ist eine gute Quelle für Vitamin C."],"desc":"Calamansi Saft Getränk ist eine philippinische Version von Limonade, weil calamansi ist leicht auf dem Markt erhältlich.","img":"Calamansi juice (Filipino lemonade).jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Calamansi_Juice_Drink","i":"wb-en-1143","im":["c/c2/Calamansi_juice_%28Filipino_lemonade%29.jpg/960px-Calamansi_juice_%28Filipino_lemonade%29.jpg","Obsidian Soul","CC0","Calamansi juice (Filipino lemonade).jpg","r"],"on":"Calamansi Juice Drink","og":["3 or 4 calamansi","1 glass cold water","½ tablespoon granulated sugar","Ice cubes (optional)"],"mt":1},{"n":"Kalifornisches Curryhähnchen","c":"fleisch","k":"","p":4,"t":45,"d":2,"v":0,"l":"en","g":["#Fleisch und Gemüse","4 EL Speiseöl","1 Tasse gewürfelte gelbe Zwiebeln","2 TL fein gehackter Knoblauch","450 g Hähnchenfleisch ohne Knochen, gewürfelt","6 kleine Kartoffeln, geschält, geviertelt, und gegart (gekocht, gebacken oder gedämpft)","#Gewürze","4 EL mildes Currypulver","1 EL Chilipulver","1 EL Paprikapulver","1 TL gemahlener Kreuzkümmel","1 TL Knoblauchpulver","2 TL gemahlener Kardamom","1 TL gemahlene Kurkuma","1 TL Senfpulver","¼ TL gemahlener Zimt","1 Lorbeerblatt","#Soße","340 g Kokosmilch","3 Tassen Wasser","1 Tasse Joghurt","1 Dose gewürfelte Tomaten (340 g), mit Flüssigkeit","4 EL Butter","#Zum Andicken","¼–½ Tassen Kartoffelpüree-Flocken","Salz, nach Geschmack","Pfeffer, nach Geschmack"],"s":["Kochendes Öl in einem 3,8-Liter großen Topf erhitzen.","Zwiebeln und Knoblauch hinzufügen. Fry für etwa 1 Minute.","Hühnchen hinzufügen. Rühren Sie für etwa 5 Minuten.","Gekochte Kartoffeln dazugeben.","Alle Gewürze dazugeben und Hähnchen und Kartoffeln umrühren. Für ca. 5 Minuten mehr kochen.","Soßenzutaten zugeben, gut umrühren, zum Kochen bringen und 10 Minuten kochen.","1⁄4 Tasse Kartoffelflocken pürieren und umrühren, bis Curry verdickt ist. Wenn ein dickeres Curry gewünscht wird, fügen Sie zusätzliche Kartoffelflocken einen Esslöffel zu einer Zeit hinzu, bis die gewünschte Dicke erreicht ist.","Salz und Pfeffer nach Geschmack hinzufügen."],"x":["Mit gedämpftem Reis servieren."],"desc":"Dieses Gericht ist ein Versuch, den Geschmack von Curry-Hühnchengerichte zu replizieren, die in indischen Restaurants in Kalifornien serviert werden.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:California_Curry_Chicken","i":"wb-en-1144","im":["5/51/Chicken_curry_at_Divewalk_Cafe_-_Sarah_Stierch.jpg/500px-Chicken_curry_at_Divewalk_Cafe_-_Sarah_Stierch.jpg","Missvain","CC BY 4.0","Chicken curry at Divewalk Cafe - Sarah Stierch.jpg","c"],"on":"California Curry Chicken","og":["#Meat and vegetables","4 tbsp cooking oil","1 cup diced yellow onions","2 tsp minced garlic","1 lb boneless chicken meat, cut into cubes","6 small potatoes, peeled, quartered, and cooked (boiled, baked, or steamed)","#Spices","4 tbsp mild curry powder","1 tbsp chile powder","1 tbsp paprika","1 tsp ground cumin","1 tsp garlic powder","2 tsp cardamom powder","1 tsp turmeric powder","1 tsp mustard powder","¼ tsp ground cinnamon","1 bay leaf","#Sauce","1 ½ cups (12 oz) coconut milk","3 cups water","1 cup yogurt","1 can (12 oz) diced tomatoes, with liquid","4 tbsp butter","#Thickener","¼–½ cup of instant mashed potato flakes","Salt to taste","Pepper to taste"],"mt":1},{"n":"Pfirsich-Salsa nach kalifornischer Art","c":"snacks","k":"USA","p":6,"t":5,"d":1,"v":0,"l":"en","g":["2 Dosen Pfirsiche (850 g), abgetropft und gehackt","2 Frühlingszwiebeln, in dünne Scheiben geschnitten, mit Grün","2 EL Limettensaft","2 TL gehackter frischer Koriander","2 TL Knoblauch-Chilisoße","½ TL Fünf-Gewürze-Pulver","¼ TL weißer Pfeffer"],"s":["In einer Schüssel die abgelassenen, gehackten Pfirsiche, in Scheiben geschnittene grüne Zwiebeln, gehackte Koriander, Knoblauch Chilisauce, Limettensaft, fünf Gewürzpulver und weißer Pfeffer mischen.","Wirf gut los.","Beruhige dich vor dem Servieren.","Servieren Sie als Salsa mit Tortilla-Chips oder als Garnierung für Fleischgerichte."],"x":["Wenn Sie diesen kalifornischen Stil machen wollen, verwenden Sie frische Pfirsiche."],"desc":"Diese Fusion Salsa Rezept kombiniert heiße Chili-Sauce und süße Pfirsiche mit asiatischen Gewürzen für eine leckere, würzige Pfirsich Salsa.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:California_Fusion_Peach_Salsa","i":"wb-en-1145","on":"California Fusion Peach Salsa","og":["2 cans (30 oz) peaches, drained and chopped","2 green onions, sliced thin, including tops","2 tablespoons lime juice","2 teaspoons chopped fresh cilantro","2 teaspoons garlic chili sauce","½ teaspoon five spice powder","¼ teaspoon white pepper"],"mt":1},{"n":"Callaloo (karibisches geschmortes Blattgemüse)","c":"suppen","k":"Karibik","p":8,"t":60,"d":2,"v":0,"l":"en","g":["12 Taroblätter (Taro-Blätter, Dasheen oder Callaloo)","115 g gepökeltes Rind- oder Schweinefleisch (optional)","8 Okra (Okra, Ochroe)","4 Stangen Schnittlauch","2 Zweige Thymian","½ Tasse gehackte Zwiebel","1 TL fein gehackter Knoblauch","2 Krabben, geputzt und in Stücke gebrochen","2 Tassen Kokosmilch","2 Tassen heißes Wasser","1 TL Butter"],"s":["Die Stiele und Mittelrippen von den Taroblättern abstreifen.","Waschen und schneiden Sie Blätter und weiche Stiele, werfen Rest weg.","Gesalzenes Rindfleisch oder gesalzenes Schweinefleisch einweichen und in Bissstücke schneiden.","Okra, Schnittlauch und Thymian in kleine Stücke schneiden.","In einem großen Topf kombinieren Kalaloo Blätter, gesalzenes Fleisch, Okra, Schnittlauch, Thymian, Zwiebel, Knoblauch, Krabbe, Kokosmilch und Wasser.","Zum Kochen bringen; Hitze reduzieren, decken und köcheln für 30 Minuten oder mehr, bis alles weich und gekocht ist.","Swizzle oder schlagen mit einem Handschläger.","Butter dazugeben und gut umrühren.","Salz und Pfeffer nach Geschmack hinzufügen."],"x":["Verwenden Sie 1⁄2 Pfund gewürzte Hühnerfüße anstelle von gesalzenem Rindfleisch oder Schweinefleisch.","1 ganzer heißer Pfeffer kann vor dem Kochen hinzugefügt werden; Denken Sie daran, es zu entfernen, wenn Sie kochen. Nicht den Pfeffer sprengen."],"desc":"Servieren Sie als Suppe oder begleitet von Reis und gekochten Bodenvorräten.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Callaloo_(Caribbean_Stewed_Greens)","i":"wb-en-1146","im":["d/d5/Callaloo.jpg/960px-Callaloo.jpg","unbekannt","CC BY 2.0","Callaloo.jpg","w"],"on":"Callaloo (Caribbean Stewed Greens)","og":["12 taro (dasheen or callaloo) leaves","¼ pound salted beef or salted pork (optional)","8 okra (ochroe)","4 stalks chives","2 sprigs thyme","½ cup chopped onion","1 tsp minced garlic","2 crabs, cleaned and broken in pieces","2 cups coconut milk","2 cups hot water","1 tsp butter"],"mt":1},{"n":"Calzone","c":"welt","k":"Italien","p":4,"t":45,"d":1,"v":0,"l":"en","g":["240 ml Ricotta","240 ml geriebener Mozzarella","115 g beliebiger Belag (z. B. Schinken, Speck, Salami, Pepperoni und/oder Wurst) (optional)","2 TL Oregano (10 ml)","1 Packung gekaufter Pizzateig"],"s":["Backofen auf 200 °C vorheizen.","Kombinieren Sie Ricotta, Mozzarella, Toppings und Oregano.","Den Pizzateig zwischen 2 Stück Backpapier rollen.","Die Käsemischung in die Mitte des Teiges geben.","Befeuchten Sie die Ränder des Teiges leicht. Falten Sie den Teig über, und versiegeln Kanten durch Drücken mit einer Gabel.","Backen bis goldbraun, ca. 10 oder 12 Minuten.","Mit Marinara-Sauce servieren."],"x":[],"desc":"Calzone ist eine beliebte italienische Form der Pizza. Das Wort bedeutet Socke, weil die daraus resultierende Pizza einer Socke ähnlich aussieht.","img":"20000227--calzone.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Calzone","i":"wb-en-1147","im":["6/6d/20000227--calzone.jpg/500px-20000227--calzone.jpg","unbekannt","CC BY-SA 3.0","20000227--calzone.jpg","r"],"og":["1 cup (240 ml) ricotta cheese","1 cup (240 ml) shredded mozzarella cheese","4 ounces (115 g) any topping (such as ham, bacon, salami, pepperoni, and/or sausage) (optional)","2 teaspoons (10 ml) oregano","1 package store-bought pizza dough"],"mt":1},{"n":"Koki-Mais aus Kamerun","c":"welt","k":"Kamerun","p":1,"t":40,"d":1,"v":0,"l":"en","g":["⅓–¼ Tassen Palmöl","4 Tassen frischer Mais","½ Zwiebel","1 Tasse gelbes Maismehl","1 TL Salz","1 Brühwürfel","5 Bananenblätter"],"s":["Das Palmöl in einer Pfanne 2–3 Minuten erwärmen, ohne es zu bleichen.","Mais, Zwiebel und Paprika in einen Mixer oder Lebensmittelverarbeiter geben. Fügen Sie 1⁄4 Tasse Wasser, dann mischen, bis Sie eine grob gemahlene Paste zu erreichen. Vermeiden Sie es in eine feine Paste zu mischen; Kleine Stücke und Stücke von Mais sollten noch sichtbar sein.","Übertragen Sie die Mischung in eine Schüssel und fügen Sie das Maismehl. Das erwärmte Öl eingießen und gründlich mischen. Salz und Brühewürfel hinzufügen, dann weiter mischen.","Die gehackten Blätter in die Mischung einbinden und bis gut kombiniert vermischen.","Bereiten Sie einen Topf, indem Sie den Boden mit abgestreiften Maiskolben. Dadurch entsteht eine erhöhte Basis, die verhindert, dass Wasser in den Koki-Mais einsickert.","Gießen Sie etwa 1⁄2 Tasse Wasser in den Topf und bringen Sie es zu einem sanften Kochen, während Sie mit der Verpackung des Koki Mais.","Wickeln Sie die Maismischung in Bananenblätter, um kleine Bündel zu machen. Legen Sie sie in den Topf, dann bedecken Sie sie mit zerrissenen oder ungenutzten Bananenblättern (oder Aluminiumfolie). Dies hilft, den Dampf beim Kochen zu behalten.","Den Deckel auf den Topf legen und ca. 30 Minuten dampfen lassen. Alle 5–10 Minuten den Topf öffnen und 1⁄2 Tasse Wasser dazugeben, damit er nicht austrocknet.","Nach dem Kochen, lassen Sie es für etwa 10 Minuten ruhen. Die Bündel auspacken und den Koki Mais warm servieren.","Genießen Sie Ihren leckeren Koki-Mais!"],"x":[],"desc":"Koki Mais ist ein klassisches kamerunisches Gericht, bekannt für seine lebendige gelbe Farbe, die aus rotem Palmöl gewonnen wird, sowie seinen köstlichen süßen Geschmack, der von frischem Mais stammt. Mais nimmt eine bedeutende Position als Grundnahrungsmittel in der westafrikanischen Region ein, und gedämpfte Maisrezepte sind weit verbreitet. Diese","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cameroon_Koki_Corn","i":"wb-en-1148","im":["8/8c/Koki_Corn.jpg/960px-Koki_Corn.jpg","Adesolive","CC0","Koki Corn.jpg","c"],"on":"Cameroon Koki Corn","og":["⅓–¼ cup palm oil","4 cups fresh corn","½ onion","1 cup yellow corn meal","1 teaspoon salt","1 stock cube","5 banana leaves"],"mt":1},{"n":"Camotes Enmielados (mexikanische Süßkartoffeln in Sirup)","c":"dessert","k":"Mexiko","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 große Yamswurzel oder Süßkartoffel, nach Belieben geschält","1 großer Piloncillo-Kegel (Rohrzucker) (unraffinierter mexikanischer Zucker)","450 g Zimt","½ Wasser"],"s":["Ganze oder dick geschliffene Yams in eine große Backform geben.","Platz piloncilo Kegel auf die Yams, dann fügen Sie Wasser und Zimt.","Für ca. 60 Minuten backen und die Yams mit der jetzt gesüßten Kochflüssigkeit nach Bedarf abfüllen."],"x":["Jeder dunkle, unraffinierte Zucker kann vernünftigerweise durch den Piloncilo ersetzt werden, einschließlich Turbinadozucker, brauner Zucker, brauner Zucker mit zugesetzter Melasse, Muskovado und sogar Jaggerie."],"desc":"Camotes enmielados, auch bekannt als camotes con pilocilo, oder camotes enmielados al horno, camotes con piloncilo al horno, ist ein gebackenes, oder Kochfeld, Dessert-Stil mexikanische Yam / Süßkartoffel Gericht. Es ist traditionell ein hausgemachtes Essen, nicht typisches Restaurantgericht. Das fertige Produkt sollte eine starke","img":"CandiedCamotesMX.JPG","u":"https://en.wikibooks.org/wiki/Cookbook:Camotes_Enmielados_(Mexican_Sweet_Yams)","i":"wb-en-1149","im":["0/0c/CandiedCamotesMX.JPG/960px-CandiedCamotesMX.JPG","Thelmadatter","CC BY-SA 3.0","CandiedCamotesMX.JPG","r"],"on":"Camotes Enmielados (Mexican Sweet Yams)","og":["1 large yam or sweet potato, optionally peeled","1 large piloncilo cone (unrefined Mexican sugar)","4 sticks cinnamon","½ water"],"mt":1},{"n":"Lagerfeuer-Bananenboot","c":"dessert","k":"","p":1,"t":0,"d":1,"v":0,"l":"en","g":["1 Banane","Mini-Marshmallows","Schokotropfen"],"s":["Ziehen Sie einen 1 1⁄2 Zoll (4 cm) breiten Streifen der Schale von der inneren Kurve der Banane, so dass ein Ende an der Banane befestigt.","Schneiden Sie aus und entfernen Sie einen keilförmigen Hohlraum von der Länge der Banane.","Füllen Sie Hohlraum mit Mini-Marshmallows und Schokoladenchips","Peeling ersetzen und gut in schwere Folie wickeln.","Auf Kohlen für ca. 5 Minuten stellen.","Vorsichtig öffnen und mit einem Löffel aus der Bananenschale essen."],"x":[],"desc":"Campfire Bananenboot ist ein sehr einfaches und beliebtes Camping Dessert. Es braucht kein Geschirr – man isst es direkt aus der Schale!","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Campfire_Banana_Boat","i":"wb-en-1150","im":["c/c5/Banana_boat.jpg/960px-Banana_boat.jpg","Andrew Malone","CC BY 2.0","Banana boat.jpg","c"],"on":"Campfire Banana Boat","og":["1 banana","Mini marshmallows","Chocolate chips"],"mt":1},{"n":"Barbecue-Hähnchenflügel vom Lagerfeuer","c":"fleisch","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["#Hähnchenflügel","24 Hähnchenflügel-Mittelstücke","1 EL Cayennepfeffer","1 EL Salz","1 EL schwarzer Pfeffer","#Soße","1 Tasse Tomatenmark","¼ Tasse Melasse","3 Tropfen Flüssigrauch","2 EL Apfelessig","2 EL Weißwein"],"s":["Cayenne, Salz und Pfeffer kombinieren und mit Flügeln werfen. Kühlen.","Kombinieren Sie Sauce Zutaten. In einer Mikrowelle warm und gut gemischt erhitzen. Abkühlen lassen.","Bürsten Sie Flügel an allen Seiten mit etwa 3⁄4 der Soße (oder stellen Sie einfach 3⁄4 der Soße in einem Ziplock mit den Flügeln) und im Kühlschrank so lange wie möglich.","Grillen, bis die Kerntemperatur 74 °C erreicht.","Auf eine Platte nehmen und bedecken. 5 Minuten vor dem Servieren mit den restlichen 1⁄4 der Sauce ruhen lassen."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Campfire_Barbecue_Chicken_Wings","i":"wb-en-1151","on":"Campfire Barbecue Chicken Wings","og":["#Chicken wings","24 chicken wingettes","1 tbsp cayenne pepper","1 tbsp salt","1 tbsp black pepper","#Sauce","1 cup tomato paste","¼ cup molasses","3 drops liquid smoke","2 tbsp cider vinegar","2 tbsp white wine"],"mt":1},{"n":"S'mores vom Lagerfeuer","c":"dessert","k":"","p":1,"t":0,"d":1,"v":0,"l":"en","g":["2 Graham-Cracker","1 Marshmallow","4 Stück Vollmilchschokolade"],"s":["Toast Marshmallow bis goldbraun über Lagerfeuer auf langen grünen Stock mit Rinde abgeschält.","Platzieren Sie auf Graham Cracker, dann mit Schokolade und Rest Cracker."],"x":["Sei vorsichtig. Wenn die Marshmallows bereit sind, sind sie sehr heiß und können Feuer fangen. Verbrenn dich nicht!"],"desc":"Campfire s'mores sind ein klassischer Snack und ein Favorit mit Kindern.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Campfire_S'mores","i":"wb-en-1152","im":["d/d9/Smores-Microwave.jpg/960px-Smores-Microwave.jpg","Evan-Amos","CC0","Smores-Microwave.jpg","w"],"on":"Campfire S'mores","og":["2 graham crackers","1 marshmallow","4 squares milk chocolate"],"mt":1},{"n":"Forelle vom Lagerfeuer","c":"fisch","k":"","p":2,"t":0,"d":2,"v":0,"l":"en","g":["2 ganze ausgenommene Forelle, zwischen 25 und 35 cm","4 Streifen Speck","2 EL Butter","Zitrone","Salz, nach Geschmack","Pfeffer, nach Geschmack"],"s":["Machen Sie eine Pfanne aus Aluminiumfolie etwas größer als Ihre beiden Fische. Die Pfanne sollte eine doppelte Folienschicht am Boden und eine Lippe um den Rand von etwa 3⁄4–2,5 cm Höhe haben.","Legen Sie die Pfanne auf einen Grill über dem Lagerfeuer. Die Butter in die Pfanne geben und mit dem Schmelzen beginnen. Jede Forelle mit 2 Speckstreifen umwickeln. Die Forelle in die Pfanne geben und abschmecken.","Nachdem die Forelle für einige Minuten gekocht hat (5–7 je nach Größe des Fisches), überprüfen Sie die Innenseite. Wenn die Seite in der Nähe des Feuers ist weiß und Flocken leicht, ist der Fisch bereit zu drehen.","Dreht den Fisch um und kocht die andere Seite 3–4 Minuten lang, bis er fertig ist.","Mit Zitrone auf einem Bett aus weißem Reis servieren."],"x":[],"desc":"Gentgeen's Campfire Trout ist das Rezept, mit dem Gentgeen Forelle beim Camping gefangen kocht. Diese Methode kann zu Hause mit Forellen auf dem Fischmarkt gekauft verwendet werden, aber irgendwie schmeckt nie ganz so gut.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Campfire_Trout","i":"wb-en-1153","on":"Campfire Trout","og":["2 whole cleaned trout, between 10 and 14 inches","4 strips bacon","2 tablespoons butter","Lemon","Salt to taste","Pepper to taste"],"mt":1},{"n":"Gebrannte Mandeln (Brända mandlar)","c":"dessert","k":"Schweden","p":4,"t":0,"d":2,"v":1,"l":"en","g":["100 g blanchierte Mandeln","100 g Puderzucker","125 ml Wasser","1 Tropfen rote Lebensmittelfarbe (optional)"],"s":["Legen Sie die Mandeln in den Ofen bei 180 °C für ein paar Minuten, um sie anzustoßen.","Gießen Sie das Wasser in einen schwer unterlegten Topf, dann bestreuen Sie den Zucker. Über eine niedrige Hitze stellen und rühren, bis die Mischung verdickt.","Fügen Sie die Färbung hinzu. Rühren Sie die Mandeln, damit sie eine schöne Beschichtung bekommen.","Die Mandeln auf etwas Backpapier verteilen, die Mandeln mit einer Gabel trennen und ein wenig abkühlen lassen."],"x":[],"desc":"Brända mandlar (wörtlich \"brennte Mandeln\") ist ein Rezept für schwedische kandierte Mandeln.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Candied_Almonds_(Brända_mandlar)","i":"wb-en-1154","im":["4/40/Gebrannte_Mandeln.JPG/960px-Gebrannte_Mandeln.JPG","User:Mattes","Public domain","Gebrannte Mandeln.JPG","w"],"on":"Candied Almonds (Brända mandlar)","og":["100 g blanched almonds","100 g icing sugar","125 ml water","1 drop red food colouring (optional)"],"mt":1},{"n":"Kandierte Aprikosen","c":"welt","k":"","p":2,"t":15,"d":1,"v":0,"l":"en","g":["6–10 + getrocknete Aprikosen","etwa 1 Tasse Wasser","eine große Handvoll Zucker","Walnüsse (optional)"],"s":["Soak getrocknet Aprikosen in einem großen Wasservolumen für etwa 10 Minuten.","Kombinieren Sie die 1 Tasse Wasser und den Zucker, und Geschmack, um die Süße anzupassen.","Zuckermischung zum Kochen bringen und Aprikosen hinzufügen.","Simmer bis die Flüssigkeit reduziert ist. Die traditionelle Konsistenz ist nahe an einem leichten Sirup."],"x":["Wenn reduziert, bis es ein dunkler Sirup ist, wird es sehr heiß und schnell härten, so entsprechend planen.","Wenn Sie als Dessert können Sie reduzieren, um einen leichten Sirup und Zeug oder garnieren mit Walnüssen.","Das ist gut mit der türkischen Dolma Pilav serviert, oder mit einem Huhn oder Schweinefleisch Gericht. Es kann auch allein mit Nüssen als Dessert serviert werden."],"desc":"Dies ist ein sehr einfaches Rezept mit nur wenigen Zutaten gemacht. Die Aprikosen können mit Huhn, Schweinefleisch oder türkischer Dolma Pilav serviert werden. Dies sollte für zwei Personen ausreichen, aber es kann leicht nach oben skaliert werden.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Candied_Apricots","i":"wb-en-1155","on":"Candied Apricots","og":["6–10+ dried apricots","About 1 cup water","A generous handful of sugar","Walnuts (optional)"],"mt":1},{"n":"Kandierte Süßkartoffeln","c":"brot","k":"","p":4,"t":60,"d":1,"v":0,"l":"en","g":["4 mittelgroße Süßkartoffeln, geschält und in Scheiben geschnitten","4 Granny-Smith-Äpfel, geschält, entkernt, und in Scheiben geschnitten","½ Tasse Rosinen","2 EL Honig","3 EL Apfelsaft oder Apfelmost","3 EL geschmolzene Butter"],"s":["In Scheiben geschnittene Süßkartoffeln, Äpfel und Rosinen in einer gefetteten 1,9-Liter-Backform anrichten.","Mischen Sie die Flüssigkeiten und Butter zusammen. Übergießen Sie den Inhalt des Tellers.","Mit Folie bedecken und 30 bis 45 Minuten bei 175 °C backen, bis Süßkartoffeln zart und glasiert sind."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Candied_Sweet_Potatoes","i":"wb-en-1156","im":["6/63/CamoteTenancingo.JPG/960px-CamoteTenancingo.JPG","AlejandroLinaresGarcia","CC BY-SA 4.0","CamoteTenancingo.JPG","w"],"on":"Candied Sweet Potatoes","og":["4 medium sweet potatoes, peeled and sliced","4 Granny Smith apples, peeled, cored, and sliced","½ cup raisins","2 Tablespoons honey","3 Tablespoons apple juice or cider","3 Tablespoons melted butter"],"mt":1},{"n":"Kandierte Süßkartoffeln (Yams)","c":"beilagen","k":"USA","p":4,"t":0,"d":1,"v":0,"l":"en","g":["6 Süßkartoffeln","½ Tasse Margarine","1 Tasse brauner Zucker","2 EL Vanilleextrakt","¼ Tasse Wasser"],"s":["Backofen auf 175 °C vorheizen.","Yamswurzeln in Häuten kochen, bis etwa die Hälfte fertig ist.","Wasser aus Yamswurzeln abtropfen, Häute entfernen und in Würfel schneiden.","Legen Sie Yam Würfel in eine gefettete Backform und Punkt mit Margarine.","Machen Sie einen Sirup durch Kochen braunen Zucker, Wasser und Vanille zusammen. Über die Yams gießen.","Für 45 bis 50 Minuten backen und häufig mit Sirup bebrühen, bis die Yamswurzel zart ist.","Dieses Rezept verwendet Material aus dem Artikel Candied Yams bei Wikipedia unter der GFDL."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Candied_Yams","i":"wb-en-1157","im":["6/63/CamoteTenancingo.JPG/960px-CamoteTenancingo.JPG","AlejandroLinaresGarcia","CC BY-SA 4.0","CamoteTenancingo.JPG","w"],"on":"Candied Yams","og":["6 sweet potatoes","½ cup margarine","1 cup brown sugar","2 tbsp vanilla extract","¼ cup water"],"mt":1},{"n":"Canh Chua (vietnamesische scharf-saure Suppe)","c":"suppen","k":"Vietnam","p":4,"t":0,"d":1,"v":0,"l":"en","g":["#Marinade","1 ganzer Wels oder anderer festfleischiger weißer Fisch","2 Frühlingszwiebeln, grüner Teil zum Garnieren aufgehoben, weißer Teil zerdrückt","4 TL Nước mắm (Fischsoße) (Fischsoße)","1 TL Salz","frisch gemahlener schwarzer Pfeffer","#Suppe","950 ml Wasser","2 TL Salz","2 EL Nước mắm (Fischsoße)","120 g saurer Bambus","¼ frische Ananas, Kerngehäuse entfernt, längs halbiert und in Scheiben geschnitten","#Garnitur","2 EL gehackter frischer Koriander","Grün der Frühlingszwiebeln, gehackt"],"s":["Marinieren Sie den Fisch für 15 Minuten mit den zerdrückten Jakobsmuscheln, schwarzem Pfeffer, Salz und n.m.","Bringt Wasser zum Kochen. Den sauren Bambus und die Ananasscheiben dazugeben. 5 Minuten kochen.","Fügen Sie marinierten Fisch und weiter kochen für insgesamt 10 Minuten. Während der Fisch kocht, füge N.C. m.m. und Salz hinzu.","Zum Servieren kann die Suppe mit Koriander und dem grünen Teil der Jakobsmuscheln garniert werden."],"x":["Traditionell ist der Fischkopf nicht entfernt, aber Sie können, wenn Sie es bevorzugen."],"desc":"Canh Chua ist die vietnamesische Suppe \"Hot & Sour\". Sie ist der thailändischen und der kambodschanischen Tom Yum-Suppe am nächsten, obwohl sie süßer und sauerer ist als ihre würzigen Pendants. Jede Familie hat ihr eigenes Canh Chua Rezept und manchmal haben Mitglieder derselben Familie ihr eigenes.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Canh_Chua_(Vietnamese_Hot_and_Sour_Soup)","i":"wb-en-1158","im":["a/a0/Canhchua2.jpg/500px-Canhchua2.jpg","Jason Hutchens","CC BY 2.0","Canhchua2.jpg","w"],"on":"Canh Chua (Vietnamese Hot and Sour Soup)","og":["#Marinade","1 whole catfish or other firm white fish","2 scallions, green part reserved for garnish and white part crushed","4 teaspoons nước mắm (fish sauce)","1 teaspoon salt","Freshly-ground black pepper","#Soup","1 quart (950 ml) water","2 teaspoons salt","2 tablespoons nước mắm","½ cup (120g) sour bamboo","¼ fresh pineapple, core removed, cut lengthwise and sliced","#Garnish","2 tablespoons chopped fresh coriander","Green part of scallions, chopped"],"mt":1},{"n":"Canjeero (somalischer Pfannkuchen)","c":"kuchen","k":"Somalia","p":4,"t":0,"d":1,"v":0,"l":"en","g":["2 Tassen Mehl","1 Tasse selbsttreibendes Mehl (Mehl mit Backpulver)","1 TL Trockenhefe","1 EL Zucker","3 Tassen lauwarmes Wasser","Salz, nach Geschmack"],"s":["Kombinieren Sie in einer großen Schüssel das Allzweckmehl und das selbstaufsteigende Mehl.","In einer separaten kleinen Schüssel die aktive Trockenhefe und den Zucker mit 1 Tasse lauwarmem Wasser vermischen. Lassen Sie es für ein paar Minuten sitzen, um die Hefe zu aktivieren; Es sollte schaumig werden.","Die Hefemischung mit den Mehlen in die große Schüssel geben.","Allmählich fügen Sie die restlichen 2 Tassen lauwarmes Wasser in die Schüssel, während whisking oder Rühren kontinuierlich zu einem glatten Teig bilden. Die Konsistenz sollte dem Pfannkuchenschläger ähnlich sein.","Bedecken Sie die Schüssel mit einem sauberen Küchentuch oder Plastikfolie und lassen Sie den Teig mindestens 2 Stunden gären, oder bis er sich in der Größe verdoppelt und leicht sprudelt.","Nach dem Gärungsprozess eine Prise Salz in den Teig geben und gut umrühren.","Vorheizen Sie eine Pfanne mit Griddle oder Non-Stick bei mittlerer Hitze.","Gießen Sie eine Pfanne des Teiges auf das heiße Gitter, um einen runden Pfannkuchen zu bilden. Sie können die Pfannkuchen so klein oder groß machen, wie Sie möchten.","Den Pfannkuchen auf einer Seite kochen, bis sich Blasen an der Oberfläche bilden und die Kanten gesetzt aussehen. Dann umdrehen und die andere Seite kochen, bis es goldbraun wird.","Wiederholen Sie den Vorgang mit dem restlichen Teig und fügen Sie mehr Öl in das Gitter oder Pfanne, wie erforderlich, um zu verhindern, dass kleben.","Servieren Sie warm mit Ihren Lieblings-Toppings, wie Honig, Butter oder Somali Tee."],"x":["Canjeero wird traditionell auf einem großen, flachen Gitter namens Taawa gekocht. Allerdings funktioniert eine Antihaft Bratpfanne auch gut.","Der Fermentationsschritt ist entscheidend, um die Signatur schwammige Textur und würzigen Geschmack von Canjeero zu erreichen. Achten Sie darauf, genügend Zeit für den Teig zu gären richtig zu lassen.","Sie können die Größe der Pfannkuchen nach Ihren Wünschen anpassen. In der somalischen Kultur werden oft kleinere Canjeero Pfannkuchen zum Frühstück mit einer Vielzahl von Begleitungen serviert."],"desc":"Canjeero ist ein beliebter Somali Pfannkuchen, der als Haupt-Frühstücksgericht genossen wird. Hergestellt aus einfachen Zutaten, sind diese schwammigen und leicht würzigen Pfannkuchen perfekt zum Aufsaugen von Eintöpfen und Saucen oder einfach auf eigene Faust genossen.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Canjeero_(Somali_Pancake)","i":"wb-en-1159","im":["4/44/LahohS.jpg/500px-LahohS.jpg","Gilabrand ( talk )","CC BY-SA 3.0","LahohS.jpg","w"],"on":"Canjeero (Somali Pancake)","og":["2 cups flour","1 cup self-rising flour","1 teaspoon active dry yeast","1 tablespoon sugar","3 cups lukewarm water","Salt, to taste"],"mt":1},{"n":"Cannabis-Butter","c":"welt","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["Wasser","200 g Butter","2 g Cannabis (oder mehr, je nach gewünschter Stärke)"],"s":["Bringen Sie einen Topf mit einer kleinen Menge Wasser zum Kochen.","Fügen Sie die Butter und Cannabis hinzu.","Simmer dies für ein paar Stunden auf einer niedrigen Hitze, Zugabe von Wasser, wenn zu viel verdunstet. Lassen Sie die Temperatur nicht über etwa 88 °C steigen.","Ganz ruhig. Die Öle und Extrakte im Cannabis sind nun im Fett gelöst.","Die Mischung gießen, um die Cannabis-Feststoffe durch ein Sieb zu entfernen. Schütteln Sie die Mischung im Kühlschrank, um die Butter zu erstarren und das Wasser zu trennen. Die fertige Cannabutter sollte eine leichte grüne Farbe mit einem leicht abschmeckenden Geschmack aus dem Cannabis haben.","Die Butter bis zu 2 Wochen im Kühlschrank oder 6 Monate im Gefrierfach aufbewahren."],"x":["Die Wirkstoffe in Cannabis werden leicht von Fetten aufgenommen. Daher können alle Fette verwendet werden, einschließlich Schmalz, Verkürzung, Margarine, Öle, etc. Die unerwünschten Teile des Cannabis, wie Farbe und Geschmack, werden leichter in das Wasser aufgenommen.","Der Zweck der Einbeziehung von Wasser ist es, zu verhindern, dass die Temperatur zu hoch steigt, was dazu führen würde, dass die psychoaktiven Verbindungen aus dem Gemisch verdampfen."],"desc":"Cannabutter ist eine Zubereitung, bei der Butter mit Cannabis infundiert wird. Dies überträgt die psychoaktiven Verbindungen in Cannabis auf das Fett, und das daraus resultierende Produkt kann dann verwendet werden, um verschiedene Cannabis essbar zu machen.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cannabutter","i":"wb-en-1160","on":"Cannabutter","og":["Water","200 g (7 oz) butter","2 g cannabis (or more, depending on desired potency)"],"mt":1},{"n":"Cannoli","c":"brot","k":"Italien","p":4,"t":0,"d":1,"v":0,"l":"en","g":["Cannoli-Röllchen (gekauft oder selbstgemacht)","2 EL Ricotta","1 EL weißer Zucker","1 EL Schlagsahne","1 EL Schokotropfen","½ EL Zuckerguss"],"s":["Bereiten Sie die Cannoli-Schalen vor, wenn Sie sie selbst herstellen.","Kombinieren Sie Ricotta und Zucker. Falten Sie die Schlagsahne und Schokolade Chips.","Schalen mit der Ricotta-Mischung füllen. Ein Rohrbeutel funktioniert hier gut.","Kühle Cannoli vor dem Servieren im Kühlschrank."],"x":["Die Schokoladenchips durch getrocknete Früchte ersetzen."],"desc":"Cannoli sind süße italienische Backwaren. Sie bestehen aus einer gebratenen Backschale in Form einer Tube, gefüllt mit einer süßen Sahne- und Käsemischung.","img":"Cannoli siciliani.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Cannoli","i":"wb-en-1161","im":["9/99/Cannoli_siciliani.jpg/960px-Cannoli_siciliani.jpg","Stefano Mortellaro from Catania, Italy","CC BY 2.0","Cannoli siciliani.jpg","r"],"og":["Cannoli shells (store-bought or homemade)","2 tablespoons ricotta cheese","1 tablespoon granulated white sugar","1 tablespoon whipped cream","1 tablespoon chocolate chips","½ tablespoon icing"],"mt":1},{"n":"Kantonesisches knuspriges Brathähnchen","c":"fleisch","k":"China","p":4,"t":0,"d":3,"v":0,"l":"en","g":["#Pfeffersalz","1 EL Salz","3 EL Szechuanpfeffer (Szechuanpfeffer)","1 EL Ajinomoto-Würze (Ajinomoto, Glutamat)","#Hähnchen","1 ganzes Hähnchen (klein)","2 EL Fünf-Gewürze-Pulver (Fünf-Gewürze-Pulver)","3 Scheiben Ingwer, zerdrückt","2 Frühlingszwiebeln","Wasser zum Pochieren des Hähnchens","#Glasur","3 EL Essig","¼ Tasse Zucker","#Zum Braten","4 Tassen Öl (oder so viel, wie die Fritteuse braucht)","Krabbenchips (nicht die fertigen)"],"s":["Salz und Pfefferkörner in eine kleine Pfanne geben. Hitze auf mittlere bis niedrige Wärme, bis es kaum raucht.","Entfernen Sie sich von der Hitze.","Grind gut in Mörtel und Pestle, oder mit einem Rollstift.","Ajinomoto hinzufügen und gut mischen.","Diese Schritte können im Voraus gemacht werden, und das Huhn kann im Kühlschrank gehalten werden.","Das Huhn säubern und abspülen, die Giebel wegwerfen.","Erhitzen Sie genügend Wasser, um das Huhn bis zum Kochen in einem Topf zu decken.","Fünf-Spitzen-Pulver, Ingwer und Jakobsmuscheln in ein Tuch geben und binden. Zum Wasser geben und 15 Minuten köcheln lassen.","Hühner hinzufügen, Hitze reduzieren und 20 Minuten lang sanft pochen.","Wenn Huhn fertig ist, entfernen Sie von der Hitze, dann tub trocken mit Papierhandtüchern mit Papierhandtüchern und Luft trocken für ein wenig.","Essig und Zucker in den Topf geben und bis zum Auflösen erhitzen, um einen Sirup herzustellen.","Das gesamte Huhn innen und außen mit dem Sirup beschichten.","Das Huhn in einer Brise trocknen lassen, bis es sehr trocken ist.","Die Fritteuse mit Öl füllen und Öl auf 175 °C erhitzen.","Frittieren Huhn ca. 10 Minuten pro Seite bis braun und fertig.","Aus dem Öl nehmen und mit einem Fleischmesser in 2,5 x 5 cm Stücke hacken.","Wenn Huhn fertig ist, braten Sie die Garnelenchips in der Friteuse.","Garnelenchips mit etwas Salz bestreuen.","Hähnchen mit Garnelenchips, mit Pfeffersalz in einem kleinen Gericht an der Seite geschmückt servieren."],"x":["Das Wilden ist nicht dasselbe wie das Sieden, da die Temperatur niedriger ist, ungefähr anstatt bei, und sogar niedriger als köcheln. Wenn gekocht, wird das Fleisch hart und trocken kommen. Auch je niedriger die Wildungstemperatur ist, desto länger dauert es zum Wilden.","Das Trocknen der Haut ist wichtig, da es hilft, den Sirup zu kleben. Die zweite Trocknung ist auch wichtig, da das hilft, die Haut knusprig zu machen. Es kann am Tag zuvor gemacht werden, und das Huhn im Kühlschrank aufbewahrt.","Der karamellisierte Zucker gibt die schöne braune Farbe. Essig senkt den pH-Wert und hilft bei der Karamellisierung.","Öltemperatur ist wichtig, da sie der Haut die braune Farbe verleiht. Wenn die Öltemperatur zu niedrig ist, wird der Zucker nicht karamellisieren, und das Huhn wird nicht braun sein. Wenn es zu hoch ist, wird der Zucker brennen. Wenn Sie keine temperaturgesteuerte Fritteuse haben, verwenden Sie ein Brat- (oder Süßigkeiten) Thermometer.","Eine Fritteuse kann 2 oder 3 Liter Öl aufnehmen. Verwenden Sie so viel, wie Ihre Frittier-Handbuch diktiert.","Wenn Sie keine Friteuse haben, kann es auf dem Herd in einem Topf gebraten werden oder wok mit einem Bratthermometer, aber sehr vorsichtig sein. WARNUNG: Ein Wok kann leicht kippen, Öl verschütten und schwere Verbrennungen verursachen. Wenn das Öl überläuft, kann man leicht ein sehr gefährliches Ölfeuer haben. Bitte lesen Sie die Warnungen in dem Artikel über Deep Fat Frittieren"],"desc":"Knuspriges gebratenes Huhn ist eine Spezialität aus Hongkong/Kanton.","img":"Crispyfriedchicken.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Cantonese_Crispy_Fried_Chicken","i":"wb-en-1162","im":["5/56/Crispyfriedchicken.jpg/330px-Crispyfriedchicken.jpg","tissue_fleur","CC BY-SA 2.0","Crispyfriedchicken.jpg","r"],"on":"Cantonese Crispy Fried Chicken","og":["#Pepper salt","1 Tbsp salt","3 Tbsp Sichuan peppercorns (花椒)","1 Tbsp ajinomoto seasoning (味の素)","#Chicken","1 whole chicken (small)","2 Tbsp Chinese five-spice powder (五香粉)","3 slices of ginger, crushed","2 scallions","Water to poach chicken in","#Glaze","3 Tbsp vinegar","¼ cup sugar","#For Frying","4 cups oil (or enough for deep fryer)","Prawn crackers/shrimp chips (not the ready made ones)"],"mt":1},{"n":"Kantonesische Bratente","c":"saucen","k":"China","p":4,"t":0,"d":2,"v":0,"l":"en","g":["#Marinade","2 EL helle Sojasoße","2 EL dunkle Sojasoße (optional, ersatzweise helle Sojasoße)","450 ml Weißwein, Sherry, oder chinesischer Kochwein","1 TL Fünf-Gewürze-Pulver","#Glasur","2 EL Hoisinsoße","2 EL dunkle Sojasoße","#Ente","1.3–2.6 kg ganze Ente oder Gans","3 Frühlingszwiebeln oder 1 Zwiebel"],"s":["Alle Marinade-Zutaten miteinander vermischen.","Alle Glasur-Zutaten miteinander vermischen.","Die Marinademischung innen und außen auf der Ente putzen.","Bürsten Sie etwas Glasurmischung im Inneren der Entenhöhle.","Setze die Entenbrust auf ein Gestell in einem offenen Behälter.","In den Kühlschrank geben, um über Nacht zu kühlen.","Backofen auf 220 °C vorheizen","1⁄2–2,5 cm Wasser in eine Bratpfanne geben – das Fett, das beim Rösten aus der Ente herauskommt und das Rauchen verhindert.","Grüne Zwiebeln in die Entenhöhle legen.","Legen Sie die Ente auf ein Röstgestell in der Bratpfanne. Roast die Ente für 15 Minuten.","Drehen Sie die Ente Brust-up, und braten für weitere 15 Minuten.","Ofenhitze auf 190 °C umdrehen und die Ente rösten, bis die Kerntemperatur mindestens 82 °C erreicht hat (Prüfung zwischen dem Oberschenkel, dem dicksten Teil der Ente/Goose, wobei darauf geachtet wird, den Knochen nicht zu berühren)","Die Ente mit der Glasur putzen, den Ofen bis zu 200 °C drehen und ca. 10 Minuten wieder rösten.","Carve und Servieren!"],"x":[],"desc":"Dies ist ein Rezept für kantonesische Röstente oder Gans.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cantonese_Roast_Duck","i":"wb-en-1163","im":["9/94/Roast_duck_Cantonese_styleCNE.jpg/960px-Roast_duck_Cantonese_styleCNE.jpg","CNEcija12345","CC BY-SA 4.0","Roast duck Cantonese styleCNE.jpg","c"],"on":"Cantonese Roast Duck","og":["#Marinade","2 Tbsp light soy sauce","2 Tbsp dark soy sauce (optional, can use light soy sauce instead)","2 cups (450 ml) of white wine, sherry, or Chinese cooking wine","1 tsp Chinese five spice powder","#Glaze","2 Tbsp Hoisin sauce","2 Tbsp dark soy sauce","#Duck","3–6 lb (1.3–2.6 kg) whole duck or goose","3 green onions or 1 onion"],"mt":1},{"n":"Cao lầu (vietnamesische Schweinefleischnudeln mit Grün)","c":"pasta","k":"Vietnam","p":3,"t":0,"d":2,"v":0,"l":"en","g":["300 g Schweinefleisch","150 g ungekochte Hokkien-Reisnudeln","150 g Sojasprossen","4 Zehen Knoblauch","1 TL Fünf-Gewürze-Pulver","1 EL Sojasoße","1 TL Zucker","1 Prise Hühnerbrühpulver","gemahlene Kurkuma (oder Paprikapulver), für die Farbe","2 EL Pflanzenöl","250 ml Wasser","Blattsalat","asiatisches Blattgemüse (Basilikum, Koriander usw.)","gehackte frische Chilis (z. B. Serrano-Chilis)","Croûtons","Frühlingszwiebeln"],"s":["Öl und Paprika in einer Pfanne erhitzen.","Schweinefleisch, zerschmetterter Knoblauch, Sojasauce, Hühnerbrühe und Gewürze hinzufügen. 3 Minuten lang braten.","1 EL Wasser zugeben und weitere 2 Minuten braten.","Von der Hitze entfernen und beiseite stellen.","Bringen Sie einen Topf mit Wasser zum Kochen. Sprossen hinzufügen und 1–2 Minuten kochen, bis es weich ist.","Sprossen entfernen, Nudeln hinzufügen und 2 Minuten lang Nudeln kochen.","Nudeln in eine Schüssel auf Salat und Grün geben. Schweinefleischmischung, gehackte Frühlingszwiebeln, Croûtons und Chilis zugeben."],"x":[],"desc":"== Geschichte ==Cao l-u ist eine vietnamesische Nudelschale aus der Provinz Quang Nam in Vietnam.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cao_lầu_(Vietnamese_Pork_Noodles_with_Greens)","i":"wb-en-1164","im":["4/4e/Cao_l%E1%BA%A7u_H%E1%BB%99i_An_%282024%29.jpg/960px-Cao_l%E1%BA%A7u_H%E1%BB%99i_An_%282024%29.jpg","Chainwit.","CC BY 4.0","Cao lầu Hội An (2024).jpg","w"],"on":"Cao lầu (Vietnamese Pork Noodles with Greens)","og":["300 g pork","2 cups (150 g) uncooked Hokkien-style rice noodles","2 cups (150 g) bean sprouts","4 cloves garlic","1 tsp Chinese five-spice powder","1 tbsp soy sauce","1 tsp sugar","1 pinch chicken stock powder","Turmeric powder (or paprika), for color","2 tbsp vegetable oil","1 cup (250 ml) water","Lettuce","Asian greens (basil, cilantro, etc.)","Chopped fresh chiles (for example Serrano chiles)","Croûtons","Spring onions"],"mt":1},{"n":"Butter Chicken nach Kap-Malaien-Art","c":"fleisch","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["½ Tasse Joghurt","1 EL Öl","2 EL Ingwer-Knoblauch-Paste","2 EL Zitronensaft","1 EL zerstoßener schwarzer Pfeffer","1 EL weißer Pfeffer","¼ EL Thuja-Pulver (Zimt)","¼ EL gemahlener Kardamom (Kardamom)","¼ EL gemahlene Nelken","1 ½ EL frisch zerstoßene rote Chilis","1 EL Salz","2 Hähnchen (halbiert)","¼ Tasse Butter","1 Dose passierte Tomaten","¼ Tasse Sahne","frische Minzzweige"],"s":["Joghurt, Öl, Ingwer- und Knoblauchpaste, die Hälfte Zitronensaft und Gewürze miteinander vermischen. Diese Mischung über die Hähnchenhälften streuen und ein paar Stunden marinieren lassen.","Grill Huhn über lebende Kohlen oder Rotisserie bis gebräunt. Alternativ leicht pan-fry und kochen Sie sie.","Butter, Tomatenpüree und den restlichen Zitronensaft kombinieren. Die übrig gebliebene Marinade vom Huhn vermischen. Bringen Sie diese Mischung zum Kochen und köcheln für ein paar Minuten. Aus der Hitze herausnehmen und die Creme unterrühren.","Das Huhn auf eine Platte legen und die Sauce darüber verteilen. Mit Minzzweigen garnieren und heiß servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cape_Malay_Butter_Chicken","i":"wb-en-1165","im":["4/41/Butter_Chicken_%26_Butter_Naan_-_Home_-_Chandigarh_-_India_-_0006.jpg/960px-Butter_Chicken_%26_Butter_Naan_-_Home_-_Chandigarh_-_India_-_0006.jpg","Yuvraj Singh 97","CC BY-SA 4.0","Butter Chicken & Butter Naan - Home - Chandigarh - India - 0006.jpg","w"],"on":"Cape Malay Butter Chicken","og":["½ cup yoghurt","1 tablespoon oil","2 tablespoons ginger/garlic paste","2 tablespoons lemon juice","1 tablespoon crushed black pepper","1 tablespoon white pepper","¼ tablespoon powdered tuj (cinnamon)","¼ tablespoon powdered elachi (cardamom)","¼ tablespoon powdered cloves","1 ½ tablespoon freshly pounded red chillies","1 tablespoon salt","2 chickens (split in halves)","¼ cup butter","1 can (1 cup) tomato purée","¼ cup cream","Fresh mint sprigs"],"mt":1},{"n":"Caponata (sizilianisches Auberginengemüse)","c":"beilagen","k":"Italien","p":2,"t":60,"d":1,"v":0,"l":"en","g":["1 kg Aubergine (Aubergine)","225 g grüne Oliven in Lake, entsteint","170 g Salzkapern, abgespült","570 g Selleriestangen","1 Tasse Tomatensoße (optional)","300 g Zwiebeln","300 g Tomaten","⅓ Tasse Essig","2 EL Zucker","Basilikum","⅜ Tasse Pinienkerne","Olivenöl","Salz"],"s":["Die Filamente aus den Selleriestäbchen streifen und fünf Minuten lang in leicht gesalzenem Wasser blanchieren. Den Sellerie abtropfen und in Bissstücke schneiden, in ein wenig Öl anbraten und beiseite stellen.","Auberginen waschen und würfeln, abseihen und mit Salz streuen und mehrere Stunden stehen lassen, um die Bitterkeit herauszuziehen. In der Zwischenzeit blanch, schälen, säen und hacken die Tomaten.","Sobald die Aubergine gesessen hat, das Salz wegspülen und die Stücke trocknen. Zwiebel fein in Scheiben schneiden und in Olivenöl anbraten; Sobald sie transluzent geworden sind, fügen Sie die Kapern, Pinienkerne, Oliven und Tomaten hinzu.","Weiter kochen, mit einem Holzlöffel rühren, bis die Tomaten fertig sind, etwa 15 Minuten, und dann den Topf aus der Hitze entfernen.","Während die Tomaten kochen, erhitzen Sie eine weitere Pfanne Öl und braten Sie die Auberginen in Chargen, um eine Senkung der Brattemperatur zu verhindern.","Wenn die letzte Partie fertig ist, geben Sie den Tomatentopf in die Hitze und rühren Sie in der Aubergine zusammen mit dem zuvor gesauten Sellerie.","Mehrere Minuten lang bei schwacher Flamme kochen, sanft umrühren, dann Essig und Zucker unterrühren; Wenn der Essig fast vollständig verdunstet ist, den Topf aus dem Feuer entfernen und abkühlen lassen.","Die Caponata kalt mit einer garnieren von frischem Basilikum servieren. Caponata hält mehrere Tage im Kühlschrank."],"x":["Sie können diese auf Toast als Vorspeise, als Beilage oder als Hauptgericht für eine leichte Mahlzeit dienen."],"desc":"Caponata ist ein sizilianisches Auberginengericht, das aus gekochtem Gemüse mit gehackten gebratenen Auberginen, Sellerie, gesüßtem Essig und Kapern mit süßer Soße besteht.","img":"Sicilian_caponata.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Caponata_(Sicilian_Eggplant_and_Vegetables)","i":"wb-en-1166","im":["2/2f/Sicilian_caponata.jpg/960px-Sicilian_caponata.jpg","Massimoweb","CC BY-SA 3.0","Sicilian caponata.jpg","r"],"on":"Caponata (Sicilian Eggplant and Vegetables)","og":["2 ¼ pounds (1 kg) eggplant (aubergine)","½ pound (225 g) green olives packed in brine, pitted","6 ounces (170 g) salted capers, rinsed","1 ¼ (570 g) pounds celery ribs","1 cup tomato sauce (optional)","⅔ pound (300 g) onions","⅔ pound (300 g) tomatoes","⅓ cup vinegar","2 tablespoons sugar","Basil","⅜ cup pine nuts","Olive oil","Salt"],"mt":1},{"n":"Cappelletti in Brühe (Cappelletti in Brodo)","c":"suppen","k":"Italien","p":4,"t":0,"d":1,"v":0,"l":"en","g":["250 g Packung Cappelletti","½ l Wasser plus etwas mehr zum Verdünnen der Suppe, falls nötig","2 gute Hühnerbrühwürfel","½ Tasse Sahne (18 % Fett)","1 Prise gemahlener schwarzer Pfeffer","1 Spritzer Olivenöl","1 Handvoll gehackte Petersilie","1 Spritzer süßer Sherry","frisch geriebener Parmesan zum Servieren"],"s":["Bringen Sie das Wasser zum rollenden Kochen, fügen Sie die Brühewürfel hinzu und lassen Sie sie sich auflösen.","Fügen Sie die Cappelletti Nudeln, und kochen Sie nach den Anweisungen auf der Packung.","Die Sahne und die Petersilie etwa 2 Minuten vor dem Ende des Kochens hinzufügen. Mach die Hitze leiser.","Fügen Sie die Schnecke Sherry kurz vor dem Servieren. Wenn man Kindern dient, kann der Sherry nach dem Servieren zum Teller des Erwachsenen hinzugefügt werden!","Lassen Sie für ein paar Minuten stehen.","Mit geriebenem Parmesankäse bestreut servieren. Ein weiterer Serviervorschlag könnte einen grünen Salat oder einen kalten Bohnensalat enthalten."],"x":[],"desc":"Cappeletti in Brodo ist eine sehr einfache und köstliche italienische Pastasuppe, die mit Cappeletti (kleines Fleisch oder Gemüse gefüllt) Ravioli zubereitet wird. Es ist köstlich an einem kalten Tag, immer in von einem langen Tag bei der Arbeit, und ohne viel Zeit für die Zubereitung einer leckeren Mahlzeit widmen. Am besten serviert mit einigen hausgemachten Garl","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cappelletti_Pasta_Soup_(Cappelletti_in_Brodo)","i":"wb-en-1167","im":["9/95/02_Cappelletti_-_Cappellacci_-_Pasta_ripiena_-_Cucina_tipica_-_Ferrara.jpg/960px-02_Cappelletti_-_Cappellacci_-_Pasta_ripiena_-_Cucina_tipica_-_Ferrara.jpg","Lungoleno","CC BY-SA 2.5","02 Cappelletti - Cappellacci - Pasta ripiena - Cucina tipica - Ferrara.jpg","w"],"on":"Cappelletti Pasta Soup (Cappelletti in Brodo)","og":["250 g packet of Cappelletti pasta pillows","½ litre of water plus more to thin out the soup if required","2 good quality chicken stock cubes","½ cup of single cream","1 pinch of ground black pepper","1 dash of olive oil","1 handful of chopped parsley","1 dash of sweet sherry","Freshly-grated Parmesan to serve"],"mt":1},{"n":"Cappuccino-Mousse","c":"dessert","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["½ Tasse frisch gebrühter Espresso, abgekühlt","⅓ Tasse Zucker","2 EL Schokoladensirup","1 Prise Salz","2 Tassen Schlagsahne, weich geschlagen"],"s":["Kombinieren Sie Espresso, Zucker, Schokolade, Salz und Schokolade Sirup.","Die Schlagsahne vorsichtig einfalten.","Für 20 Minuten abkühlen; Dienen."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cappucino_Mousse","i":"wb-en-1168","on":"Cappucino Mousse","og":["½ cup brewed espresso, cooled","⅓ cup granulated sugar","2 tbsp chocolate syrup","1 pinch of salt","2 cups heavy cream, whipped to soft peaks"],"mt":1},{"n":"Caprese-Salat","c":"salate","k":"Italien","p":1,"t":0,"d":1,"v":0,"l":"en","g":["1 mittelgroße Tomate","ein paar Basilikumblätter","Mozzarella, etwa ¾ des Tomatengewichts, in Scheiben geschnitten","Olivenöl","Aceto balsamico","italienische Kräuter oder Oregano und Pfeffer (optional)"],"s":["Die Tomate in etwa 5 Scheiben schneiden.","Legen Sie eine Scheibe Mozzarella-Käse auf jede Tomatenscheibe.","Schneiden Sie einen horizontalen Schlitz auf halbem Wege durch jede Scheibe.","Lege ein Basilikumblatt auf jedes einzelne Blatt.","Kräuter über jede Scheibe streuen.","Etwas Essig und Olivenöl darüber giessen. Essig und Olivenöl nicht mischen.","Essen Sie frisch."],"x":[],"desc":"Caprese Salat ist ein köstliches italienisches Gericht mit Tomaten und Mozzarella Käse gemacht. Es ist ziemlich einfach, schmeckt aber toll und sieht attraktiv aus.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Caprese_Salad","i":"wb-en-1169","im":["b/b1/Caprese-1_%28tigher_crop%29.jpg/960px-Caprese-1_%28tigher_crop%29.jpg","Rainer Zenz","CC BY-SA 3.0","Caprese-1 (tigher crop).jpg","w"],"on":"Caprese Salad","og":["1 medium tomato","A few basil leaves","about ¾ the weight of Mozzarella cheese as the tomato, sliced","Olive oil","Balsamic vinegar","Italian seasoning or oregano and pepper (optional)"],"mt":1},{"n":"Karamell-Kaffeekuchen","c":"kuchen","k":"","p":12,"t":0,"d":2,"v":0,"l":"en","g":["#Kuchen","3 Eier","400 g Zucker","355 ml Pflanzenöl","2 TL Vanilleextrakt","Weizenmehl","1 TL Salz","1 TL Natron","#Belag","Butter oder Margarine","Milch","fest gedrückter brauner Zucker","1 Prise Salz"],"s":["In einer Mischschüssel Eier schaumig schlagen; Schritt für Schritt in Zucker schlagen.","Öl und Vanille vermischen.","Mehl, Salz und Backpulver kombinieren; Zur Eiermischung hinzufügen und einklappen.","In eine gefettete Rohrpfanne von 25 cm gießen; Bei 175 °C 1 Stunde und 15 Minuten backen oder bis die Kuchentests abgeschlossen sind.","Abkühlen in der Pfanne auf einem Drahtträger für 10 Minuten. Kuchen auf eine Servierplatte entfernen.","Kombinieren Sie alle Zutaten in einem Topf; 3 Minuten kochen, ständig rühren.","Gießen Sie langsam Soße über warmen Kuchen (einige Topping wird auf den Servierteller laufen)."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Caramel_Coffee_Cake","i":"wb-en-1170","im":["5/54/Coffee_cake_%28Unsplash%29.jpg/960px-Coffee_cake_%28Unsplash%29.jpg","Rachael Gorjestani rachaelgorjestani","CC0","Coffee cake (Unsplash).jpg","w"],"on":"Caramel Coffee Cake","og":["#Cake","3 eggs","400 g (14 oz) white granulated sugar","355 ml (12 fl oz) vegetable oil","2 teaspoons vanilla extract","all-purpose flour","1 teaspoon salt","1 teaspoon baking soda","#Topping","butter or margarine","milk","packed brown sugar","1 pinch salt"],"mt":1},{"n":"Karamellsoße I","c":"saucen","k":"","p":36,"t":0,"d":1,"v":2,"l":"en","g":["480 g Zucker","1.2 l kochendes Wasser"],"s":["Zucker in Topf schmelzen und langsam erhitzen, ständig umrührend bis goldbraun","Vorsichtig in das kochende Wasser rühren.","Für 3 Minuten kochen, dann aus der Hitze entfernen."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Caramel_Sauce_I","i":"wb-en-1171","im":["8/89/Caramel-2.jpg/960px-Caramel-2.jpg","No machine-readable author provided. Rainer Zenz assumed (ba","CC BY-SA 3.0","Caramel-2.jpg","w"],"on":"Caramel Sauce I","og":["2 cups (480 g) granulated sugar","5 cups (1.2 L) boiling water"],"mt":1},{"n":"Karamellsoße II","c":"saucen","k":"","p":6,"t":60,"d":2,"v":0,"l":"en","g":["2 Tassen Wasser","4 Tassen Zucker","2 EL Maissirup (optional)","1 Prise Salz","2 Tassen Schlagsahne","½ Tasse ungesalzene Butter, in 2,5-cm-Würfel geschnitten"],"s":["Wasser, Zucker und Maissirup bei mittlerer Hitze in einem Topf auflösen, bis sie vollständig aufgelöst sind.","Rühren Sie nicht mehr und lassen Sie die Lösung bei mittlerer Hitze kochen. Überprüfen Sie die Lösung alle 5 Minuten. Du wirst sehen, wie die Blasen langsamer werden und größer werden. Wenn die Blasen beginnen, 1⁄2–3⁄4 Zoll in der Größe zu erreichen, starten Sie mit der Überwachung der Lösung sorgfältig.","Wenn die Lösung beginnt, Bernstein zu drehen, holen Sie Ihre Sahne und Butter und beobachten Sie es ständig.","Wenn die Lösung einen Farbton von Karamell gedreht hat, den Sie mögen (darker ist tiefer und wird beginnen, auf ein wenig Bitterkeit zu nehmen), treten Sie zurück und fügen Sie die Creme an den Armen Länge, Rühren ständig und kratzen die Seiten der Pfanne.","Die Butter zugeben und rühren, bis sie eingearbeitet ist. Die Soße in ein Serviergericht geben, um sofort mit Brot zu servieren, auf Eis gedünstet, als Garnierung oder für die Verwendung in anderen Desserts.","Wenn Sie wünschen, folgen Standard-Eindosen Verfahren und verteilen in Konservengläser. Abkühlen lassen, bis die Tasten gedrückt sind. Alle Gläser mit Knöpfen, die nicht depressiv sind, sollten erst gekühlt und verbraucht werden.","Um die Karamellsauce zu erhitzen, Mikrowelle die Gläser (ohne Abdeckungen) für 10–30 Sekunden, je nachdem, wie weich und heiß Sie es wollen.","Zucker und Wasser in der Pfanne Zuckerlösung kochen Zuckerlösung drehen bernsteinig Rühren in der Creme Rühren in der Butter Caramel in Gläsern gelagert"],"x":["Im Folgenden sind alle Variationen, die in verschiedenen Phasen des Rezepts oben gemacht werden können.","Karamell-Kaut: Die Creme mit 3⁄4 Tasse halb und halb ersetzen. Die fertige heiße Karamellmischung auf eine Silikonmatte oder Backpapier gießen, um abzukühlen. Wenn es kühl genug ist, um das Karamell ein paar Mal zu handhaben, zu falten und zu kneten, dann brechen Sie in Bissgrößen Stücke. Vor dem Umpacken vollständig abkühlen lassen.","Toffee: Statt Creme, verwenden Sie 7 Sticks Butter (insgesamt 8 Sticks oder 4 Tassen, so dass Sie gleiche Teile Butter und Zucker). Auf Wunsch in gehackte Nüsse mischen und die fertige heiße Karamellmischung auf eine Silikonmatte, Backpapier oder Formen geben. Einmal abkühlen, mit Schokolade und gehackten Nüssen beträufeln oder eintauchen.","Nuss spröde: Verwenden Sie keine Creme oder Butter. Rühren Sie 1⁄2 tsp Backpulver in die Karamellmischung, dann gießen Sie das geschmolzene Karamell über 4 Tassen Ihrer Lieblingsnüsse auf eine Silikonmatte oder Backpapier und lassen Sie es abkühlen. Wenn es Raumtemperatur erreicht hat, brechen Sie es mit einem Hammer oder indem Sie das Blatt auf dem Zähler. In einem luftdichten Behälter einpacken und lagern."],"desc":"Um die Textur von Karamell-Sauce zu schaffen, benötigen Sie ein 1:1 Verhältnis von Fett und Flüssigkeit. In diesem Rezept wird schwere Creme (40% Fett) zusammen mit Butter verwendet, um dieses Verhältnis zu schaffen. Wenn Sie Milch ersetzen wollen, müssen Sie weniger Milch und mehr Butter verwenden, um das Verhältnis zu halten. Sie können auch ersetzen Soja-Milch und","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Caramel_Sauce_II","i":"wb-en-1172","im":["8/89/Caramel-2.jpg/960px-Caramel-2.jpg","No machine-readable author provided. Rainer Zenz assumed (ba","CC BY-SA 3.0","Caramel-2.jpg","w"],"on":"Caramel Sauce II","og":["2 cups water","4 cups white granulated sugar","2 Tbsp corn syrup (optional)","1 pinch salt","2 cups heavy whipping cream","½ cup (1 stick) unsalted butter, chopped into 1-inch cubes"],"mt":1},{"n":"Karamellschnitten","c":"kuchen","k":"Großbritannien","p":8,"t":90,"d":3,"v":0,"l":"en","g":["#Boden","350 g selbsttreibendes Mehl (Mehl mit Backpulver)","225 g ungesalzene Butter","110 g feiner Zucker","#Füllung","225 g feiner Zucker","225 g ungesalzene Butter","5 EL Golden Sirup (heller Zuckersirup)","400 ml gezuckerte Kondensmilch (Vollfett)","#Belag","340 g gute Schokolade (Vollmilch oder Zartbitter), geschmolzen"],"s":["Den Ofen auf 180 °C vorheizen (Gaszeichen 4); 175 °C). Reiben Sie Mehl, Butter und Casterzucker zusammen, bis es Brotkrumen ähnelt.","In eine 25 x 38 x 4 cm Schweizer Rollpfanne drücken.","20 Minuten backen oder bis golden.","Ganz ruhig.","Butter in einem Kochtopf auf schwerer Basis bei geringer Hitze schmelzen; Zucker, Goldsirup und Kondensmilch zugeben.","Dauernd 40–50 Minuten umrühren. Es sollte goldbraun sein, wenn es zum Essen bereit ist. Um zu testen, werfen Sie einen kleinen Blob in eine Schüssel mit kaltem Wasser; Es sollte festmachen.","Diese Karamellmischung über die Basis geben und abkühlen lassen.","Die geschmolzene Schokolade darüber gießen.","Die Schokolade gleichmäßig verteilen und einstellen lassen."],"x":[],"desc":"Quadrate aus Karamell (alternativ: Karamellscheiben, Karamell-Shortbread oder Millionärs-Shortbread) sind ein wunderbar reicher und klassischer Leckerbissen, sehr beliebt in ganz Großbritannien und Irland. Sie können oft in Cafés gefunden werden, serviert mit Morgenkaffee oder Nachmittagstee. Sie sind perfekt für Picknicks, Mittagessen und","img":"Millionaire's shortbread.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Caramel_Squares","i":"wb-en-1173","im":["3/3e/Millionaire%27s_shortbread.jpg/500px-Millionaire%27s_shortbread.jpg","Aurore D","CC BY 2.0","Millionaire's shortbread.jpg","r"],"on":"Caramel Squares","og":["#Base","350 g self-raising flour","225 g unsalted butter","110 g caster sugar","#Filling","225 g caster sugar","225 g unsalted butter","5 Tablespoons golden syrup","400 ml full-fat condensed milk","#Topping","340 g good-quality chocolate (milk or dark), melted"],"mt":1},{"n":"Karamellisierte Ananas","c":"dessert","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["2 Tassen gewürfelte Ananas","½ Tasse dunkler brauner Zucker, aufgeteilt","½ Tasse Schlagsahne","3 EL dunkler Rum","1 Vanilleschote, aufgeschnitten und ausgekratzt"],"s":["Kombinieren Sie Vanillebohne und flüssige Zutaten außer Rum und 1⁄4 Tasse braunen Zucker.","Bei mittlerer Hitze erhitzen, bis der Zucker gelöst ist und sich leicht verdickt hat, 15–30 Minuten.","Vanilleschote entfernen und die Zuckermischung 30 Minuten bei Raumtemperatur sitzen lassen.","Tauchen Sie Ananas in Zuckermischung dann Dredge in verbleibenden Zucker, Hinzufügen mehr nach Bedarf.","Ananas auf ein gefettetes Backblech legen und unter Broiler stellen, ständig schütteln bis gut gebräunt.","Ananas entfernen; Halt dich warm.","Backblech auf zwei Brenner legen und bei hoher Hitze erhitzen. Rum hinzufügen und entzünden. Scrape gebräunte Stücke aus der Pfanne und Rum kochen, bis um die Hälfte reduziert.","Rum zur restlichen Zuckermischung zugeben und umrühren. Ananas mit der restlichen Zuckermischung an der Seite servieren."],"x":[],"desc":"Karamellisierte Ananas ist an der Außenseite knusprig, süß und fruchtig.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Caramelized_Pineapple","i":"wb-en-1174","on":"Caramelized Pineapple","og":["2 cups diced pineapple","½ cup dark brown sugar, divided","½ cup heavy cream","3 tbsp dark rum","1 vanilla bean, split and scraped"],"mt":1},{"n":"Karamellisierte Himbeersoße","c":"saucen","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["1 Tasse TK-Himbeeren, aufgetaut","¼ Tasse Zucker","¼ Tasse Schlagsahne","1 Prise Salz (optional)","¼ Tasse ungesalzene Butter, aufgeteilt","1 EL Vanilleextrakt","Eis oder Obst"],"s":["Beeren auf ein Backblech legen und mit der Hälfte des Zuckers bestreuen. 5–15 cm unter einen vorgeheizten Broiler legen und die Brühe gut bräunen.","Entfernen und beiseite legen, bis kühl.","Sahne, Salz und restlichen Zucker in einem schweren Topf bei mittlerer Hitze zu kombinieren. Himbeeren hinzufügen und kochen, bis die Beeren leicht brechen.","Aus der Hitze entfernen und beiseite stellen, bis abkühlen. Purée in einem Lebensmittelverarbeiter oder Mixer, bis glatt. Alternativ verwenden Sie einen Eintauchmischer direkt in den Topf.","Mischen Sie die Mischung wieder in Topf, und legen Sie bei mittlerer Hitze. Zum Kochen bringen und kochen, bis die Flüssigkeit um 2⁄3 reduziert hat.","Butter und Vanille glatt einrühren, dann abkühlen.","Soße über Eis oder Obst gießen und servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Caramelized_Raspberry_Sauce","i":"wb-en-1175","on":"Caramelized Raspberry Sauce","og":["1 cup frozen raspberries, thawed","¼ cup white granulated sugar","¼ cup heavy cream","1 pinch of salt (optional)","¼ cup unsalted butter, divided","1 tbsp vanilla extract","Ice cream or fruit"],"mt":1},{"n":"Süßsaure karamellisierte Zwiebelmarmelade","c":"saucen","k":"USA","p":2,"t":0,"d":2,"v":1,"l":"en","g":["4 EL Oliven- oder Pflanzenöl","4 große gelbe oder weiße Zwiebeln, in dünne Streifen geschnitten","½ Tasse Zucker","¼ Tasse Aceto balsamico","¼ TL Salz","⅛ TL grob gemahlener schwarzer Pfeffer"],"s":["Öl in einer großen Pfanne bei mittlerer Hitze erhitzen. Zwiebeln hinzufügen, und braten, Rühren, für etwa 15 Minuten, oder bis sie beginnen zu braun. Kochen Sie nicht bei hoher Hitze, da die Außenseite der Zwiebeln zu schnell kohlen wird, bevor die Innenräume erweicht und gesüßt haben.","Wenn Zwiebeln erweicht und ein hellgoldenes Braun gedreht haben, Zucker hinzufügen. Rühren Sie weiter, bis Zucker schmilzt und beginnt zu blasen.","Während die Zwiebeln ein reicheres Braun drehen, einen Raum in der Mitte der Pfanne frei. Balsamico-Essig direkt auf die heiße Pfanne geben, dann in Zwiebeln rühren.","Wenn Essig reduziert hat, so dass eine sirupartige Beschichtung auf den Zwiebeln, schalten Sie die Hitze.","Salz und Pfeffer einrühren und Zwiebeln abkühlen lassen."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Caramelized_Sweet_and_Sour_Onion_Marmalade","i":"wb-en-1176","on":"Caramelized Sweet and Sour Onion Marmalade","og":["4 tablespoons olive or vegetable oil","4 large yellow or white onions, sliced into thin strips","½ cups white granulated sugar","¼ cup balsamic vinegar","¼ teaspoon salt","⅛ teaspoon coarse ground black pepper"],"mt":1},{"n":"Pasta carbonara","c":"pasta","k":"Italien","p":4,"t":0,"d":2,"v":0,"l":"en","g":["4 Freilandeier mit großem Dotter","65 g frische italienische Pancetta, in 6 bis 9 mm große Würfel geschnitten","1 Zweig frischer Thymian, fein gehackt","¼ kleine Zwiebel, fein gehackt","fein gehackte Schale von ½ Zitrone","Salz, nach Geschmack","Pfeffer, nach Geschmack","geriebener Parmigiano und/oder Pecorino Romano","340 g ungekochte Nudeln (z. B. Spaghetti oder Penne)"],"s":["Legen Sie auf die gewünschte Menge an Nudeln zu kochen.","Knacken Sie die Eier sorgfältig und trennen Sie das Eigelb von den Weißen – eine gute Möglichkeit, dies zu tun ist es, das Ei durch die fast geschlossenen Finger Ihrer umgedrehten Handfläche zu laufen, so wie das Weiß durch die Finger wegläuft, und das Eigelb bleibt in Ihrer Hand.","Halten Sie das Eigelb in einer großen Schüssel, und verwenden Sie die Weißen für einen anderen Zweck. Denken Sie daran, das lästige kleine weiße Stück auszusuchen, das immer auf dem Eigelb zurückbleibt.","Die Pancetta in einer trockenen Bratpfanne auf schwacher Hitze anbraten, bis sie knusprig ist.","Wenn die Pancetta gekocht wird, abtropfen lassen und für ein paar Minuten abkühlen lassen, bevor sie mit dem Eigelb in einer großen Schüssel kombiniert wird. Die Abkühlung verhindert das Kochen der Eier.","Eine Prise Steinsalz und eine sehr großzügige Menge gemahlener Pfeffer in die Dottermischung geben.","Fügen Sie die geriebene Zitronenschale, gehackten Thymian und eine kleine Menge des Parmigiano Käse.","Die Nudeln durch ein Colander abtropfen lassen, bis 10 zählen, um die Nudeln leicht abkühlen zu lassen und mit der Eigelbmischung in die Schüssel geben.","Mischen Sie ihn mit einem Holzlöffel durch und servieren Sie sofort den restlichen Parmigiano-Käse über die Oberseite."],"x":["Kaufen Sie für die Pancetta nicht das fertig gewürfelte Zeug, sondern die frische, italienische Version mit etwas zerkleinertem Pfeffer auf der Rinde. Wenn Sie es wirklich nicht finden, wird geräucherter Speck tun.","Verwenden Sie Eigelb so frisch und gelb wie möglich!","Wenn Sie ein wenig gehackte flache Blatt Petersilie (nicht das lockige Zeug) hinzufügen wollen, um Farbe hinzuzufügen, gehen Sie vor.","Serviert mit einem einfachen grünen Salat, ist es köstlich."],"desc":"Dies ist ein wunderbares Gericht, das sehr einfach zu tun ist. Es verwendet rohe Eier, die nicht nach jedermanns Geschmack sind und von schwangeren Frauen vermieden werden sollten.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Carbonara_Pasta","i":"wb-en-1177","im":["2/22/Pasta_carbonara.jpg/960px-Pasta_carbonara.jpg","Dandy1022","CC BY-SA 3.0","Pasta carbonara.jpg","c"],"on":"Carbonara Pasta","og":["4 free-range eggs with large yolks","3 oz (65 g) fresh Italian pancetta, cubed into ¼–⅜-inch (0.64–0.95 cm) pieces","1 sprig of fresh thyme, finely chopped","¼ small onion, finely chopped","The minced zest of ½ a lemon","Salt to taste","Pepper to taste","Grated parmigiano and/or pecorino romano cheese","12 oz (340 g) uncooked pasta (e.g. spaghetti or penne)"],"mt":1},{"n":"Carpetbag Steak (Steak mit Austernfüllung)","c":"fisch","k":"Australien","p":4,"t":0,"d":2,"v":0,"l":"en","g":["1 Rib-Eye-Steak (dick geschnitten)","Salz (optional)","gemahlener schwarzer Pfeffer (optional)","Cayennepfeffer (optional)","Zitronensaft (optional)","Olivenöl (optional)","3–4 Austern","Worcestersoße","Limetten (optional)","geriebener Käse (optional)"],"s":["Schneiden Sie eine kleine Tasche, ca. 6 cm (6,5 cm) in der Länge und etwa die gleiche Tiefe, am Rand des dicken Steaks.","Auf Wunsch die Innentasche mit etwas Salz, Pfeffer, Cayennepfeffer, Zitronensaft und Olivenöl würzen.","Tauchen Sie die Austern in die Worcestershire-Sauce und legen Sie sie dann in die Tasche im Steak ein.","Wenn gewünscht, fügen Sie Limettenfleisch oder etwas geschredderten Käse in die Tasche.","Verschließen Sie die Tasche mit einem befeuchteten Spieß.","Grillen, grillen oder kochen Sie das Steak auf Ihre gewünschte Ebene der Fertigkeit. Alternativ kochen Sie bei mäßiger Hitze in einer schweren Bratpfanne."],"x":["Zu den Ersatzstoffen für Worcestershire-Sauce gehören Teriyaki-Sauce, Austernsauce oder Rotweinessig-Marinaden, oder das Steak hat die Marinade oder Soße.","Zu den Ersatzstoffen für Austern gehören Pilze, Yabbies und Garnelen.","Einige Rezepte pochen oder sautieren die Austern zuerst ein wenig, wenn die Gäste seltene Steak bevorzugen, aber keine rohen Austern.","Einige Rezepte wickeln das Steak in Speck oder Pancetta.","Falls zutreffend und gewünscht, können Sie die Kochpfanne mit Sherry oder Brandy ablöschen oder eine Reduktion von Austernflüssigkeit und Wein mit gehackter Petersilie vornehmen."],"desc":"Carpetbag Steak ist ein einzigartiges australisches Gericht, das erstmals um 1950 in Sydney populär wurde.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Carpetbag_Steak","i":"wb-en-1178","on":"Carpetbag Steak","og":["1 Scotch fillet steak (thickly-cut)","Salt (optional)","Ground black pepper (optional)","Cayenne pepper (optional)","Lemon juice (optional)","Olive oil (optional)","3–4 oysters","Worcestershire sauce","Limes (optional)","Shredded cheese (optional)"],"mt":1},{"n":"Carquinyoli (katalanische Mandelkekse)","c":"brot","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["150 g Mehl","1 TL Zimt","1 TL Backpulver","1 Ei","100 g Zucker","1 Zitrone, Schale abgerieben","125 g ganze rohe Mandeln","1 Ei, verquirlt"],"s":["Mehl, Zimt und Backpulver kombinieren.","Kombinieren Sie Ei, Zucker und geriebene Zitronenschale. Whip bis sehr schaumig.","Rühren Sie die Mehlmischung und Mandeln in die Eiermischung, um einen Teig zu bekommen.","Den Teig auf einem Backpapier gefütterten Backblech zu zwei abgeflachten Stämmen von ca. 6 x 3 cm formen.","Den Teig mit dem geschlagenen Ei bürsten.","Im Backofen bei mittlerer Hitze (180 °C) 25 Minuten backen.","Den gebackenen Teig noch heiß in dünne Scheiben von weniger als 1 cm Dicke schneiden. Auf Backblechen Scheiben anordnen, ohne sie berühren zu lassen.","Backen sie für 5 Minuten mehr im Ofen, um ihre Oberflächen zu bräunen.","Vor dem Essen abkühlen lassen."],"x":[],"desc":"Carquinyoli sind katalanische Kekse ähnlich wie Biscotti.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Carquinyoli_(Catalan_Almond_Cookies)","i":"wb-en-1179","on":"Carquinyoli (Catalan Almond Cookies)","og":["150 g flour","1 teaspoon cinnamon","1 teaspoon baking powder","1 egg","100 g granulated sugar","1 lemon, zested","125 g whole raw almonds","1 egg, beaten"],"mt":1},{"n":"Möhrenkuchen I","c":"kuchen","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["#Frosting","100 g Puderzucker","50 g Frischkäse oder cremiger Hüttenkäse","25 g Margarine oder Butter","2,5 ml Vanillearoma","#Kuchen","225 g Mehl","225 g geriebene Möhre","150 g Margarine oder Butter","250 g brauner Zucker","2 TL Zimt","1 EL Zitronensaft","1,5 TL Backpulver","1 Ei","Rosinen (optional)","Nüsse (optional)"],"s":["Alle Zutaten miteinander vermischen.","Butter und Zucker zusammenschmelzen, dann die trockenen Zutaten vermischen.","Schlag das Ei und füge es dem Teig hinzu.","In Rosinen und Nüssen umrühren, bis alles gut kombiniert ist.","Bei 180 °C ca. 50 Minuten in einer gefetteten Dose mit fettfestem Papier auf dem Boden backen.","Wenn Kuchen abgekühlt ist, oben mit Sahnekäse Frostung."],"x":[],"desc":"","img":"0112 Karottenkuchen, ciasto marchwiowe.JPG","u":"https://en.wikibooks.org/wiki/Cookbook:Carrot_Cake_I","i":"wb-en-1180","im":["7/7b/0112_Karottenkuchen%2C_ciasto_marchwiowe.JPG/960px-0112_Karottenkuchen%2C_ciasto_marchwiowe.JPG","Silar","CC BY-SA 3.0","0112 Karottenkuchen, ciasto marchwiowe.JPG","r"],"on":"Carrot Cake I","og":["#Frosting","100 g icing sugar","50 g cream cheese or creamy cottage cheese","25 g margarine or butter","2.5 ml vanilla essence","#Cake","225 g flour","225 g grated carrot","150 g margarine or butter","250 g brown sugar","2 teaspoons cinnamon","1 tablespoon lemon juice","1.5 teaspoons baking powder","1 egg","Raisins (optional)","Nuts (optional)"],"mt":1},{"n":"Möhrenkuchen II","c":"kuchen","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["#Kuchen","450 ml Pflanzenöl","400 g Weizenmehl (Type 405)","2 TL Natron","570 g Zucker","290 g Eier","1 Prise Salz","12 g gemahlener Zimt","530 g Möhren, geschält und gerieben","150 g Walnüsse, gehackt","#Belag","200 g Frischkäse","150 g Zucker","100 g Butter"],"s":["Mischen Sie alle Zutaten zusammen in einem Lebensmittel-Verarbeiter für 5 Minuten.","Teig in eine Tortendose mit einem Durchmesser von 26 cm gießen.","Bei 160 °C/Gas 3) 45 Minuten backen.","Überprüfen Sie, ob der Kuchen gekocht wird, dann aus dem Ofen entfernen und 10 Minuten in der Dose abkühlen lassen.","Entschmolzener Kuchen und legen Sie ihn auf ein Kühlregal.","Für das Topping den Frischkäse, Zucker und Butter in eine Rührschüssel geben und die Sahne glatt und weich zusammensetzen.","Mit einem Palettenmesser über den Kuchen verteilen."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Carrot_Cake_II","i":"wb-en-1181","im":["f/fe/Carrot_cake_at_America_Graffiti_%28cropped%29.jpg/960px-Carrot_cake_at_America_Graffiti_%28cropped%29.jpg","Elitre","CC BY-SA 4.0","Carrot cake at America Graffiti (cropped).jpg","w"],"on":"Carrot Cake II","og":["#Cake","450 ml (14 fl oz) vegetable oil","400 g (14 oz) plain flour","2 tsp bicarbonate soda","570 g (1 lb 4 oz) granulated sugar","290 g (10 oz) eggs","1 pinch of salt","12 g (½ oz) ground cinnamon","530 g (1 lb 3 oz) carrots, peeled and grated","150 g (5 oz) walnuts, chopped","#Topping","200 g (7 oz) cream cheese","150 g (5 oz) granulated sugar","100 g (3½ oz) butter"],"mt":1},{"n":"Möhrenkuchen-Smoothie","c":"getraenke","k":"","p":2,"t":10,"d":1,"v":0,"l":"en","g":["2 Möhren","2 TL Wasser","185 ml Wasser","½ sehr reife Banane","1 Orange, geschält und gehackt","2 cm Stück Ingwer, geschält und gehackt","½ TL gemahlener Zimt, plus etwas zum Bestäuben","½ EL fettfreier Naturjoghurt (natur)","Eiswürfel zum Servieren"],"s":["Mikrowelle die Karotten mit 2 Teelöffeln Wasser in einer mikrowellensicheren Schüssel auf hoch für 4–5 Minuten.","Die Karotte in einen Mixer mit restlichen Zutaten, außer Eiswürfeln, geben und glatt mischen.","In zwei große Gläser gießen und Eiswürfel dazugeben.","Staub mit ein wenig Zimt und servieren."],"x":[],"desc":"Karottenkuchen Smoothie ist ein Rezept, das aus einem Rezept in Seite 42 der April 2023 Ausgabe von Tesco's Magazin angepasst wird.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Carrot_Cake_Smoothie","i":"wb-en-1182","im":["f/fe/Carrot_cake_at_America_Graffiti_%28cropped%29.jpg/960px-Carrot_cake_at_America_Graffiti_%28cropped%29.jpg","Elitre","CC BY-SA 4.0","Carrot cake at America Graffiti (cropped).jpg","w"],"on":"Carrot Cake Smoothie","og":["2 carrots","2 teaspoons water","¾ cup (185 ml / 6.3 fl oz) water","½ very ripe banana","1 orange, peeled and chopped","2 cm (0.8 inch) piece ginger, peeled and chopped","½ teaspoon ground cinnamon, plus extra for dusting","½ tablespoon fat-free natural (plain) yogurt","Ice cubes to serve"],"mt":1},{"n":"Möhren-Fufu","c":"welt","k":"","p":1,"t":5,"d":1,"v":0,"l":"en","g":["4 Möhren, gehackt","1 TL Flohsamenschalenpulver oder Xanthan","½ Tasse Wasser"],"s":["Die gehackte Karotte glatt mischen.","Übertragen Sie die Karotte zum Käsetuch, und drücken Sie das ganze Wasser aus der Karottenpaste heraus.","Die Karottenpaste 5 Minuten lang bei mittlerer Hitze in einem Topf kochen.","In die Psylliumschale rühren, um das Fufu zu verdicken und zu binden."],"x":["Die Funktion der Psyllium-Husk ist es, die Karottenfufu formbar zu machen, und dies gibt ihm die Textur von eba.","Schneiden oder abkratzen Sie alle dunklen Markierungen auf der Karotte."],"desc":"Karottenfufu ist eine Schwalbe aus Karotte, die in Nigeria aufgrund ihres geringen Kohlenhydratgehalts üblich ist. Es ist leicht zu machen, wenn die Karotte glatt gemischt wird.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Carrot_Fufu","i":"wb-en-1183","im":["1/1f/Wrapped_fufu.jpg/330px-Wrapped_fufu.jpg","daSupremo","CC BY-SA 4.0","Wrapped fufu.jpg","w"],"on":"Carrot Fufu","og":["4 carrots, chopped","1 teaspoon psyllium husk powder or xanthan gum","½ cup water"],"mt":1},{"n":"Möhrenkonfitüre","c":"saucen","k":"Dänemark","p":50,"t":0,"d":1,"v":0,"l":"en","g":["1 kg Möhren, geschält und fein gerieben","¼ l Wasser","Saft von 4 Zitronen","½ kg Zucker"],"s":["Kochen Sie das Wasser und Karotten bis zart.","Saft und Zucker zugeben und weitere 15–20 Minuten kochen lassen."],"x":[],"desc":"Da Karotten ziemlich süß sind, können sie oft in süßen Gerichten mit guten Ergebnissen verwendet werden. Ein solches Rezept ist Karottenmarmelade; Dies ist eine einfache Version aus Dänemark.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Carrot_Jam","i":"wb-en-1184","im":["6/6c/Shrimp_frittata_with_carrot_jam_%28cropped%29.jpg/330px-Shrimp_frittata_with_carrot_jam_%28cropped%29.jpg","judywitts","CC BY 2.0","Shrimp frittata with carrot jam (cropped).jpg","w"],"on":"Carrot Jam","og":["1 kg carrots, peeled and finely grated","¼ liter water","Juice of 4 lemons","½ kg sugar"],"mt":1},{"n":"Möhren-Kugel (Auflauf)","c":"welt","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["4 Eier, getrennt","75 g Zucker","25 g Butter","1 kleiner Kochapfel","abgeriebene Schale von 1 Orange","225 g Möhren","Saft von 1 Orange","1 TL Zitronensaft","50 g Kartoffelmehl"],"s":["Den Backofen auf 190 °C vorheizen.","Eine 1-Liter-Backform fetten.","Die Eigelbe und den Zucker in einer Schüssel bis hell und flauschig und blass in der Farbe schlagen.","Die Karotte und den Apfel sehr fein reiben, dann ausquetschen und die gesamte Flüssigkeit wegwerfen.","Die geriebene Karotte, Apfel, Orangenrinde, Orangen- und Zitronensaft und Mehl vermischen.","Kombinieren Sie Ei und Karottenmischungen.","Das Eiweiß so lange rühren, bis es sehr steif ist, und in eine Karottenmischung falten.","Löffelmischung in die gefettete Backform.","35 Minuten backen oder goldbraun."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Carrot_Kugel","i":"wb-en-1185","im":["e/ef/Noodle_Kugel.jpg/960px-Noodle_Kugel.jpg","Off-shell","CC BY-SA 4.0","Noodle Kugel.jpg","w"],"on":"Carrot Kugel","og":["4 eggs, separated","75 grams white granulated sugar","25 grams butter","1 small cooking apple","Grated zest of 1 orange","225 grams carrots","Juice of 1 orange","1 teaspoon lemon juice","50 grams potato flour"],"mt":1},{"n":"Möhren-Paprika-Aufstrich","c":"veggie","k":"","p":1,"t":15,"d":1,"v":2,"l":"en","g":["250 g Haferflocken (oder rohes Dinkelmehl)","250 g Tofu","1 Möhre (oder mehr) (n)","1 Paprikapulver (oder mehr) (n) (ersatzweise rote oder süße Paprika)","1 Zwiebel (oder mehr) (n)","Margarine","Rapsöl oder anderes Pflanzenöl","Sojasoße","Senf","Ketchup","Knoblauch","Pfeffer","Sojalecithin-Pulver"],"s":["Kombinieren Sie Haferflocken und Tofu mit etwas Wasser, um die Basis zu machen. Du solltest vielleicht Lecithinpulver als Emulgator hinzufügen.","Maischekarotte, Paprika und Zwiebel. Wenn Sie größere Stücke bevorzugen, können Sie stattdessen auch einige davon schneiden.","Einen Löffel Margarine und/oder einen Löffel Rapsöl hinzufügen.","Senf, Catsup, Knoblauch und Pfeffer nach Geschmack hinzufügen."],"x":[],"desc":"Karottenpaprika Verbreitung ist eine Verbreitung, bestehend aus Tofu und Haferflocken.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Carrot_Paprika_Spread","i":"wb-en-1186","on":"Carrot Paprika Spread","og":["250g oat flakes (or raw spelt flour)","250g tofu","1 (or more) carrot(s)","1 (or more) paprika(s) (may substitute with red bell peppers, sweet peppers)","1 (or more) onion(s)","Margarine","Rapeseed oil or other vegetable oil","Soy sauce","Mustard","Catsup","garlic","pepper","Soy lecithin powder"],"mt":1},{"n":"Möhrenpudding","c":"dessert","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["1.25 kg Möhren","1 ¼ Tassen Mehl","1 TL Salz","½ TL Backpulver","½ TL Natron","1 Tasse Backfett, Butter, oder Margarine","2 Eigelb","⅓ Tasse brauner Zucker","1 EL Wasser","1 EL Zitronensaft","½ TL Vanille","2 Eiweiß"],"s":["Backofen auf 150 °C vorheizen.","Karotten weich kochen, abtropfen lassen und zermaschen. Beiseite legen.","Mehl, Salz, Backpulver und Backnatron zusammensieben.","Sahne zusammen Verkürzen und Eigelb.","In braunen Zucker, kaltem Wasser, Zitronensaft und Vanille gut mischen. In Karottenmaische rühren, dann die Zutaten trocknen.","Das Eiweiß steif rühren, dann in Karottenkarotte falten.","Übertragen Sie Teig in eine gut-fettete Ringform (mit einem Boden).","Legen Sie eine große flache Pfanne mit etwa einem Zentimeter Wasser in den vorgeheizten Ofen und legen Sie den Pudding in die Pfanne.","1 Stunde backen. Entschmolzen auf eine Servierplatte, während sie noch etwas warm ist."],"x":["Bei Bedarf können Sie Babykarotten für die normalen Karotten ersetzen.","Wenn gewünscht, können Sie andere gehackte Gemüse (Erbsen, gehackte Bohnen usw.) hinzufügen.","Wenn Sie kein Wasserbad machen können, backen Sie einfach ohne."],"desc":"Dieses Rezept stammt von Ida Geller Weiner (1912–2008), von New Haven CT, die es Thanksgiving und andere Familientreffen gemacht hat.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Carrot_Pudding","i":"wb-en-1187","im":["2/27/Carrot_pudding_with_fruits.jpg/500px-Carrot_pudding_with_fruits.jpg","mari from tokyo, japan","CC BY 2.0","Carrot pudding with fruits.jpg","w"],"on":"Carrot Pudding","og":["1.5 lbs (1.25 kg / about 4–5 ea.) carrots","1¼ cups flour","1 tsp salt","½ tsp baking powder","½ tsp baking soda","1 cup shortening, butter, or margarine","2 egg yolks","⅓ cup brown sugar","1 tbsp water","1 tbsp lemon juice","½ tsp vanilla","2 egg whites"],"mt":1},{"n":"Möhrensalat","c":"salate","k":"","p":2,"t":5,"d":1,"v":2,"l":"en","g":["Möhren (etwa 4 mittelgroße)","Mandelöl","weißer Balsamicoessig (oder eine Mischung aus 2 Teilen Rotweinessig und 1 Teil Aceto balsamico)","grobes Salz","frisch gemahlener Pfeffer","Pinienkerne","frisches Blattgemüse wie Mizuna oder junger Chinasenf, oder auch Buttersalat (optional)","Schnittlauch (optional)"],"s":["Juliene die Karotten (oder reiben sie, wenn julienning nicht möglich ist).","Mantel mit etwa 1–2 Esslöffel Mandelöl.","Großzügig mit Essig, Salz und Pfeffer bestreuen.","Fügen Sie eine kräftige Portion Pinienkerne."],"x":["Karottensalat in Grün verpackt: Legen Sie ein wenig von der Karottensalat auf ein grünes Blatt und wickeln Sie es zusammen mit einem Schnittlauch. Sie machen etwa 2-Bite Hors d'œuvres, die leicht sind, gesund und überraschend füllen. Wenn Sie die jungen Senfgrüne erreichen können, fügen sie eine fantastische Würze hinzu, die nicht aufeinander abgestimmt werden kann."],"desc":"","img":"Nest of Carrot Salad, by LadyofProcrastination.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Carrot_Salad","i":"wb-en-1188","im":["4/49/Nest_of_Carrot_Salad%2C_by_LadyofProcrastination.jpg/960px-Nest_of_Carrot_Salad%2C_by_LadyofProcrastination.jpg","Melinda","CC BY-SA 2.0","Nest of Carrot Salad, by LadyofProcrastination.jpg","r"],"on":"Carrot Salad","og":["Carrots (about 4 medium sized)","Almond oil","White balsalmic vinegar (or a mix of two parts red wine vinegar to one part balsamic vinegar)","Coarse salt","Freshly-ground pepper","Pine nuts","Fresh greens like matzumi or baby Chinese mustard, or even Boston lettuce (optional)","Chives (optional)"],"mt":1},{"n":"Möhren-Koriander-Suppe","c":"suppen","k":"","p":4,"t":0,"d":1,"v":2,"l":"en","g":["1 EL Olivenöl","1 große Zwiebel, gewürfelt","500 g Möhren, gewürfelt","1 TL gemahlener Koriander","1,2 l Gemüsebrühe","1 großes Bund frischer Koriander (Koriandergrün), grob gehackt","Salz","schwarzer Pfeffer"],"s":["Das Olivenöl in einer Antihaft-Pfanne auf mittlerer Hitze erhitzen.","Zwiebeln und Karotten dazugeben. Etwa 5 Minuten kochen, bis sie weich werden.","Den gemahlenen Koriander, Salz und Pfeffer hinzufügen. Noch eine Minute kochen.","Fügen Sie die Gemüsebrühe, und bringen Sie die Mischung zum Kochen. 10–15 Minuten köcheln, bis die Karotten sehr weich sind.","Purée, bis er glatt ist.","Den frischen Koriander dazugeben und servieren."],"x":[],"desc":"Karotten- und Koriandersuppe ist eine klassische Kombination aus frischem und gemahlenem Koriander. Der frische Koriander, der am Ende des Kochens hinzugefügt wird, fügt wirklich den hellen Geschmack des Korianders hinzu, der mit der Karotte übereinstimmt.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Carrot_and_Coriander_Soup","i":"wb-en-1189","im":["a/ab/Carrot_soup.jpg/960px-Carrot_soup.jpg","jules / stone soup","CC BY 2.0","Carrot soup.jpg","w"],"on":"Carrot and Coriander Soup","og":["1 tablespoon olive oil","1 large onion, diced","500 g (1.1 lb) carrots, diced","1 teaspoon ground coriander","1.2 L (41 oz) vegetable stock","1 large bunch fresh coriander (cilantro), roughly chopped","Salt","Black pepper"],"mt":1},{"n":"Möhren-Rosinen-Salat","c":"salate","k":"Kanada","p":2,"t":30,"d":2,"v":2,"l":"en","g":["2 Möhren (250 g), gerieben","40 g Rosinen","1 Zitrone, Schale abgerieben und Saft ausgepresst","1 Orange, Schale abgerieben und Saft ausgepresst","Zucker oder Honig, nach Geschmack"],"s":["Karotten in einer Schüssel mit Rosinen vermischen.","Etwa 1 Teelöffel fein gegratete Zitrone und geriebene Orangenschale zugeben, dann die Säfte dazugeben.","Fügen Sie Zucker oder Honig nach Geschmack, und werfen alles zusammen gut.","Kühlen und servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Carrot_and_Raisin_Salad","i":"wb-en-1190","im":["f/f1/Carrot_n_raisin_salad.jpg/960px-Carrot_n_raisin_salad.jpg","Adishrimaiti","CC BY-SA 4.0","Carrot n raisin salad.jpg","c"],"on":"Carrot and Raisin Salad","og":["2 ea. (250 g / 8.8 oz) carrots, shredded","½ cup (40 g / 1.4 oz) raisins","1 lemon, zested and juiced","1 orange, zested and juiced","Sugar or honey to taste"],"mt":1},{"n":"Möhren nach Kinpira-Art","c":"beilagen","k":"Japan","p":4,"t":0,"d":1,"v":2,"l":"en","g":["250 g Möhren, in feine Streifen geschnitten","1 EL Pflanzenöl, am besten Sesamöl","Wasser","Tamari oder Shoyu (Sojasoße), nach Geschmack"],"s":["Die Karotten in dünne Streichholzstücke schneiden (sen-giri, oder julienned)","Eine kleine Menge Öl in einen Topf geben und die Karottenstücke kurz anbraten.","Fügen Sie gerade genug Wasser, um die Karottenstücke halb zu decken","Den Deckel auf den Topf legen und die Karotten bei mittlerer Hitze kurz köcheln lassen","Fügen Sie ein wenig Tamari oder Shoyu, um den Geschmack zu verbessern. Servieren."],"x":[],"desc":"Kinpira ist ein japanischer Kochbegriff, der grob übersetzt zu sauté und köcheln. Das Ziel ist es, Wurzelgemüse wie Karotten und Klettenwurzel in einer minimalen Menge Wasser zu kochen, so dass sie am Ende zart gekocht und mit keinem ihrer Geschmack oder Nährwert verloren in weggeworfen Kochwasser.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Carrots_Cooked_Kinpira_Style","i":"wb-en-1191","on":"Carrots Cooked Kinpira Style","og":["250 g (½ lb) carrots, julienned","1 Tbsp vegetable oil, preferably sesame oil","Water","Tamari or shoyu soy sauce, to taste"],"mt":1},{"n":"Cashewsoße","c":"saucen","k":"","p":2,"t":0,"d":1,"v":2,"l":"en","g":["½ Zwiebel in dünnen Scheiben","½ Paprika in dünnen Streifen","2 EL Erdnussöl","Salz, nach Geschmack","Pfeffer, nach Geschmack","2 TL Weißwein","1 ½ Tassen Milch oder ungesüßte Sojamilch","½ Tasse Cashewmus","1 Prise Cayennepfeffer"],"s":["Lassen Sie die Cashewbutter auf Raumtemperatur zu kommen, wenn gekühlt.","Zwiebel und Paprika im Erdnussöl bei geringer bis mittlerer Hitze mit Salz und Pfeffer anbraten, bis die Zwiebel durchscheinend zu werden beginnt und der Paprika weich ist.","Den Wein dazugeben und die Pfanne ablöschen.","Cayenne-Pfeffer und Milch hinzufügen und durchwärmen.","Die Cashewbutter im Löffel geben und rühren, bis sie eingearbeitet und glatt ist. Gravy erscheint zunächst klumpig, wird aber nach ein paar Minuten Rühren und Simmern glatt werden.","Die Menge Milch oder Cashewbutter je nach Bedarf für die gewünschte Konsistenz anpassen.","Geschmack und bei Bedarf Salz zugeben.","Servieren Sie Soße auf grüne Bohnen oder andere Gemüse, oder brauner Reis."],"x":[],"desc":"Diese Soße ist eine dicke Cashew-basierte Sauce, die auf Gemüse schmeckt. Cashew Soße ist traditionell eine Möglichkeit, eine cremige vegane Sauce zu machen – verwenden Sie ungesüßte Sojamilch statt Milch, wenn ein veganes Rezept gewünscht wird.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cashew_Gravy","i":"wb-en-1192","on":"Cashew Gravy","og":["½ thinly-sliced onion","½ thinly-sliced bell pepper","2 tbsp peanut oil","Salt to taste","Pepper to taste","2 tsp white wine","1½ cup milk or unsweetened soy milk","½ cup cashew butter","1 pinch cayenne pepper"],"mt":1},{"n":"Maniokkuchen (Cassava Pone)","c":"dessert","k":"","p":10,"t":120,"d":1,"v":0,"l":"en","g":["1.36 kg roher Maniok, geschält und gerieben","½ TL gemahlener Zimt (2.5 ml)","½ TL gemahlener schwarzer Pfeffer (2.5 ml)","½ TL gemahlene Muskatnuss (2.5 ml)","2 TL Vanilleextrakt (10 ml)","4 EL geschmolzene Butter oder Kokosöl (60 ml)","180 ml brauner Zucker","720 ml ungesüßte Kondensmilch oder Kokosmilch"],"s":["Den Ofen auf 180 °C vorheizen.","Kombinieren Sie alle Zutaten zusammen, gut mischen, um zu integrieren.","Übertragen Sie die Mischung in eine Backform.","Backen Sie die Cassava Pone für 60 Minuten, bis fest und golden."],"x":[],"desc":"Cassava Pone ist ein Dessert mit Ursprung in der Karibik. Dieses Rezept wird von Alica's Pepperpot modifiziert.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cassava_Pone","i":"wb-en-1193","im":["b/b6/Trinidad_cassava_pone_on_plate.jpg/960px-Trinidad_cassava_pone_on_plate.jpg","999real","CC0","Trinidad cassava pone on plate.jpg","c"],"on":"Cassava Pone","og":["3 lbs (1.36 kg) raw cassava, peeled and grated","½ tsp (2.5 ml) ground cinnamon","½ tsp (2.5 ml) ground black pepper","½ tsp (2.5 ml) ground nutmeg","2 tsp (10 ml) vanilla extract","4 tbsp (60 ml) melted butter or coconut oil","¾ cup (180 ml) brown sugar","3 cups (720 ml) unsweetened evaporated milk or coconut milk"],"mt":1},{"n":"Cassoulet","c":"suppen","k":"Frankreich","p":4,"t":0,"d":2,"v":0,"l":"en","g":["500 g getrocknete weiße Bohnen","Kreuzkümmel","1 Schweineohr oder Schwarte (optional)","1 kg gemischtes Enten- oder Gänsefleisch, Toulouser Würste (kräftige Knoblauchwürste), Schwein, und/oder Hammel","Entenschmalz, Gänseschmalz, oder Olivenöl","1 Zwiebel, gehackt","Brühe oder Weißwein","Bouquet garni","1 Kopf Knoblauch, geschält","Salz","Pfeffer","Gewürznelken","Wacholderbeeren","Wasser oder Brühe"],"s":["Die Bohnen für ein paar Minuten blanchieren, indem sie in reichlich kochendes Wasser für ein paar Minuten und dann in kaltes Wasser mit Kreuzkümmel gewürzt.","Bohnen abtropfen lassen und beiseite stellen.","Das Fleisch in einer Pfanne mit Ente oder Gänsefett nähen – nur außen braun. Das Fleisch entfernen und beiseite stellen.","Die Zwiebel in der gleichen Pfanne gold- oder dunkelbraun anbraten oder rühren, dann beiseite stellen.","Entwässern und wegwerfen Restfett aus der Pfanne. Den dunklen Rückstand in der Pfanne mit Brühe oder Weißwein ablöschen. Stellen Sie die entglasende Flüssigkeit beiseite.","In einer Backform, Pfanne oder Topf, Schicht Bohnen, Fleisch, gekochte Zwiebeln, Knoblauchzehen, Bouquet garni und Wacholderbeeren. Fügen Sie die entglasende Flüssigkeit dann genug kochendes Salzwasser, um die Bohnen um etwa einen Zoll zu decken.","Bei 90 °C etwa 41⁄2 Stunden backen. Bei Bedarf während des Backens zusätzliches kochendes Wasser zugeben. Wenn sich eine leichte Kruste gebildet hat und die Bohnen das ganze Wasser absorbiert haben und zart werden, wird die Zubereitung durchgeführt.","Lassen Sie für etwa 1 Stunde vor dem Servieren stehen."],"x":["Wenn es kühl gehalten wird, kann das Cassoulet am nächsten Tag wieder erhitzt werden, danach aber wahrscheinlich sauer werden.","Das Fleisch kann auch Konfitüren von Schweinefleisch, billige Dosen Schwein, Schweinetrotter, Wurst und / oder grüner Speck."],"desc":"Cassoulet (Pays D'OC caçolet) ist eine Spezialität der Region Languedoc und benannt nach dem Toneintopf, in dem es hergestellt wird. Es ist möglicherweise mit Cocido in Spanien verwandt. Cocido soll aus der jüdischen und muslimischen Tradition der Zubereitung von Essen die ein oder zwei Tage zuvor stammen, um","img":"Cassoulet.cuit.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Cassoulet","i":"wb-en-1194","im":["1/15/Cassoulet.cuit.jpg/960px-Cassoulet.cuit.jpg","GD. Guilhem06 21:37, 20 April 2007 (UTC)","Public domain","Cassoulet.cuit.jpg","r"],"og":["500 g (about 1 lb) dried white haricot/navy beans","Cumin","1 pig ear or pork rind (optional)","1 kg (about 2 lb) mixture of duck or goose meat, Toulouse sausages (strong garlic sausage), pork, and/or mutton","Duck fat, goose fat, or olive oil","1 onion, chopped","Stock or white wine","Bouquet garni","1 head of garlic, peeled","Salt","Pepper","Cloves","Juniper berries","Water or stock"],"mt":1},{"n":"Blumenkohl mit Käsesoße","c":"welt","k":"Großbritannien","p":1,"t":20,"d":1,"v":0,"l":"en","g":["1 großer Blumenkohl","300 ml weiße Soße (Béchamel)","100 g Parmesan","30 g ungesalzene Butter","1 EL Semmelbrösel","1 EL Salz","1 EL Pfeffer"],"s":["Schneiden Sie Ihren Blumenkohl in kleine Floretten, und legen Sie sie Köpfe nach unten in eine Schüssel mit salzigem Wasser, um sie für eine Stunde zu kleiden.","Die Floretten abtropfen lassen und zu einem Topf mit gesalzenem kochendem Wasser hinzufügen. Kochen, aufgedeckt, regelmäßig überprüfen das Gefühl des Blumenkohls mit einem Messer zu sehen, wenn sie bereit sind. Ihr Messer sollte glatt gehen, aber mit etwas Festigkeit zum Blumenkohl noch.","Den Backofen auf 200 °C vorheizen (180 °C Lüfter/200 °C/Gas 6).","Sobald der Blumenkohl gekocht hat, entleeren Sie die Floretten und legen sie in einem Gericht Ihrer Wahl. Die weiße Sauce mit 2⁄3 Parmesankäse kombinieren und über den Blumenkohl gießen. Über die Brotkrumen und den restlichen Käse streuen.","Legen Sie Ihr Gericht in den Ofen für etwa 20 Minuten, oder bis goldbraun.","Servieren Sie sofort."],"x":[],"desc":"Blumenkohlkäse oder Blumenkohlgratin (Französisch: Choufleur au Gratin) ist ein gefülltes und kitschiges Gericht, ideal als eine Seite zu einem Braten-Dinner oder jedem anderen Gericht.","img":"Cauliflower cheese side dish.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Cauliflower_Cheese","i":"wb-en-1195","im":["5/51/Cauliflower_cheese_side_dish.jpg/960px-Cauliflower_cheese_side_dish.jpg","AnemoneProjectors - Peter O'Connor ( talk ; Flickr )","CC BY-SA 2.0","Cauliflower cheese side dish.jpg","r"],"on":"Cauliflower Cheese","og":["1 large cauliflower head","300 ml (10 oz / 1 ¼ cups) white sauce","100 g (3.5 oz) parmesan","30 g (1.1 oz) unsalted butter","1 tbsp breadcrumbs","1 tbsp salt","1 tbsp pepper"],"mt":1},{"n":"Blumenkohlreis","c":"beilagen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["Blumenkohl","Essig","Pflanzenöl","Salz","weißer Pfeffer"],"s":["Mit einem Messer die grünen Blätter des Blumenkohls entfernen.","Den Blumenkohlkopf mit Essig in Wasser tauchen. Soak für 5 Minuten bis 1 Stunde. Blumenkohl abtropfen lassen und gut trocknen.","Verwenden Sie eine Reibe mit mittelgroßen Löchern, um den Blumenkohl in Reis-ähnliche Bits zu reiben.","2 EL Pflanzenöl in einer Pfanne erhitzen. Den Reiskohl hinzufügen und 3 Minuten bei geringer Hitze kontinuierlich umrühren. Dadurch erhält der Blumenkohlreis eine ähnliche Textur wie regelmäßiger Reis und hilft, die Wassermenge in ihm zu verringern.","Fügen Sie einen Schuss Salz und etwas weißer Pfeffer, dann decken und kochen für 1 Minute.","Entfernen Sie von der Hitze, Saison, und verwenden Sie wie gewünscht."],"x":[],"desc":"Blumenkohlreis ist eine Reisalternative, die weniger Kalorien und weniger Kohlenhydrate enthält. Geriebener Blumenkohl kann genauso zubereitet werden wie regelmäßiger brauner und weißer Reis: Gebraten, gedämpft, gekocht oder anders gekocht.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cauliflower_Rice","i":"wb-en-1196","im":["2/2f/Chou-fleur_02.jpg/960px-Chou-fleur_02.jpg","Coyau","CC BY-SA 3.0","Chou-fleur 02.jpg","w"],"on":"Cauliflower Rice","og":["White cauliflower","Vinegar","Vegetable oil","Salt","White pepper"],"mt":1},{"n":"Causa Rellena con Pollo (peruanischer Kartoffel-Hähnchen-Schichtsalat)","c":"fleisch","k":"Peru","p":6,"t":60,"d":1,"v":0,"l":"en","g":["10 mittelgroße Kartoffeln (gelbe, neue oder rote eignen sich gut)","450 g gezupftes gekochtes Hähnchenfleisch","100 g Mayonnaise","25 g Butter","2 Zehen Knoblauch","Salz","Pfeffer","Blattsalat","3 hartgekochte Eier","schwarze Oliven"],"s":["Kartoffeln kochen und schälen. Abkühlen lassen, dann massieren.","In einer Schüssel das Huhn, Mayonnaise, Zwiebel, Salz und Pfeffer zu kombinieren.","Legen Sie eine tiefe Schüssel mit Plastikfolie, oder legen Sie einen Formzylinder auf einer Platte.","Fügen Sie die Kartoffelpüree, um ein Bett ca. 1 cm hoch an der Unterseite zu bilden.","Fügen Sie eine zweite Schicht von 1 cm der Hühnermischung gleichmäßig über die Kartoffel.","Die Hähnchenmischung mit einer letzten Kartoffelschicht auffüllen und in zwei Kartoffelschichten ein Sandwich aus Hähnchen bilden.","Entfernen oder entfernen Sie den Zylinder.","Mit Salat und Mayonnaise garnieren.","Die hart gekochten Eier in Scheiben schneiden und darauf legen. Wenn gewünscht, schwarze Oliven hinzufügen.","Dieses Gericht kann leicht kalt serviert werden."],"x":["Kartoffelpüree kann mit einer Mischung aus Olivenöl und Butter zubereitet werden und fügt einen Esslöffel Zitronensaft hinzu. Sie können Zitrone mit Salz kompensieren. Nicht Milch dazugeben.","Sie können das Huhn durch eine Dose Thunfisch mit Mayonnaise und fein gehackte Zwiebel gemischt ersetzen. Diese Variation nur frisch servieren."],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Causa_Rellena_con_Pollo_(Peruvian_Layered_Potato_and_Chicken)","i":"wb-en-1197","on":"Causa Rellena con Pollo (Peruvian Layered Potato and Chicken)","og":["10 medium potatoes (yellow, new, or red are a good choice)","1 pound of shredded boiled chicken meat","100 g mayonnaise","25 g butter","2 cloves garlic","Salt","Pepper","Lettuce","3 hard boiled eggs","Black olives"],"mt":1},{"n":"Scharfe Cayenne-Soße","c":"saucen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["¾ Tasse Malzessig","¼ Tasse Cayennepfeffer","1 EL Salz"],"s":["Kombinieren Sie alle Zutaten. Unbestimmt bei Raumtemperatur in einer Spritzflasche aufbewahren."],"x":[],"desc":"Diese scharfe Soße schmeckt sehr nach Tabasco und anderen auf Essig basierenden Cayenne heißen Soßen.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cayenne_Hot_Sauce","i":"wb-en-1198","im":["a/a3/Fermented_hot_sauce.jpg/960px-Fermented_hot_sauce.jpg","Veganbaking.net from USA","CC BY-SA 2.0","Fermented hot sauce.jpg","w"],"on":"Cayenne Hot Sauce","og":["¾ cup malt vinegar","¼ cup cayenne pepper","1 tbsp salt"],"mt":1},{"n":"Cazuela Gallega (Auflauf mit Ei, Schinken und Käse)","c":"fruehstueck","k":"Kolumbien","p":1,"t":40,"d":1,"v":0,"l":"en","g":["2 Eier","2 Scheiben Schinken","2 EL Petits Pois (feine Erbsen) (Erbsen aus der Dose)","2 EL Ketchup","1 EL Butter","½ Tasse geriebener Parmesan","Salz"],"s":["3 Blatt Aluminiumfolie (ca. 38 x 38 cm oder 35 x 35 cm) in eine Schüssel mit einem Durchmesser von 13 cm (12 cm) und einer Tiefe von 5 cm geben. Drücken Sie die Folie vorsichtig nach unten, um ihr die Form der Schale zu geben.","Die Butter über die Innenwände der aluminiumförmigen Schale verteilen.","Legen Sie eine Scheibe Schinken in den Boden der Schüssel. Die zusätzliche Scheibe in drei Streifen schneiden. Mit jedem Streifen, decken Sie innerhalb der Wände von Aluminiumschüssel.","Beide Eier in die Schüssel geben.","Die Erbsen dazugeben und über die Eier verteilen. Sei vorsichtig mit dem Eigelb – zerbreche sie nicht. Fügen Sie 1 Teelöffel der Flüssigkeit aus der Dose.","Fügen Sie eine Prise Salz, und die Ketchup, versuchen, den gesamten Bereich zu decken.","Die Folie vorsichtig mit dem Auflauf aus der Schüssel entfernen. Den Käse auffüllen und 30 Minuten in einem vorgeheizten 205 °C (205C) Ofen backen."],"x":[],"desc":"Cazuela Gallega ist ein köstliches Ei, Schinken und Käse Auflauf, gut zum Frühstück oder Abendessen.","img":"Cazuela_Gallega.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Cazuela_Gallega_(Egg,_Ham,_and_Cheese_Casserole)","i":"wb-en-1199","im":["8/8f/Cazuela_Gallega.jpg/960px-Cazuela_Gallega.jpg","Lgvanegas at English Wikibooks","Public domain","Cazuela Gallega.jpg","r"],"on":"Cazuela Gallega (Egg, Ham, and Cheese Casserole)","og":["2 eggs","2 slices of ham","2 tablespoons of petit pois (canned peas)","2 tablespoons of ketchup","1 tablespoon of butter","½ cup of ground Parmesan cheese","Salt"],"mt":1},{"n":"Pintobohnen aus Zentraltexas","c":"beilagen","k":"","p":10,"t":0,"d":1,"v":0,"l":"en","g":["450 g getrocknete Pintobohnen","8 Tassen Wasser","1 TL gemahlener schwarzer Pfeffer","1 EL Salz","1 Schinkenknochen oder etwa die gleiche Menge Salzspeck","1–2 Lorbeerblätter","5 Tassen Wasser","ein kleiner Schluck Kaffee vom selben Tag (90 g) (optional)"],"s":["Bohnen sorgfältig waschen und über Nacht in 8 Tassen Wasser einweichen.","Abtropfen und mit 5 Tassen Wasser nachfüllen.","Alle anderen Zutaten zugeben.","Zum Kochen bringen und mindestens 1 Stunde köcheln lassen, oder bis zart.","Lorbeerblätter entfernen.","Nicht vor dem Servieren abtropfen lassen, ist die Flüssigkeit ein wichtiger Aspekt der Schüssel.","Kann mit Schlitzlöffel serviert werden, um das Entleeren zu ermöglichen, oder mit einer Pfanne in kleine Seitenschalen"],"x":["Die Bohnen und die Flüssigkeit können zum Trocknen aufgelegt werden, gelagertes Maisbrot (das sonst außergewöhnlich trocken sein kann, um zu essen). Die Kombination ist sehr traditionell."],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Central_Texan_Pinto_Beans","i":"wb-en-1200","on":"Central Texan Pinto Beans","og":["1 lb (450 g) dry pinto beans","8 cups water","1 tsp ground black pepper","1 tbsp salt","1 ham bone or a rough equivalent of salt bacon","1–2 bay leaves","5 cups water","A very small amount (3 oz / ~90 g) of that day's brewed coffee (optional)"],"mt":1},{"n":"Tausendjähriges Ei mit Schinken und Ingwer","c":"welt","k":"China","p":4,"t":0,"d":1,"v":0,"l":"en","g":["4 tausendjährige Eier","80 g Jinhua-Schinken","80 g eingelegter Ingwer","1 kleine Schale dunkler Essig (zum Dippen)"],"s":["Jahrhundert Eier sauber waschen.","Eier schälen und in 4 Scheiben schneiden. Den eingelegten Ingwer in dünne Scheiben schneiden.","Den Jinhua-Schinken in dünne Scheiben schneiden. Eine Weile in Wasser einweichen.","Sandwich eine Scheibe Ingwer mit einem Schinken und einem geschnittenen Jahrhundert Ei.","Mit Essig servieren."],"x":[],"desc":"Das Jahrhundert-Ei (auch bekannt als \"Ei\"). Erhaltenes Ei, 1000 Jahre Ei, 100 Jahre Ei, 100 Jahre altes Ei, tausend Jahre altes Ei; Chinesisch: Mit einer Breite von nicht mehr als 2 mm Pinyin: Pídàn oder chinesisch: Mit einer Dicke von mehr als 2 mm Pinyin: Sōnghūadàn) ist eine chinesische Delikatesse, hergestellt durch die Erhaltung von Enten- oder weniger häufig Hühnereiern in einer Mischung aus Kohle und Kalk für","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Century_Egg_with_Ham_and_Ginger","i":"wb-en-1201","on":"Century Egg with Ham and Ginger","og":["4 century eggs","80 g Jinhua ham","80 g pickled stem ginger","1 small bowl of dark vinegar (use for dipping)"],"mt":1},{"n":"Gegrillter Fisch aus dem Tschad","c":"fisch","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["2 EL Pflanzenöl","1 TL Paprikapulver","1 TL gemahlener Ingwer","1 TL gemahlener Knoblauch","1 TL gemahlener Kreuzkümmel","1 TL gemahlener Koriander","Salz","frisch gemahlener schwarzer Pfeffer, nach Geschmack","2 ganzer frischer Fisch (z. B. Tilapia oder Wels), geputzt und entschuppt","Zitronenspalten, zum Servieren"],"s":["Vorheizen Sie Ihren Grill oder Grill zu mittlerer Hitze.","Kombinieren Sie in einer Schüssel das Pflanzenöl, Paprika, Ingwer, Knoblauch, Kreuzkümmel, Koriander, Salz und schwarzen Pfeffer. Gut vermischen, um eine glatte Marinade zu bilden.","Dab trocken mit Papiertüchern die Fische mit Papiertüchern und legen Sie sie auf einen Teller oder Tablett. Mit einer Bürste, beide Seiten des Fisches großzügig mit der Marinade beschichten. Achten Sie darauf, die Fische gründlich für maximale Geschmack zu decken.","Auf Wunsch können Sie die Fische ca. 30 Minuten im Kühlschrank marinieren lassen, damit die Aromen eindringen können. Allerdings ist dieser Schritt optional, und Sie können direkt zum Grillen gehen, wenn Sie nicht rechtzeitig sind.","Sobald der Grill erwärmt wird, ölen Sie die Gitter leicht, um das Kleben zu verhindern. Sie verwenden ein gefaltetes Papiertuch, das in Pflanzenöl eingeweicht und mit Zangen gehalten wird.","Legen Sie die marinierten Fische vorsichtig auf den Grill und schließen Sie den Deckel. Je nach Fischdicke ca. 4–5 Minuten pro Seite kochen, oder bis das Fleisch undurchsichtig ist und mit einer Gabel leicht flickt.","Beim Grillen können Sie die Fische mit jeder verbleibenden Marinade basteln, indem Sie eine Bürste für zusätzlichen Geschmack und Feuchtigkeit verwenden.","Sobald der Fisch durchgekocht und schön verkohlt wird, mit Zangen oder einem Spatel vom Grill entfernen. Achten Sie darauf, das zarte Fleisch nicht zu brechen.","Servieren Sie heiß mit Zitronenkeile an der Seite zum Drücken über den Fisch. Es paart sich gut mit einer Seite von Reis oder Hirse und kann von einem frischen Salat oder gedämpftem Gemüse begleitet werden."],"x":["Die Kochzeiten können je nach Größe und Dicke des Fisches sowie der Hitze Ihres Grills variieren. Passen Sie entsprechend an, um sicherzustellen, dass die Fische auf Ihre gewünschte Fertigkeit gekocht werden.","Wenn gewünscht, können Sie die Fische auf ein Blatt Aluminiumfolie auf dem Grill platzieren, um einen direkten Kontakt mit den Gittern zu verhindern und leichteres Umdrehen zu erleichtern."],"desc":"Chadian gegrillter Fisch ist ein beliebtes Gericht im Tschad bekannt für seine Einfachheit und Geschmack. Frischer Fisch wird mit lokalen Gewürzen mariniert, dann bis zur Perfektion gegrillt, was zu einer köstlichen und aromatischen Mahlzeit führt. Es wird oft mit einer Seite von Reis oder Hirse für eine vollständige und befriedigende Erfahrung serviert.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Chadian_Gilled_Fish","i":"wb-en-1202","on":"Chadian Gilled Fish","og":["2 tablespoons vegetable oil","1 teaspoon ground paprika","1 teaspoon ground ginger","1 teaspoon ground garlic","1 teaspoon ground cumin","1 teaspoon ground coriander","Salt","Freshly ground black pepper, to taste","2 whole fresh fish (such as tilapia or catfish), cleaned and scaled","Lemon wedges, for serving"],"mt":1},{"n":"Tschadischer Salat","c":"salate","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["2 Tomaten, gewürfelt","1 Gurke, gewürfelt","1 rote Zwiebel, in dünne Scheiben geschnitten","1 Paprikaschote (beliebige Farbe), gewürfelt","1 Möhre, geschält und gerieben","1 Zitrone, ausgepresst","2 EL Olivenöl","Salz, nach Geschmack","Pfeffer, nach Geschmack","frische Petersilie oder Minzblätter, gehackt (optional, zum Garnieren)"],"s":["Tomaten, Gurken, Paprika, rote Zwiebeln und Karotten in einer Schüssel mischen.","In einer separaten kleinen Schüssel den Zitronensaft, Olivenöl, Salz und Pfeffer zu einem Dressing zusammenrühren. Passen Sie die Würze nach Ihrem Geschmack an.","Gießen Sie das Dressing über das Gemüse in die Mischschüssel. Werfen Sie vorsichtig den Salat, um sicherzustellen, dass alle Gemüse mit dem Dressing überzogen sind.","Die Schüssel mit Plastikfolie oder Deckel bedecken und den Salat mindestens 30 Minuten im Kühlschrank marinieren lassen. Dies ermöglicht es den Aromen zu mischen und verbessert den Geschmack.","Den Salat aus dem Kühlschrank nehmen. Geben Sie ihm einen letzten Wurf, um die Aromen zu mischen, und übertragen Sie es auf ein Serviergericht. Auf Wunsch zerkleinerte Petersilie oder Minzeblätter als Garnierung darüber streuen.","Genießen Sie als eigenständiges Gericht oder als Nebensalat neben gegrilltem Fleisch, Fisch oder anderen Hauptgerichten."],"x":["Fühlen Sie sich frei, um den Salat durch Hinzufügen oder ersetzen Gemüse nach Ihren Vorlieben und Verfügbarkeit anpassen. Sie können auch einen Hauch von Wärme hinzufügen, indem Sie gehackte Chili-Pfeffer oder eine Prise Paprika einschließen."],"desc":"Chadischer Salat ist ein bunter und würziger Salat, der frisches Gemüse mit einem leckeren Dressing kombiniert. Es ist ein gesundes und erfrischendes Gericht, ideal für heiße Sommertage oder als Beilage zu gegrilltem Fleisch oder Fisch begleiten.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Chadian_Salad","i":"wb-en-1203","on":"Chadian Salad","og":["2 tomatoes, diced","1 cucumber, diced","1 red onion, thinly sliced","1 bell pepper (any color), diced","1 carrot, peeled and grated","1 lemon, juiced","2 tablespoons olive oil","Salt to taste","Pepper to taste","Fresh parsley or mint leaves, chopped (optional, for garnish)"],"mt":1},{"n":"Chakalaka (südafrikanisches Gemüseragout)","c":"suppen","k":"Südafrika","p":4,"t":40,"d":2,"v":1,"l":"en","g":["1 EL Öl, oder nach Bedarf","3 mittelgroße Zwiebeln, gewürfelt","1 TL Currypulver, oder nach Geschmack","1 TL Chilipulver","2 kleine grüne Thai-Chilis, gehackt","3 mittelgroße Möhren, gewürfelt","3 mittelgroße Tomaten, gewürfelt","2 mittelgroße grüne Paprika, gewürfelt","¼ Tasse Wasser","1 Gemüsebrühwürfel, zerbröselt","Salz und gemahlener schwarzer Pfeffer, nach Geschmack"],"s":["Öl in einem großen Topf bei mittlerer Hitze erhitzen.","Die gehackten Zwiebeln dazugeben und 2–3 Minuten anbraten, bis sie weich sind.","Das Currypulver, das Chilipulver und die gehackten Chilischoten einrühren. 1 Minute kochen, bis er duftet.","Die gehackten Tomaten, die geriebenen Karotten und die gewürfelten Paprika hinzufügen. Rühren Sie gut um.","Den zerbröckelten Bouillonwürfel und Wasser dazugeben. 10–15 Minuten köcheln lassen, bis das Gemüse zart ist.","Die gebackenen Bohnen einrühren und weitere 3–5 Minuten kochen, aufgedeckt, bis die Mischung verdickt ist.","Mit Salz und Pfeffer würzen."],"x":["Chakalaka kann vor der Zeit gemacht werden und schmeckt am nächsten Tag noch besser.","Geriebener Kohl oder grüne Bohnen können für zusätzliche Vielfalt hinzugefügt werden.","Es kann heiß oder kalt serviert werden, je nach Vorliebe."],"desc":"Chakalaka ist ein würziges südafrikanisches Gemüse aus Bohnen, Paprika, Karotten und Tomaten. Es wird oft als Beilage mit Brot, pap (Maisbrei) oder Fleisch serviert. Chakalaka ist vielseitig und kann mit verschiedenen Gemüse und Gewürzen je nach regionalem oder persönlichem Wunsch angepasst werden","img":"Chakalaka.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Chakalaka_(South_African_Vegetable_Stew)","i":"wb-en-1204","im":["d/d0/Chakalaka.jpg/960px-Chakalaka.jpg","philipp from cape town, south africa","CC BY 2.0","Chakalaka.jpg","r"],"on":"Chakalaka (South African Vegetable Stew)","og":["1 tablespoon oil, or as needed","3 medium onions, diced","1 teaspoon curry powder, or to taste","1 teaspoon chile powder","2 small Thai green chiles, chopped","3 medium carrots, diced","3 medium tomatoes, diced","2 medium green bell peppers, diced","¼ cup water","1 cube vegetable bouillon, crumbled","Salt and ground black pepper to taste"],"mt":1},{"n":"Chakkarai Pongal (süßer Reis-Linsen-Pudding)","c":"dessert","k":"Indien","p":8,"t":0,"d":1,"v":1,"l":"en","g":["½ Tasse weißer Reis","½ Tasse Moong Dal (gelbe Linsen)","4 Tassen Wasser","¼ Tasse gehackte Cashewkerne","¼ Tasse helle Rosinen","1 EL gemahlener Kardamom","1 Tasse Ghee (oder Butter)","¾ Tasse Jaggery (Rohrohrzucker)","¼ Tasse Milch"],"s":["Den Reis kochen und zusammen mit Wasserbechern in einem Topf oder einem Schnellkochtopf den Dhal kochen.","In der Zwischenzeit die Jaggery mit 1 Tasse Wasser in einer Pfanne schmelzen.","Fügen Sie die Kardamom auf die Jaggery, wie es schmilzt.","Den Reis und die Paruppu (Dal) Mischung gut mischen und in die Pfanne der Jaggery hinzufügen.","Gut umrühren und bei geringer Hitze kochen, bis die Mischung gut zusammenkommt.","4 Esslöffel der Ghee in einer separaten Pfanne erhitzen und Cashews goldbraun anbraten.","Rosinen hinzufügen und noch ein paar Sekunden braten, bis sie anschwellen.","Die Nüsse und Rosinen in den Pongal geben.","Heiß servieren mit einem zusätzlichen Dollop von neyyi oder Ghee."],"x":[],"desc":"Chakarai Pongal ist ein süßes und butteriges Brei-ähnliches Gericht, das traditionell in Südindien für das Makar Sankranti Festival zubereitet wird, das die Ankunft des Sommers ankündigt. Die khara pongal Sorte unterscheidet sich nur in den Gewürzen hinzugefügt, und die beiden werden oft zusammen aus der gleichen Partie Reis gekocht und","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Chakarai_Pongal_(Sweet_Rice_and_Black_Gram_Pudding)","i":"wb-en-1205","im":["2/21/Ven_pongal_with_sambar_and_chutney.jpg/960px-Ven_pongal_with_sambar_and_chutney.jpg","Shafana jasmine","CC BY-SA 4.0","Ven pongal with sambar and chutney.jpg","w"],"on":"Chakarai Pongal (Sweet Rice and Black Gram Pudding)","og":["½ cup white rice","½ cup moong dhal","4 cups water","¼ cup chopped cashew nuts","¼ cup white raisins","1 tablespoon cardamom powder","1 cup ghee (or butter)","¾ cup jaggery","¼ cup milk"],"mt":1},{"n":"Chalupa","c":"salate","k":"Mexiko","p":4,"t":0,"d":1,"v":0,"l":"en","g":["Pflanzenöl","12 Maistortillas","6 Tassen Refried Beans (Bohnenmus) (ersatzweise Pinto- oder schwarze Bohnen)","230 g geriebener Queso fresco","gehackte Zwiebel","1 große Tomate, gehackt","3 Tassen Eisbergsalat in Streifen"],"s":["In einer kleinen Pfanne ca. 1⁄2 Zoll Pflanzenöl erhitzen. Testen Sie das Öl auf die richtige Temperatur, indem Sie ein kleines Stück Tortilla. Wenn das Öl sofort hektisch bläst und das Brot schnell knusprig wird, dann ist das Öl bei der richtigen Temperatur.","Dies ist wichtig, weil eine niedrige Temperatur eine unangenehm ölige und soggy Chalupa Schale produzieren wird.","Die Tortilla ganz flach im Öl anbraten, auf beiden Seiten, bis sehr knusprig. Abtropfen und die gebratene Tortilla auf einem Zeitungs- oder Papiertuch bezogenen Backblech in einem warmen Ofen warm halten. Auf jeder gebratenen Tortilla eine Schicht refriedierter Bohnen verteilen, ca. 1⁄4 Zoll dick.","Top mit einer großzügigen Menge an geriebenem Cheddar-Käse und ca. 1 Esslöffel gehackte Zwiebel.","Legen Sie die zusammengebauten Chalupas auf ein Backblech und braun unter Broiler, bis der Käse schmilzt und beginnt zu blasen. Beobachten Sie sie vorsichtig in diesem Stadium, da sie ziemlich schnell brennen können.","Oben mit geschreddertem Salat und Tomaten, und servieren Sie sofort."],"x":[],"desc":"Ein Chalupa ist eine Art Tostada-Platte in der mexikanischen Küche. Es ist eine Spezialität der südlichen Zentralregionen Mexikos, wie die Bundesstaaten Guerrero und Oaxaca. Es wird durch Drücken einer dünnen Schicht Masa Teig um die Außenseite einer kleinen Form gemacht und dann tief braten, um eine knackige flache Maisbecher produzieren","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Chalupa","i":"wb-en-1206","im":["b/b1/Chalupas_%28food%29.jpg/960px-Chalupas_%28food%29.jpg","alex lines","CC BY-SA 2.0","Chalupas (food).jpg","w"],"og":["Vegetable oil","12 corn tortillas","6 cups refried beans (pinto beans or black beans may be substituted)","½ pound grated queso fresco cheese","Chopped onion","1 large tomato, chopped","3 cups shredded lettuce"],"mt":1},{"n":"Champ (irisches Kartoffelpüree mit Frühlingszwiebeln)","c":"beilagen","k":"","p":2,"t":0,"d":1,"v":1,"l":"en","g":["450 g Kartoffeln, geschält","60 g Frühlingszwiebeln","120 ml Milch","frisch gemahlener Pfeffer","Salz (optional)","4 EL Butter"],"s":["Kartoffeln in Wasser kochen, bis fertig.","Die Kartoffeln abtropfen lassen und zerkleinern.","Die Milch in einen Topf geben, die gehackten Jakobsmuscheln dazugeben und kräftig kochen.","Nach dem Kochen die Jakobsmuscheln absieben und die Milch beiseite stellen.","Die Jakobsmuscheln zu den Kartoffeln geben und gut vermischen.","Fügen Sie so viel Milch wie möglich zu, um eine „feuchte\" weiche Mischung herzustellen.","Mit frisch gemahlenem Pfeffer und Salz abschmecken.","Mit einem zentralen Brunnen mit geschmolzener Butter servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Champ_(Irish_Mashed_Potato_with_Scallion)","i":"wb-en-1207","im":["5/51/Sous_vide_mashed_potatoes.jpg/960px-Sous_vide_mashed_potatoes.jpg","sousvideguy","CC BY 2.0","Sous vide mashed potatoes.jpg","w"],"on":"Champ (Irish Mashed Potato with Scallion)","og":["1 lb (450 g) potatoes, peeled","2 oz (60 g) scallions","¼ pint (½ cup) milk","Freshly-ground pepper","Salt (optional)","4 tbsp butter"],"mt":1},{"n":"Champagner-Vinaigrette","c":"saucen","k":"Frankreich","p":3,"t":35,"d":1,"v":1,"l":"en","g":["1 Knoblauchzehe","1 Tasse Champagneressig","½ TL frisch gemahlener schwarzer Pfeffer","1 Prise Salz","2 TL Dijonsenf","2 Tassen natives Olivenöl extra"],"s":["Knoblauchzehe mit der Seite der Klinge eines Kochmessers oder anderen flachen Gegenstand zerkleinern. Übertragen Sie die Nelke, so dass sie in einem Stück, in eine Mischschüssel.","Essig, Pfeffer und Salz zugeben und 30 Minuten stehen lassen.","Entfernen und den Knoblauch wegwerfen. Im Senf flüstern. Langsam das Öl hinzufügen, ständig keimen, um zu emulgieren."],"x":["Wenn Sie es nicht sofort verwenden, lagern Sie es in einem abgedeckten Behältnis im Kühlschrank. Wischen Sie erneut oder schütteln Sie den Behälter kräftig, um vor dem Servieren wieder zu emulgieren."],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Champagne_Vinaigrette","i":"wb-en-1208","im":["9/98/Vinaigrette_dressing_with_a_chopped_salad.jpg/960px-Vinaigrette_dressing_with_a_chopped_salad.jpg","GrammarFascist","CC BY-SA 4.0","Vinaigrette dressing with a chopped salad.jpg","w"],"on":"Champagne Vinaigrette","og":["1 garlic clove","1 cup champagne vinegar","½ teaspoon freshly ground black pepper","1 pinch salt","2 teaspoons Dijon mustard","2 cups extra virgin olive oil"],"mt":1},{"n":"Champorado (Schoko-Reisbrei)","c":"dessert","k":"Philippinen","p":4,"t":0,"d":2,"v":0,"l":"en","g":["½ kg Klebreis","Wasser (etwa die 4- bis 6-fache Reismenge)","½ kg Zucker","2 Löffel Kakaopulver","1 Dose Kondensmilch (ungesüßt) (340 g)"],"s":["Den Reis zweimal waschen.","Kombinieren Sie Reis und Wasser in einem Topf. Den Topf über die mittlere Hitze stellen, bedecken und zum Kochen bringen.","Den Topf entdecken und den Zucker und das Kakaopulver unterrühren, bis er gut vermischt ist.","Bei geringer Hitze köcheln, regelmäßig umrühren, bis der Reis gekocht und der Brei nach Belieben verdickt ist.","In die verdunstete Milch einrühren und servieren."],"x":["Manchmal schmeckt champorado gut, wenn er mit gesalzenem Fisch gegessen wird."],"desc":"Champorado ist ein Schokoladenbrei und Favorit Filipino Komfort Essen, vor allem bei kaltem Wetter.","img":"Champorado.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Champorado_(Chocolate_Rice_Porridge)","i":"wb-en-1209","im":["9/93/Champorado.jpg/960px-Champorado.jpg","Josh James from Imus, Philippines","CC BY 2.0","Champorado.jpg","r"],"on":"Champorado (Chocolate Rice Porridge)","og":["½ kg glutinous rice","Water (about 4–6 times the rice volume)","½ kg white granulated sugar","2 spoons cocoa powder","1 can (12 oz) evaporated milk"],"mt":1},{"n":"Pfifferlingsgulasch","c":"welt","k":"Österreich","p":4,"t":25,"d":1,"v":0,"l":"en","g":["800 g Pfifferlinge","100 g Zwiebeln","60 g Butter oder Öl","125 g saure Sahne","10 g Paprikapulver","3–4 EL Weißweinessig","1 TL Mehl","1 EL Petersilie","Salz","Pfeffer"],"s":["Die großen Pilze in Hälften schneiden. Alle sollten etwa die gleiche Größe haben, was durchschnittlich 2–3 cm beträgt.","Zwiebeln schälen und fein in kleine Würfel hacken.","Die Butter in einem Topf erhitzen.","Wenn der Topf heiß genug ist, fügen Sie die gehackten Zwiebeln hinzu. Zwiebeln goldbraun kochen.","Fügen Sie die Paprika hinzu. Gut umrühren und sofort mit dem Weißweinessig ablöschen. Es ist wichtig, dass das Paprikapulver nicht zu heiß wird, weil es bei einer bestimmten Temperatur bitter wird.","Die Pfifferlinge in den Topf geben und Pfeffer und Salz nach Geschmack hinzufügen. Legen Sie einen Deckel darauf und dampfen Sie die Mischung für etwa 10-12 Minuten, bis die Chanterellen weich sind.","Entfernen Sie den Deckel und erhöhen die Temperatur, um die entweichende Flüssigkeit der Chanterellen zu erhalten.","Mehl und saure Sahne mischen. Rühren Sie diese Mischung in den Auflauf, reduzieren die Temperatur und kochen für weitere 5 Minuten."],"x":[],"desc":"Gulasch von Chanterelles ist ein typisches österreichisches Hauptgericht. Es wird hauptsächlich im Sommer serviert, was die Pilzsaison in Österreich ist. Obwohl es möglich ist, Pilze einzufrieren, kann der Geschmack von gefrorenen Chanterellen nicht mit dem Geschmack von frischen verglichen werden. Der Gulasch besteht aus Chanterellen,","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Chanterelle_Goulash","i":"wb-en-1210","im":["5/5c/Gulyas080.jpg/960px-Gulyas080.jpg","Lily15","CC BY-SA 3.0","Gulyas080.jpg","w"],"on":"Chanterelle Goulash","og":["800 g chanterelle mushrooms","100 g onions","60 g butter or oil","125 g sour cream","10 g paprika powder","3–4 tbsp white wine vinegar","1 tsp flour","1 tbsp parsley","Salt","Pepper"],"mt":1},{"n":"Chapati","c":"brot","k":"Pakistan","p":8,"t":60,"d":2,"v":2,"l":"en","g":["3 Tassen Weizenvollkornmehl","Salz, nach Geschmack","warmes Wasser, nach Bedarf","Ghee (Butterschmalz, optional)"],"s":["Das Mehl und das Wasser zusammenkneten, beginnend mit nur einem leichten Dribbeln von Wasser und mehr hinzufügen, wie Sie gehen, bis der Teig glatt, aber nicht zu klebrig wird.","Teig abdecken und mindestens 5 Minuten ruhen lassen.","Teig in Kugeln teilen und in Scheiben rollen, etwas dicker als Denimmaterial; Mit Mehl bestreuen, wie Sie rollen.","Legen Sie eine nicht geölte Pfanne über mäßig hohe Hitze und testen Sie ihre Oberflächentemperatur, indem Sie Ihre Hand über sie.","Wenn sehr heiß, setzen Sie eine Chapati auf die Pfanne und drücken Sie sie flach mit einem Spatel oder trockenen Tuch, um es aufstehen zu lassen.","Drehen und wiederholen, so dass es auf beiden Seiten leicht braun wird.","Wenn gewünscht, mit Ghee bürsten."],"x":["Es gibt karibisch-spezifische Variationen von Roti, von denen eine gekochte und gemahlene gelbe Splisserbsen in der Zubereitung verwendet.","Chapatis werden in der Regel mit gekochtem Dal (Lentil Suppe) oder Gemüsegerichten wie indische Curry gegessen. Teile der Chapati werden verwendet, um Bisse der anderen Gerichte zu wickeln und zu heben."],"desc":"Die Chapati, auch als Roti bekannt, ist das Grundbrot von Nordindien und Pakistan. Es kann aus vielen Arten von Getreide hergestellt werden, wird aber am häufigsten mit fein gemahlenem Vollkornmehl hergestellt. Manchmal wird es in ein wenig Öl gekocht.","img":"Baking Chapatis.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Chapati","i":"wb-en-1211","im":["3/3f/Baking_Chapatis.jpg/500px-Baking_Chapatis.jpg","Claude Renault","CC BY 2.0","Baking Chapatis.jpg","r"],"og":["3 cups whole wheat flour","Salt to taste (about 1 teaspoon)","Warm water as required (about 1 ½ cups)","Ghee (clarified butter; optional)"],"mt":1},{"n":"Chapati za Maji (tansanische Pfannkuchen)","c":"kuchen","k":"Tansania","p":4,"t":10,"d":1,"v":0,"l":"en","g":["1 Tasse Milch","2 Eier","½ Tasse Wasser","1 Tasse Weizenmehl","⅓ Tasse weißer Zucker","1 TL Salz","Rapsöl"],"s":["Kombinieren Sie Milch, Eier und Wasser.","Mehl, Zucker und Salz mischen.","Nach und nach die nasse Mischung in die trockene Mischung rühren, bis man einen dünnen Teig bekommt, der dem Crêpe batter ähnlich ist. Wenn es sich zu dick anfühlt, fügen Sie etwas zusätzliches Wasser hinzu.","Den Teig bedecken und 30–60 Minuten ruhen lassen.","Eine Pfanne bei mittlerer Hitze vorheizen.","Die Pfanne mit einer kleinen Menge von Rapsöl schmieren, die Pfanne wirbeln, um die gesamte Oberfläche zu beschichten.","Eine kleine Menge Teig in die Pfanne schütten oder schütten. Die Pfanne sofort in alle Richtungen kippen, um die gesamte Oberfläche mit einem dünnen Teigfilm zu beschichten.","Den Pfannkuchen ca. 1 Minute kochen lassen. Dann heben Sie vorsichtig den Rand mit einem Spachtel, drehen Sie ihn um und kochen für eine weitere Minute. Der Pfannkuchen sollte auf beiden Seiten schwach gebräunt werden.","Entfernen Sie den Pfannkuchen und beiseite stellen.","Wiederholen Sie den Fett- und Bratprozess, bis der Teig verbraucht ist.","Heiß servieren."],"x":["Sie können die Pfannkuchen mit Zimt und Honig bestreuen und sie aufrollen, um sie zu essen."],"desc":"Chapati za maji (wörtlich \"Wasserbrot / Pfannkuchen\") sind dünne tansanische Pfannkuchen, die Crêpes sehr ähnlich sind.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Chapati_Za_Maji_(Tanzanian_Pancakes)","i":"wb-en-1212","on":"Chapati Za Maji (Tanzanian Pancakes)","og":["1 cup milk","2 eggs","½ cup water","1 cup all-purpose flour","⅓ cup white sugar","1 tsp salt","Canola oil"],"mt":1},{"n":"Chapman (nigerianisches Partygetränk)","c":"getraenke","k":"Nigeria","p":4,"t":0,"d":1,"v":0,"l":"en","g":["2 Flaschen Johannisbeer-Getränk (Boom) (6 l)","Wasser","5 Ananas, geschält, entkernt, und gewürfelt","12 Äpfel, entkernt und gewürfelt","10 Wassermelonen, von der Rinde befreit und gewürfelt"],"s":["Das schwarze Johannisbeergetränk in die Schüssel geben. Beim Rühren mit Wasser verdünnen, bis es Ihren gewünschten Geschmack erreicht.","Wenn nicht ausreichend gekühlt, in den Kühlschrank überführen und bis kalt ruhen.","Teilen Sie die gewürfelten Früchte zwischen Servierbechern, dann füllen Sie die Tassen mit dem Getränk und servieren."],"x":[],"desc":"Chapman ist ein süßes alkoholfreies Getränk, das weithin auf Partys und Veranstaltungen in ganz Nigeria serviert wird.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Chapman_(Nigerian_Party_Drink)","i":"wb-en-1213","on":"Chapman (Nigerian Party Drink)","og":["2 bottles (6 liters) Boom blackcurrant beverage","Water","5 pineapples, peeled, cored, and diced","12 apples, cored and diced","10 watermelons, removed from the rind and diced"],"mt":1},{"n":"Char Siu (chinesisches Grillschweinefleisch)","c":"fleisch","k":"China","p":1,"t":490,"d":2,"v":0,"l":"en","g":["1 kg Schweineschulter","2 EL dunkle Sojasoße","2 EL helle Sojasoße","2 EL Austernsoße","2 EL Shaoxing-Reiswein","2 EL flüssiger Honig","4 EL Hoisinsoße","½ TL Fünf-Gewürze-Pulver"],"s":["Das Fleisch in Streifen von etwa 2,5 cm (2,5 cm) breit und 15 cm (15 cm) lang schneiden. Ein langer dünner Streifen wie dieser hält seine Form besser beim Aufhängen.","Durchbohren Sie das Schweinefleisch gründlich mit einer Gabel. Dies macht das Schweinefleisch zarter und ermöglicht es der Marinade, das Fleisch einzudringen, um den ganzen Weg hindurch Geschmack zu verleihen.","Alle anderen Zutaten zu einer Marinade vermischen.","Schweinefleischstreifen in ein Tablett legen und mit Marinade bedecken. Stellen Sie sicher, dass Streifen vollständig in Marinade bedeckt sind.","Bedecken Sie fest mit Festhaltefolie und Platz im Kühlschrank für mehrere Stunden (8–24 Stunden ist vorzuziehen).","Den Backofen auf 230 °C oder 215 °C vorheizen und eine Pfanne in den Boden legen, um Tropfen zu fangen. Diese Pfanne mit Aluminiumfolie reihen, um die Reinigung zu erleichtern.","Hängen Sie das Fleisch an Haken im Ofen oder legen Sie es auf ein Gestell. Abhängig von der Methode und der Größe Ihres Ofens, kann es am einfachsten sein, dies in zwei oder drei Chargen zu tun, anstatt alle auf einmal.","20 Minuten braten, bis das Schweinefleisch den ganzen Weg hindurch gekocht wird. Baste mindestens zweimal, um eine gute Schicht Marinade auf der Außenseite des Fleisches aufzubauen. Das Schweinefleisch sollte eine gold-rote Farbe drehen, während es kocht.","Erlauben Sie zu kühlen, während noch hängen, oder legen Sie auf Draht Rack abkühlen. Vermeiden Sie das Auflegen auf anderes Fleisch oder auf eine flache Oberfläche bis zum Abkühlen.","Bedecken und kühlen, bis nötig."],"x":["Kalt servieren oder in anderen Gerichten gewürfelt verwenden.","1 EL geröstetes Sesamöl für einen nussigeren Geschmack zugeben","Fügen Sie der Marinade rote Lebensmittelfarbe hinzu, um den traditionellen tiefroten Farbton zu verleihen. Früher war dies auf das Konservierungsmittel zurückzuführen, das für das Schweinefleisch verwendet wurde. Auch in China symbolisiert die rote Farbe im Allgemeinen Glück. Aufgrund der starken Farbe der oben beschriebenen Marinade wird jedoch eine erhebliche Menge an Lebensmittelfarbstoffen benötigt.","Dieses Gericht passt sehr gut zu Ingwer und Zwiebel.","Achten Sie darauf, das rohe Schweinefleisch zu behandeln. Hände und Utensilien waschen, die mit rohem Schweinefleisch in Kontakt kommen. Lassen Sie rohes Schweinefleisch oder seine Säfte nicht mit anderen Lebensmitteln in Kontakt kommen, es sei denn, sie werden danach gekocht."],"desc":"Cha Shao ist eine Art gewürztes kantonesisches Honigbratenschwein. Es wird oft auch von den Kantonesen char siu oder char siew genannt. Manchmal (in der Regel in Amerika) wird es chinesisches BBQ Schweinefleisch genannt. Es ist sehr beliebt, und kann von selbst gegessen werden (in der Regel kalt), oder als Zutat für andere Gerichte wie cha","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Char_Siu_(Chinese_BBQ_pork)","i":"wb-en-1214","im":["9/95/Charsiu.jpg/330px-Charsiu.jpg","Simon Shek","CC BY-SA 3.0","Charsiu.jpg","w"],"on":"Char Siu (Chinese BBQ pork)","og":["1 kg (2.25 lbs) pork shoulder","2 tbsp dark soy sauce","2 tbsp light soy sauce","2 tbsp oyster sauce","2 tbsp Shaoxing rice wine","2 tbsp clear honey","4 tbsp hoisin sauce","½ tsp five spice"],"mt":1},{"n":"Char Siu (asiatisches Grillschweinefleisch)","c":"fleisch","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["3 Kati Schweinefleisch (1 Kati ≈ 600 g) (1.8–2 kg) (Sam-chang-bak, Schweinebauch)","5 EL Char-Siu-Soße","5 EL Zucker","Pfeffer","ein paar Tropfen Fleischzartmacher"],"s":["Den Filet auf das Fleisch streuen, dann die restlichen Zutaten mit dem Fleisch vermischen.","Grillen Sie das Fleisch bis fertig."],"x":[],"desc":"BBQ sam-chang-bak ist ein sehr einfaches Grillgewürz Rezept für Schweinefleisch.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Char_Sui_(Asian_Barbecued_Pork)","i":"wb-en-1215","im":["9/95/Charsiu.jpg/330px-Charsiu.jpg","Simon Shek","CC BY-SA 3.0","Charsiu.jpg","w"],"on":"Char Sui (Asian Barbecued Pork)","og":["3 katis (1.8–2 kg / 4 lbs) of pork (sam-chang-bak)","5 tablespoons char-siu sauce","5 tablespoons sugar","Pepper","A few drops of tenderizer"],"mt":1},{"n":"Gegrilltes Hüftsteak mit Cabernet-Buttersoße","c":"saucen","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["#Steak","1 Hüftsteak (Top Sirloin) (auch Mittelstück, Hüfte oder Hip genannt)","Salz","frisch gemahlener schwarzer Pfeffer","Olivenöl","1 EL ungesalzene Butter, in dünne Scheiben geschnitten und auf Zimmertemperatur gebracht","#Cabernet-Buttersoße","½ Tasse Cabernet Sauvignon","1 Schalotte, glatt püriert","3 EL ungesalzene Butter, aufgeteilt"],"s":["Bürsten Sie beide Seiten des Steaks mit Olivenöl und würzen Sie liberal mit Salz und frisch gemahlenem schwarzem Pfeffer. Beiseite legen.","Vorheizen Sie Ihren Broiler. Legen Sie einen Rack in der höchsten Position des Ofens und ein knapp darunter. Legen Sie ein Blatt Aluminiumfolie, die um die Kanten auf der unteren Rack gecrimpt wurde.","Legen Sie das Steak auf den oberen Rack. Stecken Sie ein Sondenthermometer in die Mitte des Steaks und halten Sie die Ofentür mit einem Rohr aus Aluminiumfolie offen.","Kochen bis Kerntemperatur erreicht 60 °C für mittlere seltene, 68 °C für mittlere und 74 °C für Toast (Carry-over dauert es 5 Grad).","Auf eine Platte nehmen, Butter schneiden gleichmäßig oben, und mit Aluminiumfolie bedecken. 10 Minuten ruhen lassen, bevor man in einem 45-Grad-Winkel dünn über das Korn schneidet.","Kombinieren Sie Wein und Schalott in einer mittleren Pfanne bei mittlerer Hitze.","In die Butter rühren, 1 Esslöffel auf einmal, warten, bis das letzte Stück eingearbeitet wurde, bevor Sie das nächste Stück hinzufügen.","Steak warm mit der Cabernet Butter Sauce servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Char-Broiled_Sirloin_Steak_with_Cabernet_Butter_Sauce","i":"wb-en-1216","on":"Char-Broiled Sirloin Steak with Cabernet Butter Sauce","og":["#Steak","1 top sirloin steak (also goes by the name: center cut, top butt, and hip)","Salt","Freshly-ground black pepper","Olive oil","1 Tbsp unsalted butter, sliced thinly and brought to room temperature","#Cabernet butter sauce","½ cup Cabernet Sauvignon wine","1 shallot, puréed until smooth","3 Tbsp unsalted butter, divided"],"mt":1},{"n":"Gegrilltes Strip-Steak","c":"fleisch","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["4 Strip-Steaks vom Rind, 2,5 cm dick","½ TL Salz","1 TL grob gemahlener schwarzer Pfeffer","1 ½ TL getrockneter Rosmarin","2 TL getrockneter Thymian","1 EL geräuchertes Paprikapulver","1 EL Chilipulver","1 EL Knoblauchpulver","natives Olivenöl extra"],"s":["Gewürze kombinieren. Beiseite legen.","Bürste Steaks liberal mit Olivenöl. Reiben Sie jede Seite von Steaks mit Würzmischung. Lassen Sie bei Raumtemperatur für 30–45 Minuten, bevor Sie fortfahren.","Grill für indirekte Heizung vorbereiten, hoch auf der einen Seite, mittel auf der anderen. Fügen Sie Steaks zu hohen Teil des Grills und kochen 1 1⁄4 Minuten. 90 Grad rotieren und weitere 1 1⁄4 Minuten kochen. Drehen und wiederholen Sie noch einmal.","Steaks auf mittlere Hitze bewegen und kochen, oft drehen, bis Kerntemperatur erreicht 60 °C für mittel-rare.","Auf eine Platte nehmen und mit Aluminiumfolie bedecken. Lassen Sie 7-10 Minuten ruhen.","Schneide Steaks dünn über das Getreide auf eine Vorspannung. Warm servieren."],"x":[],"desc":"Diese Steaks, gewürzt mit Gewürzen und Kräutern, sparen Ihnen Geld, dass Sie vielleicht verwendet haben, um in ein Steakhaus zu gehen.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Char-Grilled_Strip_Steak","i":"wb-en-1217","on":"Char-Grilled Strip Steak","og":["4 ea. (24–32 oz) beef strip steaks, 1 inch thick","½ tsp salt","1 tsp coarsely-ground black pepper","1 ½ tsp dried rosemary","2 tsp dried thyme","1 tbsp smoked paprika","1 tbsp chili powder","1 tbsp garlic powder","Extra-virgin olive oil"],"mt":1},{"n":"Salat mit gegrilltem Spargel","c":"veggie","k":"","p":4,"t":0,"d":1,"v":2,"l":"en","g":["1 Bund Spargel (etwa 500 g ganz, 350 g geputzt)","¼ TL Salz","3 EL Öl, aufgeteilt","3 Zehen Knoblauch, fein gehackt oder zerdrückt","3 EL abgetropfte Kapern","4 TL Zitronensaft","1 Dose Kichererbsen (230 g abgetropft)","30 g glatte Petersilie","10 g Minzblätter","100 g Babyspinat"],"s":["Schnappen Sie die Enden des Spargels, dann schnappen Sie die restlichen Stiele in der Hälfte. Spülen Sie sie gut aus.","Wirf den Spargel mit dem Salz und 1 EL Öl.","Eine Antihaft-Pfanne erhitzen oder bei hoher Hitze wok. Wirf in Spargel und Char auf hoch für etwa 5 Minuten. Den Spargel in eine (nicht-plastische) Salatschüssel geben.","2 EL Öl in die Pfanne geben, dann den Knoblauch dazugeben und die Kapern abtropfen lassen und für 2 Minuten anbraten. Dann das Knoblauchöl mit dem Spargel in die Schüssel geben.","Die Kichererbsen abtropfen und ausspülen und zusammen mit dem Zitronensaft in die Schüssel geben. Werfen Sie gut zu kombinieren.","Petersilie und Minze fein hacken, zum Salat hinzufügen und gut zusammenwerfen.","Die Spinatblätter waschen und trocknen, zum Salat hinzufügen und gut werfen."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Chargrilled_Asparagus_Salad","i":"wb-en-1218","on":"Chargrilled Asparagus Salad","og":["1 bundle (about 500 g whole, 350 g trimmed) asparagus","¼ tsp salt","3 tbsp oil, divided","3 cloves garlic, minced or crushed","3 tbsp drained capers","4 tsp lemon juice","1 can (230 g drained) chickpeas","30 g flat parsley","10 g mint leaves","100 g baby spinach leaves"],"mt":1},{"n":"Charosset (aschkenasisch)","c":"welt","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["360 g geschält, entkernt, und gehackte Äpfel (z. B. McIntosh)","180 g fein gehackte Walnüsse","2 EL süßer Rotwein","1 TL Zimt","2 EL Honig"],"s":["Mischen Sie alle Zutaten zusammen und kühlen Sie über Nacht für den besten Geschmack.","Würzung, falls nötig, nach dem Kühlen anpassen.","Servieren Sie mit Matzoh, oder essen Sie einfach mit einem Löffel."],"x":["Für eine Familie seder, verdreifachen Sie dieses Rezept."],"desc":"Ashkenazi-Charoset ist eine Vielzahl von Charoset, die Äpfel und Walnüsse als Basis verwendet, mit Honig für Süße.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Charoset_(Ashkenazi)","i":"wb-en-1219","im":["b/b2/Olve_haroset.jpg/500px-Olve_haroset.jpg","unbekannt","CC BY-SA 3.0","Olve haroset.jpg","w"],"on":"Charoset (Ashkenazi)","og":["1½ cups (360 g) peeled, cored, and chopped apples (e.g. MacIntosh)","¾ cup (180 g) finely-chopped walnuts","2 tbsp sweet red wine","1 tsp cinnamon","2 tbsp honey"],"mt":1},{"n":"Charosset (irakisch)","c":"veggie","k":"Irak","p":4,"t":0,"d":1,"v":2,"l":"en","g":["500 ml irakische Datteln, gehackt und entkernt","Wasser","Salz","125 ml gehackte Walnüsse oder Pistazien"],"s":["Kocht in leicht gesalzenem Wasser, das häufig umrührt wird, bis es eine dicke Paste ist.","In fein gehackten Nüssen vermischen."],"x":["Eine traditionelle Variante wird hergestellt, indem das Fruchtfleisch aus der Paste gezogen wird und ein honigähnlicher Dattelsirup entsteht. Dieses Verfahren verwendet wesentlich mehr Daten und kann mehrere Tage dauern, um genügend Sirup zu produzieren."],"desc":"Irakischer Charoset ist eine getrocknete Frucht und Nusspaste, die während der jüdischen Passahfeier von Juden aus dem Irak serviert wird.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Charoset_(Iraqi)","i":"wb-en-1220","im":["b/b2/Olve_haroset.jpg/500px-Olve_haroset.jpg","unbekannt","CC BY-SA 3.0","Olve haroset.jpg","w"],"on":"Charoset (Iraqi)","og":["500 ml Iraqi dates, chopped and seeded","Water","Salt","125 ml chopped walnuts or pistachios"],"mt":1},{"n":"Charosset (maghrebinisch)","c":"veggie","k":"Afrika","p":4,"t":0,"d":1,"v":2,"l":"en","g":["1 ½ Tassen helle Rosinen","½ Tasse getrocknete Aprikosen oder Pfirsiche, gehackt","2 Orangen, ausgepresst","¼ Tasse gehackte Mandeln","1 TL Zimt","1 TL Ingwer, am besten frisch gerieben","2 EL Honig","2 EL Matzemehl"],"s":["Trockene Früchte in Saft einweichen, bis sie gepflückt sind.","Mash rekonstituierte Früchte mit Mandel und Gewürzen, um eine mörtelartige Textur zu erhalten.","Textur mit Matsoh-Mahlzeit anpassen und bei Bedarf mit Honig versüßen."],"x":[],"desc":"Maghrebi charoset ist eine Vielzahl von Charoset während der jüdischen Feier des Passahs von Juden aus Nordwestafrika serviert. Als Teil des Seders dienen. Die nordwestafrikanische Tradition verwendet bittere Grüns wie endive statt Meerrettich mit dem Charoseth.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Charoset_(Maghrebi)","i":"wb-en-1221","im":["b/b2/Olve_haroset.jpg/500px-Olve_haroset.jpg","unbekannt","CC BY-SA 3.0","Olve haroset.jpg","w"],"on":"Charoset (Maghrebi)","og":["1½ cup white raisins","½ cup dried apricots or dried peaches, chopped","2 oranges, juiced","¼ cup chopped almonds","1 tsp cinnamon","1 tsp ginger, preferably freshly-grated","2 tbsp honey","2 tbsp matsoh meal"],"mt":1},{"n":"Käsechips","c":"brot","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["230 g weiche Margarine","2 Tassen geriebener würziger Cheddar","2 Tassen Mehl","1 TL Salz","¾ TL gemahlener Cayennepfeffer","2 Tassen Puffreis-Frühstücksflocken"],"s":["Backofen auf 150 °C vorheizen.","In einer großen Schüssel die Margarine mit Cheddar vermischen.","Mehl, Salz und Cayennepfeffer in die Schüssel geben.","Getreide einrühren, gründlich mischen.","Gestalten Sie in kleine Kugeln, flach jeder Ball mit einer Gabel. Legen Sie jeden Keks auf ein ungefettetes Backblech.","20 Minuten bei 150 °C backen."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_Crisps","i":"wb-en-1222","im":["2/2f/Arizona_Cheese_Crisp.jpg/960px-Arizona_Cheese_Crisp.jpg","Zekerags","CC BY-SA 3.0","Arizona Cheese Crisp.jpg","w"],"on":"Cheese Crisps","og":["½ pound softened margarine","2 cups grated sharp cheddar","2 cups flour","1 teaspoon salt","¾ teaspoon powdered cayenne pepper","2 cups puffed rice cereal"],"mt":1},{"n":"Käseknödel","c":"beilagen","k":"Österreich","p":4,"t":15,"d":1,"v":0,"l":"en","g":["250 g Weißbrot ohne Rinde, fein gewürfelt","250 ml Milch","2–3 Eier","250 g geriebener Käse (z. B. Pinzgauer Bierkäse, Tiroler Graukäse)","50 g Butter","1 Zwiebel, in dünne Scheiben geschnitten","1 Prise je Salz, Pfeffer, Petersilie, und Kümmel","Mehl"],"s":["Die Eier mit der Milch vermischen.","Das weiße Brot in der Eimischung einweichen. Kneten und dann ruhen lassen.","Zwiebeln mit Butter in einer Pfanne anbraten.","Die gekochten Zwiebeln, Salz, Pfeffer, Petersilie, Kümmel und geriebenen Käse in das weiße Brot geben. Das Mehl dazugeben und die Mischung weitere 10 Minuten ruhen lassen.","Formieren Sie Knödel, die etwa die Größe eines Golfballs haben, dann drücken Sie sie flach (etwa 2–3 cm / 0,8–3 cm dick). Sie zu bilden ist am einfachsten, wenn Ihre Hände leicht nass sind.","Butter oder Öl in einer Pfanne erhitzen und die gepressten Käseknödel hineinlegen. Kochen Sie sie auf der einen Seite und dann die andere bis goldbraun.","Lege die Knödel auf ein Papiertuch, um das überschüssige Fett aufzunehmen.","Die Knödel in einer Rinderbrühe mit Sauerkraut oder einem grünen Salat servieren. Viel Spaß!"],"x":[],"desc":"Käseknödel (kaspressknödel) sind ein typisches österreichisches Gericht, das ursprünglich von Bauern in ganz Österreich gegessen wurde. Brot, Kartoffeln und Mehl wurden für den Teig verwendet. Außerdem wurden Eier, Butter, übrig gebliebenes Fleisch, Speck oder Früchte aus dem Garten verwendet, um sie zu füllen. Tiroler, Südtiroler und Bavar","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_Dumplings","i":"wb-en-1223","im":["4/40/HK_SYP_%E8%A5%BF%E7%87%9F%E7%9B%A4_Sai_Ying_Pun_Kwan_Yick_Building_%E5%90%8D%E6%98%9F%E6%B5%B7%E9%AE%AE%E9%85%92%E5%AE%B6_Star_Seafood_Restaurant_food_%E5%90%9E%E9%BA%B5_Wonton_dim_sum_October_2020_SS2_01.jpg/960px-HK_SYP_%E8%A5%BF%E7%87%9F%E7%9B%A4_Sai_Ying_Pun_Kwan_Yick_Building_%E5%90%8D%E6%98%9F%E6%B5%B7%E9%AE%AE%E9%85%92%E5%AE%B6_Star_Seafood_Restaurant_food_%E5%90%9E%E9%BA%B5_Wonton_dim_sum_October_2020_SS2_01.jpg","Honmustak Chooica","CC BY-SA 4.0","HK SYP 西營盤 Sai Ying Pun Kwan Yick Building 名星海鮮酒家 Star Seafood Restaurant food 吞麵 Wonton dim sum October 2020 SS2 01.jpg","w"],"on":"Cheese Dumplings","og":["250 g (8.8 oz / 1¾ cups) white crustless bread, finely diced","250 ml (8.5 fl oz / 1 cup) milk","2–3 eggs","250 g (8.8 oz / 2½ cups) grated cheese (e.g. Pinzgauer beer cheese, Tyrolean grey cheese )","50 g (1.8 oz) butter","1 onion, thinly-sliced","1 pinch each of salt, pepper, parsley, and caraway seeds","Flour"],"mt":1},{"n":"Käse-Ei-Toast","c":"welt","k":"","p":3,"t":15,"d":1,"v":0,"l":"en","g":["Salz, nach Geschmack","Pfeffer, nach Geschmack","4 Brotscheiben","2 Käsescheiben","2 Eier","Butter, nach Bedarf"],"s":["Eier in einer Schüssel schlagen. Salz und Pfeffer vermischen.","Eine Käsescheibe auf eine Brotscheibe geben und Pfefferpulver darüber streuen. Legen Sie eine weitere Brotscheibe oben auf, dann schneiden Sie das Sandwich in der Hälfte diagonal.","Butter bei mittlerer Hitze in einer Pfanne schmelzen.","Das geschnittene Sandwich in die geschlagene Eimischung eintauchen und in die Pfanne geben. Backen Sie das Sandwich braten, drehen Teil, bis goldbraun auf beiden Seiten.","Servieren Sie sofort."],"x":[],"desc":"","img":"Cheese egg toast.jpg","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_Egg_Toast","i":"wb-en-1224","im":["9/92/Cheese_egg_toast.jpg/960px-Cheese_egg_toast.jpg","AnkitaS","CC BY-SA 3.0","Cheese egg toast.jpg","r"],"on":"Cheese Egg Toast","og":["Salt to taste","Pepper to taste","4 bread slices","2 cheese slices","2 eggs","Butter, as needed"],"mt":1},{"n":"Käse-Enchilada","c":"welt","k":"Mexiko & USA","p":5,"t":0,"d":1,"v":0,"l":"en","g":["3 EL Mehl","3 EL Chilipulver","3 EL Pflanzenöl","3 Tassen Wasser","680 g geriebener Cheddar","1 große Zwiebel, gehackt","etwa 20 Maistortillas"],"s":["Backofen auf 175 °C vorheizen.","Chilipulver und Mehl in Öl in einer 10–30 cm (25–30 cm) Pfanne bis emulgiert braten. Wasser dazugeben, zum Kochen bringen und dann ca. 5 Minuten rühren, bis es leicht verdickt ist. Die Hitze wird zu niedrig.","Eine Tortilla in der Chilisoße einweichen, bis sie erweicht ist (20–30 Sekunden). Tortilla aus der Soße entfernen, flach auf den Teller legen und ~1 EL Käse und ~1 EL Zwiebel zur Mitte der Tortilla hinzufügen.","Rollen Sie es auf, und legen Sie mit Kanten nach unten in einer 23 x 30 cm (23 x 30 cm) Backform. Wiederhole das, bis du alle Tortillas benutzt hast. Wenn Sie die Soße am Ende niedrig bekommen, rühren Sie in 1⁄4–1⁄4 Tasse Wasser.","Die Enchiladas mit dem restlichen Käse, Zwiebeln und Chilisoße bedecken.","Im Ofen ca. 5 Minuten backen – länger wird der Käse härten.","Heiß servieren."],"x":["Diese frieren gut ein, entfrosten aber vor der Wiedererwärmung vollständig.","In der Tex-Mex Küche werden diese oft mit mexikanischem Reis, Pintobohnen und Guacamole Salat serviert."],"desc":"Dieses Käse Enchilada Rezept wurde von der Großmutter und Mutter des ursprünglichen Mitwirkenden überreicht.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_Enchilada","i":"wb-en-1225","im":["e/ec/Enchilada_Rice_Beans.jpg/960px-Enchilada_Rice_Beans.jpg","Jon Sullivan","Public domain","Enchilada Rice Beans.jpg","w"],"on":"Cheese Enchilada","og":["3 tbsp flour","3 tbsp chili powder","3 tbsp vegetable oil","3 cups water","1½ pounds (680 g) grated cheddar cheese","1 large onion, chopped","~20 corn tortillas"],"mt":1},{"n":"Käsefüllung für Peynirli Börek","c":"welt","k":"Türkei","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 Tasse Hüttenkäse","1 Tasse Feta, zerbröselt","1 Ei, verquirlt","1 EL Petersilie oder Dill, gehackt","¼ TL Pfeffer"],"s":["Mischen Sie die Feta in den Hüttenkäse, indem Sie zusammen mit einer Gabel maschen.","Das geschlagene Ei, die gehackten Kräuter und den Pfeffer zugeben und rühren, bis es einfach gemischt ist.","In einen kunststoffbeschichteten Behälter geben und bis zum Gebrauch im Kühlschrank lagern.","Siehe Börek Rezept für weitere Anweisungen."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_Filling_for_Peynirli_Börek","i":"wb-en-1226","im":["1/13/Burek_trokut_1.png/500px-Burek_trokut_1.png","unbekannt","CC BY-SA 2.5","Burek trokut 1.png","w"],"on":"Cheese Filling for Peynirli Börek","og":["1 cup cottage cheese","1 cup feta, crumbled","1 egg, beaten","1 Tbsp parsley or dill, chopped","¼ tsp pepper"],"mt":1},{"n":"Käseomelett","c":"fruehstueck","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["2 Eier, zimmerwarm und verquirlt","1 Prise feines Salz","1 Tasse geriebener Monterey Jack, zimmerwarm","½ Tasse geriebener Mozzarella, zimmerwarm","¼ Tasse geriebener milder Cheddar, zimmerwarm","2 ½ Scheiben Pepper Jack (Käse mit Chili), extrem fein gewürfelt und zimmerwarm","Butter"],"s":["Erhitzen Sie eine kleine Antihaft Pfanne über mittlere hohe Hitze, bis Butter Blasen schön, wenn Sie es herumwirbeln.","Wenn Sie die Butter nicht schon um die Pfanne gewirbelt haben, tun Sie das jetzt. Eier und Salz in die Pfanne geben und auf der Seite schön bräunen.","Bestreuen Sie Käse über die Hälfte der ungekochten Seite der Eier. Falten Sie die Eier in der Hälfte, dann kochen, bis Käse geschmolzen und erhitzt wurde. Servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_Omelette","i":"wb-en-1227","im":["b/b1/FoodOmelete.jpg/960px-FoodOmelete.jpg","Renee Comet (photographer)","Public domain","FoodOmelete.jpg","w"],"on":"Cheese Omelette","og":["2 eggs, room temperature and beaten","1 pinch of fine-grain salt","1 cup grated Monterey Jack cheese, room temperature","½ cup grated mozzarella cheese, room temperature","¼ cup grated mild Cheddar cheese, room temperature","2 ½ slices pepper jack cheese, diced extremely fine and at room temperature","Butter"],"mt":1},{"n":"Käsefüllung für Piroggen","c":"veggie","k":"Polen","p":4,"t":0,"d":1,"v":1,"l":"en","g":["230 g Bauernkäse (Farmer's Cheese) (ein weicher, kein harter Käse)","115 g Frischkäse","1 Ei","2 EL Mehl"],"s":["Mischen Sie alle Zutaten bis gut gemischt."],"x":["Farmer's Käse ist ähnlich wie ein trocken-curd Hüttenkäse und ist außerhalb überwiegend osteuropäischen und jüdischen Gebieten nicht verfügbar. Trockenkäse ist eine Subpar-Ersetzung und muss von allen überschüssigen Flüssigkeiten entleert werden, wenn sie verwendet werden soll.","Wenn der Bauernkäse unversalzen ist, 1 TL Salz hinzufügen."],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_Pierogi_Filling","i":"wb-en-1228","on":"Cheese Pierogi Filling","og":["8 oz farmer's cheese (a soft, NOT a hard cheese)","4 oz cream cheese","1 egg","2 tbsp flour"],"mt":1},{"n":"Käsebällchen (Pão de Queijo)","c":"brot","k":"Brasilien","p":20,"t":0,"d":2,"v":0,"l":"en","g":["160 ml Milch","80 ml neutrales Öl (z. B. Pflanzenöl)","450 g feines Maniok- oder Tapiokamehl","170 g geriebener Hartkäse (eine Mischung aus Cheddar und Parmesan passt gut)","2 Eier","Salz, nach Geschmack","Pfeffer, nach Geschmack"],"s":["Milch und Öl in einem Topf vermischen und kochen, bis ein weißer Schaum erscheint.","Diesem heißen Gemisch nach und nach Mehl hinzufügen; Gut vermischen, um einen festen Teig ohne Klumpen zu bilden.","Den Teig 15 Minuten ruhen lassen.","Den Backofen auf 190 °C vorheizen.","Eier, Käse, Salz und Pfeffer in den Teig mischen. Der Teig wird klebrig und nass. Wenn der Teig zu nass ist, fügen Sie mehr Mehl und Käse hinzu, um festere Kugeln (statt Kekse) zu machen.","Fetten Sie Ihre Hände und bilden kleine Kugeln 1–5 cm im Durchmesser.","Die Kugeln auf ein gefettetes Backblech legen. 15–20 Minuten backen, bis die Spitze braun wird.","Etwas cool."],"x":["Stellen Sie sicher, dass Sie ein feines Mehl verwenden, und nicht die gröbere Art von Mehl verwendet, um Farofa zu machen. Dieses Rezept sollte kleine kitschige Brötchen produzieren, so dass eine feinere Mehl Konsistenz erforderlich ist.","Ein Eierersatz wie Egg Beaters ist in Ordnung."],"desc":"Pães de queijo sind brasilianische Käsepuffs aus Tapioka. Sie sind ähnlich wie Gougères und werden typischerweise zum Frühstück oder als Snack serviert.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_Puffs_(Pão_de_Queijo)","i":"wb-en-1229","im":["2/20/Cheesebread.jpg/960px-Cheesebread.jpg","Murilo manzini","CC BY-SA 4.0","Cheesebread.jpg","w"],"on":"Cheese Puffs (Pão de Queijo)","og":["⅔ cup (160 ml) milk","⅓ cup (80 ml) neutral oil (e.g. vegetable oil)","2 cups (450 g) fine cassava flour or tapioca flour","6 ounces (170 g) grated hard cheese (a mix of cheddar and parmesan is good)","2 eggs","Salt to taste","Pepper to taste"],"mt":1},{"n":"Käsefüllung für Ravioli","c":"welt","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 ½ Tassen Ricotta oder Hüttenkäse","¾ Tasse frisch geriebener Parmigiano Reggiano","2 TL fein gehackte Zwiebel","1 Ei","1 ½ TL Salz"],"s":["In einer Schüssel alle Zutaten zusammenrühren.","Stellen Sie beiseite, während Sie den Teig rollen."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_Ravioli_Filling","i":"wb-en-1230","im":["9/95/Flickr_-_cyclonebill_-_Ravioli_med_skinke_og_asparges_i_mascarponecreme.jpg/960px-Flickr_-_cyclonebill_-_Ravioli_med_skinke_og_asparges_i_mascarponecreme.jpg","cyclonebill","CC BY-SA 2.0","Flickr - cyclonebill - Ravioli med skinke og asparges i mascarponecreme.jpg","w"],"on":"Cheese Ravioli Filling","og":["1½ cups ricotta or cottage cheese","¾ cup freshly-grated Parmigiano Reggiano","2 tsp finely-chopped onion","1 egg","1½ tsp salt"],"mt":1},{"n":"Käsesoße I","c":"saucen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["2 ½ EL Butter","1 ½ EL Mehl","1 Tasse Schlagsahne oder ½ Tasse Vollmilch, heiß","1 Tasse Frischkäse","½ Tasse geriebener Cheddar","⅓ Tasse geriebener Mozzarella","½ TL Senf (optional)","1 ½–2 Prisen Salz"],"s":["Die Butter in einem Topf schmelzen. Mehl dazugeben und bei mittlerer Hitze 2–3 Minuten lang zusammenbeißen, um einen weißen Roux zu machen. Nicht braun lassen. Von der Hitze entfernen und fast auf Raumtemperatur abkühlen lassen.","Nach und nach heiße schwere Schlagsahne in den Roux geben, whisking zu kombinieren. Dies wird auch mit einem heißen Roux und Raumtemperatur schwere Sahne oder Milch arbeiten.","Fügen Sie das Salz, Käse und Senf, dann Hitze, bis nur köcheln und Käse geschmolzen ist."],"x":["Wenn gewünscht, können Sie die Sauce zum Kochen bringen; Sobald die Käsesauce zum Kochen gekommen ist, senken Sie die Hitze zu niedrig und sehr langsam köcheln für etwa 45 Minuten. Rühren Sie es so oft, um zu vermeiden, an der Unterseite (ein Schneebesen ist hier angebracht).","Lassen Sie die Sauce nicht braun.","Je länger die Sauce köchelt, desto glatter wird sie durch das Kochen und Anschwellen der Stärkekörner."],"desc":"Käsesauce ist eine Variante der Béchamel Sauce.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_Sauce_I","i":"wb-en-1231","im":["3/32/Broccoli_with_cheese_sauce%2C_Holiday_Restaurant%2C_Semarang%2C_2014-06-19.jpg/960px-Broccoli_with_cheese_sauce%2C_Holiday_Restaurant%2C_Semarang%2C_2014-06-19.jpg","Crisco 1492","CC BY-SA 3.0","Broccoli with cheese sauce, Holiday Restaurant, Semarang, 2014-06-19.jpg","w"],"on":"Cheese Sauce I","og":["2½ tablespoons butter","1½ tablespoons flour","1 cup heavy whipping cream or ½ cup whole milk, hot","1 cup cream cheese","½ cup grated cheddar cheese","⅓ cup grated mozzarella cheese","½ teaspoon mustard (optional)","1½–2 pinches of salt"],"mt":1},{"n":"Käsespätzle","c":"welt","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["Butter","Zwiebeln, gewürfelt","Spätzle, in Salzwasser gekocht","Emmentaler oder Gruyère"],"s":["Langsam gewürfelte Zwiebeln mit Butter braten. Wenn die Zwiebeln gebräunt sind, entfernen Sie sie aus der Pfanne.","Die Spaetzle bei geringer Hitze in Butter braten.","Den Käse über den Bratspreiz braten und gut werfen.","Die Zwiebeln zum Spaetzle und Käse geben und gut werfen.","Mit einem grünen Salat servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_Spaetzle","i":"wb-en-1232","im":["2/28/Sp%C3%A4tzle-02.jpg/960px-Sp%C3%A4tzle-02.jpg","Kobako","CC BY-SA 2.5","Spätzle-02.jpg","w"],"on":"Cheese Spaetzle","og":["Butter","Onions, diced","Spaetzle, boiled in salted water","Emmental or Gruyère cheese"],"mt":1},{"n":"Käseaufstrich auf Baguette","c":"brot","k":"","p":8,"t":240,"d":1,"v":0,"l":"en","g":["½ EL Dijonsenf","1 EL Butter, zimmerwarm","2 TL getrockneter Salbei","¼ Tasse Apfelsaft","2 Tassen geriebener würziger Cheddar","½ TL Pfeffer","230 g Packung Frischkäse, weich","1 Baguette, in kleine Scheiben geschnitten"],"s":["In einer großen Schüssel Senf, Butter und Salbei vermischen.","Apfelsaft, Cheddar-Käse und Pfeffer dazugeben, dann gut umrühren.","Den Frischkäse dazugeben, gut mischen.","Bedecken und im Kühlschrank für 3 Stunden.","Wenn bereit zum Servieren, entfernen Sie aus dem Kühlschrank und lassen zu stehen für 1⁄2 Stunde.","Auf Brot verteilen und mit Milch servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_Spread_on_French_Bread","i":"wb-en-1233","im":["b/bf/Eru_goudkuipje_sambal_%28cropped%29.jpg/960px-Eru_goudkuipje_sambal_%28cropped%29.jpg","Takeaway","CC BY 3.0","Eru goudkuipje sambal (cropped).jpg","w"],"on":"Cheese Spread on French Bread","og":["½ tbsp Dijon mustard","1 tbsp butter, room temperature","2 tsp dried sage","¼ cup apple juice","2 cups shredded sharp cheddar cheese","½ tsp pepper","8 oz package cream cheese, softened","1 loaf French bread, cut in small slices"],"mt":1},{"n":"Tomaten mit Käsefüllung","c":"snacks","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["¼ Tasse Frischkäse","1 EL Basilikum in feinen Streifen","1 EL fein gehackter Knoblauch","2 EL ungesalzene Butter","½ TL Salz","½ TL frisch gemahlener schwarzer Pfeffer","¼ Tasse Ricotta","30 Kirschtomaten, oberste Spitze entfernt"],"s":["Kombinieren Sie alle Zutaten außer Tomaten, um die Füllung zu machen.","Füllung in eine gallonengroße Zip-Top-Tasche mit einem kleinen Loch in einer der unteren Ecken gesnippt.","Tomaten etwa 3⁄4 voll füllen.","Als Vorspeise gekühlt servieren."],"x":[],"desc":"Dies ist toll als Vorspeise für Ihre nächste Dinner-Party.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_Stuffed_Tomatoes","i":"wb-en-1234","im":["c/cc/Pomidor_dolmas%C4%B1_Azerbaijani_cuisine.jpg/960px-Pomidor_dolmas%C4%B1_Azerbaijani_cuisine.jpg","MrArifnajafov","CC BY-SA 4.0","Pomidor dolması Azerbaijani cuisine.jpg","w"],"on":"Cheese Stuffed Tomatoes","og":["¼ cup cream cheese","1 tbsp basil chiffonade","1 tbsp minced garlic","2 tbsp unsalted butter","½ tsp salt","½ tsp freshly-ground black pepper","¼ cup ricotta cheese","30 cherry tomatoes, with the very top removed"],"mt":1},{"n":"Käsetarte","c":"kuchen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["½ Tasse Brie, Rinde entfernt","¾ Tasse Mascarpone","½ Tasse Zucker","½ Tasse ungesalzene Butter, geschmolzen","1 Prise Salz","½ Teig vom klassischen amerikanischen Apple Pie, mit Mascarpone statt Applejack"],"s":["Alle Zutaten mit Ausnahme von Teig zerkleinern. Beiseite legen.","Teig in einen groben Kreis rollen. Teig in eine 25 cm lange Pfanne geben, um eine Tortenschale zu machen, und den überschüssigen Teig von den Rändern entfernen.","Die Käsemischung in die Schale geben und bei 220 °C auf dem Boden des Ofens 15 Minuten backen. Bewegen Sie sich zum unteren Rack und backen für 10 Minuten mehr.","Entfernen und 10 Minuten ruhen lassen. Servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_Tart","i":"wb-en-1235","im":["1/1f/Slice_of_chocolate_cheese_tart_with_blueberries.jpg/960px-Slice_of_chocolate_cheese_tart_with_blueberries.jpg","Shisma","CC BY 4.0","Slice of chocolate cheese tart with blueberries.jpg","c"],"on":"Cheese Tart","og":["½ cup Brie cheese, rind removed","¾ cup mascarpone cheese","½ cup white granulated sugar","½ cup unsalted butter, melted","1 pinch of salt","½ dough from Classic American Apple Pie, made with mascarpone cheese instead of applejack"],"mt":1},{"n":"Käse mit Kräckern","c":"welt","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["Käse","Kräcker"],"s":["Holt ein Schneidebrett raus.","Schneiden Sie Käse in Stücke klein genug, um auf einen Cracker passen.","Käse auf einen Cracker legen (oder mit einem Messer bei Verwendung von Frischkäse verteilen).","Top-Käse mit einem anderen Cracker, wenn Sie möchten."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_and_Crackers","i":"wb-en-1236","im":["8/81/HK_CWB_%E9%A6%99%E6%B8%AF%E6%80%A1%E6%9D%B1%E9%85%92%E5%BA%97_Excelsior_Hotel_Cheese_Biscuit_Dec-2011.jpg/960px-HK_CWB_%E9%A6%99%E6%B8%AF%E6%80%A1%E6%9D%B1%E9%85%92%E5%BA%97_Excelsior_Hotel_Cheese_Biscuit_Dec-2011.jpg","Cookantean","CC BY-SA 3.0","HK CWB 香港怡東酒店 Excelsior Hotel Cheese Biscuit Dec-2011.jpg","w"],"on":"Cheese and Crackers","og":["Cheese","Crackers"],"mt":1},{"n":"Käsetoast","c":"snacks","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["dick geschnittenes Brot","fester, kräftiger Käse, gerieben","Beläge (z. B. Essiggurken, Zwiebel, Walnüsse usw.)"],"s":["Toast eine Seite des Brotes unter einem mittleren Broiler.","Leichte Toast auf die andere Seite des Brotes, gerade genug, um es zu erwärmen, dann den geriebenen Käse darüber verteilen. Gewünschte Toppings hinzufügen.","Die kitschige Seite des Brotes braten, bis der Käse sprudelt und braun ist.","Essen Sie schnell, aber seien Sie vorsichtig, wie der Käse wird Zunge-brennend heiß!"],"x":[],"desc":"Cheese on Toast ist ein einfaches Konzept, aber einfach falsch zu verstehen.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese_on_Toast","i":"wb-en-1237","im":["3/3e/Cheese_on_toast-11.jpg/960px-Cheese_on_toast-11.jpg","jules","CC BY 2.0","Cheese on toast-11.jpg","w"],"on":"Cheese on Toast","og":["Thick-cut bread","Firm-fleshed strong-flavoured cheese, grated","Toppings (e.g. pickles, onion, walnuts, etc.)"],"mt":1},{"n":"Hähnchenbrust mit Käsefüllung","c":"saucen","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["4 Hähnchenbrustfilets ohne Haut","1 EL Salz, aufgeteilt","1 EL frisch gemahlener schwarzer Pfeffer, aufgeteilt","1 Tasse zerkrümeltes Maisbrot","¼ Tasse getrocknete Cranberrys, grob gehackt","½ Tasse Apfelgelee","3 getrocknete Apfelringe, fein gehackt","½ Tasse Frischkäse","Olivenöl","Honig"],"s":["Kombinieren Sie 1⁄4 TL Salz, 1⁄4 TL schwarzer Pfeffer, Maisbrot, Obst, Gelee und Käse. In eine Gallone (4 Liter) große Zip-Top-Tasche mit einem sehr kleinen Loch in einer der unteren Ecken gesnippt gießen.","Mit einem schmalen Knochenmesser, machen Sie einen Schlitz in einer der Seite des Huhns Brust, aber nicht den ganzen Weg durch. Wiederholen Sie, bis alle Hühner geschnitten wurden.","Die Schlitze 2⁄3 des Weges voll mit der Kornbrotmischung füllen. Bürsten Sie die Kanten mit Honig und drücken Sie zusammen, um zu versiegeln. Krawatte mit Küchengarn geschlossen.","Legen Sie das Huhn in eine große Bratpfanne. Mit Olivenöl abbürsten und jedes Stück liberal mit restlichem Salz und Pfeffer würzen.","Setzen Sie ein Sondenthermometer in einem der Stücke, aber nicht berühren Füllung. Pfanne in die Mitte eines 205 °C Ofens legen und kochen, bis Kerntemperatur 74 °C erreicht","Auf eine Platte nehmen und mit Aluminiumfolie bedecken. Lassen Sie 7 Minuten vor dem Entfernen Thermometer und losbinden ruhen. Warm servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese-Stuffed_Chicken_Breasts","i":"wb-en-1238","on":"Cheese-Stuffed Chicken Breasts","og":["4 boneless skinless chicken breasts","1 tbsp salt, divided","1 tbsp freshly ground black pepper, divided","1 cup crumbled cornbread","¼ cup dried cranberries, roughly chopped","½ cup apple jelly","3 dried apple rings, finely minced","½ cup cream cheese","Olive oil","Honey"],"mt":1},{"n":"Pizza mit Käse im Rand","c":"fleisch","k":"USA","p":1,"t":40,"d":1,"v":0,"l":"en","g":["Backtrennspray","Maismehl","1 Dose Pizzateig aus dem Kühlregal","7 2,5 cm lange Stücke Fadenkäse (2,5 cm)","½ Tasse Pizzasoße","24 Scheiben Pepperoni (Salami)","1 Tasse gebratene italienische Wurst, zerbröselt","2 Tassen geriebene italienische Käsemischung"],"s":["Backofen auf 220 °C vorheizen (220C)","30 cm (30 cm) Pizzapfanne mit Kochspray besprühen. Auf Wunsch leicht mit Maismehl bestreuen.","Ab in der Mitte, drücken Pizzateig in Pfanne jenseits der Seiten der Pfanne um einen Zoll.","Falten Sie den hängenden Rand des Teiges zurück in die Mitte, indem Sie die Stöcke von String-Käse in der Tasche, den ganzen Weg um den Kreis.","Den Teig zum Versiegeln in den Käse stechen.","Backen Sie die Kruste 8 oder 10 Minuten, oder bis die Kanten hell golden und der Teig hat begonnen zu setzen.","Aus dem Ofen nehmen und die Sauce mit der Rückseite eines Löffels über die Kruste verteilen.","Auf der Soße den Pfefferoni, die Wurst und den geschredderten italienischen Käse verteilen.","Im Ofen ersetzen und backen, bis die Kruste tief goldbraun ist und der (Topping-)Käse geschmolzen wird.","In 6–8 Scheiben schneiden."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheese-Stuffed_Crust_Pizza","i":"wb-en-1239","im":["9/91/Pizza-3007395.jpg/960px-Pizza-3007395.jpg","igorovsyannykov","CC0","Pizza-3007395.jpg","w"],"on":"Cheese-Stuffed Crust Pizza","og":["Cooking spray","Corn meal","1 can refrigerated pizza crust","7 ea. 1-inch (2.5 cm) pieces of string cheese","½ cup pizza sauce","24 slices pepperoni","1 cup cooked Italian sausage, crumbled","2 cups Italian blend shredded cheese"],"mt":1},{"n":"Cheeseburger","c":"fleisch","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["230 g Rinderschulter, geputzt und in 4-cm-Würfel geschnitten","230 g Rinderhüfte, geputzt und in 4-cm-Würfel geschnitten","Steakgewürz","Olivenöl","4 Hamburgerbrötchen, halbiert","4 Scheiben dein Lieblingskäse (z. B. Pepper Jack)","Lieblingsbeläge"],"s":["Übergeben Sie Fleischwürfel durch eine Fleischmühle gesetzt, um zu fein. Einmal gemahlen, vermischen und in 4 Patties formen.","Bürsten Sie Patties mit Olivenöl und streuen Sie liberal mit Steak Rub.","Grillen Sie auf hoch für etwa 3–4 Minuten pro Seite für mittlere selten, 5–6 für mittel, und 7–8 für gut gemacht. Legen Sie in der letzten Minute ein Stück Käse darauf.","Entfernen und legen Sie eine Patty auf jeder unteren Hälfte der halbierten Brötchen.","Top mit Ihren Lieblings-Würfel und beenden mit der oberen Hälfte. Servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheeseburgers","i":"wb-en-1240","im":["4/4d/Cheeseburger.jpg/960px-Cheeseburger.jpg","Renee Comet (photographer)","Public domain","Cheeseburger.jpg","w"],"on":"Cheeseburgers","og":["8 ounces chuck, trimmed and cut into 1½-inch cubes","8 ounces sirloin, trimmed and cut into 1½-inch cubes","Steak Rub","Olive oil","4 hamburger buns, halved","4 slices of your favorite cheese (e.g. pepper jack)","Favorite toppings"],"mt":1},{"n":"Käsekuchen-Törtchen","c":"kuchen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["450 g Frischkäse","2 Eier","180 g Zucker","Halbbitter-Schokotropfen"],"s":["Den Backofen auf 180 °C vorheizen.","Den Frischkäse in der Mikrowelle in einer Schüssel weich machen. Dreißig Sekunden bei einer mittleren Einstellung sollten ausreichen.","Kombinieren Sie den Frischkäse, Eier und Zucker.","Legen Sie die Pfanne mit den Papieren aus.","Schokoladenchips in den Boden der Cupcake-Papiere setzen, weniger als eine volle Schicht zu machen; Nicht vollständig den Boden der Papiere zu decken.","Die Tassen mit der Frischkäsemischung füllen und dann in den Ofen geben.","Für etwa 15 Minuten backen. Die Schokolade wird schmelzen und schaffen einen Boden zu Ihren Kuchen, aber ein Teil dieser Schokolade wird auch Blase durch den Frischkäse für eine zusätzliche Wirkung.","Entfernen und 20 Minuten abkühlen lassen, bis die Schokolade auf der Unterseite härtet und knusprig wird."],"x":["Sie können auch die Spitze der Kuchen mit Schokolade garnieren, die Sie in einem Doppelkessel schmelzen."],"desc":"Diese kleinen Konfitüren sind große ein-per-afternoon Snacks. Sie sind dicht und geben Ihnen eine euphorische Hoch auf Süßigkeiten, aber machen Sie wollen nach der Arbeit gehen.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheesecake_Cups","i":"wb-en-1241","im":["e/ea/Cheesecake_cups_in_aluminum_forms.jpg/960px-Cheesecake_cups_in_aluminum_forms.jpg","Eric Kilby","CC BY-SA 2.0","Cheesecake cups in aluminum forms.jpg","c"],"on":"Cheesecake Cups","og":["1 lb (450 g) cream cheese","2 eggs","¾ cups (180 g) granulated sugar","Semi-sweet chocolate chips"],"mt":1},{"n":"Käsige Hähnchen-Nudeln","c":"pasta","k":"","p":2,"t":15,"d":1,"v":0,"l":"en","g":["85 g getrocknete Nudeln (beliebige Form)","¼ Tasse Frischkäse","¾ Tasse geriebener Mozzarella","¾ Tasse geriebener Cheddar","2 ½–3 ½ EL Hoisinsoße, nach Geschmack","1 Tasse gehacktes gegartes Hähnchen","½ Tasse Schlagsahne"],"s":["Bringen Sie einen Topf mit Wasser zum Kochen. Fügen Sie die Nudeln hinzu und kochen Sie etwa 10 Minuten (oder bis die Nudeln weich sind).","Die Nudeln so abtropfen lassen, dass kein Wasser in der Pfanne bleibt. Zurück abgelassene Nudeln in den Topf.","Sahne, Käse, Huhn und Hoisin-Sauce in die Pasta geben.","Kochen Sie für ein paar Minuten, um alles durch zu wärmen.","Servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheesy_Chicken_Pasta","i":"wb-en-1242","on":"Cheesy Chicken Pasta","og":["¾ cup (85 g/3 oz) dried pasta (whatever shape you like)","¼ cup () cream cheese","¾ cup () grated mozzarella cheese","¾ cup () grated cheddar cheese","2½–3½ tablespoons hoisin sauce to taste","1 cup () chopped cooked chicken","½ cup () heavy whipping cream"],"mt":1},{"n":"Käsige Maisbrotfüllung mit Mascarpone","c":"saucen","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["2 ½ Tassen Maisbrot, zerbröselt","¾ Tasse Mascarpone, aufgeteilt","2 Tassen Schlagsahne, weich geschlagen","½ TL Salz","½ TL schwarzer Pfeffer","1 EL Salbei, in dünne Scheiben geschnitten","4 Eigelb, verquirlt","¼ Tasse Butter, geschmolzen"],"s":["Kombinieren Sie alle Zutaten mit Ausnahme von Sahne und 1⁄4 Tasse Mascarpone Käse.","Sanft in Creme falten.","Im 175 °C Ofen 30–35 Minuten backen.","Restlicher Käse darüber verteilen und unter einen vorgeheizten Broiler stellen, bis er gebräunt und sprudelt wird.","Kühle 10 Minuten; Dienen."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheesy_Mascarpone_Cornbread_Stuffing","i":"wb-en-1243","im":["a/ae/Stuffing_a_turkey.jpg/960px-Stuffing_a_turkey.jpg","Rick Kimpel","CC BY-SA 2.0","Stuffing a turkey.jpg","w"],"on":"Cheesy Mascarpone Cornbread Stuffing","og":["2 ½ cups cornbread, crumbled","¾ cup mascarpone cheese, divided","2 cups heavy cream, whipped to soft peaks","½ tsp salt","½ tsp black pepper","1 tbsp sage, sliced thinly","4 egg yolks, beaten","¼ cup butter, melted"],"mt":1},{"n":"Käsige Kartoffelsuppe","c":"suppen","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["Speck, gehackt","Butter","Zwiebel, fein gehackt","3 Zehen Knoblauch, fein gehackt","¼ Tasse Weizenmehl","Hühnerbrühe","Kartoffeln, gewürfelt","Milch","Salz","gemahlener schwarzer Pfeffer","geriebener Cheddar","Schnittlauch, gehackt"],"s":["Den Speck bei mittlerer Hitze bis braun und knusprig anbraten. Wenn der Speck mager ist, 1 TL Öl beim Braten hinzufügen. Entfernen Sie von der Hitze, und abtropfen auf Papiertücher.","Butter und gehackte Zwiebel in die gleiche Pfanne geben. 2 Minuten bei mittlerer Hitze bis aromatisch kochen.","Den gehackten Knoblauch dazugeben und noch ein paar Minuten kochen, bis die Zwiebel weich ist.","Rühren Sie das Mehl, und kochen für ein paar Minuten, um den Rohgeschmack zu entfernen.","Nach und nach die Hühnerbrühe einrühren, um Klumpen zu vermeiden. Die gewürfelten Kartoffeln mit einem Schuss Milch vermischen und köcheln, bis die Kartoffeln zart sind.","Wenn gewünscht, können Sie die Hälfte der Suppe mit einem Eintauchmischer vermischen und in den Rest der Suppe rühren. Dadurch erhält die Suppe eine cremige, dicke Konsistenz.","Mit Salz und gemahlenem Pfeffer würzen, dann mit der sauren Sahne und der Hälfte des knusprigen Specks vermischen. Die Pfanne bedecken und 10 Minuten köcheln lassen.","Den Cheddar-Käse mischen und heiß servieren, mit den restlichen Speckstücken und gehackten Schnittlauch garnieren."],"x":[],"desc":"Dieses Rezept für kitschige Kartoffelsuppe macht eine dicke und cremige Suppe, garniert mit Käse und Schnittlauch.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cheesy_Potato_Soup","i":"wb-en-1244","im":["1/14/Cheesy_cream_of_potato_soup.jpg/960px-Cheesy_cream_of_potato_soup.jpg","jeffreyw","CC BY 2.0","Cheesy cream of potato soup.jpg","c"],"on":"Cheesy Potato Soup","og":["Bacon, chopped","Butter","Onion, finely chopped","3 cloves garlic, minced","¼ cup all-purpose flour","Chicken broth","Potatoes, diced","Milk","Salt","Ground black pepper","Shredded cheddar cheese","Chives, chopped"],"mt":1},{"n":"Cherbet Mazhar (algerisches Getränk mit Orangenblütenwasser)","c":"getraenke","k":"Algerien","p":4,"t":10,"d":1,"v":0,"l":"en","g":["1 l frisches Wasser","1 großes Glas Orangenblütenwasser","2–3 EL Zucker (nach Geschmack)","1 TL gemahlener Zimt","115 g Zimt"],"s":["Kombinieren Sie Wasser und Orangenblütenwasser in einem großen Topf bei mittlerer Hitze. Mit einem Holzlöffel umrühren.","Das Zimtpulver dazugeben und rühren, bis es vollständig verdünnt ist. Dann den Zucker dazugeben und alles gut mischen.","Wenn der Zucker vollständig aufgelöst ist, das Getränk auf einen Krug übertragen und im Kühlschrank abkühlen lassen. Mit Quittenmarmelade oder saisonalem Obst servieren."],"x":[],"desc":"Orange Blossom Cherbet (, Cherbet Mazhar) ist ein erfrischendes algerisches Getränk. Es stammt aus Algier und wird auch Cherbet Khotba (Proposal Cherbet) genannt, da es nur während Ehevorschlägen nach den Traditionen der Algier serviert wird.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cherbet_Mazhar_(Algerian_Flower_Water_Drink)","i":"wb-en-1245","im":["a/a6/Cherbet.jpg/500px-Cherbet.jpg","Toranciel8","CC BY-SA 4.0","Cherbet.jpg","d"],"on":"Cherbet Mazhar (Algerian Flower Water Drink)","og":["1 L of fresh water","1 large glass of orange blossom water","2–3 tbsp of granulated sugar (depending on taste)","1 tsp of cinnamon powder","1 stick of cinnamon"],"mt":1},{"n":"Cherbet Meliana (algerisches Kirschgetränk)","c":"getraenke","k":"Algerien","p":4,"t":10,"d":1,"v":0,"l":"en","g":["1 kg Zuckerwürfel","1 Glas warmes Wasser","1 Glas gepresster Kirschsaft","1 TL zerstoßene Kirschkerne"],"s":["Zuckerwürfel mit warmem Wasser vermischen. Kirschsaft und gebrochene Gruben hinzufügen.","Bringen Sie zum Kochen bei hoher Hitze, während Abschäumen, bis der Sirup in einen dünnen Strom tropft.","Entfernen Sie von Hitze und Belastung. Flasche. Mit funkelndem oder stillem Wasser servieren."],"x":["Dieses Getränk kann auch mit Zitronen-, Trauben- oder Granatapfelsaft zubereitet werden."],"desc":"Cherbet Meliana ist ein erfrischendes algerisches Getränk. Wie der Name schon sagt, stammt das Getränk aus Meliana, einer Stadt in der Provinz Aïn Defla im Nordwesten Algeriens, wo es als traditionelles Getränk gilt. Der Konsum des Getränks ist aufgrund der Abnahme der Produktion erheblich eingestellt","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cherbet_Meliana_(Algerian_Cherry_Beverage)","i":"wb-en-1246","on":"Cherbet Meliana (Algerian Cherry Beverage)","og":["1 kg of sugar cubes","1 glass of warm water","1 glass of pressed cherry juice","1 tsp of broken cherry pits"],"mt":1},{"n":"Chereh Tamba (gambischer Erdnusseintopf)","c":"suppen","k":"","p":4,"t":0,"d":2,"v":0,"l":"en","g":["1 Tasse Erdnüsse (Erdnüsse)","2 EL Pflanzenöl","2 große Zwiebeln, fein gehackt","4 Zehen Knoblauch, fein gehackt","2 Tomaten, gewürfelt","1 Paprikaschote, gewürfelt","1 TL gemahlener Ingwer","1 TL Paprikapulver","1 TL gemahlener Cayennepfeffer (optional, für mehr Schärfe)","2 EL Tomatenmark","500 g Hähnchen, in Stücke geschnitten","Wasser oder Brühe zum Garen","Salz","Pfeffer"],"s":["Den Ofen auf 180 °C vorheizen.","Die Erdnüsse gleichmäßig auf ein Backblech verteilen. Die Erdnüsse im vorgeheizten Ofen ca. 10–15 Minuten rösten, oder bis sie goldbraun und duftend sind.","Die gerösteten Erdnüsse aus dem Ofen nehmen und abkühlen lassen.","Nach dem Abkühlen die gerösteten Erdnüsse auf einen Lebensmittelverarbeiter oder Mixer übertragen und in eine glatte Paste schleifen. Beiseite legen.","In einem großen Topf das Pflanzenöl bei mittlerer Hitze erhitzen. Die gehackten Zwiebeln und gehackten Knoblauch dazugeben. Sauté, bis sie weich und durchscheinend werden.","Fügen Sie die gewürfelten Tomaten, gewürfelten Paprika, gemahlen Ingwer, gemahlen Paprika und gemahlen Cayenne Pfeffer (wenn verwendet) in den Topf. Rühren Sie gut zu kombinieren.","In die Tomatenpaste und die Erdnusspaste mischen, um sicherzustellen, dass sie gleichmäßig in das Gemisch eingearbeitet werden.","Die Hühnerstücke in den Topf geben und rühren, um sie mit der Soße zu beschichten. Gießen Sie genügend Wasser oder Brühe in den Topf, um das Huhn zu bedecken und eine Eintopf-ähnliche Konsistenz zu schaffen. Bringen Sie die Mischung zum Kochen, dann reduzieren Sie die Hitze zu niedrig und decken Sie den Topf mit einem Deckel.","Lassen Sie die Chereh-Tamba für ca. 30-40 Minuten köcheln, oder bis das Huhn durchgekocht und zart ist. Gelegentlich umrühren, um das Kleben zu verhindern.","Probieren Sie die Chereh Tamba und passen Sie die Würze mit Salz, Pfeffer und zusätzlichen Gewürzen auf Wunsch an.","Heiß mit Reis oder Couscous servieren."],"x":[],"desc":"Chereh Tamba, auch bekannt als Gambian Erdnuss Eintopf, ist ein würziger und herzhafter Eintopf, der die Verwendung von Erdnüssen (Erdnüsse) als Schlüsselbestandteil darstellt. Es ist ein traditionelles gambisches Rezept, das die reichen Aromen der Region hervorhebt. Chereh Tamba ist ein beliebter Hauptgang, der oft mit Ri serviert wird","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Chereh_Tamba_(Gambian_Groundnut_Stew)","i":"wb-en-1247","im":["3/31/Mafe.malien.jpg/960px-Mafe.malien.jpg","Marshiayers","CC0","Mafe.malien.jpg","w"],"on":"Chereh Tamba (Gambian Groundnut Stew)","og":["1 cup groundnuts (peanuts)","2 tablespoons vegetable oil","2 large onions, finely chopped","4 cloves of garlic, minced","2 tomatoes, diced","1 bell pepper, diced","1 teaspoon ground ginger","1 teaspoon ground paprika","1 teaspoon ground cayenne pepper (optional, for added spiciness)","2 tablespoons tomato paste","500 g chicken, cut into pieces","Water or broth for cooking","Salt","Pepper"],"mt":1},{"n":"Cherries Jubilee (flambierte Kirschen)","c":"dessert","k":"","p":4,"t":0,"d":1,"v":0,"l":"en","g":["1 Tasse Maraschino-Kirschen, abgetropft","½ Tasse Zucker","½ TL frisch gemahlener Zimt","½ TL abgeriebene Orangenschale, fein gerieben","½ Tasse dunkler Rum","2 EL ungesalzene Butter","¼ TL frisch gemahlener Piment"],"s":["Kirschen mit Zucker und Gewürzen bestreuen. Beiseite legen.","Butter bei mittlerer Hitze in einer großen Pfanne schmelzen. Kirschen hinzufügen und bis leicht gebräunt, 4–5 Minuten anbraten.","Rum und geriebene Orangenschale kombinieren. Über Kirschen gießen und vorsichtig mit einem Feuerstab entzünden. Pfanne schütteln, bis die Flammen sterben.","Warm mit etwas Eis servieren."],"x":[],"desc":"","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cherries_Jubilee","i":"wb-en-1248","im":["3/3c/Cherriesjubilee.jpg/960px-Cherriesjubilee.jpg","stu_spivack","CC BY-SA 2.0","Cherriesjubilee.jpg","w"],"on":"Cherries Jubilee","og":["1 cup maraschino cherries, drained","½ cup white granulated sugar","½ tsp freshly-ground cinnamon","½ tsp orange zest, finely grated","½ cup dark rum","2 tbsp unsalted butter","¼ tsp freshly-ground allspice"],"mt":1},{"n":"Kirsch-Brownies","c":"brot","k":"","p":36,"t":50,"d":2,"v":0,"l":"en","g":["#Boden","2 Eier (100 g)","2.4 dl Zucker","6 EL Margarine","0.6 dl Kakao","1.8 dl Mehl","¼ TL Salz","#Belag","110 g weicher Frischkäse","0.6 dl Maraschino-Kirschsirup","0.6 dl Puderzucker","1 Ei","1.2 dl Halbbitter-Schokotropfen","1.2 dl Maraschino-Kirschen"],"s":["Margarine bei mittlerer Hitze in einem Topf schmelzen, dann im Kakao vermischen.","Zucker, Salz und Eier dazugeben. Gut vermischen und dann in das Mehl falten.","In einer gefetteten 23 x 23 cm (22 x 22 cm) Kuchenpfanne verteilen und beiseite stellen.","Sahnekäse, Kirschsirup und Puderzucker in einer Schüssel cremig zusammenschlagen.","Das Ei in die Mischung geben und gut vermischen.","Schokoladenchips und Kirschen vermischen.","Die zweite Mischung über die Basis gießen.","Backen Sie bei 175 °C für 30–40 Minuten, bis ein Zahnstocher durch die Mitte gestochen wird feucht (aber nicht nass mit Teig).","Abkühlen lassen und in 36 Quadrate schneiden."],"x":["Kühlen Sie mindestens 10 Minuten vor dem Schneiden und Essen oder Sie werden heiße gebrochene Brownies haben."],"desc":"Cherry Brownies sind ein reichhaltiger Brownie ohne Frost, eine Fudge-ähnliche Basis und ein Käsekuchen-ähnliches Oberteil, gefüllt mit Maraschinokirschen und Schokoladenchips.","img":"","u":"https://en.wikibooks.org/wiki/Cookbook:Cherry_Brownies","i":"wb-en-1249","im":["b/b1/Brownie_with_cherry.jpg/960px-Brownie_with_cherry.jpg","Селтәр","CC BY-SA 4.0","Brownie with cherry.jpg","c"],"on":"Cherry Brownies","og":["#Base","2 ea. (100 g) eggs","1 cup (2.4 dl) white granulated sugar","6 tbsp margarine","¼ cup (0.6 dl) cocoa","¾ cup (1.8 dl) flour","¼ tsp salt","#Topping","4 ounces (110 g) softened cream cheese","¼ cup (0.6 dl) maraschino cherry syrup","¼ cup (0.6 dl) icing sugar","1 egg","½ cup (1.2 dl) semi-sweet chocolate chips","½ cup (1.2 dl) maraschino cherries"],"mt":1}]);
